// MustJSON implements the must json helper.
func MustJSON(v interface{}) []byte {

	// `b` and `err` store the error produced by this operation.
	b, err := json.Marshal(v)

	if err != nil {

		log.Printf("[WARN] MustJSON marshal failed: %v", err)
		return []byte("{}")

	}

	return b

}

// BroadcastTx implements the broadcast tx helper.
func (n *Node) BroadcastTx(tx Transaction) {

	if n.TxTopic == nil && n.PubSub == nil {

		if DebugConsensus {

		}

		return

	}

	// `txPayload` and `err` store the error produced by this operation.
	txPayload, err := MarshalTransactionProtobuf(tx)
	if err != nil {
		return
	}

	// `msg` stores the value produced by this operation.
	msg := Message{

		Type: MsgTx,

		Data: txPayload,
	}

	// `data` and `err` store the error produced by this operation.
	data, err := MarshalP2PMessage(msg)

	if err != nil {

		return

	}

	if n.TxTopic != nil {
		// `err` stores the error produced by this operation.
		if err := n.TxTopic.Publish(context.Background(), data); err != nil {
			if DebugConsensus {
			}
			return
		}
	} else if n.PubSub != nil {
		// `err` stores the error produced by this operation.
		if err := n.PubSub.Publish(TopicTx, data); err != nil {
			_ = n.PubSub.Publish(TopicTransactionsLegacy, data)
		}
	}

	if DebugConsensus {

	}

}

// BroadcastData implements the broadcast data helper.
func BroadcastData(node *Node, data string) {

	// `peer` tracks the current values while iterating.
	for _, peer := range node.Peers {

		println("Node", node.ID, "sent data to peer", peer, ":", data)

	}

}

// txID implements the tx id helper.
func txID(tx Transaction) string {

	if tx.ID != "" {

		return tx.ID

	}

	return ComputeTxID(tx)

}

// txPriorityLess implements the tx priority less helper.
func txPriorityLess(a, b Transaction) bool {

	if a.Fee != b.Fee {

		return a.Fee > b.Fee

	}

	// `maxInt64` defines the constant value used by this package.
	const maxInt64 = int64(^uint64(0) >> 1)

	// `aExpiry` stores the value produced by this operation.
	aExpiry := a.Expiry

	// `bExpiry` stores the value produced by this operation.
	bExpiry := b.Expiry

	if aExpiry <= 0 {

		aExpiry = maxInt64

	}

	if bExpiry <= 0 {

		bExpiry = maxInt64

	}

	if aExpiry != bExpiry {

		return aExpiry < bExpiry

	}

	return txID(a) < txID(b)

}

// pendingSpendAmount implements the pending spend amount helper.
func pendingSpendAmount(tx Transaction) int {

	switch tx.Type {

	case TxValidatorUpdate, TxUnstake:

		return 0
	case TxDTL:
		if tx.Fee < 0 {
			return 0
		}
		return tx.Fee

	}

	// `amount` stores the value produced by this operation.
	amount := tx.Amount + tx.Fee

	if amount < 0 {

		return 0

	}

	return amount

}

// mempoolSenderNonceKey implements the mempool sender nonce key helper.
func mempoolSenderNonceKey(sender string, nonce int) string {
	return mempoolSenderKey(sender) + "|" + strconv.Itoa(nonce)
}

// mempoolSenderKey implements the mempool sender key helper.
func mempoolSenderKey(sender string) string {
	return canonicalAddressKey(sender)
}

// ensureIndexesLocked implements the ensure indexes locked helper.
func (m *Mempool) ensureIndexesLocked() {
	if m.SeenTxIDs == nil {
		m.SeenTxIDs = make(map[string]bool)
	}
	if m.txByID == nil {
		m.txByID = make(map[string]struct{})
	}
	if m.txBySenderNonce == nil {
		m.txBySenderNonce = make(map[string]string)
	}
	if m.pendingCountBySender == nil {
		m.pendingCountBySender = make(map[string]int)
	}
	if m.nextNonceBySender == nil {
		m.nextNonceBySender = make(map[string]int)
	}
	if len(m.txByID) != len(m.Transactions) || len(m.txBySenderNonce) != len(m.Transactions) {
		m.rebuildIndexesLocked()
	}
}

// rebuildIndexesLocked implements the rebuild indexes locked helper.
func (m *Mempool) rebuildIndexesLocked() {
	m.txByID = make(map[string]struct{}, len(m.Transactions))
	m.txBySenderNonce = make(map[string]string, len(m.Transactions))
	m.pendingCountBySender = make(map[string]int)
	m.nextNonceBySender = make(map[string]int)

	// `tx` tracks the transaction data handled by this operation.
	for _, tx := range m.Transactions {
		// `senderKey` stores the key used to access the related value.
		senderKey := mempoolSenderKey(tx.From)
		m.txByID[tx.ID] = struct{}{}
		m.txBySenderNonce[mempoolSenderNonceKey(tx.From, tx.Nonce)] = tx.ID
		m.pendingCountBySender[senderKey]++
		// `next` stores the value produced by this operation.
		next := tx.Nonce + 1
		if next > m.nextNonceBySender[senderKey] {
			m.nextNonceBySender[senderKey] = next
		}
	}
}

// pruneExpiredLocked implements the prune expired locked helper.
func (m *Mempool) pruneExpiredLocked(now int64) int {

	if len(m.Transactions) == 0 {

		return 0

	}

	m.ensureIndexesLocked()
	if m.SeenTxIDs == nil {
		m.SeenTxIDs = make(map[string]bool)
	}

	// `removed` stores the value produced by this operation.
	removed := 0
	// `removedIDs` stores the value produced by this operation.
	removedIDs := make([]string, 0, 4)

	// `filtered` stores the value produced by this operation.
	filtered := m.Transactions[:0]

	// `tx` tracks the transaction data handled by this operation.
	for _, tx := range m.Transactions {

		if tx.Expiry > 0 && now > tx.Expiry {

			// `amount` stores the value produced by this operation.
			if amount := pendingSpendAmount(tx); amount > 0 {

				rollbackPendingSpend(normalizeCoin(tx.Coin), tx.From, amount)

			}

			removed++
			if tx.ID != "" {
				removedIDs = append(removedIDs, tx.ID)
			}

			continue

		}

		filtered = append(filtered, tx)

	}

	if removed > 0 {

		m.Transactions = filtered
		m.rebuildIndexesLocked()
		// `id` tracks the current position in the related collection.
		for _, id := range removedIDs {
			delete(m.SeenTxIDs, id)
		}

	}

	return removed

}

// PruneExpired prunes expired.
func (m *Mempool) PruneExpired() int {

	// `now` stores the value produced by this operation.
	now := time.Now().Unix()

	m.mu.Lock()

	// `removed` stores the value produced by this operation.
	removed := m.pruneExpiredLocked(now)

	m.mu.Unlock()

	return removed

}

// HasTx reports whether tx exists.
func (m *Mempool) HasTx(id string) bool {

	if id == "" {

		return false

	}

	m.mu.Lock()

	defer m.mu.Unlock()
	m.ensureIndexesLocked()

	// `ok` stores whether the related condition is satisfied.
	_, ok := m.txByID[id]
	return ok

}

const (
	// mempoolPressureTxPerBlock is a proposer-side pressure cap. It stays below
	// the protocol max so validators can still accept larger historical blocks,
	// while new high-pressure proposals avoid 250-tx execution spikes.
	mempoolPressureTxPerBlock = 200
)

func mempoolPressureDepth() int {
	depth := ConsensusMaxTxPerBlock + ConsensusMaxTxPerBlock/2
	if depth < 1 {
		return 1
	}
	return depth
}

func mempoolBatchPressureDepth() int {
	depth := ConsensusMaxTxPerBlock * 2
	if depth < 1 {
		return 1
	}
	return depth
}

// localProducerMaxTxPerBlock caps local producer batching at the protocol transaction limit.
func localProducerMaxTxPerBlock() int {
	// `limit` stores the value produced by this operation.
	limit := GlobalConfig.MaxTxPerBlock
	if limit <= 0 || limit > ConsensusMaxTxPerBlock {
		return ConsensusMaxTxPerBlock
	}
	return limit
}

func localProducerMaxTxPerBlockForDepth(depth int) int {
	limit := localProducerMaxTxPerBlock()
	if depth >= mempoolBatchPressureDepth() && limit > mempoolPressureTxPerBlock {
		return mempoolPressureTxPerBlock
	}
	return limit
}

// selectTxBatch implements the select tx batch helper.
func selectTxBatch(txs []Transaction, ledger Ledger) []Transaction {

	if len(txs) == 0 {

		return nil

	}

	sort.Slice(txs, func(i, j int) bool {

		return txPriorityLess(txs[i], txs[j])

	})

	// `maxBlock` stores the synchronization state protecting shared data.
	maxBlock := localProducerMaxTxPerBlockForDepth(len(txs))

	if maxBlock <= 0 || maxBlock > len(txs) {

		maxBlock = len(txs)

	}

	// `perAccountLimit` stores the value produced by this operation.
	perAccountLimit := MaxTxPerAccountPerBlock

	if perAccountLimit <= 0 {

		perAccountLimit = maxBlock

	}

	// `selected` stores the value produced by this operation.
	selected := make([]Transaction, 0, maxBlock)

	// `perAccountCount` stores the measured quantity used by this operation.
	perAccountCount := make(map[string]int)

	// `nextNonce` stores the value produced by this operation.
	nextNonce := make(map[string]int)

	// `selectedIDs` stores the value produced by this operation.
	selectedIDs := make(map[string]struct{})

	// `progress` stores the value produced by this operation.
	progress := true

	for progress && len(selected) < maxBlock {

		progress = false

		// `tx` tracks the transaction data handled by this operation.
		for _, tx := range txs {

			if len(selected) >= maxBlock {

				break

			}

			// `id` stores the current position in the related collection.
			id := txID(tx)

			// `exists` stores whether the related condition is satisfied.
			if _, exists := selectedIDs[id]; exists {

				continue

			}

			// `senderKey` stores the key used to access the related value.
			senderKey := mempoolSenderKey(tx.From)

			if perAccountLimit > 0 && perAccountCount[senderKey] >= perAccountLimit {

				continue

			}

			// `expected` and `ok` store whether the related condition is satisfied.
			expected, ok := nextNonce[senderKey]

			if !ok {

				expected = getNonce(ledger, tx.From) + 1

			}

			if tx.Nonce != expected {

				continue

			}

			selected = append(selected, tx)

			selectedIDs[id] = struct{}{}

			perAccountCount[senderKey]++

			nextNonce[senderKey] = expected + 1

			progress = true

		}

	}

	return selected

}

// AddTransaction adds transaction.
func (m *Mempool) AddTransaction(tx Transaction, ledger Ledger, currentHeight uint64) (bool, string) {

	// =====================================================

	// =====================================================
	normalizeIncomingTx(&tx)
	// `err` stores the error produced by this operation.
	if err := validateRemovedVMEnvelope(tx); err != nil {
		RecordFakeTxAttempt(tx.From)
		return false, err.Error()
	}
	// `err` stores the error produced by this operation.
	if err := validateTransactionShape(tx); err != nil {
		RecordFakeTxAttempt(tx.From)
		return false, err.Error()
	}

	// `err` stores the error produced by this operation.
	if err := EnforceTxBan(tx.From); err != nil {

		return false, "address banned"

	}

	// =====================================================

	// =====================================================

	now := time.Now().Unix()

	if tx.Expiry <= now {

		RecordFakeTxAttempt(tx.From)

		return false, "transaction expired"

	}

	if MaxTxTTLSeconds > 0 && tx.Expiry-now > int64(MaxTxTTLSeconds) {

		RecordFakeTxAttempt(tx.From)

		return false, "transaction expiry too far"

	}

	// `executionHeight` stores the height at which a mempool tx is expected to execute.
	executionHeight := currentHeight + 1
	// `err` stores the error produced by this operation.
	if err := m.ValidateTransactionAtHeight(tx, &ledger, executionHeight); err != nil {

		RecordFakeTxAttempt(tx.From)

		return false, err.Error()

	}

	// =====================================================

	// =====================================================

	m.mu.Lock()

	defer m.mu.Unlock()

	m.pruneExpiredLocked(now)
	m.ensureIndexesLocked()
	// `senderKey` stores the key used to access the related value.
	senderKey := mempoolSenderKey(tx.From)

	if MaxMempoolSize > 0 && len(m.Transactions) >= MaxMempoolSize {

		RecordFakeTxAttempt(tx.From)

		return false, "mempool full"

	}

	// Deterministic tx_id (SHA256(tx_bytes))
	canonicalID := ComputeTxID(tx)
	if tx.ID == "" {
		tx.ID = canonicalID
	} else if tx.ID != canonicalID {
		if matchesLegacySignedTxID(tx, tx.ID) {
			tx.ID = canonicalID
		} else {
			RecordFakeTxAttempt(tx.From)
			return false, "tx id mismatch"
		}
	}

	// =====================================================

	// =====================================================

	count := m.pendingCountBySender[senderKey]

	if count >= MaxTxPerAddress {

		RecordFakeTxAttempt(tx.From)

		return false, "too many pending transactions"

	}

	// =====================================================

	// =====================================================

	if m.SeenTxIDs[tx.ID] {

		RecordFakeTxAttempt(tx.From)

		return false, "duplicate transaction"

	}

	// `exists` stores whether the related condition is satisfied.
	if _, exists := m.txByID[tx.ID]; exists {

		RecordFakeTxAttempt(tx.From)

		return false, "duplicate transaction"

	}

	// =====================================================

	// =====================================================

	coin := normalizeCoin(tx.Coin)

	if !isProtocolCoinAllowed(coin) {

		RecordFakeTxAttempt(tx.From)

		return false, "unsupported coin"

	}

	// =====================================================

	// =====================================================

	if tx.Type == TxValidatorUpdate {

		// `requiredFee` stores the request data being processed.
		requiredFee := requiredFeeForTxWithLedger(&ledger, tx)

		// `nonceKey` stores the key used to access the related value.
		nonceKey := mempoolSenderNonceKey(tx.From, tx.Nonce)
		// `existingID` and `exists` store whether the related condition is satisfied.
		if existingID, exists := m.txBySenderNonce[nonceKey]; exists {
			RecordFakeTxAttempt(tx.From)
			return false, fmt.Sprintf("duplicate nonce already in mempool: %s", existingID)
		}

		if tx.Fee != requiredFee {
			RecordFakeTxAttempt(tx.From)
			return false, fmt.Sprintf("invalid fee: got %d expected %d", tx.Fee, requiredFee)
		}

		// `expectedNonce` stores the value produced by this operation.
		expectedNonce := getNonce(ledger, tx.From) + 1
		// `cachedNext` stores the value produced by this operation.
		if cachedNext := m.nextNonceBySender[senderKey]; cachedNext > expectedNonce {
			expectedNonce = cachedNext
		}
		if tx.Nonce != expectedNonce {
			RecordFakeTxAttempt(tx.From)
			return false, fmt.Sprintf("invalid nonce: got %d expected %d", tx.Nonce, expectedNonce)
		}

		// `required` stores the request data being processed.
		required := pendingSpendAmount(tx)
		if required > 0 {
			pendingSpendMu.Lock()
			// `pendingKey` stores the key used to access the related value.
			pendingKey := balanceKey(coin, tx.From)
			// `available` stores the value produced by this operation.
			available := getBalance(ledger, coin, tx.From) - PendingSpend[pendingKey]
			if available < required {
				pendingSpendMu.Unlock()
				RecordFakeTxAttempt(tx.From)
				return false, "insufficient balance"
			}
			PendingSpend[pendingKey] += required
			pendingSpendMu.Unlock()
		}
	} else {
		if tx.Type == TxDTL {
			// `err` stores the error produced by this operation.
			if err := validateDTLTransaction(&ledger, tx, currentHeight); err != nil {
				RecordFakeTxAttempt(tx.From)
				return false, err.Error()
			}
		} else if tx.Amount <= 0 {

			RecordFakeTxAttempt(tx.From)

			return false, "invalid amount"

		}
		// `requiredFee` stores the request data being processed.
		requiredFee := requiredFeeForTxWithLedger(&ledger, tx)

		// `nonceKey` stores the key used to access the related value.
		nonceKey := mempoolSenderNonceKey(tx.From, tx.Nonce)
		// `existingID` and `exists` store whether the related condition is satisfied.
		if existingID, exists := m.txBySenderNonce[nonceKey]; exists {
			if existingID == tx.ID {
				return false, "duplicate transaction"
			}
			return false, fmt.Sprintf("pending nonce conflict: nonce %d already queued", tx.Nonce)
		}

		if tx.Type == TxDTL {

			// `err` stores the error produced by this operation.
			if err := validateDTLFeeBounds(tx.Fee, requiredFee); err != nil {

				RecordFakeTxAttempt(tx.From)

				return false, err.Error()

			}

		} else if tx.Fee != requiredFee {

			RecordFakeTxAttempt(tx.From)

			return false, fmt.Sprintf("invalid fee: got %d expected %d", tx.Fee, requiredFee)

		}

		// `expectedNonce` stores the value produced by this operation.
		expectedNonce := getNonce(ledger, tx.From) + 1
		// `cachedNext` stores the value produced by this operation.
		if cachedNext := m.nextNonceBySender[senderKey]; cachedNext > expectedNonce {
			expectedNonce = cachedNext
		}

		if tx.Nonce != expectedNonce {

			RecordFakeTxAttempt(tx.From)

			return false, fmt.Sprintf("invalid nonce: got %d expected %d", tx.Nonce, expectedNonce)

		}

		switch tx.Type {

		case TxStake:

			// `validatorID` stores whether the related condition is satisfied.
			validatorID := strings.TrimSpace(tx.To)

			if validatorID == "" {

				RecordFakeTxAttempt(tx.From)

				return false, "missing validator id"

			}

			// `other` and `ok` store whether the related condition is satisfied.
			if other, ok := walletBoundValidator(&ledger, tx.From, validatorID); ok {

				RecordFakeTxAttempt(tx.From)

				return false, fmt.Sprintf("wallet already bound to validator %s", other)

			}

			// `pending` tracks the current values while iterating.
			for _, pending := range m.Transactions {

				if pending.Type != TxStake || !addressesEqual(pending.From, tx.From) {

					continue

				}

				// `pendingValidator` stores the value produced by this operation.
				pendingValidator := strings.TrimSpace(pending.To)

				if pendingValidator == "" {

					continue

				}

				if !strings.EqualFold(pendingValidator, validatorID) {

					RecordFakeTxAttempt(tx.From)

					return false, fmt.Sprintf("wallet already has pending stake to validator %s", pendingValidator)

				}

			}

			// `lockEpochs` stores the synchronization state protecting shared data.
			lockEpochs := tx.StakeEpochs

			if lockEpochs == 0 {

				lockEpochs = DefaultStakeLockEpochs

			}

			if lockEpochs < minUnstakeEpochs() {

				RecordFakeTxAttempt(tx.From)

				return false, "stake lock too short"

			}
			// `err` stores the error produced by this operation.
			if _, err := validateStakeConsensusPubKey(tx, GlobalValidatorRegistry.Snapshot()); err != nil {

				RecordFakeTxAttempt(tx.From)

				return false, err.Error()

			}

		case TxUnstake:

			// `validatorID` stores whether the related condition is satisfied.
			validatorID := strings.TrimSpace(tx.To)

			if validatorID == "" {

				RecordFakeTxAttempt(tx.From)

				return false, "missing validator id"

			}

			if tx.Amount <= requiredFee {

				RecordFakeTxAttempt(tx.From)

				return false, "unstake amount must exceed fee"

			}

			// `key` stores the key used to access the related value.
			key := stakeKey(tx.From, validatorID)

			// `rec` and `ok` store whether the related condition is satisfied.
			rec, ok := ledger.Stakes[key]

			if !ok || rec.Amount < tx.Amount {

				RecordFakeTxAttempt(tx.From)

				return false, "insufficient staked balance"

			}

			if currentHeight > 0 && rec.LockedUntil > currentHeight {

				RecordFakeTxAttempt(tx.From)

				return false, fmt.Sprintf("stake still locked until height %d", rec.LockedUntil)

			}

		case TxDTL:
			// DTL tx spends fee only in base coin; token balance effects are in DTL state.
			if tx.Fee <= 0 {
				RecordFakeTxAttempt(tx.From)
				return false, "invalid dtl fee"
			}

		}

		// `required` stores the request data being processed.
		required := pendingSpendAmount(tx)

		if required > 0 {

			pendingSpendMu.Lock()

			// `pendingKey` stores the key used to access the related value.
			pendingKey := balanceKey(coin, tx.From)

			// `available` stores the value produced by this operation.
			available := getBalance(ledger, coin, tx.From) - PendingSpend[pendingKey]

			if available < required {

				pendingSpendMu.Unlock()

				RecordFakeTxAttempt(tx.From)

				return false, "insufficient balance"

			}

			PendingSpend[pendingKey] += required

			pendingSpendMu.Unlock()

		}

	}

	m.SeenTxIDs[tx.ID] = true

	m.Transactions = append(m.Transactions, tx)
	m.txByID[tx.ID] = struct{}{}
	m.txBySenderNonce[mempoolSenderNonceKey(tx.From, tx.Nonce)] = tx.ID
	m.pendingCountBySender[senderKey]++
	// `nextNonce` stores the value produced by this operation.
	nextNonce := tx.Nonce + 1
	if nextNonce > m.nextNonceBySender[senderKey] {
		m.nextNonceBySender[senderKey] = nextNonce
	}

	return true, ""

}

// NextNonce implements the next nonce helper.
func (m *Mempool) NextNonce(addr string, ledger Ledger) int {

	if addr == "" {

		return 1

	}

	m.mu.Lock()

	defer m.mu.Unlock()

	m.pruneExpiredLocked(time.Now().Unix())
	m.ensureIndexesLocked()
	// `senderKey` stores the key used to access the related value.
	senderKey := mempoolSenderKey(addr)

	// `expected` stores the value produced by this operation.
	expected := getNonce(ledger, addr) + 1

	// `cachedNext` stores the value produced by this operation.
	if cachedNext := m.nextNonceBySender[senderKey]; cachedNext > expected {
		expected = cachedNext
	}

	return expected

}

// computeDTLABIHash computes dtlabi hash.
func computeDTLABIHash(raw json.RawMessage) string {
	// `canonical` stores the value produced by this operation.
	canonical := canonicalDTLRawJSONMessageForHash(raw)
	if canonical == "" {
		return ""
	}
	// `sum` stores the value produced by this operation.
	sum := sha256.Sum256([]byte(canonical))
	return hex.EncodeToString(sum[:])
}

// deriveDTLReceiptMetadata implements the derive dtl receipt metadata helper.
func deriveDTLReceiptMetadata(tx Transaction, ledger *Ledger) (StateReceipt, bool) {
	// `receipt` stores the value produced by this operation.
	receipt := StateReceipt{}
	if tx.Type != TxDTL {
		return receipt, false
	}
	// `decoded` and `err` store the error produced by this operation.
	decoded, err := decodeDTLTransaction(tx)
	if err != nil {
		return receipt, false
	}
	if isDTLContractTxKind(decoded.Kind) {
		return receipt, false
	}
	receipt.DTLTxType = string(decoded.Kind)
	switch decoded.Kind {
	case DTLTxOracleFeedCreate:
		if decoded.OracleFeedCreate != nil {
			// `chainID` and `err` store the error produced by this operation.
			chainID, err := canonicalDTLTransactionChainID(tx)
			if err != nil {
				return receipt, false
			}
			receipt.OracleFeedID = normalizeDTLTokenID(dtlOracleFeedIDFromCreate(chainID, uint64(tx.Nonce), *decoded.OracleFeedCreate))
		}
	case DTLTxOraclePriceSubmit:
		if decoded.OraclePriceSubmit != nil {
			receipt.OracleFeedID = normalizeDTLTokenID(decoded.OraclePriceSubmit.FeedID)
		}
	case DTLTxLendMarketCreate:
		if decoded.LendMarketCreate != nil {
			receipt.OracleFeedID = normalizeDTLTokenID(decoded.LendMarketCreate.CollateralFeedID)
		}
	case DTLTxPoolSwapRoute:
		if decoded.PoolSwapRoute != nil {
			receipt.RouteHops = uint64(len(decoded.PoolSwapRoute.Path))
			receipt.RouteTokenIn = normalizeDTLTokenID(decoded.PoolSwapRoute.TokenIn)
			if ledger != nil && ledger.DTL != nil {
				// `currentToken` stores the value produced by this operation.
				currentToken := receipt.RouteTokenIn
				// `rawPoolID` tracks the current values while iterating.
				for _, rawPoolID := range decoded.PoolSwapRoute.Path {
					// `pool` stores the value produced by this operation.
					pool := ledger.DTL.Pools[normalizeDTLPoolID(rawPoolID)]
					if pool == nil {
						currentToken = ""
						break
					}
					switch currentToken {
					case pool.TokenA:
						currentToken = pool.TokenB
					case pool.TokenB:
						currentToken = pool.TokenA
					default:
						currentToken = ""
					}
					if currentToken == "" {
						break
					}
				}
				receipt.RouteTokenOut = currentToken
			}
		}
	}
	if ledger != nil && ledger.DTL != nil {
		// `computeHealth` stores the value produced by this operation.
		computeHealth := func(marketID, account string) {
			marketID = normalizeDTLMarketID(marketID)
			account = normalizeDTLAccount(account)
			if marketID == "" || account == "" {
				return
			}
			// `market` stores the value produced by this operation.
			market := ledger.DTL.LendingMarkets[marketID]
			if market == nil {
				return
			}
			// `position` stores the value produced by this operation.
			position := ledger.DTL.LendingPositions[dtlLendingPositionKey(marketID, account)]
			if position == nil {
				receipt.HealthFactor = DTLMaxTaxBPS
				if receipt.OracleFeedID == "" {
					receipt.OracleFeedID = normalizeDTLTokenID(market.CollateralFeedID)
				}
				return
			}
			// `hf` and `err` store the error produced by this operation.
			_, hf, err := dtlLendingHealthFactorBPS(ledger.DTL, market, position.Collateral, position.Debt, 0)
			if err == nil {
				receipt.HealthFactor = hf
			}
			if receipt.OracleFeedID == "" {
				receipt.OracleFeedID = normalizeDTLTokenID(market.CollateralFeedID)
			}
		}
		switch decoded.Kind {
		case DTLTxLendDeposit:
			if decoded.LendDeposit != nil {
				computeHealth(decoded.LendDeposit.MarketID, decoded.LendDeposit.Account)
			}
		case DTLTxLendBorrow:
			if decoded.LendBorrow != nil {
				computeHealth(decoded.LendBorrow.MarketID, decoded.LendBorrow.Account)
			}
		case DTLTxLendRepay:
			if decoded.LendRepay != nil {
				computeHealth(decoded.LendRepay.MarketID, decoded.LendRepay.Account)
			}
		case DTLTxLendWithdraw:
			if decoded.LendWithdraw != nil {
				computeHealth(decoded.LendWithdraw.MarketID, decoded.LendWithdraw.Account)
			}
		case DTLTxLendLiquidate:
			if decoded.LendLiquidate != nil {
				computeHealth(decoded.LendLiquidate.MarketID, decoded.LendLiquidate.Borrower)
			}
		}
	}
	return receipt, true
}

// buildReceiptDTLLogs builds receipt dtl logs.
func buildReceiptDTLLogs(ledger Ledger, startIndex int, txID string, txIndex int, blockHeight uint64) []DTLEventLog {
	if ledger.DTL == nil || startIndex >= len(ledger.DTL.EventLogs) {
		return nil
	}
	if startIndex < 0 {
		startIndex = 0
	}
	// `logs` stores the value produced by this operation.
	logs := make([]DTLEventLog, 0, len(ledger.DTL.EventLogs)-startIndex)
	// `i` stores the current position in the related collection.
	for i := startIndex; i < len(ledger.DTL.EventLogs); i++ {
		// `entry` stores the value produced by this operation.
		entry := ledger.DTL.EventLogs[i]
		entry.ContractID = normalizeDTLContractID(entry.ContractID)
		entry.Data = canonicalDTLRawJSONStringForState(entry.Data)
		entry.TxID = txID
		entry.TxIndex = txIndex
		entry.BlockHeight = blockHeight
		entry.LogIndex = len(logs)
		logs = append(logs, entry)
	}
	return logs
}

// ProduceWorkBlock implements the produce work block helper.
func (n *Node) ProduceWorkBlock(bc *Blockchain) Block {

	// =====================================================

	// =====================================================

	if err := EnforceTxBan(n.ValidatorKey.ID); err != nil {

		return Block{}

	}

	// =====================================================

	// =====================================================

	last := bc.LastBlock()

	// =====================================================

	// =====================================================

	n.Mempool.PruneExpired()

	// `txs` stores the transaction data handled by this operation.
	txs := append([]Transaction{}, n.Mempool.Transactions...)

	// `executionAuthorityLedger` stores the value produced by this operation.
	executionAuthorityLedger := n.currentExecutionLedgerClone()
	txs = selectTxBatch(txs, executionAuthorityLedger)

	// =====================================================

	// =====================================================

	candidateBlock := Block{ID: last.ID + 1, Transactions: txs}
	candidateResult := executeCandidateTransactions(BlockExecutionInput{
		Context:   newExecutionStateContext(executionAuthorityLedger),
		Block:     candidateBlock,
		Authority: n.prepareBlockExecutionAuthority(candidateBlock),
	})
	for _, rejected := range candidateResult.Rejected {
		RecordFakeTxAttempt(rejected.Transaction.From)
	}
	txs = candidateResult.Accepted
	receipts := candidateResult.Receipts

	// =====================================================

	// =====================================================

	validators := n.GetConsensusValidators(int(last.ID + 1))

	// `lt` stores the value produced by this operation.
	lt := LogicalTimeForEpoch(last.ID + 1)

	// `block` stores the synchronization state protecting shared data.
	block := Block{

		ID: last.ID + 1,

		Type: BlockTypeWork,

		Transactions: txs,

		Receipts: receipts,

		PrevHash: last.BlockHash,

		Proposer: n.ValidatorKey.ID,

		Signatures: validators,

		Timestamp: int64(SystemTimeUnits(lt)),

		BlockTime: lt,

		MempoolRoot: ComputeMempoolRoot(txs),
		ReceiptRoot: ComputeReceiptRoot(receipts),
	}

	// `activeSet` stores the value produced by this operation.
	activeSet := n.freezeValidatorSetForHeight(block.ID, validators)
	block.ValidatorSetHash = n.validatorSetHashFromFinalizedSnapshot(block.ID, activeSet)
	n.fillBlockNextValidatorSetCommitment(&block)

	// =====================================================

	// =====================================================

	block.BlockHash = HashBlock(block)

	// =====================================================

	// =====================================================

	n.SignBlock(&block)

	if DebugConsensus {

	}

	return block

}

