// recordSyncPeerInvalidProof implements the record sync peer invalid proof helper.
func (n *Node) recordSyncPeerInvalidProof(peerID string) {
	if n == nil || strings.TrimSpace(peerID) == "" {
		return
	}
	n.syncPeerScoreMu.Lock()
	if n.syncPeerScores == nil {
		n.syncPeerScores = make(map[string]*SyncPeerScore)
	}
	// `score` stores the value produced by this operation.
	score := n.syncPeerScores[peerID]
	if score == nil {
		score = &SyncPeerScore{}
		n.syncPeerScores[peerID] = score
	}
	score.InvalidProofCount++
	score.SnapshotFail++
	score.UpdatedAt = time.Now()
	n.syncPeerScoreMu.Unlock()

	// Snapshot proof failures should poison only snapshot-provider selection.
	// Disconnecting the peer here also removes it from consensus gossip and can
	// halt a small validator set when a stale/partial snapshot proof is seen.
	n.setSyncAvoidProviderOnce(peerID)
}

// syncActionSnapshot implements the sync action snapshot helper.
func (n *Node) syncActionSnapshot(localHeight, targetHeight uint64, syncing bool) (stage string, mode string, lag uint64, action string) {
	if n == nil {
		return "idle", "idle", 0, "up_to_date"
	}
	lag = syncLagBlocks(localHeight, targetHeight)
	n.syncMu.Lock()
	stage = normalizeSyncStage(n.syncStage)
	// `cachedStage` stores the value produced by this operation.
	cachedStage := stage
	mode = normalizeSyncMode(n.syncMode)
	action = strings.TrimSpace(n.syncAction)
	// `cachedLag` stores the value produced by this operation.
	cachedLag := n.syncLagBlocks
	n.syncMu.Unlock()
	if lag == 0 {
		lag = cachedLag
	}
	// `plan` stores the value produced by this operation.
	plan := syncCatchupPlanForLag(localHeight, targetHeight)
	// `session` stores the value produced by this operation.
	session := n.snapshotSessionSnapshot()
	if session.Active {
		stage = plan.Stage
		if !syncStageUsesSnapshotTransfer(stage) {
			stage = "snapshot_delta"
		}
		plan = syncCatchupPlanForStage(stage, localHeight, targetHeight)
		mode = plan.Mode
		if strings.TrimSpace(action) == "" || cachedStage != stage {
			action = syncSnapshotProgressAction(stage, "snapshot_fetch_verify")
		}
		if targetHeight == 0 && session.FreezeHeight > localHeight {
			targetHeight = session.FreezeHeight
			lag = syncLagBlocks(localHeight, targetHeight)
			plan = syncCatchupPlanForStage(stage, localHeight, targetHeight)
		}
	}
	if !syncing {
		if lag > 0 {
			if plan.Stage != "" {
				stage = plan.Stage
			}
			if plan.Mode != "" {
				mode = plan.Mode
			}
			if plan.Action != "" {
				action = plan.Action
			} else if action == "" {
				action = syncStageStatusAction(stage)
			}
			if action == "" {
				action = "catch_up"
			}
			return stage, mode, lag, action
		}
		if stage == "" {
			stage = "idle"
		}
		if mode == "" {
			mode = "idle"
		}
		if action == "" {
			action = "up_to_date"
		}
		return stage, mode, 0, action
	}
	if !session.Active && plan.Stage != "" && plan.Stage != "idle" {
		stage = plan.Stage
	} else if stage == "" {
		stage = plan.Stage
	}
	if plan.Mode != "" && (mode == "" || cachedStage != stage) {
		mode = plan.Mode
	} else if mode == "" {
		mode = syncModeForStage(stage)
	}
	if action == "" || cachedStage != stage {
		action = plan.Action
		if action == "" {
			action = "up_to_date"
		}
	}
	return stage, mode, lag, action
}

// shouldUseObservedSyncHeight implements the should use observed sync height helper.
func shouldUseObservedSyncHeight(observedVotes, required int) bool {
	if observedVotes <= 0 {
		return false
	}
	if required <= 1 {
		return true
	}
	// Only trust non-quorum "best observed" targets when they are quorum-backed.
	return observedVotes >= required
}

// shouldUseObservedLagCatchup implements the should use observed lag catchup helper.
func shouldUseObservedLagCatchup(localHeight uint64, observedHeight uint64, observedVotes int, required int) bool {
	if observedHeight <= localHeight || observedVotes <= 0 {
		return false
	}
	if required <= 1 {
		return true
	}
	// Catch-up may use one fewer vote than finality because fetched blocks are
	// still verified against strict committed quorum evidence before they apply.
	return observedVotes >= required-1
}

// selectSyncTargetHeight implements the select sync target height helper.
func selectSyncTargetHeight(
	localHeight uint64,
	quorumHeight uint64,
	quorumOK bool,
	observedHeight uint64,
	observedVotes int,
	required int,
) uint64 {
	// `target` stores the value produced by this operation.
	target := uint64(0)
	if quorumOK && quorumHeight > target {
		target = quorumHeight
	}
	if (!quorumOK || shouldUseObservedSyncHeight(observedVotes, required)) && observedHeight > target {
		target = observedHeight
	}
	if shouldUseObservedLagCatchup(localHeight, observedHeight, observedVotes, required) && observedHeight > target {
		target = observedHeight
	}
	if target <= localHeight {
		return 0
	}
	return target
}

// bestObservedValidatorSetHash implements the best observed validator set hash helper.
func (n *Node) bestObservedValidatorSetHash() (string, int, uint64, bool) {
	if n == nil {
		return "", 0, 0, false
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `maxAge` stores the value produced by this operation.
	maxAge := validatorLivenessHeartbeatTTL() + validatorLivenessGrace()
	// `counts` stores the measured quantity used by this operation.
	counts := make(map[string]int)
	// `bestFinalized` stores the value produced by this operation.
	bestFinalized := uint64(0)

	n.validatorMu.RLock()
	// `st` tracks the current values while iterating.
	for _, st := range n.validatorStatus {
		if st == nil {
			continue
		}
		if st.LastSeen.IsZero() {
			continue
		}
		// `age` stores the value produced by this operation.
		age := now.Sub(st.LastSeen)
		if age < 0 {
			age = 0
		}
		if age > maxAge {
			continue
		}
		// `hash` stores the digest used to identify or verify the related data.
		hash := strings.ToLower(strings.TrimSpace(st.ValidatorSetHash))
		if hash == "" {
			continue
		}
		counts[hash]++
		if st.FinalizedHeight > bestFinalized {
			bestFinalized = st.FinalizedHeight
		}
	}
	n.validatorMu.RUnlock()

	// `bestHash` stores the digest used to identify or verify the related data.
	bestHash := ""
	// `bestVotes` stores the value produced by this operation.
	bestVotes := 0
	// `hash` and `votes` track the digest used to identify or verify the related data.
	for hash, votes := range counts {
		if votes > bestVotes || (votes == bestVotes && (bestHash == "" || hash < bestHash)) {
			bestHash = hash
			bestVotes = votes
		}
	}
	// `peerHash`, `peerVotes`, `peerHeight`, and `peerOK` store whether the related condition is satisfied.
	peerHash, peerVotes, peerHeight, peerOK := n.bestObservedValidatorSetHashFromPeerState()
	if peerOK {
		if bestHash == "" || bestVotes == 0 || peerVotes > bestVotes {
			return peerHash, peerVotes, peerHeight, true
		}
		if strings.EqualFold(peerHash, bestHash) && peerHeight > bestFinalized {
			bestFinalized = peerHeight
		}
	}
	if bestHash == "" || bestVotes == 0 {
		return "", 0, bestFinalized, false
	}
	return bestHash, bestVotes, bestFinalized, true
}

// bestObservedValidatorSetHashFromPeerState implements the best observed validator set hash from peer state helper.
func (n *Node) bestObservedValidatorSetHashFromPeerState() (string, int, uint64, bool) {
	if n == nil {
		return "", 0, 0, false
	}
	type peerSample struct {
		// `hash` stores the digest used to identify or verify the related data.
		hash string
		// `height` stores the value associated with this record.
		height uint64
	}

	// `samples` stores the value produced by this operation.
	samples := make([]peerSample, 0)
	n.peerStateMu.Lock()
	// `peerID` and `role` track the current values while iterating.
	for peerID, role := range n.peerRole {
		if normalizeNodeRole(role) != "validator" {
			continue
		}
		if !n.peerHelloOK[peerID] {
			continue
		}
		if strings.TrimSpace(n.peerToValidator[peerID]) == "" {
			continue
		}
		// `hash` stores the digest used to identify or verify the related data.
		hash := strings.ToLower(strings.TrimSpace(n.peerSetHash[peerID]))
		if hash == "" {
			continue
		}
		// `height` stores the value produced by this operation.
		height := n.peerAckHeight[peerID]
		samples = append(samples, peerSample{hash: hash, height: height})
	}
	n.peerStateMu.Unlock()

	if len(samples) == 0 {
		return "", 0, 0, false
	}

	// `counts` stores the measured quantity used by this operation.
	counts := make(map[string]int)
	// `bestHeight` stores the value produced by this operation.
	bestHeight := uint64(0)
	// `sample` tracks the current values while iterating.
	for _, sample := range samples {
		counts[sample.hash]++
		if sample.height > bestHeight {
			bestHeight = sample.height
		}
	}

	// `bestHash` stores the digest used to identify or verify the related data.
	bestHash := ""
	// `bestVotes` stores the value produced by this operation.
	bestVotes := 0
	// `hash` and `votes` track the digest used to identify or verify the related data.
	for hash, votes := range counts {
		if votes > bestVotes || (votes == bestVotes && (bestHash == "" || hash < bestHash)) {
			bestHash = hash
			bestVotes = votes
		}
	}
	if bestHash == "" || bestVotes == 0 {
		return "", 0, bestHeight, false
	}
	return bestHash, bestVotes, bestHeight, true
}

// startupRemoteObservedValidatorSetHash implements the startup remote observed validator set hash helper.
func (n *Node) startupRemoteObservedValidatorSetHash() (string, int, uint64, bool) {
	if n == nil {
		return "", 0, 0, false
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `maxAge` stores the value produced by this operation.
	maxAge := validatorLivenessHeartbeatTTL() + validatorLivenessGrace()
	// `selfID` stores the local consensus identity to exclude from remote observations.
	selfID := n.localConsensusValidatorID()
	// `counts` stores the measured quantity used by this operation.
	counts := make(map[string]int)
	// `bestFinalized` stores the value produced by this operation.
	bestFinalized := uint64(0)

	n.validatorMu.RLock()
	// `id` and `st` track the current position in the related collection.
	for id, st := range n.validatorStatus {
		if st == nil {
			continue
		}
		if normalizeValidatorID(id) == selfID {
			continue
		}
		if st.LastSeen.IsZero() {
			continue
		}
		// `age` stores the value produced by this operation.
		age := now.Sub(st.LastSeen)
		if age < 0 {
			age = 0
		}
		if age > maxAge {
			continue
		}
		// `hash` stores the digest used to identify or verify the related data.
		hash := strings.ToLower(strings.TrimSpace(st.ValidatorSetHash))
		if hash == "" {
			continue
		}
		counts[hash]++
		if st.FinalizedHeight > bestFinalized {
			bestFinalized = st.FinalizedHeight
		}
	}
	n.validatorMu.RUnlock()

	// `bestHash` stores the digest used to identify or verify the related data.
	bestHash := ""
	// `bestVotes` stores the value produced by this operation.
	bestVotes := 0
	// `hash` and `votes` track the digest used to identify or verify the related data.
	for hash, votes := range counts {
		if votes > bestVotes || (votes == bestVotes && (bestHash == "" || hash < bestHash)) {
			bestHash = hash
			bestVotes = votes
		}
	}
	// `peerHash`, `peerVotes`, `peerHeight`, and `peerOK` store whether the related condition is satisfied.
	peerHash, peerVotes, peerHeight, peerOK := n.bestObservedValidatorSetHashFromPeerState()
	if peerOK {
		if bestHash == "" || bestVotes == 0 || peerVotes > bestVotes {
			return peerHash, peerVotes, peerHeight, true
		}
		if strings.EqualFold(peerHash, bestHash) && peerHeight > bestFinalized {
			bestFinalized = peerHeight
		}
	}
	if bestHash == "" || bestVotes == 0 {
		return "", 0, bestFinalized, false
	}
	return bestHash, bestVotes, bestFinalized, true
}

// startupNetworkValidatorSetSampleStatus implements the startup network validator set sample status helper.
func (n *Node) startupNetworkValidatorSetSampleStatus(localHeight uint64) (bool, string, uint64, int, string) {
	if n == nil {
		return false, "node_unavailable", 0, 0, ""
	}
	if n.Host == nil {
		// Runtime status and isolated unit tests may evaluate startup readiness
		// before a transport exists. Avoid a permanent false negative there.
		return true, "network_transport_unavailable", localHeight, 0, ""
	}
	// `checkHeight` stores the value produced by this operation.
	checkHeight := localHeight + 1
	if checkHeight == 0 {
		checkHeight = 1
	}
	// `active` and `reason` store the value produced by this operation.
	if active, reason := n.selfActiveValidatorAt(checkHeight); !active {
		if strings.EqualFold(strings.TrimSpace(reason), "activation_pending_not_in_frozen_set") {
			// `networkHeight` stores the value produced by this operation.
			networkHeight := uint64(0)
			// `quorumHeight` and `ok` store whether the related condition is satisfied.
			if quorumHeight, _, _, ok := n.startupRemoteHeartbeatHeight(); ok && quorumHeight > networkHeight {
				networkHeight = quorumHeight
			}
			// `observedHeight` and `observedVotes` store the value produced by this operation.
			if observedHeight, observedVotes := n.startupRemoteObservedSyncHeight(); observedVotes > 0 && observedHeight > networkHeight {
				networkHeight = observedHeight
			}
			return true, "network_validator_set_sample_not_required_inactive_candidate", networkHeight, 0, ""
		}
	}
	// `ok` and `hash` store whether the related condition is satisfied.
	if ok, hash := n.startupCommittedTipNetworkSampleReady(localHeight, checkHeight); ok {
		return true, "steady_state_committed_tip", localHeight, 0, hash
	}
	// `requiredVotes` stores the request data being processed.
	requiredVotes := n.startupNetworkSampleRequiredVotes(localHeight)
	if requiredVotes <= 0 {
		requiredVotes = 1
	}

	// `networkHeight` stores the value produced by this operation.
	networkHeight := uint64(0)
	// `quorumHeight` and `ok` store whether the related condition is satisfied.
	if quorumHeight, _, _, ok := n.startupRemoteHeartbeatHeight(); ok && quorumHeight > networkHeight {
		networkHeight = quorumHeight
	}
	// `observedHeight` and `observedVotes` store the value produced by this operation.
	if observedHeight, observedVotes := n.startupRemoteObservedSyncHeight(); shouldUseObservedSyncHeight(observedVotes, requiredVotes) && observedHeight > networkHeight {
		networkHeight = observedHeight
	}

	// `networkHash`, `votes`, `hashHeight`, and `ok` store whether the related condition is satisfied.
	networkHash, votes, hashHeight, ok := n.startupRemoteObservedValidatorSetHash()
	if votes >= requiredVotes && hashHeight > networkHeight {
		networkHeight = hashHeight
	}

	if networkHeight == 0 && localHeight == 0 {
		return true, "genesis_bootstrap", 0, 0, ""
	}
	if !ok || votes < requiredVotes || strings.TrimSpace(networkHash) == "" {
		return false, "waiting_network_validator_set_sample", networkHeight, votes, ""
	}
	return true, "network_validator_set_sample", networkHeight, votes, strings.ToLower(strings.TrimSpace(networkHash))
}

// startupCommittedTipNetworkSampleReady implements the startup committed tip network sample ready helper.
func (n *Node) startupCommittedTipNetworkSampleReady(localHeight uint64, checkHeight uint64) (bool, string) {
	if n == nil || localHeight == 0 || checkHeight == 0 {
		return false, ""
	}
	n.commitMu.Lock()
	// `committedHeight` stores the value produced by this operation.
	committedHeight := n.committedHeight
	if n.finalizedHeight > committedHeight {
		committedHeight = n.finalizedHeight
	}
	n.commitMu.Unlock()
	if committedHeight == 0 || committedHeight < localHeight {
		return false, ""
	}
	// `active` stores the value produced by this operation.
	if active, _ := n.selfActiveValidatorAt(checkHeight); !active {
		return false, ""
	}
	// `expected` and `expectedSource` store the value produced by this operation.
	expected, expectedSource := n.expectedValidatorSetHashWithSource(checkHeight)
	expected = strings.ToLower(strings.TrimSpace(expected))
	if expected == "" || !startupNetworkSampleSourceRequiresQuorum(expectedSource) {
		return false, ""
	}
	// `localHash`, `localSource`, and `ok` store whether the related condition is satisfied.
	_, localHash, localSource, ok := n.startupResolvedValidatorSetHash(checkHeight)
	localHash = strings.ToLower(strings.TrimSpace(localHash))
	if !ok || localHash == "" || !strings.EqualFold(expected, localHash) {
		return false, ""
	}
	if !startupNetworkSampleSourceRequiresQuorum(localSource) && !validatorSetSourceIsChainAuthoritative(localSource) {
		return false, ""
	}
	return true, expected
}

// startupNetworkSampleRequiredVotes implements the startup network sample required votes helper.
func (n *Node) startupNetworkSampleRequiredVotes(localHeight uint64) int {
	if n == nil {
		return 1
	}
	// `height` stores the value produced by this operation.
	height := localHeight + 1
	if height == 0 {
		height = 1
	}
	// `validators` stores whether the related condition is satisfied.
	validators := []string(nil)
	// `source` stores the value produced by this operation.
	source := "none"
	// `committed`, `committedSource`, and `ok` store whether the related condition is satisfied.
	if committed, committedSource, ok := n.chainDerivedValidatorAuthorityForHeight(height); ok {
		validators = committed
		source = committedSource
	}
	if len(validators) == 0 || !startupNetworkSampleSourceRequiresQuorum(source) {
		return 1
	}
	if len(validators) > 0 {
		// `required` stores the request data being processed.
		required := n.executionQuorumPolicy(height).Required
		if required <= 0 {
			required = execQuorumRequired(len(validators))
		}
		if required > 0 {
			// `selfID` stores the local consensus identity selected from the sampled validators.
			selfID := n.localConsensusValidatorIDForSet(validators)
			if required > 1 && selfID != "" && containsNormalizedValidatorID(validators, selfID) {
				required--
			}
			if required < 1 {
				required = 1
			}
			return required
		}
	}
	return 1
}

// startupNetworkSampleSourceRequiresQuorum implements the startup network sample source requires quorum helper.
func startupNetworkSampleSourceRequiresQuorum(source string) bool {
	switch normalizeCommittedValidatorAuthoritySource(source) {
	case "snapshot_committed", "tip_snapshot_repair", "trusted_snapshot", "chain_parent_commitment", "registry_verified", "genesis_bootstrap":
		return true
	default:
		return false
	}
}

// startupNetworkValidatorSetPrecheck implements the startup network validator set precheck helper.
func (n *Node) startupNetworkValidatorSetPrecheck() bool {
	if n == nil {
		return false
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := n.Blockchain.Height()
	// `sampleReady`, `networkHeight`, `votes`, and `networkHash` store the digest used to identify or verify the related data.
	sampleReady, _, networkHeight, votes, networkHash := n.startupNetworkValidatorSetSampleStatus(localHeight)
	if !sampleReady || networkHeight <= localHeight {
		return false
	}

	// `expectedHeight` stores the value produced by this operation.
	expectedHeight := localHeight + 1
	// `expectedHash` stores the digest used to identify or verify the related data.
	expectedHash := strings.ToLower(strings.TrimSpace(n.expectedValidatorSetHash(expectedHeight)))
	if expectedHash == "" || strings.EqualFold(expectedHash, networkHash) {
		return false
	}

	n.setValidatorStartupCheckStatus(false, expectedHeight, expectedHash, networkHash, "startup_network_validator_set_mismatch")
	if DebugConsensus {
		fmt.Printf("[STARTUP-PRECHECK] local=%d network=%d expected=%s observed=%s votes=%d action=force_snapshot\n",
			localHeight, networkHeight, ShortHash(expectedHash), ShortHash(networkHash), votes)
	}
	// `target` stores the value produced by this operation.
	target := networkHeight
	if target <= localHeight {
		target = expectedHeight
	}
	n.forceSnapshotResyncNow(target, "startup-validator-set-hash-mismatch-precheck")
	return true
}

// syncReadyForConsensus implements the sync ready for consensus helper.
func (n *Node) syncReadyForConsensus(height uint64) (bool, string) {
	if n == nil {
		return false, "node_unavailable"
	}
	// `ok` and `reason` store whether the related condition is satisfied.
	if ok, reason := n.startupValidatorSetSelfCheck(); !ok {
		return false, reason
	}
	// `isolated` and `reason` store the current position in the related collection.
	if isolated, reason := n.validatorSyncIsolationState(height); isolated {
		return false, reason
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := n.consensusSyncReferenceHeight()
	// `blocked` and `reason` store the block data handled by this operation.
	if blocked, reason, _ := n.consensusSyncGateForHeight(height); blocked {
		if reason == "" {
			reason = "sync_in_progress"
		}
		return false, reason
	}
	// `sampleReady` and `networkHeight` store the value produced by this operation.
	if sampleReady, _, networkHeight, _, _ := n.startupNetworkValidatorSetSampleStatus(localHeight); sampleReady {
		if networkHeight > 0 && !n.consensusSyncTargetReached(localHeight, networkHeight) {
			return false, fmt.Sprintf("lagging_local_%d_target_%d", localHeight, networkHeight)
		}
	}
	if n.Host != nil && len(n.Host.Network().Peers()) > 0 {
		// `quorumHeight`, `quorumRequired`, and `quorumOK` store whether the related condition is satisfied.
		quorumHeight, _, quorumRequired, quorumOK := n.majorityHeartbeatHeight()
		// `observedHeight` and `observedVotes` store the value produced by this operation.
		observedHeight, observedVotes := n.bestObservedSyncHeight()
		// `target` stores the value produced by this operation.
		target := selectSyncTargetHeight(localHeight, quorumHeight, quorumOK, observedHeight, observedVotes, quorumRequired)
		if target > 0 && !n.consensusSyncTargetReached(localHeight, target) {
			return false, fmt.Sprintf("lagging_local_%d_target_%d", localHeight, target)
		}
	}

	if height == 0 {
		height = n.currentEpoch()
	}
	if height > 0 {
		// `expected` stores the value produced by this operation.
		expected := strings.TrimSpace(n.expectedValidatorSetHash(height))
		if expected == "" {
			return false, "validator_set_unresolved"
		}
		// `validators` and `ok` store whether the related condition is satisfied.
		if validators, _, ok := n.deterministicCommitteeValidatorsForHeight(height); !ok || len(validators) == 0 {
			return false, "validator_set_unresolved"
		}
	}
	return true, "ready"
}

// canEnforceConsensusPenalty implements the can enforce consensus penalty helper.
func (n *Node) canEnforceConsensusPenalty(height uint64) (bool, string) {
	// `isolated` and `reason` store the current position in the related collection.
	if isolated, reason := n.validatorSyncIsolationState(height); isolated {
		return false, reason
	}
	// `mode` stores the value produced by this operation.
	mode := normalizeConsensusPenaltyEnforceMode(ConsensusPenaltyEnforceMode)
	if mode != "converged_only" {
		return true, "always"
	}
	if n == nil {
		return false, "node_unavailable"
	}
	if n.consensusRecomputePauseActive() {
		return false, "recompute_pause_active"
	}
	// `ready` and `reason` store the value produced by this operation.
	if ready, reason := n.syncReadyForConsensus(height); !ready {
		return false, reason
	}
	if height == 0 {
		height = n.currentEpoch()
	}
	// `expected` stores the value produced by this operation.
	expected := strings.TrimSpace(n.expectedValidatorSetHash(height))
	if expected == "" {
		return false, "validator_set_unresolved"
	}
	// `frozenHash` and `ok` store whether the related condition is satisfied.
	frozenHash, ok := n.frozenValidatorSetHash(height)
	if !ok || strings.TrimSpace(frozenHash) == "" {
		return false, "validator_set_not_frozen"
	}
	if !strings.EqualFold(expected, frozenHash) {
		return false, "validator_set_not_converged"
	}
	return true, "converged"
}

// consensusRecomputePauseDuration implements the consensus recompute pause duration helper.
func consensusRecomputePauseDuration() time.Duration {
	if ConsensusRecomputePause <= 0 {
		return 4 * time.Second
	}
	return ConsensusRecomputePause
}

// consensusRecomputePauseDurationFor implements the consensus recompute pause duration for helper.
func consensusRecomputePauseDurationFor(reason string) time.Duration {
	// `pause` stores the value produced by this operation.
	pause := consensusRecomputePauseDuration()
	reason = strings.ToLower(strings.TrimSpace(reason))
	if reason == "" {
		return pause
	}
	if strings.Contains(reason, "validator_set_hash_mismatch") ||
		strings.Contains(reason, "validator_set_repair") ||
		strings.Contains(reason, "validator-set-hash-mismatch") ||
		strings.Contains(reason, "peer-validator-set-mismatch") {
		// `override` stores the value produced by this operation.
		if override := validatorSetAutohealPauseDuration(); override > 0 {
			return override
		}
	}
	return pause
}

// consensusRecomputePauseReasonBlocksConsensus implements the consensus recompute pause reason blocks consensus helper.
func consensusRecomputePauseReasonBlocksConsensus(reason string) bool {
	reason = strings.ToLower(strings.TrimSpace(reason))
	if reason == "" {
		return true
	}
	// Liveness shortfall is an observation, not a validator-set mutation. Do not
	// suppress verified proposal votes while the network is trying to recover
	// quorum; finality still requires the normal strict vote threshold.
	if strings.Contains(reason, "live_quorum_unavailable") {
		return false
	}
	return true
}

// doubleProposalEvidenceKey implements the double proposal evidence key helper.
func doubleProposalEvidenceKey(height uint64, round uint32, proposer, prevHash, gotHash string) string {
	proposer = normalizeValidatorID(proposer)
	if proposer == "" || height == 0 {
		return ""
	}
	prevHash = strings.ToLower(strings.TrimSpace(prevHash))
	gotHash = strings.ToLower(strings.TrimSpace(gotHash))
	if prevHash == "" {
		prevHash = "unknown"
	}
	if gotHash == "" {
		gotHash = "unknown"
	}
	return fmt.Sprintf("%d|%d|%s|%s|%s", height, round, proposer, prevHash, gotHash)
}

// shouldCountDoubleProposalEvidence implements the should count double proposal evidence helper.
func (n *Node) shouldCountDoubleProposalEvidence(height uint64, round uint32, proposer, prevHash, gotHash string) bool {
	if n == nil || height == 0 {
		return true
	}
	// `key` stores the key used to access the related value.
	key := doubleProposalEvidenceKey(height, round, proposer, prevHash, gotHash)
	if key == "" {
		return true
	}

	// `now` stores the value produced by this operation.
	now := time.Now()
	// `ttl` stores the value produced by this operation.
	ttl := invalidProposerStrikeWindow
	if ttl <= 0 {
		ttl = 3 * time.Minute
	}
	// `cutoff` stores the value produced by this operation.
	cutoff := now.Add(-ttl)

	n.doubleProposalMu.Lock()

	if n.doubleProposalEvidenceSeen == nil {
		n.doubleProposalEvidenceSeen = make(map[string]time.Time)
	}
	// `evidenceKey` and `seenAt` track the key used to access the related value.
	for evidenceKey, seenAt := range n.doubleProposalEvidenceSeen {
		if seenAt.Before(cutoff) {
			delete(n.doubleProposalEvidenceSeen, evidenceKey)
		}
	}
	// `seenAt` and `ok` store whether the related condition is satisfied.
	if seenAt, ok := n.doubleProposalEvidenceSeen[key]; ok && !seenAt.Before(cutoff) {
		n.doubleProposalMu.Unlock()
		return false
	}
	n.doubleProposalEvidenceSeen[key] = now
	n.doubleProposalMu.Unlock()

	n.persistConsensusEvidenceRecord(consensusEvidenceRecord{
		Type:       "double_proposal",
		Key:        key,
		Height:     height,
		Round:      round,
		Validator:  normalizeValidatorID(proposer),
		PrevHash:   strings.ToLower(strings.TrimSpace(prevHash)),
		BlockHash:  strings.ToLower(strings.TrimSpace(gotHash)),
		SeenAtUnix: now.Unix(),
	})
	return true
}

// invalidProposerEvidenceKey implements the invalid proposer evidence key helper.
func invalidProposerEvidenceKey(height uint64, round uint32, expected, got, blockHash string) string {
	expected = normalizeValidatorID(expected)
	got = normalizeValidatorID(got)
	blockHash = strings.ToLower(strings.TrimSpace(blockHash))
	if blockHash == "" {
		blockHash = "unknown"
	}
	return fmt.Sprintf("%d|%d|%s|%s|%s", height, round, expected, got, blockHash)
}

// shouldCountInvalidProposerEvidence implements the should count invalid proposer evidence helper.
func (n *Node) shouldCountInvalidProposerEvidence(height uint64, round uint32, expected, got, blockHash string) bool {
	if n == nil || height == 0 {
		return true
	}
	// `key` stores the key used to access the related value.
	key := invalidProposerEvidenceKey(height, round, expected, got, blockHash)
	if key == "" {
		return true
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `ttl` stores the value produced by this operation.
	ttl := invalidProposerStrikeWindow
	if ttl <= 0 {
		ttl = 3 * time.Minute
	}
	// `cutoff` stores the value produced by this operation.
	cutoff := now.Add(-ttl)

	n.invalidProposerMu.Lock()

	if n.invalidProposerEvidenceSeen == nil {
		n.invalidProposerEvidenceSeen = make(map[string]time.Time)
	}
	// `evidenceKey` and `seenAt` track the key used to access the related value.
	for evidenceKey, seenAt := range n.invalidProposerEvidenceSeen {
		if seenAt.Before(cutoff) {
			delete(n.invalidProposerEvidenceSeen, evidenceKey)
		}
	}
	// `seenAt` and `ok` store whether the related condition is satisfied.
	if seenAt, ok := n.invalidProposerEvidenceSeen[key]; ok && !seenAt.Before(cutoff) {
		n.invalidProposerMu.Unlock()
		return false
	}
	n.invalidProposerEvidenceSeen[key] = now
	n.invalidProposerMu.Unlock()

	n.persistConsensusEvidenceRecord(consensusEvidenceRecord{
		Type:       "invalid_proposer",
		Key:        key,
		Height:     height,
		Round:      round,
		Expected:   normalizeValidatorID(expected),
		Got:        normalizeValidatorID(got),
		BlockHash:  strings.ToLower(strings.TrimSpace(blockHash)),
		SeenAtUnix: now.Unix(),
	})
	return true
}

// invalidProposerEvent implements the invalid proposer event helper.
func (n *Node) invalidProposerEvent(height uint64, expected, got string) (count int, shouldPause bool) {
	if n == nil || height == 0 {
		return 1, true
	}
	expected = normalizeValidatorID(expected)
	got = normalizeValidatorID(got)
	// `key` stores the key used to access the related value.
	key := expected + "->" + got
	if key == "->" {
		key = "unknown"
	}

	n.invalidProposerMu.Lock()
	defer n.invalidProposerMu.Unlock()

	if n.invalidProposerSeen == nil {
		n.invalidProposerSeen = make(map[uint64]map[string]int)
	}
	// Keep recent heights only; this cache is for log/pause dedupe.
	for h := range n.invalidProposerSeen {
		if h+8 < height {
			delete(n.invalidProposerSeen, h)
		}
	}
	// `perHeight` stores the value produced by this operation.
	perHeight := n.invalidProposerSeen[height]
	if perHeight == nil {
		perHeight = make(map[string]int)
		n.invalidProposerSeen[height] = perHeight
	}
	perHeight[key]++
	count = perHeight[key]
	// First mismatch at this height/pair gets recompute pause.
	// Repeats are ignored to prevent pause-loop spam.
	shouldPause = count == 1
	return count, shouldPause
}

// invalidProposerStrikeKey implements the invalid proposer strike key helper.
func invalidProposerStrikeKey(proposer, expected, got string) string {
	proposer = normalizeValidatorID(proposer)
	expected = normalizeValidatorID(expected)
	got = normalizeValidatorID(got)
	return proposer + "|" + expected + "|" + got
}

// decayInvalidProposerStrikeCount implements the decay invalid proposer strike count helper.
func decayInvalidProposerStrikeCount(count int, lastAt time.Time, now time.Time) int {
	if count <= 0 || lastAt.IsZero() {
		return 0
	}
	if now.IsZero() {
		now = time.Now()
	}
	if now.Before(lastAt) {
		return count
	}
	// `decayEvery` stores the value produced by this operation.
	decayEvery := invalidProposerStrikeDecayEvery
	if decayEvery <= 0 {
		decayEvery = time.Hour
	}
	// `decay` stores the value produced by this operation.
	decay := int(now.Sub(lastAt) / decayEvery)
	if decay <= 0 {
		return count
	}
	count -= decay
	if count < 0 {
		return 0
	}
	return count
}

// invalidProposerStrikeTrackerExpired implements the invalid proposer strike tracker expired helper.
func invalidProposerStrikeTrackerExpired(tracker ExecMismatchTracker, now time.Time) bool {
	return decayInvalidProposerStrikeCount(tracker.Count, tracker.LastAt, now) <= 0
}

// recordInvalidProposerStrike implements the record invalid proposer strike helper.
func (n *Node) recordInvalidProposerStrike(proposer string, height uint64, expected string, got string) int {
	// `key` stores the key used to access the related value.
	key := invalidProposerStrikeKey(proposer, expected, got)
	if n == nil || key == "||" || height == 0 {
		return 0
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	n.invalidProposerMu.Lock()
	defer n.invalidProposerMu.Unlock()
	if n.invalidProposerStrikes == nil {
		n.invalidProposerStrikes = make(map[string]ExecMismatchTracker)
	}
	// `tracker` stores the value produced by this operation.
	tracker := n.invalidProposerStrikes[key]
	tracker.Count = decayInvalidProposerStrikeCount(tracker.Count, tracker.LastAt, now)
	tracker.Count++
	tracker.LastEpoch = height
	tracker.LastAt = now
	n.invalidProposerStrikes[key] = tracker
	if len(n.invalidProposerStrikes) > ExecMismatchTrackMax {
		// `id` and `st` track the current position in the related collection.
		for id, st := range n.invalidProposerStrikes {
			if invalidProposerStrikeTrackerExpired(st, now) {
				delete(n.invalidProposerStrikes, id)
			}
		}
	}
	return tracker.Count
}

// recordInvalidProposerPeerStrike implements the record invalid proposer peer strike helper.
func (n *Node) recordInvalidProposerPeerStrike(peerID string, height uint64, expected string, got string) int {
	peerID = strings.TrimSpace(peerID)
	if n == nil || peerID == "" || height == 0 {
		return 0
	}
	// `tuple` stores the value produced by this operation.
	tuple := invalidProposerStrikeKey(got, expected, got)
	// `now` stores the value produced by this operation.
	now := time.Now()
	n.invalidProposerMu.Lock()
	defer n.invalidProposerMu.Unlock()
	if n.invalidProposerPeerStrikes == nil {
		n.invalidProposerPeerStrikes = make(map[string]ExecMismatchTracker)
	}
	// `tracker` stores the value produced by this operation.
	tracker := n.invalidProposerPeerStrikes[peerID+"|"+tuple]
	tracker.Count = decayInvalidProposerStrikeCount(tracker.Count, tracker.LastAt, now)
	tracker.Count++
	tracker.LastEpoch = height
	tracker.LastAt = now
	n.invalidProposerPeerStrikes[peerID+"|"+tuple] = tracker
	if len(n.invalidProposerPeerStrikes) > ExecMismatchTrackMax {
		// `id` and `st` track the current position in the related collection.
		for id, st := range n.invalidProposerPeerStrikes {
			if invalidProposerStrikeTrackerExpired(st, now) {
				delete(n.invalidProposerPeerStrikes, id)
			}
		}
	}
	return tracker.Count
}

// `transitionBarrierPauseDedupeCooldown` defines the constant value used by this package.
const transitionBarrierPauseDedupeCooldown = 25 * time.Second

// transitionBarrierPauseTupleKey implements the transition barrier pause tuple key helper.
func transitionBarrierPauseTupleKey(reason string, updateHeight uint64, nextSetHash string, matches, reports, required int) string {
	reason = strings.TrimSpace(strings.ToLower(reason))
	nextSetHash = strings.TrimSpace(strings.ToLower(nextSetHash))
	return fmt.Sprintf("%s|%d|%s|%d|%d|%d", reason, updateHeight, nextSetHash, matches, reports, required)
}

// shouldRequestTransitionBarrierPause implements the should request transition barrier pause helper.
func (n *Node) shouldRequestTransitionBarrierPause(reason string, updateHeight uint64, nextSetHash string, matches, reports, required int) bool {
	if n == nil {
		return true
	}
	// `cooldown` stores the value produced by this operation.
	cooldown := transitionBarrierPauseDedupeCooldown
	if cooldown <= 0 {
		return true
	}
	// `key` stores the key used to access the related value.
	key := transitionBarrierPauseTupleKey(reason, updateHeight, nextSetHash, matches, reports, required)
	// `now` stores the value produced by this operation.
	now := time.Now()

	n.transitionBarrierPauseMu.Lock()
	defer n.transitionBarrierPauseMu.Unlock()
	if n.transitionBarrierPauseLast == nil {
		n.transitionBarrierPauseLast = make(map[string]time.Time)
	}
	// `last` and `ok` store whether the related condition is satisfied.
	if last, ok := n.transitionBarrierPauseLast[key]; ok && now.Sub(last) < cooldown {
		return false
	}
	// `pruneBefore` stores the value produced by this operation.
	pruneBefore := now.Add(-4 * cooldown)
	// `tupleKey` and `seenAt` track the key used to access the related value.
	for tupleKey, seenAt := range n.transitionBarrierPauseLast {
		if seenAt.Before(pruneBefore) {
			delete(n.transitionBarrierPauseLast, tupleKey)
		}
	}
	n.transitionBarrierPauseLast[key] = now
	return true
}

// transitionBarrierRetryStateKey implements the transition barrier retry state key helper.
func transitionBarrierRetryStateKey(reason string, updateHeight uint64, nextSetHash string) transitionBarrierRetryKey {
	return transitionBarrierRetryKey{
		Reason:       strings.TrimSpace(strings.ToLower(reason)),
		UpdateHeight: updateHeight,
		NextSetHash:  strings.TrimSpace(strings.ToLower(nextSetHash)),
	}
}

// transitionBarrierFailureTuple implements the transition barrier failure tuple helper.
func transitionBarrierFailureTuple(matches, reports, required int) string {
	return fmt.Sprintf("%d|%d|%d", matches, reports, required)
}

// transitionBarrierCheckpointInterval implements the transition barrier checkpoint interval helper.
func transitionBarrierCheckpointInterval() uint64 {
	// `interval` stores the value currently being processed.
	interval := SyncCheckpointIntervalBlocks
	if interval == 0 {
		interval = 32
	}
	return interval
}

// transitionBarrierNextCheckpointAtOrAfter implements the transition barrier next checkpoint at or after helper.
func transitionBarrierNextCheckpointAtOrAfter(height uint64) uint64 {
	return alignHeightToCheckpointBoundary(height, transitionBarrierCheckpointInterval())
}

// nextTransitionBarrierRetryHeight implements the next transition barrier retry height helper.
func nextTransitionBarrierRetryHeight(currentHeight uint64) uint64 {
	// `delay` stores the value produced by this operation.
	delay := validatorSetActivationDelayBlocks()
	if delay == 0 {
		delay = 1
	}
	// `maxU64` stores the value produced by this operation.
	maxU64 := ^uint64(0)
	if currentHeight > maxU64-delay {
		return maxU64
	}
	return currentHeight + delay
}

// shouldAttemptTransitionBarrierRetry implements the should attempt transition barrier retry helper.
func (n *Node) shouldAttemptTransitionBarrierRetry(
	reason string,
	updateHeight uint64,
	currentHeight uint64,
	nextSetHash string,
	matches int,
	reports int,
	required int,
) (bool, bool, uint64) {
	if n == nil {
		return true, true, currentHeight
	}
	if currentHeight == 0 {
		currentHeight = updateHeight
	}
	// `key` stores the key used to access the related value.
	key := transitionBarrierRetryStateKey(reason, updateHeight, nextSetHash)
	// `tuple` stores the value produced by this operation.
	tuple := transitionBarrierFailureTuple(matches, reports, required)
	// `now` stores the value produced by this operation.
	now := time.Now()

	n.transitionBarrierRetryMu.Lock()
	defer n.transitionBarrierRetryMu.Unlock()
	if n.transitionBarrierRetryStateByKey == nil {
		n.transitionBarrierRetryStateByKey = make(map[transitionBarrierRetryKey]transitionBarrierRetryState)
	}

	// `state` and `ok` store whether the related condition is satisfied.
	state, ok := n.transitionBarrierRetryStateByKey[key]
	// `mode` stores the value produced by this operation.
	mode := normalizeTransitionBarrierRetryMode(TransitionBarrierRetryMode)
	if mode == transitionBarrierRetryModePerBlock {
		// Deterministic retry points:
		// - first attempt at the scheduled update height
		// - subsequent attempts only at checkpoint boundaries.
		nextRetry := transitionBarrierNextCheckpointAtOrAfter(updateHeight)
		if !ok {
			state = transitionBarrierRetryState{
				NextRetryHeight: nextRetry,
				LastFailTuple:   tuple,
				LastUpdatedAt:   now,
			}
			n.transitionBarrierRetryStateByKey[key] = state
		}
		// `tupleChanged` stores the value produced by this operation.
		tupleChanged := state.LastFailTuple != tuple
		if tupleChanged {
			state.LastFailTuple = tuple
		}
		if state.NextRetryHeight == 0 {
			state.NextRetryHeight = nextRetry
		}
		if currentHeight < state.NextRetryHeight {
			state.LastUpdatedAt = now
			n.transitionBarrierRetryStateByKey[key] = state
			return false, tupleChanged, state.NextRetryHeight
		}
		// `nextBase` stores the value produced by this operation.
		nextBase := currentHeight + 1
		state.NextRetryHeight = transitionBarrierNextCheckpointAtOrAfter(nextBase)
		state.LastUpdatedAt = now
		n.transitionBarrierRetryStateByKey[key] = state
		return true, tupleChanged, state.NextRetryHeight
	}

	if !ok {
		// `nextRetry` stores the value produced by this operation.
		nextRetry := nextTransitionBarrierRetryHeight(currentHeight)
		n.transitionBarrierRetryStateByKey[key] = transitionBarrierRetryState{
			NextRetryHeight: nextRetry,
			LastFailTuple:   tuple,
			LastUpdatedAt:   now,
		}
		return true, true, nextRetry
	}

	if state.LastFailTuple != tuple {
		// `nextRetry` stores the value produced by this operation.
		nextRetry := nextTransitionBarrierRetryHeight(currentHeight)
		state.NextRetryHeight = nextRetry
		state.LastFailTuple = tuple
		state.LastUpdatedAt = now
		n.transitionBarrierRetryStateByKey[key] = state
		return true, true, nextRetry
	}

	if state.NextRetryHeight == 0 || currentHeight >= state.NextRetryHeight {
		// `nextRetry` stores the value produced by this operation.
		nextRetry := nextTransitionBarrierRetryHeight(currentHeight)
		state.NextRetryHeight = nextRetry
		state.LastFailTuple = tuple
		state.LastUpdatedAt = now
		n.transitionBarrierRetryStateByKey[key] = state
		return true, false, nextRetry
	}

	state.LastUpdatedAt = now
	n.transitionBarrierRetryStateByKey[key] = state
	return false, false, state.NextRetryHeight
}

// clearTransitionBarrierRetry implements the clear transition barrier retry helper.
func (n *Node) clearTransitionBarrierRetry(reason string, updateHeight uint64, nextSetHash string) {
	if n == nil {
		return
	}
	// `key` stores the key used to access the related value.
	key := transitionBarrierRetryStateKey(reason, updateHeight, nextSetHash)
	n.transitionBarrierRetryMu.Lock()
	if n.transitionBarrierRetryStateByKey != nil {
		delete(n.transitionBarrierRetryStateByKey, key)
	}
	n.transitionBarrierRetryMu.Unlock()
}

// pruneTransitionBarrierRetry implements the prune transition barrier retry helper.
func (n *Node) pruneTransitionBarrierRetry(activeHeights map[uint64]struct{}) {
	if n == nil {
		return
	}
	n.transitionBarrierRetryMu.Lock()
	defer n.transitionBarrierRetryMu.Unlock()
	if len(n.transitionBarrierRetryStateByKey) == 0 {
		return
	}
	if len(activeHeights) == 0 {
		clear(n.transitionBarrierRetryStateByKey)
		return
	}
	// `key` tracks the key used to access the related value.
	for key := range n.transitionBarrierRetryStateByKey {
		// `ok` stores whether the related condition is satisfied.
		if _, ok := activeHeights[key.UpdateHeight]; ok {
			continue
		}
		delete(n.transitionBarrierRetryStateByKey, key)
	}
}

// clearTransitionPlanLocked implements the clear transition plan locked helper.
func (n *Node) clearTransitionPlanLocked() {
	if n == nil {
		return
	}
	n.transitionPlan = validatorSetTransitionPlan{}
}

// transitionPlanSnapshot implements the transition plan snapshot helper.
func (n *Node) transitionPlanSnapshot() validatorSetTransitionPlan {
	if n == nil {
		return validatorSetTransitionPlan{}
	}
	n.validatorSetMu.RLock()
	defer n.validatorSetMu.RUnlock()
	// `plan` stores the value produced by this operation.
	plan := n.transitionPlan
	if len(plan.NextValidators) > 0 {
		plan.NextValidators = append([]string{}, plan.NextValidators...)
	}
	if len(plan.ProcessedAdds) > 0 {
		plan.ProcessedAdds = append([]string{}, plan.ProcessedAdds...)
	}
	if len(plan.ProcessedRemoves) > 0 {
		plan.ProcessedRemoves = append([]string{}, plan.ProcessedRemoves...)
	}
	return plan
}

// requestConsensusRecomputePause implements the request consensus recompute pause helper.
func (n *Node) requestConsensusRecomputePause(height uint64, reason string) {
	if n == nil {
		return
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `pauseFor` stores the value produced by this operation.
	pauseFor := consensusRecomputePauseDurationFor(reason)
	// `until` stores the value produced by this operation.
	until := now.Add(pauseFor)

	// `shouldLog` stores the value produced by this operation.
	shouldLog := false
	// `logReason` stores the value produced by this operation.
	logReason := reason
	// `logHeight` stores the value produced by this operation.
	logHeight := height
	// `logUntil` stores the value produced by this operation.
	logUntil := until
	// `pauseBlocksConsensus` stores the value produced by this operation.
	pauseBlocksConsensus := true
	// `scheduleResume` stores whether a resume task should be scheduled.
	scheduleResume := false

	n.recomputePauseMu.Lock()
	// `prevUntil` stores the value produced by this operation.
	prevUntil := n.recomputePauseUntil
	// `prevReason` stores the value produced by this operation.
	prevReason := n.recomputePauseReason
	if until.After(n.recomputePauseUntil) {
		n.recomputePauseUntil = until
	}
	if height > n.recomputePauseHeight {
		n.recomputePauseHeight = height
	}
	if strings.TrimSpace(reason) != "" {
		n.recomputePauseReason = reason
	}
	// `reasonChanged` stores the value produced by this operation.
	reasonChanged := n.recomputePauseReason != prevReason
	// `extended` stores the value produced by this operation.
	extended := n.recomputePauseUntil.After(prevUntil.Add(250 * time.Millisecond))
	scheduleResume = reasonChanged || extended || prevUntil.IsZero()
	if n.recomputePauseReason == "" {
		n.recomputePauseReason = "validator_set_recompute"
	}
	if logReason == "" {
		logReason = n.recomputePauseReason
	}
	if logHeight == 0 {
		logHeight = n.recomputePauseHeight
	}
	logUntil = n.recomputePauseUntil
	pauseBlocksConsensus = consensusRecomputePauseReasonBlocksConsensus(n.recomputePauseReason)
	if (reasonChanged || extended || prevUntil.IsZero()) &&
		(now.Sub(n.recomputePauseLastLog) >= time.Second) {
		n.recomputePauseLastLog = now
		shouldLog = true
	}
	n.recomputePauseMu.Unlock()

	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		if pauseBlocksConsensus && !n.Consensus.Syncing && !n.Consensus.Paused {
			n.Consensus.Paused = true
			n.recomputePauseMu.Lock()
			n.recomputePauseApplied = true
			n.recomputePauseMu.Unlock()
		}
		n.Consensus.mu.Unlock()
	}

	if shouldLog && DebugConsensus {
		fmt.Printf("[CONSENSUS-PAUSE] reason=%s height=%d hold_until=%s\n",
			logReason, logHeight, logUntil.Format(time.RFC3339Nano))
	}
	if scheduleResume && pauseFor > 0 {
		n.SafeGo(fmt.Sprintf("consensus_recompute_auto_resume_%d", logHeight), func() {
			time.Sleep(pauseFor + 25*time.Millisecond)
			if n == nil || n.isShuttingDown() {
				return
			}
			if n.consensusRecomputePauseActive() {
				return
			}
			n.replayQueuedLeaderBlocksForCurrentEpoch()
			n.replayQueuedExecutionVotes()
			n.maybeBroadcastCurrentLeaderExecutionVote("recompute_auto_resume")
		})
	}
}

// consensusRecomputePauseActive implements the consensus recompute pause active helper.
func (n *Node) consensusRecomputePauseActive() bool {
	if n == nil {
		return false
	}

	// `now` stores the value produced by this operation.
	now := time.Now()
	var (
		// `release` stores the value used by this operation.
		release bool
		// `wasApplied` stores the value used by this operation.
		wasApplied bool
		// `reason` stores the value used by this operation.
		reason string
		// `height` stores the value used by this operation.
		height uint64
		// `active` stores the value used by this operation.
		active bool
		// `pauseApplied` stores the value used by this operation.
		pauseApplied bool
		// `activeReason` stores the value used by this operation.
		activeReason string
	)

	n.recomputePauseMu.Lock()
	if !n.recomputePauseUntil.IsZero() && now.Before(n.recomputePauseUntil) {
		active = true
		pauseApplied = n.recomputePauseApplied
		activeReason = n.recomputePauseReason
	} else if !n.recomputePauseUntil.IsZero() {
		release = true
		wasApplied = n.recomputePauseApplied
		reason = n.recomputePauseReason
		height = n.recomputePauseHeight
		n.recomputePauseUntil = time.Time{}
		n.recomputePauseHeight = 0
		n.recomputePauseReason = ""
		n.recomputePauseLastLog = time.Time{}
		n.recomputePauseApplied = false
	}
	n.recomputePauseMu.Unlock()

	if active {
		if !consensusRecomputePauseReasonBlocksConsensus(activeReason) {
			if pauseApplied && n.Consensus != nil {
				n.Consensus.mu.Lock()
				if !n.Consensus.Syncing {
					n.Consensus.Paused = false
				}
				n.Consensus.mu.Unlock()
				n.recomputePauseMu.Lock()
				n.recomputePauseApplied = false
				n.recomputePauseMu.Unlock()
			}
			return false
		}
		if n.Consensus != nil {
			n.Consensus.mu.Lock()
			if !n.Consensus.Syncing && !n.Consensus.Paused {
				n.Consensus.Paused = true
				if !pauseApplied {
					n.recomputePauseMu.Lock()
					n.recomputePauseApplied = true
					n.recomputePauseMu.Unlock()
				}
			}
			n.Consensus.mu.Unlock()
		}
		return true
	}

	if !release {
		return false
	}

	if wasApplied && n.Consensus != nil {
		n.Consensus.mu.Lock()
		if !n.Consensus.Syncing {
			n.Consensus.Paused = false
		}
		n.Consensus.mu.Unlock()
	}
	if DebugConsensus {
		fmt.Printf("[CONSENSUS-RESUME] reason=%s height=%d\n", reason, height)
	}
	n.replayQueuedExecutionVotes()
	n.maybeBroadcastCurrentLeaderExecutionVote("recompute_resume")
	return false
}

// maybeSyncToBestObservedHeight implements the maybe sync to best observed height helper.
func (n *Node) maybeSyncToBestObservedHeight(reason string) {
	if n == nil {
		return
	}
	// `queuedReason` stores the value produced by this operation.
	queuedReason := strings.TrimSpace(reason)
	if !n.scheduleSyncTask(func() {
		n.maybeSyncToBestObservedHeightNow(queuedReason)
	}) {
		n.SafeGo("sync_best_observed_fallback", func() {
			n.maybeSyncToBestObservedHeightNow(queuedReason)
		})
	}
}

// maybeSyncToBestObservedHeightNow implements the maybe sync to best observed height now helper.
func (n *Node) maybeSyncToBestObservedHeightNow(reason string) {
	// `localHeight` stores the value produced by this operation.
	localHeight := n.Blockchain.Height()
	if n.Host == nil {
		return
	}
	// `peerCount` stores the measured quantity used by this operation.
	peerCount := len(n.Host.Network().Peers())
	if peerCount == 0 {
		return
	}
	// `quorumHeight`, `votes`, `required`, and `ok` store whether the related condition is satisfied.
	quorumHeight, votes, required, ok := n.majorityHeartbeatHeight()
	// `observedHeight` and `observedVotes` store the value produced by this operation.
	observedHeight, observedVotes := n.bestObservedSyncHeight()
	if localHeight == 0 {
		// `observedHash`, `observedHashVotes`, `hashHeight`, and `sampleOK` store whether the related condition is satisfied.
		if observedHash, observedHashVotes, hashHeight, sampleOK := n.bestObservedValidatorSetHash(); sampleOK && observedHashVotes > 0 {
			// `sampleHeight` stores the value produced by this operation.
			sampleHeight := uint64(0)
			switch {
			case hashHeight > 0:
				sampleHeight = hashHeight + 1
			case observedHeight > 0:
				sampleHeight = observedHeight + 1
			}
			// Fresh clusters at genesis can exchange validator-set hashes before any
			// block is finalized. Do not force late-join snapshot authority in that
			// case or validators can deadlock in startup observer mode at height 0.
			if sampleHeight > 0 {
				n.noteLateJoinAuthoritySample(sampleHeight, observedHash)
			}
		}
	}

	// `targetHeight` stores the value produced by this operation.
	targetHeight := selectSyncTargetHeight(localHeight, quorumHeight, ok, observedHeight, observedVotes, required)
	// `frozenTarget` and `frozen` store the value produced by this operation.
	if frozenTarget, frozen := n.snapshotSessionFrozenTarget(localHeight); frozen {
		if targetHeight != frozenTarget {
			targetHeight = frozenTarget
			if DebugSync || DebugConsensus {
				fmt.Printf("[SYNC-ANCHOR] hold reason=%s local=%d frozen=%d\n", reason, localHeight, frozenTarget)
			}
		}
	}
	if targetHeight <= localHeight {
		// Liveness fallback:
		// if we already queued contiguous future blocks, trust that horizon to avoid
		// quorum blind-spots caused by stale local validator-set state.
		queuedTarget := n.maxQueuedFutureHeight(localHeight)
		if queuedTarget > targetHeight {
			targetHeight = queuedTarget
			if (DebugSync || DebugConsensus) && n.shouldLogSyncQueueTarget(targetHeight) {
				fmt.Printf("[SYNC-QUEUE] reason=%s local=%d target=%d\n", reason, localHeight, targetHeight)
			}
		}
	}
	if targetHeight <= localHeight {
		// Secondary fallback: if commit is stalled and at least one live peer reports
		// a higher finalized height, allow observed target to break local deadlock.
		if observedHeight > localHeight && observedVotes > 0 && n.commitStallDuration() >= execQuorumEmergencyStallTimeout {
			targetHeight = observedHeight
			if DebugSync || DebugConsensus {
				fmt.Printf("[SYNC-OBSERVED] reason=%s local=%d target=%d votes=%d required=%d\n",
					reason, localHeight, targetHeight, observedVotes, required)
			}
		}
	}
	if targetHeight <= localHeight && observedHeight > localHeight && observedVotes > 0 {
		// `gap` stores the value produced by this operation.
		gap := observedHeight - localHeight
		if gap > validatorLivenessMaxHeightDriftBlocks() {
			targetHeight = observedHeight
			if DebugSync || DebugConsensus {
				fmt.Printf("[SYNC-OBSERVED-GAP] reason=%s local=%d target=%d gap=%d votes=%d required=%d\n",
					reason, localHeight, targetHeight, gap, observedVotes, required)
			}
		}
	}
	if targetHeight == 0 || targetHeight <= localHeight {
		n.maybeExitSyncMode("up_to_date")
		return
	}
	// `targetVotes` stores the value produced by this operation.
	targetVotes := votes
	if targetHeight == observedHeight && observedHeight > quorumHeight {
		targetVotes = observedVotes
	}
	n.maybeSnapshotSyncToHeight(targetHeight, reason, targetVotes, required)
}

// bestFollowupSyncTarget implements the best followup sync target helper.
func (n *Node) bestFollowupSyncTarget(localHeight uint64) uint64 {
	if n == nil || localHeight == 0 {
		return 0
	}
	// `quorumHeight`, `required`, and `quorumOK` store whether the related condition is satisfied.
	quorumHeight, _, required, quorumOK := n.majorityHeartbeatHeight()
	// `observedHeight` and `observedVotes` store the value produced by this operation.
	observedHeight, observedVotes := n.bestObservedSyncHeight()
	// `target` stores the value produced by this operation.
	target := selectSyncTargetHeight(localHeight, quorumHeight, quorumOK, observedHeight, observedVotes, required)
	// `queuedTarget` stores the value produced by this operation.
	if queuedTarget := n.maxQueuedFutureHeight(localHeight); queuedTarget > target {
		target = queuedTarget
	}
	// `frozenTarget` and `frozen` store the value produced by this operation.
	if frozenTarget, frozen := n.snapshotSessionFrozenTarget(localHeight); frozen && frozenTarget > target {
		target = frozenTarget
	}
	if target <= localHeight {
		return 0
	}
	return target
}

// shouldLogSyncQueueTarget implements the should log sync queue target helper.
func (n *Node) shouldLogSyncQueueTarget(targetHeight uint64) bool {
	if n == nil || targetHeight == 0 {
		return false
	}
	// `syncQueueLogCooldown` defines the constant value used by this package.
	const syncQueueLogCooldown = 3 * time.Second

	n.syncMu.Lock()
	defer n.syncMu.Unlock()

	// `now` stores the value produced by this operation.
	now := time.Now()
	if n.lastSyncQueueLogTarget == targetHeight &&
		!n.lastSyncQueueLogAt.IsZero() &&
		now.Sub(n.lastSyncQueueLogAt) < syncQueueLogCooldown {
		return false
	}

	n.lastSyncQueueLogTarget = targetHeight
	n.lastSyncQueueLogAt = now
	return true
}

// shouldScheduleImmediateSyncResume implements the should schedule immediate sync resume helper.
func shouldScheduleImmediateSyncResume(startHeight uint64, localAfter uint64, targetHeight uint64) bool {
	if targetHeight == 0 {
		return false
	}
	if localAfter <= startHeight {
		return false
	}
	return localAfter < targetHeight
}

// scheduleImmediateSyncResume implements the schedule immediate sync resume helper.
func (n *Node) scheduleImmediateSyncResume(reason string, targetHeight uint64) {
	if n == nil || targetHeight == 0 {
		return
	}
	n.syncMu.Lock()
	if n.syncResumePending {
		n.syncMu.Unlock()
		return
	}
	if n.Blockchain != nil && n.Blockchain.Height() >= targetHeight {
		n.syncMu.Unlock()
		return
	}
	n.syncResumePending = true
	n.syncMu.Unlock()

	go func() {
		// `timer` stores the value produced by this operation.
		timer := time.NewTimer(250 * time.Millisecond)
		defer timer.Stop()
		defer func() {
			n.syncMu.Lock()
			n.syncResumePending = false
			n.syncMu.Unlock()
		}()

		select {
		case <-n.shutdownCh:
			return
		case <-timer.C:
		}

		// `local` stores the value produced by this operation.
		local := uint64(0)
		if n.Blockchain != nil {
			local = n.Blockchain.Height()
		}
		if local >= targetHeight {
			return
		}
		if DebugSync || DebugConsensus {
			fmt.Printf("[SYNC-RESUME] reason=%s local=%d target=%d\n",
				strings.TrimSpace(reason), local, targetHeight)
		}
		n.maybeSyncToBestObservedHeight(reason)
	}()
}

// maybeForceNearTipValidatorSetResync implements the maybe force near tip validator set resync helper.
func (n *Node) maybeForceNearTipValidatorSetResync(localHeight uint64, mismatchHeight uint64, reason string) {
	if n == nil || mismatchHeight == 0 {
		return
	}
	// Stuck-at-next-height case: local H, mismatch on H+1.
	if mismatchHeight != localHeight+1 {
		return
	}

	// `target` stores the value produced by this operation.
	target := mismatchHeight + 1
	// `quorumHeight` and `ok` store whether the related condition is satisfied.
	if quorumHeight, _, _, ok := n.majorityHeartbeatHeight(); ok && quorumHeight > target {
		target = quorumHeight
	}
	// `observedHeight` stores the value produced by this operation.
	if observedHeight, _ := n.bestObservedSyncHeight(); observedHeight > target {
		target = observedHeight
	}
	if target <= localHeight {
		target = localHeight + 2
	}
	if target <= localHeight {
		return
	}

	if DebugConsensus {
		fmt.Printf("[SYNC-ESCALATE] reason=%s local=%d mismatch=%d target=%d (near_tip)\n",
			reason, localHeight, mismatchHeight, target)
	}
	// Near-tip validator-set mismatches should prefer regular catch-up path first.
	// Forced snapshot is kept as last-resort for larger divergence only.
	if target-localHeight > 64 {
		n.forceSnapshotResyncNow(target, reason)
		return
	}
	n.maybeSnapshotSyncToHeight(target, reason, 0, 0)
}

// maybeRequestSyncFromHeartbeats implements the maybe request sync from heartbeats helper.
func (n *Node) maybeRequestSyncFromHeartbeats() {
	n.maybeSyncToBestObservedHeight("heartbeat")
}

// syncBlockRangeWarmupEligible implements the sync block range warmup eligible helper.
func syncBlockRangeWarmupEligible(localHeight uint64, targetHeight uint64) bool {
	return syncLagBlocks(localHeight, targetHeight) > validatorLivenessMaxHeightDriftBlocks()
}

// markSyncWarmupEligible implements the mark sync warmup eligible helper.
func (n *Node) markSyncWarmupEligible(eligible bool) {
	if n == nil || !eligible {
		return
	}
	n.syncMu.Lock()
	n.syncWarmupEligible = true
	n.syncMu.Unlock()
}

// consumeSyncWarmupEligible implements the consume sync warmup eligible helper.
func (n *Node) consumeSyncWarmupEligible() bool {
	if n == nil {
		return false
	}
	n.syncMu.Lock()
	// `eligible` stores the value produced by this operation.
	eligible := n.syncWarmupEligible
	n.syncWarmupEligible = false
	n.syncMu.Unlock()
	return eligible
}

// armSyncWarmupAfterCatchup implements the arm sync warmup after catchup helper.
func (n *Node) armSyncWarmupAfterCatchup(reason string, localHeight uint64, targetHeight uint64) {
	if n == nil || localHeight == 0 || targetHeight == 0 || !n.consumeSyncWarmupEligible() {
		return
	}
	if n.snapshotWarmupActive(localHeight) {
		return
	}
	n.setSnapshotWarmupJoinHeight(localHeight)
	n.clearLateJoinAuthorityState()
	if DebugSync || DebugConsensus {
		// `remaining` stores the value produced by this operation.
		if remaining := n.snapshotWarmupRemaining(localHeight); remaining > 0 {
			fmt.Printf("[REJOIN-WARMUP] reason=%s local=%d target=%d warmup_seconds=%d\n",
				strings.TrimSpace(reason), localHeight, targetHeight, remaining)
		}
	}
}

// maybeExitSyncMode implements the maybe exit sync mode helper.
func (n *Node) maybeExitSyncMode(reason string) bool {
	if n == nil || n.Consensus == nil {
		return false
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := n.Blockchain.Height()
	// `cleared` stores the value produced by this operation.
	cleared := false
	// `target` stores the value produced by this operation.
	target := uint64(0)
	// `armWarmup` stores the value produced by this operation.
	armWarmup := false

	n.Consensus.mu.Lock()
	target = n.Consensus.SyncTarget
	if (n.Consensus.Syncing || n.Consensus.Paused || n.Consensus.syncInFlight) &&
		(target == 0 || localHeight >= target) {
		armWarmup = target > 0 && localHeight > 0
		n.Consensus.Syncing = false
		n.Consensus.Paused = false
		n.Consensus.SyncTarget = 0
		n.Consensus.syncInFlight = false
		cleared = true
	}
	n.Consensus.mu.Unlock()

	if cleared {
		n.setSyncAction("idle", 0, "up_to_date")
		n.setSyncProvider("")
		n.closeSnapshotSession(true, "sync_cleared")
		n.persistDurableSyncAnchorAsync(localHeight, reason)
		n.syncMu.Lock()
		n.syncStallSeconds = 0
		n.syncMu.Unlock()
		if DebugConsensus {
			fmt.Printf("[SYNC-CLEAR] reason=%s local=%d target=%d\n", reason, localHeight, target)
		}
		if armWarmup {
			n.armSyncWarmupAfterCatchup(reason, localHeight, target)
		} else {
			n.consumeSyncWarmupEligible()
		}
		if n.consensusRecomputePauseActive() {
			return true
		}
		// Replaying queued votes inline can finalize the next height and call
		// ReceiveBlock recursively while the current block still holds receiveMu.
		// The post-commit drain waits for that apply lock to be released first.
		n.schedulePostCommitConsensusDrain(localHeight)
	}
	return cleared
}

// maybeSnapshotSyncToHeight implements the maybe snapshot sync to height helper.
func (n *Node) maybeSnapshotSyncToHeight(targetHeight uint64, reason string, votes int, required int) {
	if n.Host == nil || targetHeight == 0 {
		return
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := n.Blockchain.Height()
	// `reasonLower` stores the value produced by this operation.
	reasonLower := strings.ToLower(strings.TrimSpace(reason))
	if !n.snapshotSessionActive() {
		// `peerCount` stores the measured quantity used by this operation.
		peerCount := len(n.Host.Network().Peers())
		if peerCount == 0 {
			return
		}
		// `minSnapshotPeers` stores the value produced by this operation.
		minSnapshotPeers := n.snapshotSyncStartMinPeers(targetHeight, required)
		if peerCount < minSnapshotPeers && syncStageUsesSnapshotTransfer(syncCatchupStage(localHeight, targetHeight)) {
			return
		}
	}
	// `frozenTarget` and `frozen` store the value produced by this operation.
	if frozenTarget, frozen := n.snapshotSessionFrozenTarget(localHeight); frozen {
		targetHeight = frozenTarget
	}
	if targetHeight <= localHeight {
		if n.snapshotSessionActive() {
			n.closeSnapshotSession(true, "up_to_date")
		}
		n.maybeExitSyncMode("up_to_date")
		return
	}

	n.syncMu.Lock()
	if !n.lastSyncAttempt.IsZero() && time.Since(n.lastSyncAttempt) < 2*time.Second {
		n.syncMu.Unlock()
		return
	}
	n.lastSyncAttempt = time.Now()
	n.syncMu.Unlock()

	// `lag` stores the value produced by this operation.
	lag := syncLagBlocks(localHeight, targetHeight)
	// `stage` stores the value produced by this operation.
	stage := syncCatchupStage(localHeight, targetHeight)
	// Snapshot offers should bypass block-range loops when lag is already beyond
	// snapshot threshold; this prevents repeated direct-gossip stalls.
	if strings.Contains(reasonLower, "snapshot_offer") &&
		lag >= syncSnapshotCatchupThresholdBlocks() &&
		!syncStageUsesSnapshotTransfer(stage) {
		stage = "snapshot_delta"
	}
	// `preferBlockRange` stores the value produced by this operation.
	preferBlockRange := n.preferBlockRangeCatchup(localHeight, targetHeight)
	// `allowBlockCatchup` stores the value produced by this operation.
	allowBlockCatchup := n.allowFreshNodeBlockCatchup(localHeight, targetHeight)
	// `forceSnapshot` stores the value produced by this operation.
	forceSnapshot := n.shouldForceSnapshotForFreshNode(localHeight, targetHeight)
	if stage == "delta_replay" &&
		!preferBlockRange &&
		!allowBlockCatchup &&
		syncPromoteDeltaReplayToSnapshot(localHeight, lag) {
		stage = "snapshot_delta"
	}
	if preferBlockRange && syncStageUsesSnapshotTransfer(stage) {
		stage = "range_fetch"
	}
	if allowBlockCatchup && syncStageUsesSnapshotTransfer(stage) {
		stage = "range_fetch"
	}
	if preferBlockRange {
		forceSnapshot = false
	}
	if !forceSnapshot &&
		syncStageUsesSnapshotTransfer(stage) &&
		n.snapshotSessionFailureDegradeActive() &&
		!syncPromoteDeltaReplayToSnapshot(localHeight, lag) {
		// `degradeStage` stores the value produced by this operation.
		degradeStage := "range_fetch"
		if lag <= syncDirectGossipMaxBlocks() {
			degradeStage = "direct_gossip"
		}
		if DebugSync || DebugConsensus {
			fmt.Printf("[SYNC-DEGRADE] reason=%s local=%d target=%d failures=degraded stage=%s action=block_range_fetch\n",
				reason, localHeight, targetHeight, degradeStage)
		}
		n.syncBlockRangeToHeight(targetHeight, degradeStage, syncBlockRangeAction(degradeStage), reason+"_snapshot_degraded", votes, required)
		return
	}
	if n.snapshotSessionActive() {
		if preferBlockRange {
			n.closeSnapshotSession(false, "block_range_preferred_policy")
			// `degradeStage` stores the value produced by this operation.
			degradeStage := "range_fetch"
			if lag <= syncDirectGossipMaxBlocks() {
				degradeStage = "direct_gossip"
			}
			n.syncBlockRangeToHeight(targetHeight, degradeStage, syncBlockRangeAction(degradeStage), reason+"_snapshot_policy_fallback", votes, required)
			return
		}
		if allowBlockCatchup && !forceSnapshot {
			// `session` stores the value produced by this operation.
			session := n.snapshotSessionSnapshot()
			// `retries` stores the value produced by this operation.
			retries := session.RetryCount
			if retries >= syncSnapshotRetryBudget() || n.snapshotSessionFailureDegradeActive() {
				n.closeSnapshotSession(false, "snapshot_anchor_fallback_block_range")
				// `degradeStage` stores the value produced by this operation.
				degradeStage := "range_fetch"
				if lag <= syncDirectGossipMaxBlocks() {
					degradeStage = "direct_gossip"
				}
				if DebugSync || DebugConsensus {
					fmt.Printf("[SYNC-FALLBACK] reason=%s local=%d target=%d retries=%d stage=%s action=block_range_fetch\n",
						reason, localHeight, targetHeight, retries, degradeStage)
				}
				n.syncBlockRangeToHeight(targetHeight, degradeStage, syncBlockRangeAction(degradeStage), reason+"_snapshot_fallback", votes, required)
				return
			}
		}
		n.setSnapshotSessionStage(SnapshotSyncStageDetectLag)
		if !syncStageUsesSnapshotTransfer(stage) {
			stage = "snapshot_delta"
		}
		// `action` stores the value produced by this operation.
		action := syncSnapshotStageAction(stage)
		if action == "" {
			action = "snapshot_delta"
		}
		n.setSyncAction(stage, lag, action)
		n.forceSnapshotSyncToHeight(targetHeight, reason+"_anchor_snapshot")
		return
	}
	if forceSnapshot {
		if !syncStageUsesSnapshotTransfer(stage) {
			stage = "snapshot_delta"
		}
		// `session` stores the value produced by this operation.
		session := n.startSnapshotSession(targetHeight, reason)
		if session.FreezeHeight > 0 {
			targetHeight = session.FreezeHeight
		}
		lag = syncLagBlocks(localHeight, targetHeight)
		n.setSnapshotSessionStage(SnapshotSyncStageDetectLag)
		// `action` stores the value produced by this operation.
		action := syncSnapshotStageAction(stage)
		if action == "" {
			action = "snapshot_delta"
		}
		n.setSyncAction(stage, lag, action)
		n.forceSnapshotSyncToHeight(targetHeight, reason+"_snapshot")
		return
	}
	if preferBlockRange && syncStageUsesSnapshotTransfer(stage) {
		stage = "range_fetch"
	}
	if syncStageUsesSnapshotTransfer(stage) {
		// `session` stores the value produced by this operation.
		session := n.startSnapshotSession(targetHeight, reason)
		if session.FreezeHeight > 0 {
			targetHeight = session.FreezeHeight
		}
		lag = syncLagBlocks(localHeight, targetHeight)
		n.setSnapshotSessionStage(SnapshotSyncStageDetectLag)
		// `action` stores the value produced by this operation.
		action := syncSnapshotStageAction(stage)
		if action == "" {
			action = "snapshot_delta"
		}
		n.setSyncAction(stage, lag, action)
		n.forceSnapshotSyncToHeight(targetHeight, reason+"_snapshot")
		return
	}

	if stage == "delta_replay" {
		n.syncDeltaReplayToHeight(targetHeight, reason, votes, required)
		return
	}

	if syncStageUsesBlockRangeFetch(stage) {
		n.syncBlockRangeToHeight(targetHeight, stage, syncBlockRangeAction(stage), reason, votes, required)
	}
}

// syncReasonPreemptsInFlight implements the sync reason preempts in flight helper.
func syncReasonPreemptsInFlight(reason string) bool {
	reason = strings.ToLower(strings.TrimSpace(reason))
	if reason == "" {
		return false
	}
	if syncRecoveryReasonNeedsTrustedStateRepair(reason) {
		return true
	}
	// Level-2 autoheal has already decided that bounded block replay cannot
	// close the gap. Let its trusted snapshot replace an older sync in flight.
	if strings.Contains(reason, "autoheal_lag_snapshot") {
		return true
	}
	// `preemptTokens` stores the value produced by this operation.
	preemptTokens := []string{
		"queue_stall",
		"queue_gap",
		"queue_apply_failed",
		"parent_mismatch",
		"prev_hash_mismatch",
		"queue_prevhash_mismatch",
		"sync_stall",
		"watchdog",
		"no_progress",
		"missing_block",
		"block_range_unavailable",
		"range_timeout",
	}
	// `token` tracks the current values while iterating.
	for _, token := range preemptTokens {
		if strings.Contains(reason, token) {
			return true
		}
	}
	return false
}

// syncBlockRangeToHeight implements the sync block range to height helper.
func (n *Node) syncBlockRangeToHeight(targetHeight uint64, stage string, action string, reason string, votes int, required int) {
	if n == nil {
		return
	}

	// `localHeight` stores the value produced by this operation.
	localHeight := n.Blockchain.Height()
	// `lag` stores the value produced by this operation.
	lag := syncLagBlocks(localHeight, targetHeight)
	// `reasonLower` stores the value produced by this operation.
	reasonLower := strings.ToLower(strings.TrimSpace(reason))
	// `plan` stores the value produced by this operation.
	plan := syncCatchupPlanForStage(stage, localHeight, targetHeight)
	if !plan.BlockRange {
		plan = syncCatchupPlanForStage(syncCatchupStage(localHeight, targetHeight), localHeight, targetHeight)
	}
	if plan.BlockRange {
		stage = plan.Stage
		if strings.TrimSpace(action) == "" {
			action = syncBlockRangeAction(stage)
		}
	}

	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		if n.Consensus.syncInFlight {
			if syncReasonPreemptsInFlight(reasonLower) {
				n.Consensus.syncInFlight = false
			} else {
				n.Consensus.mu.Unlock()
				return
			}
		}
		n.Consensus.syncInFlight = true
		n.Consensus.Syncing = true
		n.Consensus.Paused = true
		if targetHeight > n.Consensus.SyncTarget {
			n.Consensus.SyncTarget = targetHeight
		}
		n.Consensus.mu.Unlock()
	}
	n.markSyncWarmupEligible(syncBlockRangeWarmupEligible(localHeight, targetHeight))

	n.syncMu.Lock()
	if localHeight > n.syncLastObservedHeight {
		n.syncLastObservedHeight = localHeight
		n.syncLastProgressAt = time.Now()
		n.syncStallSeconds = 0
	} else if n.syncLastProgressAt.IsZero() {
		n.syncLastProgressAt = time.Now()
	}
	n.syncResumeTarget = targetHeight
	n.syncMu.Unlock()

	n.setSyncProvider("")
	n.setSyncAction(stage, lag, action)
	n.persistSyncResumeState(stage, targetHeight, reason)

	if DebugConsensus {
		fmt.Printf("[SYNC] reason=%s local=%d target=%d votes=%d required=%d stage=%s action=%s\n",
			reason, localHeight, targetHeight, votes, required, stage, action)
	}

	// `synced` stores the value produced by this operation.
	synced := n.syncBlocksFromPeersWithStage(targetHeight, plan.BatchMax, false, stage)
	// `localAfter` stores the value produced by this operation.
	localAfter := n.Blockchain.Height()
	// `followupTarget` stores the value produced by this operation.
	followupTarget := uint64(0)
	// `followupPending` stores the value produced by this operation.
	followupPending := false
	if synced && localAfter >= targetHeight {
		followupTarget = n.bestFollowupSyncTarget(localAfter)
		followupPending = followupTarget > localAfter
	}
	// `cleared` stores the value produced by this operation.
	cleared := false
	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		n.Consensus.syncInFlight = false
		if synced && localAfter >= targetHeight && !followupPending {
			n.Consensus.Syncing = false
			n.Consensus.Paused = false
			n.Consensus.SyncTarget = 0
			cleared = true
		} else if synced {
			n.Consensus.Syncing = true
			n.Consensus.Paused = true
			// `nextTarget` stores the value produced by this operation.
			nextTarget := targetHeight
			if followupTarget > nextTarget {
				nextTarget = followupTarget
			}
			if nextTarget > n.Consensus.SyncTarget {
				n.Consensus.SyncTarget = nextTarget
			}
		} else {
			n.Consensus.Syncing = false
			n.Consensus.Paused = false
			if n.Consensus.SyncTarget == targetHeight {
				n.Consensus.SyncTarget = 0
			}
		}
		n.Consensus.mu.Unlock()
	}
	if cleared {
		n.setSyncAction("idle", 0, "up_to_date")
		n.setSyncProvider("")
		n.clearSyncResumeState()
		n.armSyncWarmupAfterCatchup(reason, localAfter, targetHeight)
		n.replayQueuedExecutionVotes()
	} else if followupPending {
		n.scheduleImmediateSyncResume("followup_sync_target", followupTarget)
	} else if shouldScheduleImmediateSyncResume(localHeight, localAfter, targetHeight) {
		n.scheduleImmediateSyncResume("partial_sync_resume", targetHeight)
	} else {
		n.consumeSyncWarmupEligible()
	}
}

// syncDeltaReplayToHeight implements the sync delta replay to height helper.
func (n *Node) syncDeltaReplayToHeight(targetHeight uint64, reason string, votes int, required int) {
	if n == nil {
		return
	}

	// `localHeight` stores the value produced by this operation.
	localHeight := n.Blockchain.Height()
	// `lag` stores the value produced by this operation.
	lag := syncLagBlocks(localHeight, targetHeight)
	// `reasonLower` stores the value produced by this operation.
	reasonLower := strings.ToLower(strings.TrimSpace(reason))

	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		if n.Consensus.syncInFlight {
			if syncReasonPreemptsInFlight(reasonLower) {
				n.Consensus.syncInFlight = false
			} else {
				n.Consensus.mu.Unlock()
				return
			}
		}
		n.Consensus.syncInFlight = true
		n.Consensus.Syncing = true
		n.Consensus.Paused = true
		if targetHeight > n.Consensus.SyncTarget {
			n.Consensus.SyncTarget = targetHeight
		}
		n.Consensus.mu.Unlock()
	}

	n.syncMu.Lock()
	if localHeight > n.syncLastObservedHeight {
		n.syncLastObservedHeight = localHeight
		n.syncLastProgressAt = time.Now()
		n.syncStallSeconds = 0
	} else if n.syncLastProgressAt.IsZero() {
		n.syncLastProgressAt = time.Now()
	}
	n.syncResumeTarget = targetHeight
	n.syncMu.Unlock()

	n.setSyncProvider("")
	n.setSyncAction("delta_replay", lag, "delta_replay")
	n.persistSyncResumeState("delta_replay", targetHeight, reason)

	if DebugConsensus {
		fmt.Printf("[SYNC] reason=%s local=%d target=%d votes=%d required=%d stage=%s action=%s\n",
			reason, localHeight, targetHeight, votes, required, "delta_replay", "delta_replay")
	}

	// `synced` stores the value produced by this operation.
	synced := n.syncDeltaReplayFromPeers(targetHeight)
	// `localAfter` stores the value produced by this operation.
	localAfter := n.Blockchain.Height()
	// `followupTarget` stores the value produced by this operation.
	followupTarget := uint64(0)
	// `followupPending` stores the value produced by this operation.
	followupPending := false
	if synced && localAfter >= targetHeight {
		followupTarget = n.bestFollowupSyncTarget(localAfter)
		followupPending = followupTarget > localAfter
	}
	// `cleared` stores the value produced by this operation.
	cleared := false
	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		n.Consensus.syncInFlight = false
		if synced && localAfter >= targetHeight && !followupPending {
			n.Consensus.Syncing = false
			n.Consensus.Paused = false
			n.Consensus.SyncTarget = 0
			cleared = true
		} else if synced {
			n.Consensus.Syncing = true
			n.Consensus.Paused = true
			// `nextTarget` stores the value produced by this operation.
			nextTarget := targetHeight
			if followupTarget > nextTarget {
				nextTarget = followupTarget
			}
			if nextTarget > n.Consensus.SyncTarget {
				n.Consensus.SyncTarget = nextTarget
			}
		} else {
			n.Consensus.Syncing = false
			n.Consensus.Paused = false
			if n.Consensus.SyncTarget == targetHeight {
				n.Consensus.SyncTarget = 0
			}
		}
		n.Consensus.mu.Unlock()
	}
	if cleared {
		n.setSyncAction("idle", 0, "up_to_date")
		n.setSyncProvider("")
		n.clearSyncResumeState()
		n.replayQueuedExecutionVotes()
	} else if followupPending {
		n.scheduleImmediateSyncResume("followup_sync_target", followupTarget)
	} else if shouldScheduleImmediateSyncResume(localHeight, localAfter, targetHeight) {
		n.scheduleImmediateSyncResume("partial_sync_resume", targetHeight)
	}
}

// startLateJoinSyncLoop implements the start late join sync loop helper.
func (n *Node) startLateJoinSyncLoop(ctx context.Context) {
	if n == nil {
		return
	}
	// `ticker` stores the value produced by this operation.
	ticker := time.NewTicker(5 * time.Second)
	defer ticker.Stop()

	// Startup probe: quickly catch up if this node joined late.
	n.maybeSyncToBestObservedHeight("startup")

	for {
		select {
		case <-ctx.Done():
			return
		case <-n.shutdownCh:
			return
		case <-ticker.C:
			n.maybeSyncToBestObservedHeight("late_join")
		}
	}
}

// startSyncStallWatchdog implements the start sync stall watchdog helper.
func (n *Node) startSyncStallWatchdog(ctx context.Context) {
	if n == nil {
		return
	}
	// `ticker` stores the value produced by this operation.
	ticker := time.NewTicker(5 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-n.shutdownCh:
			return
		case <-ticker.C:
			if n.Consensus == nil {
				continue
			}
			n.Consensus.mu.Lock()
			// `syncing` stores the value produced by this operation.
			syncing := n.Consensus.Syncing
			// `target` stores the value produced by this operation.
			target := n.Consensus.SyncTarget
			n.Consensus.mu.Unlock()
			// `local` stores the value produced by this operation.
			local := n.Blockchain.Height()
			// `session` stores the value produced by this operation.
			session := n.snapshotSessionSnapshot()
			// `anchorTarget` stores the value produced by this operation.
			anchorTarget := target
			if session.Active {
				if session.CandidateHeight > anchorTarget {
					anchorTarget = session.CandidateHeight
				} else if session.FreezeHeight > anchorTarget {
					anchorTarget = session.FreezeHeight
				}
			}
			if session.Active {
				n.syncMu.Lock()
				// `snapshotApplied` stores the value produced by this operation.
				snapshotApplied := n.syncSnapshotHeight
				// `downloadedChunks` stores the value produced by this operation.
				downloadedChunks := n.syncDownloadedChunks
				// `totalChunks` stores the measured quantity used by this operation.
				totalChunks := n.syncTotalChunks
				// `chunkProgressAt` stores the value produced by this operation.
				chunkProgressAt := n.syncChunkLastProgressAt
				n.syncMu.Unlock()
				if local == 0 && snapshotApplied == 0 && !session.StartedAt.IsZero() {
					if time.Since(session.StartedAt) >= time.Duration(syncSnapshotSessionResetWatchdogSeconds())*time.Second {
						n.setSyncAvoidProviderOnce(strings.TrimSpace(session.CurrentProvider))
						n.closeSnapshotSession(false, "snapshot_session_watchdog_reset")
						n.syncMu.Lock()
						n.lastSyncAttempt = time.Time{}
						n.syncMu.Unlock()
						if DebugConsensus {
							fmt.Printf("[SYNC-WATCHDOG] reset reason=snapshot_session_watchdog_reset local=%d target=%d stage=%s\n",
								local, anchorTarget, session.Stage)
						}
						n.forceSnapshotResyncNow(anchorTarget, "snapshot_session_watchdog_reset")
						continue
					}
				}
				if session.Required > 0 && len(session.Votes) >= session.Required && !session.Applied && !session.LastVoteAt.IsZero() {
					if time.Since(session.LastVoteAt) >= time.Duration(syncSnapshotQuorumApplyWatchdogSeconds())*time.Second {
						if DebugConsensus {
							fmt.Printf("[SYNC-WATCHDOG] reapply reason=snapshot_quorum_apply_watchdog local=%d target=%d votes=%d/%d\n",
								local, anchorTarget, len(session.Votes), session.Required)
						}
						n.setSnapshotSessionStage(SnapshotSyncStageApplySnapshot)
						n.syncMu.Lock()
						n.lastSyncAttempt = time.Time{}
						n.syncMu.Unlock()
						n.forceSnapshotSyncToHeight(anchorTarget, "snapshot_quorum_apply_watchdog_force_apply")
						continue
					}
				}
				if local < anchorTarget && totalChunks > 0 {
					// `baseAt` stores the value produced by this operation.
					baseAt := session.StartedAt
					if !chunkProgressAt.IsZero() {
						baseAt = chunkProgressAt
					}
					if !baseAt.IsZero() && time.Since(baseAt) >= time.Duration(syncSnapshotNoChunkProgressSeconds())*time.Second {
						// `currentProvider` stores the value produced by this operation.
						currentProvider := strings.TrimSpace(session.CurrentProvider)
						if currentProvider != "" {
							n.recordSyncPeerSnapshotResult(currentProvider, false, 0, 0, true)
							n.setSyncAvoidProviderOnce(currentProvider)
						}
						n.snapshotSessionMarkFailure("snapshot_chunk_stall")
						// `nextProvider` stores the value produced by this operation.
						nextProvider := n.rotateSnapshotProvider()
						fmt.Printf("[SYNC-WATCHDOG] chunk_stall local=%d target=%d downloaded=%d/%d provider=%s next=%s action=provider_rotate\n",
							local, anchorTarget, downloadedChunks, totalChunks, currentProvider, strings.TrimSpace(nextProvider))
						n.syncMu.Lock()
						n.lastSyncAttempt = time.Time{}
						n.syncMu.Unlock()
						n.forceSnapshotResyncNow(anchorTarget, "snapshot_chunk_stall")
						continue
					}
				}
			}
			// `quorumHeight` and `ok` store whether the related condition is satisfied.
			if quorumHeight, _, _, ok := n.majorityHeartbeatHeight(); ok && quorumHeight > target {
				target = quorumHeight
			}
			// `observedHeight` and `observedVotes` store the value produced by this operation.
			if observedHeight, observedVotes := n.bestObservedSyncHeight(); observedVotes > 0 && observedHeight > target {
				target = observedHeight
			}
			if n.Consensus != nil && target > 0 {
				n.Consensus.mu.Lock()
				if target > n.Consensus.SyncTarget {
					n.Consensus.SyncTarget = target
				}
				n.Consensus.mu.Unlock()
			}
			// `lag` stores the value produced by this operation.
			lag := syncLagBlocks(local, target)
			if !syncing || target == 0 || lag == 0 {
				if syncing && target > 0 && lag == 0 {
					n.maybeExitSyncMode("sync_watchdog_target_reached")
				}
				n.syncMu.Lock()
				n.syncStallSeconds = 0
				n.syncLastObservedHeight = local
				n.syncLastProgressAt = time.Now()
				n.syncMu.Unlock()
				continue
			}

			// `shouldRestart` stores the value produced by this operation.
			shouldRestart := false
			// `stall` stores the value produced by this operation.
			stall := uint64(0)
			n.syncMu.Lock()
			if local > n.syncLastObservedHeight {
				n.syncLastObservedHeight = local
				n.syncLastProgressAt = time.Now()
				n.syncStallSeconds = 0
			} else {
				if n.syncLastProgressAt.IsZero() {
					n.syncLastProgressAt = time.Now()
				}
				stall = uint64(time.Since(n.syncLastProgressAt).Seconds())
				n.syncStallSeconds = stall
				shouldRestart = stall >= syncStallThresholdSeconds()
			}
			n.syncMu.Unlock()
			if stall >= syncStallAlertThresholdSeconds() &&
				(stall == syncStallAlertThresholdSeconds() || stall%30 < 5) {
				fmt.Printf("[ALERT] sync_stall local=%d target=%d lag=%d stall=%ds stage=%s\n",
					local, target, lag, stall, syncCatchupStage(local, target))
			}

			if !shouldRestart {
				continue
			}
			n.syncMu.Lock()
			// `failedProvider` stores the value produced by this operation.
			failedProvider := strings.TrimSpace(n.syncProvider)
			n.syncMu.Unlock()
			n.setSyncAvoidProviderOnce(failedProvider)
			// `resyncStage` stores the result produced by this operation.
			resyncStage := syncCatchupStage(local, target)
			if resyncStage == "delta_replay" && syncPromoteDeltaReplayToSnapshot(local, lag) {
				resyncStage = "snapshot_delta"
			}
			// `forceSnapshot` stores the value produced by this operation.
			forceSnapshot := syncStageUsesSnapshotTransfer(resyncStage) && !n.snapshotSessionFailureDegradeActive()
			// `action` stores the value produced by this operation.
			action := syncSnapshotStageAction(resyncStage)
			if !forceSnapshot {
				action = syncBlockRangeAction(resyncStage)
				if action == "" {
					action = "range_fetch"
				}
			}
			if DebugConsensus {
				fmt.Printf("[SYNC-WATCHDOG] stalled local=%d target=%d lag=%d stall=%ds stage=%s action=%s\n",
					local, target, lag, stall, resyncStage, action)
			}
			if forceSnapshot {
				n.forceSnapshotResyncNow(target, "sync_stall_watchdog_force_snapshot")
				continue
			}
			n.syncMu.Lock()
			n.lastSyncAttempt = time.Time{}
			n.syncMu.Unlock()
			n.maybeSnapshotSyncToHeight(target, "sync_stall_watchdog", 0, 0)
		}
	}
}

// oldestLocalBlockHeight implements the oldest local block height helper.
func (n *Node) oldestLocalBlockHeight() uint64 {
	if n == nil || n.Blockchain == nil {
		return 0
	}
	n.Blockchain.mu.RLock()
	defer n.Blockchain.mu.RUnlock()
	if len(n.Blockchain.Blocks) == 0 {
		return 0
	}
	return n.Blockchain.Blocks[0].ID
}

// backfillHistoryStep implements the backfill history step helper.
func (n *Node) backfillHistoryStep() {
	if n == nil || n.Host == nil {
		return
	}
	// `oldest` stores the value produced by this operation.
	oldest := n.oldestLocalBlockHeight()
	if oldest <= 1 {
		return
	}
	// `to` stores the value produced by this operation.
	to := oldest - 1
	// `backfillBatch` defines the constant value used by this package.
	const backfillBatch uint64 = 128
	// `from` stores the value produced by this operation.
	from := uint64(1)
	if to > backfillBatch {
		from = to - backfillBatch + 1
	}
	// `exclude` stores the value produced by this operation.
	exclude := make(map[peer.ID]struct{})
	// `pid` and `ok` store whether the related condition is satisfied.
	pid, ok := n.pickSyncPeer(to, exclude)
	if !ok {
		return
	}
	// `started` stores the value produced by this operation.
	started := time.Now()
	// `blocks` and `err` store the error produced by this operation.
	blocks, _, _, err := n.requestBlocksFromPeer(pid, from, to, false, 0)
	if err != nil || len(blocks) == 0 {
		n.recordSyncPeerBlockResult(pid.String(), false, time.Since(started), 0, isSyncTimeoutError(err))
		return
	}
	n.recordSyncPeerBlockResult(pid.String(), true, time.Since(started), len(MustJSON(blocks)), false)
	// Archive backfill stores historical blocks without affecting live tip execution.
	for _, block := range blocks {
		if block.ID >= oldest {
			continue
		}
		n.StoreBlock(block)
	}
	n.syncBackfillMu.Lock()
	n.syncBackfillWatermark = from
	n.syncBackfillMu.Unlock()
}

// startHistoryBackfillLoop implements the start history backfill loop helper.
func (n *Node) startHistoryBackfillLoop(ctx context.Context) {
	if n == nil {
		return
	}
	// `ticker` stores the value produced by this operation.
	ticker := time.NewTicker(20 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-n.shutdownCh:
			return
		case <-ticker.C:
			// `mode` stores the value produced by this operation.
			mode := normalizeSyncHistoryMode(SyncHistoryMode)
			if mode == SyncHistoryModeNone {
				continue
			}
			// `runtime` stores the value produced by this operation.
			runtime := n.runtimeStatusSnapshot()
			if runtime.Syncing || !runtime.SyncComplete {
				continue
			}
			n.backfillHistoryStep()
		}
	}
}

// forceSnapshotSyncToHeight implements the force snapshot sync to height helper.
func (n *Node) forceSnapshotSyncToHeight(targetHeight uint64, reason string) {
	if n == nil || n.Blockchain == nil {
		return
	}
	if targetHeight == 0 {
		return
	}
	// `reasonLower` stores the value produced by this operation.
	reasonLower := strings.ToLower(strings.TrimSpace(reason))
	// `preemptInFlight` stores the value produced by this operation.
	preemptInFlight := syncReasonPreemptsInFlight(reasonLower) ||
		strings.Contains(reasonLower, "snapshot_quorum_apply_watchdog")
	// `allowSameHeightRefresh` stores the value produced by this operation.
	allowSameHeightRefresh := strings.Contains(reasonLower, "execution_snapshot_ledger_unavailable")
	// `transitionActive` and `transitionHeight` store the value produced by this operation.
	if transitionActive, transitionHeight := n.validatorSetTransitionActiveNow(); transitionActive {
		if DebugConsensus {
			fmt.Printf("[SYNC-LOCK] reason=%s blocked=validator_set_transition_active transition_h=%d target=%d\n",
				reason, transitionHeight, targetHeight)
		}
		return
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := n.Blockchain.Height()
	if targetHeight < localHeight || (targetHeight == localHeight && !allowSameHeightRefresh) {
		if n.snapshotSessionActive() {
			n.closeSnapshotSession(true, "stale_target")
		}
		if DebugConsensus {
			fmt.Printf("[SYNC-FORCE] reason=%s local=%d target=%d (ignored stale target)\n", reason, localHeight, targetHeight)
		}
		return
	}
	// `frozenTarget` and `frozen` store the value produced by this operation.
	if frozenTarget, frozen := n.snapshotSessionFrozenTarget(localHeight); frozen {
		targetHeight = frozenTarget
	}
	if !snapshotSyncReasonBypassesCooldown(reasonLower) {
		// `cooldown` stores the value produced by this operation.
		cooldown := SnapshotRetryController{Node: n}.BackoffDelay(5 * time.Second)
		if n.snapshotTriggerCooldownActive(cooldown) {
			return
		}
	}
	if DebugConsensus {
		fmt.Printf("[SYNC-FORCE] reason=%s local=%d target=%d\n", reason, localHeight, targetHeight)
	}
	n.syncMu.Lock()
	if localHeight > n.syncLastObservedHeight {
		n.syncLastObservedHeight = localHeight
		n.syncLastProgressAt = time.Now()
		n.syncStallSeconds = 0
	} else if n.syncLastProgressAt.IsZero() {
		n.syncLastProgressAt = time.Now()
	}
	n.syncMu.Unlock()
	n.setSnapshotSessionStage(SnapshotSyncStageFreezeAnchor)
	n.setSnapshotSessionStage(SnapshotSyncStageCheckAnchor)
	n.setSyncProvider("")
	// `stage` stores the value produced by this operation.
	stage := syncCatchupStage(localHeight, targetHeight)
	if !syncStageUsesSnapshotTransfer(stage) {
		stage = "snapshot_delta"
	}
	// `action` stores the value produced by this operation.
	action := syncSnapshotStageAction(stage)
	if action == "" {
		action = "snapshot_delta"
	}
	n.setSyncAction(stage, syncLagBlocks(localHeight, targetHeight), action)
	n.persistSyncResumeState(stage, targetHeight, reason)
	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		if n.Consensus.syncInFlight {
			if preemptInFlight {
				n.Consensus.syncInFlight = false
			} else {
				n.Consensus.mu.Unlock()
				return
			}
		}
		n.Consensus.syncInFlight = true
		n.Consensus.Syncing = true
		n.Consensus.Paused = true
		n.Consensus.SyncTarget = targetHeight
		n.Consensus.mu.Unlock()
	}
	n.syncMu.Lock()
	n.syncWarmupEligible = syncLagBlocks(localHeight, targetHeight) >= 2
	n.syncMu.Unlock()

	// `sourcePolicy` stores the value produced by this operation.
	sourcePolicy := snapshotSyncSourceLocalOrTrusted
	if localHeight == 0 || stage == "state_bootstrap" {
		sourcePolicy = snapshotSyncSourceTrustedOnly
	}
	if snapshotSyncReasonRequiresTrustedSource(reasonLower) {
		sourcePolicy = snapshotSyncSourceTrustedOnly
	}
	// `minHeightOverride` stores the value produced by this operation.
	minHeightOverride := snapshotSyncMinHeightOverrideForReason(reason, localHeight, targetHeight)
	n.setSnapshotSessionStage(SnapshotSyncStageCollectProofs)
	// `synced` stores the value produced by this operation.
	synced := n.applySnapshotForSyncHeightInternal(targetHeight, true, sourcePolicy, minHeightOverride)
	// `localAfter` stores the value produced by this operation.
	localAfter := n.Blockchain.Height()
	// `cleared` stores the value produced by this operation.
	cleared := false
	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		n.Consensus.syncInFlight = false
		if synced && localAfter >= targetHeight {
			n.Consensus.Syncing = false
			n.Consensus.Paused = false
			n.Consensus.SyncTarget = 0
			cleared = true
		} else if synced {
			n.Consensus.Syncing = true
			n.Consensus.Paused = true
		} else if localAfter < targetHeight {
			n.Consensus.Syncing = true
			n.Consensus.Paused = true
		} else {
			n.Consensus.Syncing = false
			n.Consensus.Paused = false
			if n.Consensus.SyncTarget == targetHeight {
				n.Consensus.SyncTarget = 0
			}
		}
		n.Consensus.mu.Unlock()
	}
	if cleared {
		n.closeSnapshotSession(true, "snapshot_sync_complete")
		n.setSyncAction("idle", 0, "up_to_date")
		n.setSyncProvider("")
		n.clearSyncResumeState()
		n.persistDurableSyncAnchorAsync(localAfter, reason)
		n.armSyncWarmupAfterCatchup(reason, localAfter, targetHeight)
		n.replayQueuedExecutionVotes()
	}
}

// snapshotSyncReasonRequiresTrustedSource implements the snapshot sync reason requires trusted source helper.
func snapshotSyncReasonRequiresTrustedSource(reason string) bool {
	// `reasonLower` stores the value produced by this operation.
	reasonLower := strings.ToLower(strings.TrimSpace(reason))
	return strings.Contains(reasonLower, "autoheal_") ||
		strings.Contains(reasonLower, "queue_gap") ||
		strings.Contains(reasonLower, "queue_stall") ||
		strings.Contains(reasonLower, "range_response_gap") ||
		strings.Contains(reasonLower, "missing_block") ||
		strings.Contains(reasonLower, "validator-set-hash-mismatch") ||
		strings.Contains(reasonLower, "peer-validator-set-mismatch") ||
		strings.Contains(reasonLower, "validator_set_hash_mismatch") ||
		strings.Contains(reasonLower, "validator-set-mismatch") ||
		strings.Contains(reasonLower, "parent_mismatch") ||
		strings.Contains(reasonLower, "prev_hash_mismatch") ||
		strings.Contains(reasonLower, "queue_prevhash_mismatch") ||
		strings.Contains(reasonLower, "process_block_incomplete") ||
		strings.Contains(reasonLower, "state_root_mismatch") ||
		strings.Contains(reasonLower, "startup_execution_snapshot") ||
		strings.Contains(reasonLower, "execution_snapshot_ledger_unavailable") ||
		strings.Contains(reasonLower, "large_lag_snapshot") ||
		strings.Contains(reasonLower, "snapshot_quorum_apply_watchdog")
}

// snapshotSyncReasonBypassesCooldown reports recovery reasons that must not be
// dropped behind a recent best-effort block-range attempt.
func snapshotSyncReasonBypassesCooldown(reason string) bool {
	reasonLower := strings.ToLower(strings.TrimSpace(reason))
	if reasonLower == "" {
		return false
	}
	if syncRecoveryReasonNeedsTrustedStateRepair(reasonLower) {
		return true
	}
	for _, token := range []string{
		"watchdog",
		"queue_gap",
		"queue_stall",
		"queue_apply_failed",
		"queue_prevhash_mismatch",
		"range_response_gap",
		"range_timeout",
		"missing_block",
		"block_range_unavailable",
		"process_block_incomplete",
	} {
		if strings.Contains(reasonLower, token) {
			return true
		}
	}
	return false
}

func syncRecoveryReasonNeedsTrustedStateRepair(reason string) bool {
	reason = strings.ToLower(strings.TrimSpace(reason))
	if reason == "" {
		return false
	}
	for _, token := range []string{
		"state_root_mismatch",
		"execution_mismatch",
		"parent_state_unavailable",
		"execution_snapshot_ledger_unavailable",
		"startup_execution_snapshot_rebuild_failed",
	} {
		if strings.Contains(reason, token) {
			return true
		}
	}
	return false
}

// snapshotSyncMinHeightOverrideForReason implements the snapshot sync min height override for reason helper.
func snapshotSyncMinHeightOverrideForReason(reason string, localHeight uint64, targetHeight uint64) uint64 {
	// `reasonLower` stores the value produced by this operation.
	reasonLower := strings.ToLower(strings.TrimSpace(reason))
	if (strings.Contains(reasonLower, "validator-set-hash-mismatch") ||
		strings.Contains(reasonLower, "validator_set_hash_mismatch") ||
		strings.Contains(reasonLower, "validator-set-root-mismatch") ||
		strings.Contains(reasonLower, "validator_set_root_mismatch") ||
		strings.Contains(reasonLower, "validator-set-mismatch") ||
		strings.Contains(reasonLower, "parent_mismatch") ||
		strings.Contains(reasonLower, "prev_hash_mismatch") ||
		strings.Contains(reasonLower, "queue_prevhash_mismatch") ||
		strings.Contains(reasonLower, "queue_gap") ||
		strings.Contains(reasonLower, "queue_stall") ||
		strings.Contains(reasonLower, "range_response_gap") ||
		strings.Contains(reasonLower, "missing_block") ||
		strings.Contains(reasonLower, "process_block_incomplete") ||
		strings.Contains(reasonLower, "execution_mismatch") ||
		strings.Contains(reasonLower, "state_root_mismatch")) &&
		targetHeight > localHeight {
		// `maxU64` stores the value produced by this operation.
		maxU64 := ^uint64(0)
		if localHeight == maxU64 {
			return maxU64
		}
		// Mismatch recovery must cross the bad next-height boundary. Reapplying a
		// snapshot at the current local height just replays the same stale edge and
		// traps sync in a retry loop.
		return localHeight + 1
	}
	if strings.Contains(reasonLower, "startup_execution_snapshot") ||
		strings.Contains(reasonLower, "execution_snapshot_ledger_unavailable") {
		return 1
	}
	return 0
}

// forceSnapshotResyncNow implements the force snapshot resync now helper.
func (n *Node) forceSnapshotResyncNow(targetHeight uint64, reason string) {
	if n == nil || n.Blockchain == nil {
		return
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := n.Blockchain.Height()
	// `reasonLower` stores the value produced by this operation.
	reasonLower := strings.ToLower(strings.TrimSpace(reason))
	// `isMismatchReason` stores the current position in the related collection.
	isMismatchReason := strings.Contains(reasonLower, "validator-set-hash-mismatch") ||
		strings.Contains(reasonLower, "peer-validator-set-mismatch") ||
		strings.Contains(reasonLower, "validator_set_hash_mismatch") ||
		strings.Contains(reasonLower, "validator-set-mismatch") ||
		strings.Contains(reasonLower, "parent_mismatch") ||
		strings.Contains(reasonLower, "prev_hash_mismatch") ||
		strings.Contains(reasonLower, "queue_gap") ||
		strings.Contains(reasonLower, "queue_stall") ||
		strings.Contains(reasonLower, "queue_prevhash_mismatch") ||
		strings.Contains(reasonLower, "range_response_gap") ||
		strings.Contains(reasonLower, "missing_block") ||
		strings.Contains(reasonLower, "process_block_incomplete") ||
		strings.Contains(reasonLower, "execution_mismatch") ||
		strings.Contains(reasonLower, "state_root_mismatch")
	// `isStartupExecutionReason` stores the current position in the related collection.
	isStartupExecutionReason := strings.Contains(reasonLower, "startup_execution_snapshot") ||
		strings.Contains(reasonLower, "execution_snapshot_ledger_unavailable")
	// `isBehind` stores the current position in the related collection.
	isBehind := targetHeight > localHeight
	if nearSyncTip(localHeight, targetHeight) &&
		!(isMismatchReason && isBehind) &&
		!(isMismatchReason && validatorSetAutohealNearTipForceAfter() > 0) &&
		!isStartupExecutionReason {
		if DebugConsensus {
			fmt.Printf("[SYNC-FORCE] reason=%s local=%d target=%d (near-tip skip)\n",
				reason, localHeight, targetHeight)
		}
		return
	}

	// `cooldown` stores the value produced by this operation.
	cooldown := 5 * time.Second
	if isMismatchReason {
		if isBehind {
			cooldown = 0
		} else {
			cooldown = 15 * time.Second
		}
	} else if isStartupExecutionReason {
		cooldown = 5 * time.Second
	}
	if cooldown > 0 {
		cooldown = SnapshotRetryController{Node: n}.BackoffDelay(cooldown)
	}

	n.syncMu.Lock()
	if cooldown > 0 {
		if !n.lastSyncAttempt.IsZero() && time.Since(n.lastSyncAttempt) < cooldown {
			n.syncMu.Unlock()
			if DebugConsensus {
				fmt.Printf("[SYNC-FORCE] reason=%s local=%d target=%d (cooldown)\n",
					reason, localHeight, targetHeight)
			}
			return
		}
	}
	n.lastSyncAttempt = time.Now()
	n.syncMu.Unlock()
	n.forceSnapshotSyncToHeight(targetHeight, reason)
}

// validatorAuthorityIDsForQuorum implements the validator authority i ds for quorum helper.
func (n *Node) validatorAuthorityIDsForQuorum(height uint64) []string {
	if n == nil || height == 0 {
		return nil
	}
	// `candidates` stores the value produced by this operation.
	candidates := []uint64{height}
	if height > 1 {
		candidates = append(candidates, height-1)
	}
	// `target` tracks the current values while iterating.
	for _, target := range candidates {
		// `out` and `ok` store whether the related condition is satisfied.
		if out, _, ok := n.chainDerivedValidatorAuthorityForHeight(target); ok && len(out) > 0 {
			return canonicalValidatorIDs(out)
		}
		// `frozen` stores the value produced by this operation.
		if frozen := n.frozenValidatorsForHeight(target); len(frozen) > 0 {
			return canonicalValidatorIDs(frozen)
		}
		// `hint` stores the value produced by this operation.
		if hint := n.consensusValidatorsForHeight(target); len(hint) > 0 {
			return canonicalValidatorIDs(hint)
		}
		// `hint` stores the value produced by this operation.
		if hint := n.GetConsensusValidators(int(target)); len(hint) > 0 {
			return canonicalValidatorIDs(hint)
		}
	}
	return nil
}

// snapshotBootstrapAuthorityIDsForQuorum implements the snapshot bootstrap authority i ds for quorum helper.
func (n *Node) snapshotBootstrapAuthorityIDsForQuorum(targetHeight uint64) []string {
	if n == nil || targetHeight == 0 {
		return nil
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := uint64(0)
	if n.Blockchain != nil {
		localHeight = n.Blockchain.Height()
	}
	if localHeight > 0 && targetHeight > localHeight {
		// `frozen` stores the value produced by this operation.
		if frozen := n.frozenValidatorsForHeight(localHeight); len(frozen) > 0 {
			return canonicalValidatorIDs(frozen)
		}
		// `committed` stores the value produced by this operation.
		if committed := n.consensusValidatorsForHeight(localHeight); len(committed) > 0 {
			return canonicalValidatorIDs(committed)
		}
		// `current` stores the value produced by this operation.
		if current := n.GetConsensusValidators(int(localHeight)); len(current) > 0 {
			return canonicalValidatorIDs(current)
		}
	}
	if len(n.GenesisValidators) > 0 {
		return canonicalValidatorIDs(n.GenesisValidators)
	}
	return nil
}

// coreQuorumVotesForExpectedHash implements the core quorum votes for expected hash helper.
func (n *Node) coreQuorumVotesForExpectedHash(height uint64, expectedHash string) (int, int) {
	if n == nil {
		return 0, 0
	}
	// `expected` stores the value produced by this operation.
	expected := strings.ToLower(strings.TrimSpace(expectedHash))
	if expected == "" {
		return 0, 0
	}
	// `authorityIDs` stores the value produced by this operation.
	authorityIDs := n.validatorAuthorityIDsForQuorum(height)
	if len(authorityIDs) == 0 {
		return 0, 0
	}
	// `required` stores the request data being processed.
	required := execQuorumRequired(len(authorityIDs))
	if required <= 0 {
		required = 1
	}

	// `authoritySet` stores the value produced by this operation.
	authoritySet := make(map[string]struct{}, len(authorityIDs))
	// `id` tracks the current position in the related collection.
	for _, id := range authorityIDs {
		// `norm` stores the value produced by this operation.
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		authoritySet[norm] = struct{}{}
	}
	if len(authoritySet) == 0 {
		return 0, required
	}

	// `now` stores the value produced by this operation.
	now := time.Now()
	// `maxAge` stores the value produced by this operation.
	maxAge := validatorLivenessHeartbeatTTL() + validatorLivenessGrace()
	// `voted` stores the value produced by this operation.
	voted := make(map[string]struct{}, len(authoritySet))
	// `freshStatus` stores the value produced by this operation.
	freshStatus := make(map[string]struct{}, len(authoritySet))
	// `selfID` stores the local consensus identity selected from the authority set.
	selfID := n.localConsensusValidatorIDForSet(authorityIDs)
	// `ok` stores whether the related condition is satisfied.
	if _, ok := authoritySet[selfID]; ok && selfID != "" {
		// `localHash` stores the digest used to identify or verify the related data.
		localHash := strings.ToLower(strings.TrimSpace(n.localValidatorSetHashForQuorum(height, expected)))
		if localHash == expected {
			voted[selfID] = struct{}{}
		}
	}

	n.validatorMu.RLock()
	// `id` tracks the current position in the related collection.
	for id := range authoritySet {
		if id == "" || id == selfID {
			continue
		}
		// `st` stores the value produced by this operation.
		st := n.validatorStatus[id]
		if st == nil {
			// `key` and `cand` track the key used to access the related value.
			for key, cand := range n.validatorStatus {
				if normalizeValidatorID(key) == id {
					st = cand
					break
				}
			}
		}
		if st == nil {
			continue
		}
		// `age` stores the value produced by this operation.
		age := now.Sub(st.LastSeen)
		if age < 0 {
			age = 0
		}
		if age > maxAge {
			continue
		}
		freshStatus[id] = struct{}{}
		// `hash` stores the digest used to identify or verify the related data.
		hash := strings.ToLower(strings.TrimSpace(st.ValidatorSetHash))
		if hash == "" || hash != expected {
			continue
		}
		voted[id] = struct{}{}
	}
	n.validatorMu.RUnlock()

	// Fallback: if heartbeat is fresh but status hash is stale/missing, use the
	// latest connected peer-hello hash for that validator. We only accept a peer
	// fallback hash when all connected hello-confirmed peers for that validator
	// agree on the same hash.
	if len(voted) < required {
		// `peerHashByValidator` stores the value produced by this operation.
		peerHashByValidator := make(map[string]string, len(authoritySet))
		// `peerHashConflict` stores the value produced by this operation.
		peerHashConflict := make(map[string]bool, len(authoritySet))

		n.peerStateMu.Lock()
		// `peerID` and `rawID` track the current values while iterating.
		for peerID, rawID := range n.peerToValidator {
			// `id` stores the current position in the related collection.
			id := normalizeValidatorID(rawID)
			if id == "" || id == selfID {
				continue
			}
			// `ok` stores whether the related condition is satisfied.
			if _, ok := authoritySet[id]; !ok {
				continue
			}
			// `ok` stores whether the related condition is satisfied.
			if _, ok := freshStatus[id]; !ok {
				continue
			}
			// `ok` stores whether the related condition is satisfied.
			if _, ok := voted[id]; ok {
				continue
			}
			if !n.connectedPeers[peerID] || !n.peerHelloOK[peerID] {
				continue
			}
			// `hash` stores the digest used to identify or verify the related data.
			hash := strings.ToLower(strings.TrimSpace(n.peerSetHash[peerID]))
			if hash == "" {
				continue
			}
			// `prev` and `ok` store whether the related condition is satisfied.
			if prev, ok := peerHashByValidator[id]; ok && prev != hash {
				peerHashConflict[id] = true
				continue
			}
			peerHashByValidator[id] = hash
		}
		n.peerStateMu.Unlock()

		// `id` and `hash` track the digest used to identify or verify the related data.
		for id, hash := range peerHashByValidator {
			if peerHashConflict[id] {
				continue
			}
			if hash == expected {
				voted[id] = struct{}{}
			}
		}
	}

	return len(voted), required
}

// localValidatorSetHashForQuorum implements the local validator set hash for quorum helper.
func (n *Node) localValidatorSetHashForQuorum(height uint64, expected string) string {
	if n == nil || height == 0 {
		return ""
	}
	expected = strings.ToLower(strings.TrimSpace(expected))
	// `candidates` stores the value produced by this operation.
	candidates := make([]string, 0, 4)
	// `hash` stores the digest used to identify or verify the related data.
	if hash := strings.TrimSpace(n.expectedValidatorSetHash(height)); hash != "" {
		candidates = append(candidates, hash)
	}
	// `hash` and `ok` store whether the related condition is satisfied.
	if hash, ok := n.frozenValidatorSetHash(height); ok {
		candidates = append(candidates, hash)
	}
	// `hash` and `ok` store whether the related condition is satisfied.
	if hash, ok := n.chainValidatorSetHash(height); ok {
		candidates = append(candidates, hash)
	}
	if height > 1 {
		// `hash` and `ok` store whether the related condition is satisfied.
		if hash, ok := n.chainValidatorSetHash(height - 1); ok {
			candidates = append(candidates, hash)
		}
	}
	// `hash` tracks the digest used to identify or verify the related data.
	for _, hash := range candidates {
		// `normalized` stores the value produced by this operation.
		normalized := strings.ToLower(strings.TrimSpace(hash))
		if normalized == "" {
			continue
		}
		if expected == "" || normalized == expected {
			return normalized
		}
	}
	return ""
}

const (
	// `peerDriftTupleLogCooldown` defines the constant value used by this package.
	peerDriftTupleLogCooldown = 3 * time.Second
	// `peerDriftTupleSummaryEvery` defines the constant value used by this package.
	peerDriftTupleSummaryEvery uint64 = 25
	// `peerDriftTupleRetention` defines the constant value used by this package.
	peerDriftTupleRetention = 2 * time.Minute
	// `validatorSetSyncOverrideCooldown` defines whether the related condition is satisfied.
	validatorSetSyncOverrideCooldown = 10 * time.Second
)

// peerDriftTupleKey implements the peer drift tuple key helper.
func peerDriftTupleKey(height uint64, expected, got string) string {
	expected = strings.ToLower(strings.TrimSpace(expected))
	got = strings.ToLower(strings.TrimSpace(got))
	return fmt.Sprintf("%d:%s:%s", height, expected, got)
}

// shouldTriggerValidatorSetSyncOverride implements the should trigger validator set sync override helper.
func (n *Node) shouldTriggerValidatorSetSyncOverride(height uint64, expected, got string) bool {
	if n == nil || height == 0 {
		return false
	}
	// `key` stores the key used to access the related value.
	key := peerDriftTupleKey(height, expected, got)
	if strings.TrimSpace(key) == "" {
		return false
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	n.validatorSetMismatchMu.Lock()
	defer n.validatorSetMismatchMu.Unlock()
	if n.validatorSetSyncOverrideKey == key &&
		!n.validatorSetSyncOverrideAt.IsZero() &&
		now.Sub(n.validatorSetSyncOverrideAt) < validatorSetSyncOverrideCooldown {
		return false
	}
	n.validatorSetSyncOverrideKey = key
	n.validatorSetSyncOverrideAt = now
	return true
}

// recordPeerDriftTuple implements the record peer drift tuple helper.
func (n *Node) recordPeerDriftTuple(height uint64, expected, got string, cooldown time.Duration) (uint64, bool) {
	if n == nil || height == 0 {
		return 0, false
	}
	if cooldown <= 0 {
		cooldown = peerDriftTupleLogCooldown
	}
	// `key` stores the key used to access the related value.
	key := peerDriftTupleKey(height, expected, got)
	if strings.TrimSpace(key) == "" {
		return 0, false
	}

	// `now` stores the value produced by this operation.
	now := time.Now()
	n.validatorSetMismatchMu.Lock()
	defer n.validatorSetMismatchMu.Unlock()

	if n.peerDriftTupleCount == nil {
		n.peerDriftTupleCount = make(map[string]uint64)
	}
	if n.peerDriftTupleLastSeen == nil {
		n.peerDriftTupleLastSeen = make(map[string]time.Time)
	}
	if n.peerDriftTupleLastLog == nil {
		n.peerDriftTupleLastLog = make(map[string]time.Time)
	}

	if len(n.peerDriftTupleLastSeen) > 2048 {
		// `cutoff` stores the value produced by this operation.
		cutoff := now.Add(-peerDriftTupleRetention)
		// `tupleKey` and `seenAt` track the key used to access the related value.
		for tupleKey, seenAt := range n.peerDriftTupleLastSeen {
			if seenAt.Before(cutoff) {
				delete(n.peerDriftTupleLastSeen, tupleKey)
				delete(n.peerDriftTupleLastLog, tupleKey)
				delete(n.peerDriftTupleCount, tupleKey)
			}
		}
	}

	// `count` stores the measured quantity used by this operation.
	count := n.peerDriftTupleCount[key] + 1
	n.peerDriftTupleCount[key] = count
	n.peerDriftTupleLastSeen[key] = now

	// `lastLog` stores the value produced by this operation.
	lastLog := n.peerDriftTupleLastLog[key]
	// `shouldLog` stores the value produced by this operation.
	shouldLog := count == 1
	if !shouldLog && peerDriftTupleSummaryEvery > 0 && count%peerDriftTupleSummaryEvery == 0 {
		shouldLog = true
	}
	if !shouldLog && (lastLog.IsZero() || now.Sub(lastLog) >= cooldown) {
		shouldLog = true
	}
	if shouldLog {
		n.peerDriftTupleLastLog[key] = now
	}
	return count, shouldLog
}

// shouldTreatValidatorSetMismatchAsPeerDrift implements the should treat validator set mismatch as peer drift helper.
func (n *Node) shouldTreatValidatorSetMismatchAsPeerDrift(height uint64, expectedHash string, gotHash string) bool {
	if n == nil {
		return false
	}
	if !validatorSetAutohealStrictCoreQuorum() {
		return false
	}
	// `expected` stores the value produced by this operation.
	expected := strings.TrimSpace(expectedHash)
	// `got` stores the value produced by this operation.
	got := strings.TrimSpace(gotHash)
	if expected == "" || got == "" || strings.EqualFold(expected, got) {
		return false
	}
	// `votes` and `required` store the request data being processed.
	votes, required := n.coreQuorumVotesForExpectedHash(height, expected)
	if required <= 0 || votes < required {
		return false
	}
	// `count` and `shouldLog` store the measured quantity used by this operation.
	count, shouldLog := n.recordPeerDriftTuple(height, expected, got, peerDriftTupleLogCooldown)
	if DebugConsensus && shouldLog {
		fmt.Printf("[AUTOHEAL] peer-drift ignored height=%d expected=%s got=%s validator_votes=%d/%d count=%d\n",
			height, ShortHash(expected), ShortHash(got), votes, required, count)
	}
	n.recordValidatorAutohealWait(fmt.Sprintf("peer_drift_validator_quorum_%d_of_%d", votes, required), height, expected, got)
	return true
}

// handlePersistentPeerDrift handles persistent peer drift.
func (n *Node) handlePersistentPeerDrift(localHeight, mismatchHeight uint64, expected, got, reason string) {
	if n == nil || mismatchHeight == 0 {
		return
	}
	expected = strings.TrimSpace(expected)
	got = strings.TrimSpace(got)
	if expected == "" || got == "" {
		n.maybeSyncToBestObservedHeight("validator_set_peer_drift")
		return
	}
	if n.recordValidatorSetMismatchWithLocal(localHeight, mismatchHeight, expected, got) {
		n.requestConsensusRecomputePause(mismatchHeight, "validator_set_hash_mismatch")
		// `resyncReason` stores the result produced by this operation.
		resyncReason := strings.TrimSpace(reason)
		if resyncReason == "" {
			resyncReason = "validator-set-hash-mismatch-autoheal"
		}
		if shouldForceSnapshotResyncForValidatorSetMismatch(localHeight, mismatchHeight) {
			n.forceSnapshotResyncNow(mismatchHeight, resyncReason)
		} else {
			n.maybeForceNearTipValidatorSetResync(localHeight, mismatchHeight, resyncReason)
		}
	}
	n.maybeSyncToBestObservedHeight("validator_set_peer_drift")
}

// shouldAdoptCoreQuorumValidatorSetHash implements the should adopt core quorum validator set hash helper.
func (n *Node) shouldAdoptCoreQuorumValidatorSetHash(height uint64, expectedHash string, gotHash string) bool {
	if n == nil {
		return false
	}
	if n.freshLateJoinSnapshotAnchorPending() {
		return false
	}
	if !validatorSetAutohealStrictCoreQuorum() {
		return false
	}
	// `expected` stores the value produced by this operation.
	expected := strings.TrimSpace(expectedHash)
	// `got` stores the value produced by this operation.
	got := strings.TrimSpace(gotHash)
	if expected == "" || got == "" || strings.EqualFold(expected, got) {
		return false
	}

	// `gotVotes` and `required` store the request data being processed.
	gotVotes, required := n.coreQuorumVotesForExpectedHash(height, got)
	if required <= 0 || gotVotes < required {
		return false
	}
	// `expectedVotes` stores the value produced by this operation.
	expectedVotes, _ := n.coreQuorumVotesForExpectedHash(height, expected)
	if expectedVotes >= required {
		return false
	}

	if DebugConsensus {
		fmt.Printf("[AUTOHEAL] validator-quorum prefers got hash height=%d expected=%s got=%s votes=%d/%d expected_votes=%d\n",
			height, ShortHash(expected), ShortHash(got), gotVotes, required, expectedVotes)
	}
	n.recordValidatorAutohealWait(
		fmt.Sprintf("validator_quorum_prefers_got_%d_of_%d", gotVotes, required),
		height,
		expected,
		got,
	)
	return true
}

// maybeAdoptCoreQuorumValidatorSetHash implements the maybe adopt core quorum validator set hash helper.
func (n *Node) maybeAdoptCoreQuorumValidatorSetHash(height uint64, expectedHash string, gotHash string) bool {
	if n != nil && n.freshLateJoinSnapshotAnchorPending() {
		// `expected` stores the value produced by this operation.
		expected := strings.TrimSpace(expectedHash)
		// `got` stores the value produced by this operation.
		got := strings.TrimSpace(gotHash)
		n.recordValidatorAutohealWait("late_join_snapshot_anchor_pending", height, expected, got)
		if DebugConsensus {
			fmt.Printf("[AUTOHEAL] late_join pending adopt mismatch_h=%d expected=%s got=%s\n",
				height, ShortHash(expected), ShortHash(got))
		}
		return false
	}
	if !n.shouldAdoptCoreQuorumValidatorSetHash(height, expectedHash, gotHash) {
		return false
	}
	// `ok` and `reason` store whether the related condition is satisfied.
	if ok, reason := n.autohealSafetyAllowsMutation(height, gotHash); !ok {
		// `waitReason` stores the value produced by this operation.
		waitReason := "strict_autofix_guard_" + strings.TrimSpace(reason)
		n.recordValidatorAutohealWait(waitReason, height, expectedHash, gotHash)
		if DebugConsensus {
			fmt.Printf("[AUTOHEAL] safety_guard blocked adopt mismatch_h=%d expected=%s got=%s reason=%s\n",
				height, ShortHash(expectedHash), ShortHash(gotHash), strings.TrimSpace(reason))
		}
		return false
	}
	if !n.reconcileFrozenValidatorSetHash(height, gotHash) {
		return false
	}
	// `progressHeight` stores the value produced by this operation.
	progressHeight := height
	if n.Blockchain != nil && n.Blockchain.Height() > progressHeight {
		progressHeight = n.Blockchain.Height()
	}
	n.recordValidatorAutohealSuccess(progressHeight, "validator_set_hash_reconciled_core_quorum")
	return true
}

// allowValidatorSetRepair implements the allow validator set repair helper.
func (n *Node) allowValidatorSetRepair(height uint64, expected string, got string) bool {
	if n == nil || height == 0 || expected == "" || got == "" {
		return false
	}

	// `now` stores the value produced by this operation.
	now := time.Now()
	// `window` stores the value produced by this operation.
	window := ValidatorSetMismatchResyncWindow
	if window <= 0 {
		window = 30 * time.Second
	}

	// `key` stores the key used to access the related value.
	key := fmt.Sprintf("%d:%s:%s", height, expected, got)

	n.validatorSetMismatchMu.Lock()
	defer n.validatorSetMismatchMu.Unlock()

	if !n.validatorSetRepairBackoffTil.IsZero() && now.Before(n.validatorSetRepairBackoffTil) {
		n.validatorAutohealState = "backoff"
		n.validatorAutohealLastReason = "repair_backoff_active"
		return false
	}

	// `reset` stores the result produced by this operation.
	reset := false
	if n.validatorSetRepairKey == "" || n.validatorSetRepairKey != key {
		reset = true
	} else if n.validatorSetRepairWindow.IsZero() || now.Sub(n.validatorSetRepairWindow) > window {
		reset = true
	}

	if reset {
		n.validatorSetRepairKey = key
		n.validatorSetRepairAt = time.Time{}
		n.validatorSetRepairWindow = now
		n.validatorSetRepairAttempts = 0
	}

	if !n.validatorSetRepairAt.IsZero() && now.Sub(n.validatorSetRepairAt) < ValidatorSetRepairCooldown {
		return false
	}

	n.validatorSetRepairAt = now
	n.validatorSetRepairAttempts++
	if ValidatorSetRepairMaxAttempts > 0 && n.validatorSetRepairAttempts > ValidatorSetRepairMaxAttempts {
		n.validatorSetRepairBackoffTil = now.Add(ValidatorSetRepairBackoff)
		n.validatorSetRepairAttempts = 0
		n.validatorAutohealState = "backoff"
		n.validatorAutohealLastReason = "repair_backoff_started"
		return false
	}
	n.validatorAutohealState = "repairing"
	n.validatorAutohealLastReason = "repair_attempt_started"

	return true
}

// recordValidatorSetMismatch implements the record validator set mismatch helper.
func (n *Node) recordValidatorSetMismatch(height uint64, expected string, got string) bool {
	return n.recordValidatorSetMismatchWithLocal(0, height, expected, got)
}

// shouldDeferValidatorSetMismatchDuringSync implements the should defer validator set mismatch during sync helper.
func (n *Node) shouldDeferValidatorSetMismatchDuringSync(localHeight uint64, mismatchHeight uint64, expected string, got string) bool {
	if n == nil || mismatchHeight == 0 {
		return false
	}
	if n.Consensus == nil {
		return false
	}
	n.Consensus.mu.Lock()
	// `syncing` stores the value produced by this operation.
	syncing := n.Consensus.Syncing
	n.Consensus.mu.Unlock()
	if !syncing {
		return false
	}
	// `effectiveLocal` stores the value produced by this operation.
	effectiveLocal := localHeight
	if effectiveLocal == 0 && n.Blockchain != nil {
		effectiveLocal = n.Blockchain.Height()
	}
	// `finalized` stores the value produced by this operation.
	if finalized := n.getFinalizedHeight(); finalized > effectiveLocal {
		effectiveLocal = finalized
	}
	if mismatchHeight <= effectiveLocal {
		return false
	}
	// Mainnet safety: snapshot-first on validator-set mismatch when local is behind.
	// Do not defer this path during sync; deferral can cause persistent mismatch loops.
	if shouldForceSnapshotResyncForValidatorSetMismatch(effectiveLocal, mismatchHeight) {
		return false
	}
	// `lag` stores the value produced by this operation.
	lag := mismatchHeight - effectiveLocal
	// Keep near-tip mismatch handling untouched; only defer large-lag catch-up churn.
	if lag <= validatorLivenessMaxHeightDriftBlocks() {
		return false
	}
	// `count` and `shouldLog` store the measured quantity used by this operation.
	count, shouldLog := n.recordPeerDriftTuple(mismatchHeight, expected, got, peerDriftTupleLogCooldown)
	n.recordValidatorAutohealWait(fmt.Sprintf("sync_catchup_lag_%d", lag), mismatchHeight, expected, got)
	if DebugConsensus && shouldLog {
		fmt.Printf("[AUTOHEAL] mismatch deferred height=%d local=%d lag=%d expected=%s got=%s count=%d reason=sync_catchup\n",
			mismatchHeight,
			effectiveLocal,
			lag,
			ShortHash(expected),
			ShortHash(got),
			count,
		)
	}
	return true
}

// recordValidatorSetMismatchWithLocal implements the record validator set mismatch with local helper.
func (n *Node) recordValidatorSetMismatchWithLocal(localHeight uint64, height uint64, expected string, got string) bool {
	if n == nil || ValidatorSetMismatchResyncThreshold <= 0 {
		return false
	}
	if n.shouldDeferValidatorSetMismatchDuringSync(localHeight, height, expected, got) {
		return false
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	n.validatorSetMismatchMu.Lock()
	defer n.validatorSetMismatchMu.Unlock()
	// `repairKey` stores the key used to access the related value.
	repairKey := fmt.Sprintf("%d:%s:%s", height, expected, got)
	if n.validatorSetRepairKey == repairKey &&
		!n.validatorSetRepairAt.IsZero() &&
		now.Sub(n.validatorSetRepairAt) < ValidatorSetRepairCooldown {
		// Coalesce repeated mismatch spam for the same tuple while a repair
		// attempt is still in cooldown window.
		return false
	}

	// `triggerThreshold` stores the value produced by this operation.
	triggerThreshold := ValidatorSetMismatchResyncThreshold
	// `nearTip` stores the value produced by this operation.
	nearTip := localHeight > 0 && height == localHeight+1
	if nearTip {
		// `nearTipForce` stores the value produced by this operation.
		if nearTipForce := validatorSetAutohealNearTipForceAfter(); nearTipForce > 0 {
			if triggerThreshold <= 0 || nearTipForce < triggerThreshold {
				triggerThreshold = nearTipForce
			}
		}
	}
	if triggerThreshold <= 0 {
		triggerThreshold = 1
	}

	// `reset` stores the result produced by this operation.
	reset := false
	if n.validatorSetMismatchSince.IsZero() {
		reset = true
	} else if ValidatorSetMismatchResyncWindow > 0 && now.Sub(n.validatorSetMismatchSince) > ValidatorSetMismatchResyncWindow {
		reset = true
	} else if expected != n.validatorSetMismatchExpected || got != n.validatorSetMismatchGot {
		reset = true
	}

	if reset {
		n.validatorSetMismatchCnt = 0
		n.validatorSetMismatchSince = now
		n.validatorSetMismatchExpected = expected
		n.validatorSetMismatchGot = got
		n.validatorSetMismatchHeight = height
	}

	n.validatorSetMismatchCnt++
	n.validatorSetMismatchHeight = height
	n.validatorAutohealState = "mismatch_detected"
	n.validatorAutohealLastReason = "validator_set_hash_mismatch"
	if DebugConsensus {
		// `action` stores the value produced by this operation.
		action := "recorded"
		if n.validatorSetMismatchCnt >= triggerThreshold {
			action = "trigger_repair"
		}
		fmt.Printf("[AUTOHEAL] mismatch height=%d expected=%s got=%s action=%s count=%d threshold=%d\n",
			height,
			ShortHash(expected),
			ShortHash(got),
			action,
			n.validatorSetMismatchCnt,
			triggerThreshold,
		)
	}

	if n.validatorSetMismatchCnt >= triggerThreshold {
		if validatorSetAutohealStrictCoreQuorum() &&
			n.validatorSetSyncOverrideKey == repairKey &&
			!n.validatorSetSyncOverrideAt.IsZero() &&
			now.Sub(n.validatorSetSyncOverrideAt) < validatorSetSyncOverrideCooldown {
			return false
		}
		n.validatorSetSyncOverrideKey = repairKey
		n.validatorSetSyncOverrideAt = now
		n.validatorSetMismatchCnt = 0
		n.validatorSetMismatchSince = now
		return true
	}
	return false
}

// recordValidatorAutohealWait implements the record validator autoheal wait helper.
func (n *Node) recordValidatorAutohealWait(reason string, mismatchHeight uint64, expected string, got string) {
	if n == nil {
		return
	}
	n.validatorSetMismatchMu.Lock()
	defer n.validatorSetMismatchMu.Unlock()
	n.validatorAutohealState = "waiting_core_quorum"
	if strings.TrimSpace(reason) != "" {
		n.validatorAutohealLastReason = strings.TrimSpace(reason)
	}
	if mismatchHeight > 0 {
		n.validatorSetMismatchHeight = mismatchHeight
	}
	if strings.TrimSpace(expected) != "" {
		n.validatorSetMismatchExpected = expected
	}
	if strings.TrimSpace(got) != "" {
		n.validatorSetMismatchGot = got
	}
}

// recordValidatorAutohealSuccess implements the record validator autoheal success helper.
func (n *Node) recordValidatorAutohealSuccess(height uint64, reason string) {
	if n == nil {
		return
	}
	n.validatorSetMismatchMu.Lock()
	defer n.validatorSetMismatchMu.Unlock()
	n.validatorAutohealState = "healthy"
	if strings.TrimSpace(reason) == "" {
		n.validatorAutohealLastReason = "autoheal_success"
	} else {
		n.validatorAutohealLastReason = strings.TrimSpace(reason)
	}
	n.validatorAutohealLastSuccessHeight = height
	n.validatorSetMismatchCnt = 0
	n.validatorSetMismatchSince = time.Time{}
	n.validatorSetMismatchHeight = 0
	n.validatorSetMismatchExpected = ""
	n.validatorSetMismatchGot = ""
}

// validatorAutohealStatusSnapshot implements the validator autoheal status snapshot helper.
func (n *Node) validatorAutohealStatusSnapshot() (state string, reason string, mismatchHeight uint64, expected string, got string, successHeight uint64) {
	if n == nil {
		return "unknown", "node_nil", 0, "", "", 0
	}
	n.validatorSetMismatchMu.Lock()
	defer n.validatorSetMismatchMu.Unlock()
	state = strings.TrimSpace(n.validatorAutohealState)
	reason = strings.TrimSpace(n.validatorAutohealLastReason)
	if state == "" {
		if !n.validatorSetRepairBackoffTil.IsZero() && time.Now().Before(n.validatorSetRepairBackoffTil) {
			state = "backoff"
		} else if n.validatorSetMismatchHeight > 0 {
			state = "mismatch_detected"
		} else {
			state = "idle"
		}
	}
	if reason == "" {
		reason = "none"
	}
	return state, reason, n.validatorSetMismatchHeight, n.validatorSetMismatchExpected, n.validatorSetMismatchGot, n.validatorAutohealLastSuccessHeight
}

// maybeFinalizeValidatorAutohealSuccess implements the maybe finalize validator autoheal success helper.
func (n *Node) maybeFinalizeValidatorAutohealSuccess(progressHeight uint64) {
	if n == nil || progressHeight == 0 {
		return
	}
	n.validatorSetMismatchMu.Lock()
	defer n.validatorSetMismatchMu.Unlock()
	if n.validatorSetMismatchHeight == 0 {
		return
	}
	if progressHeight <= n.validatorSetMismatchHeight {
		return
	}
	if strings.TrimSpace(n.validatorSetMismatchExpected) == "" || strings.TrimSpace(n.validatorSetMismatchGot) == "" {
		return
	}
	if !strings.EqualFold(n.validatorSetMismatchExpected, n.validatorSetMismatchGot) {
		return
	}
	n.validatorAutohealState = "healthy"
	n.validatorAutohealLastReason = "mismatch_cleared_after_progress"
	n.validatorAutohealLastSuccessHeight = progressHeight
	n.validatorSetMismatchCnt = 0
	n.validatorSetMismatchSince = time.Time{}
	n.validatorSetMismatchHeight = 0
	n.validatorSetMismatchExpected = ""
	n.validatorSetMismatchGot = ""
}

// setValidatorStartupCheckStatus implements the set validator startup check status helper.
func (n *Node) setValidatorStartupCheckStatus(ok bool, height uint64, expected string, got string, reason string) {
	if n == nil {
		return
	}
	n.validatorSetMismatchMu.Lock()
	n.validatorStartupCheckOK = ok
	n.validatorStartupCheckHeight = height
	n.validatorStartupCheckExpected = strings.TrimSpace(expected)
	n.validatorStartupCheckGot = strings.TrimSpace(got)
	n.validatorStartupCheckReason = strings.TrimSpace(reason)
	n.validatorStartupCheckAt = time.Now()
	n.validatorSetMismatchMu.Unlock()
}

// validatorStartupCheckStatusSnapshot implements the validator startup check status snapshot helper.
func (n *Node) validatorStartupCheckStatusSnapshot() (bool, uint64, string, string, string) {
	if n == nil {
		return false, 0, "", "", "node_unavailable"
	}
	n.validatorSetMismatchMu.Lock()
	defer n.validatorSetMismatchMu.Unlock()
	return n.validatorStartupCheckOK,
		n.validatorStartupCheckHeight,
		n.validatorStartupCheckExpected,
		n.validatorStartupCheckGot,
		n.validatorStartupCheckReason
}

// validatorStartupCheckStatusCurrent implements the validator startup check status current helper.
func (n *Node) validatorStartupCheckStatusCurrent() (bool, uint64, string, string, string) {
	if n == nil {
		return false, 0, "", "", "node_unavailable"
	}
	// `ok`, `height`, `expected`, `got`, and `reason` store whether the related condition is satisfied.
	ok, height, expected, got, reason := n.validatorStartupCheckStatusSnapshot()

	// `finalized` stores the value produced by this operation.
	finalized := n.getFinalizedHeight()
	if finalized == 0 && n.Blockchain != nil {
		finalized = n.Blockchain.FinalizedHeight()
		if finalized == 0 {
			finalized = n.Blockchain.Height()
		}
	}
	// `targetHeight` stores the value produced by this operation.
	targetHeight := finalized
	if finalized > 0 && validatorSetCommitmentV2EnabledAt(finalized) {
		targetHeight = finalized + 1
	}
	if strings.TrimSpace(reason) == "" ||
		strings.EqualFold(strings.TrimSpace(reason), "startup_validator_set_check_pending") ||
		height < targetHeight {
		_, _ = n.startupValidatorSetSelfCheck()
		return n.validatorStartupCheckStatusSnapshot()
	}
	return ok, height, expected, got, reason
}

// logStartupCommitmentCheck implements the log startup commitment check helper.
func (n *Node) logStartupCommitmentCheck(checkHeight uint64, expected string, expectedSource string) {
	if n == nil || !DebugConsensus {
		return
	}
	expected = strings.TrimSpace(expected)
	// `source` stores the value produced by this operation.
	source := displayExpectedValidatorSetSource(expectedSource)
	// `key` stores the key used to access the related value.
	key := fmt.Sprintf("startup_commitment:v2:%d:%s:%s:%s",
		checkHeight,
		strings.ToLower(expected),
		source,
		ShortHash(expected),
	)
	if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
		fmt.Printf("[STARTUP-COMMITMENT] mode=v2 commitment_height=%d check_h=%d expected=%s source=%s\n",
			ValidatorSetCommitmentV2Height, checkHeight, ShortHash(expected), source)
	}
	if normalizeExpectedValidatorSetSource(expectedSource) == "bootstrap_parent_fallback" {
		// `fallbackKey` stores the key used to access the related value.
		fallbackKey := fmt.Sprintf("startup_commitment_fallback:%d:%s:%s",
			checkHeight,
			strings.ToLower(expected),
			normalizeExpectedValidatorSetSource(expectedSource),
		)
		if n.shouldLogLivenessReason(fallbackKey, livenessReasonLogCooldown) {
			fmt.Printf("[STARTUP-COMMITMENT-FALLBACK] check_h=%d source=%s hash=%s\n",
				checkHeight, displayExpectedValidatorSetSource(expectedSource), ShortHash(expected))
		}
	}
}

// buildExecutionGenesisLedgerFromGenesis builds execution genesis ledger from genesis.
func buildExecutionGenesisLedgerFromGenesis(genesis *Genesis) (Ledger, error) {
	if genesis == nil {
		genesis = &Genesis{}
	}
	// `ledger` stores the value produced by this operation.
	ledger := GenesisLedger()
	if err := applyGenesisBalanceAllocations(&ledger, genesis); err != nil {
		return Ledger{}, err
	}
	applyGenesisRewardWalletBindings(&ledger, genesis)
	// `err` stores the error produced by this operation.
	if err := applyGenesisStakes(&ledger, genesis); err != nil {
		return Ledger{}, err
	}
	// `genesisValidatorBalance` stores the value produced by this operation.
	genesisValidatorBalance := int(ConsensusValidatorMinStake)
	if genesisValidatorBalance < 0 {
		genesisValidatorBalance = 0
	}
	// `vid` tracks the current values while iterating.
	for vid := range genesis.Validators {
		// `ok` stores whether the related condition is satisfied.
		if _, ok := genesis.GenesisStakes[normalizeValidatorID(vid)]; ok {
			continue
		}
		// `current` stores the value produced by this operation.
		current := getBalance(ledger, CoinSymbol, vid)
		if current >= genesisValidatorBalance {
			continue
		}
		if genesisValidatorBalance == 0 {
			break
		}
		// `poolKey` stores the key used to access the related value.
		poolKey := balanceKey(CoinSymbol, VALIDATOR_BOOTSTRAP_POOL)
		// `available` stores the value produced by this operation.
		available := ledger.Balances[poolKey]
		// `amount` stores the value produced by this operation.
		amount := genesisValidatorBalance - current
		if available < amount {
			amount = available
		}
		if amount <= 0 {
			break
		}
		addBalance(&ledger, CoinSymbol, vid, amount)
		addBalance(&ledger, CoinSymbol, VALIDATOR_BOOTSTRAP_POOL, -amount)
	}
	ensureTreasuryAndRewards(&ledger)
	if err := validateGenesisFixedSupply(&ledger, genesis); err != nil {
		return Ledger{}, err
	}
	return ledger, nil
}

// rememberStartupGenesisValidators implements the remember startup genesis validators helper.
func (n *Node) rememberStartupGenesisValidators(genesis *Genesis) {
	if n == nil || genesis == nil || len(genesis.Validators) == 0 {
		return
	}
	// `ids` stores the current position in the related collection.
	ids := canonicalValidatorIDsFromMapKeys(genesis.Validators)
	if len(ids) > 0 {
		n.GenesisValidators = ids
	}
	validatorPubKeysMu.Lock()
	// `vid` and `pkHex` track the current values while iterating.
	for vid, pkHex := range genesis.Validators {
		// `id` stores the current position in the related collection.
		id := normalizeValidatorID(vid)
		if id == "" {
			continue
		}
		// `pkBytes` and `err` store the error produced by this operation.
		pkBytes, err := hex.DecodeString(strings.TrimSpace(pkHex))
		if err != nil || len(pkBytes) != ed25519.PublicKeySize {
			continue
		}
		// `pub` stores the value produced by this operation.
		pub := ed25519.PublicKey(append([]byte(nil), pkBytes...))
		GenesisValidatorPubKeys[id] = pub
		ValidatorPubKeys[id] = pub
	}
	validatorPubKeysMu.Unlock()
}

// buildStartupExecutionGenesisLedger builds startup execution genesis ledger.
func (n *Node) buildStartupExecutionGenesisLedger() (Ledger, error) {
	if n == nil {
		return Ledger{}, fmt.Errorf("node_unavailable")
	}
	// `path` stores the value produced by this operation.
	path := resolveGenesisPath(n.DataDir)
	// `genesis` and `err` store the error produced by this operation.
	genesis, err := loadGenesisFromDisk(path)
	if err != nil {
		return Ledger{}, fmt.Errorf("genesis_read_failed path=%s err=%w", path, err)
	}
	n.rememberStartupGenesisValidators(genesis)
	return buildExecutionGenesisLedgerFromGenesis(genesis)
}

// startupExecutionBootstrapRegistrySnapshot implements the startup execution bootstrap registry snapshot helper.
func (n *Node) startupExecutionBootstrapRegistrySnapshot(height uint64) map[string]ValidatorRecord {
	if n == nil {
		return nil
	}
	// `live` stores the value produced by this operation.
	live := copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
	// `ids` stores the current position in the related collection.
	ids := canonicalValidatorIDs(append([]string{}, n.GenesisValidators...))
	if len(ids) == 0 {
		ids = canonicalValidatorIDsFromMapKeys(live)
	}
	if len(ids) == 0 {
		return live
	}
	// `out` stores the result produced by this operation.
	out := make(map[string]ValidatorRecord, len(ids))
	// `id` tracks the current position in the related collection.
	for _, id := range ids {
		if id == "" {
			continue
		}
		// `rec` and `ok` store whether the related condition is satisfied.
		rec, ok := live[id]
		if !ok {
			rec = ValidatorRecord{
				ID:               id,
				ConsensusPubKey:  consensusPubKeyHexForValidatorID(id),
				GovernanceSigner: validatorRecordBootstrapGovernanceSeed(id),
				Stake:            ConsensusValidatorMinStake,
				Reputation:       protocolValidatorReputationInitialValue(),
				Status:           ValidatorPending,
				JoinHeight:       height,
				ActiveHeights:    make([]uint64, 0),
				SignedHeights:    make([]uint64, 0),
			}
		} else {
			rec.ID = normalizeValidatorID(rec.ID)
			if rec.ID == "" {
				rec.ID = id
			}
			if rec.ConsensusPubKey == "" {
				rec.ConsensusPubKey = consensusPubKeyHexForValidatorID(id)
			}
			if validatorRecordBootstrapGovernanceSeed(id) {
				rec.GovernanceSigner = true
			}
			if !validatorPassesStakeGate(rec.ID, rec.Stake) {
				rec.Stake = ConsensusValidatorMinStake
			}
			if rec.JoinHeight == 0 {
				rec.JoinHeight = height
			}
		}
		// `updated` stores the value produced by this operation.
		updated := rec
		ValidatorStateMachine{}.Update(&updated, height)
		out[id] = updated
	}
	if len(out) == 0 {
		return live
	}
	return out
}

// authoritativeExecutionLedgerAvailable implements the authoritative execution ledger available helper.
func (n *Node) authoritativeExecutionLedgerAvailable(height uint64) bool {
	if n == nil || height == 0 {
		return false
	}
	var (
		// `block` stores the synchronization state protecting shared data.
		block Block
		// `ok` stores whether the related condition is satisfied.
		ok bool
	)
	if n.Blockchain != nil {
		block, ok = n.Blockchain.GetBlock(height)
	}
	if !ok {
		block, ok = n.LoadBlock(int(height))
	}
	if !ok || strings.TrimSpace(block.StateRoot) == "" {
		return false
	}
	// `cachedLedger` and `ok` store whether the related condition is satisfied.
	cachedLedger, ok := n.cachedExecutionSnapshotLedger(height)
	// `ledgerMatchesBlock` stores the synchronization state protecting shared data.
	ledgerMatchesBlock := func(ledger Ledger) bool {
		if !ledgerHasInitializedBacking(ledger) {
			return false
		}
		// `ledgerHash` stores the digest used to identify or verify the related data.
		ledgerHash := HashLedger(ledger)
		// `expectedRoot` stores the digest used to identify or verify the related data.
		expectedRoot := ComputeExecHashVersioned(block, ledgerHash, executionStateRootVersionForHeight(block.ID))
		return strings.EqualFold(strings.TrimSpace(expectedRoot), strings.TrimSpace(block.StateRoot))
	}
	if ok && ledgerMatchesBlock(cachedLedger) {
		return true
	}
	if ledgerMatchesBlock(n.ExecutionLedger) {
		n.cacheExecutionSnapshotLedger(height, n.ExecutionLedger)
		return true
	}
	if ledgerMatchesBlock(n.Ledger) {
		n.cacheExecutionSnapshotLedger(height, n.Ledger)
		return true
	}
	return false
}

// markExecutionSnapshotReadyHeight implements the mark execution snapshot ready height helper.
func (n *Node) markExecutionSnapshotReadyHeight(height uint64) {
	if n == nil || height == 0 {
		return
	}
	n.executionSnapshotRebuildMu.Lock()
	if height > n.executionSnapshotRebuildReadyHeight {
		n.executionSnapshotRebuildReadyHeight = height
	}
	n.executionSnapshotRebuildFailedHeight = 0
	n.executionSnapshotRebuildLastErr = ""
	n.executionSnapshotRebuildMu.Unlock()
}

// markLiveCommittedExecutionSnapshotReadyHeight implements the mark live committed execution snapshot ready height helper.
func (n *Node) markLiveCommittedExecutionSnapshotReadyHeight(height uint64) {
	if n == nil || height == 0 {
		return
	}
	n.executionSnapshotRebuildMu.Lock()
	if height > n.executionSnapshotRebuildReadyHeight {
		n.executionSnapshotRebuildReadyHeight = height
	}
	if height > n.executionSnapshotLiveCommitHeight {
		n.executionSnapshotLiveCommitHeight = height
	}
	n.executionSnapshotRebuildFailedHeight = 0
	n.executionSnapshotRebuildLastErr = ""
	n.executionSnapshotRebuildMu.Unlock()
}

// startupExecutionSnapshotPeerCount implements the startup execution snapshot peer count helper.
func (n *Node) startupExecutionSnapshotPeerCount() int {
	if n == nil || n.Host == nil {
		return 0
	}
	return len(n.Host.Network().Peers())
}

// startupExecutionSnapshotShouldPreferNetworkRecovery implements the startup execution snapshot should prefer network recovery helper.
func (n *Node) startupExecutionSnapshotShouldPreferNetworkRecovery() bool {
	if n == nil {
		return false
	}
	if n.startupExecutionSnapshotPeerCount() > 0 {
		return true
	}
	return len(ConfigSeeds) > 0 || len(ConfigPersistentPeers) > 0
}

// startupExecutionSnapshotHasFullHistory implements the startup execution snapshot has full history helper.
func (n *Node) startupExecutionSnapshotHasFullHistory(height uint64) bool {
	if n == nil || height == 0 {
		return false
	}
	return n.startupExecutionSnapshotHasBlockRange(1, height)
}

// startupExecutionSnapshotHasBlockRange implements the startup execution snapshot has block range helper.
func (n *Node) startupExecutionSnapshotHasBlockRange(start uint64, end uint64) bool {
	if n == nil || start == 0 || end == 0 || start > end {
		return false
	}
	// `h` stores the value produced by this operation.
	for h := start; h <= end; h++ {
		// `ok` stores whether the related condition is satisfied.
		if _, ok := n.LoadBlock(int(h)); !ok {
			return false
		}
	}
	return true
}

// startupExecutionTrustedBaseSnapshot implements the startup execution trusted base snapshot helper.
func (n *Node) startupExecutionTrustedBaseSnapshot(height uint64) (*StateSnapshot, uint64, bool) {
	if n == nil || height == 0 {
		return nil, 0, false
	}
	// `start` stores the value produced by this operation.
	start := height
	// `latest` and `err` store the error produced by this operation.
	if latest, err := n.GetLatestSnapshot(); err == nil && latest != nil && latest.Height > 0 {
		if latest.Height <= height {
			// `snap` and `ok` store whether the related condition is satisfied.
			if snap, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(latest.Height); ok && snap != nil {
				return snap, latest.Height, true
			}
			start = latest.Height
		}
	}
	// `h` stores the value produced by this operation.
	for h := start; h > 0; h-- {
		// `snap` and `ok` store whether the related condition is satisfied.
		if snap, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(h); ok && snap != nil {
			return snap, h, true
		}
		if h == 1 {
			break
		}
	}
	return nil, 0, false
}

// startupExecutionSnapshotCanRebuildLocally implements the startup execution snapshot can rebuild locally helper.
func (n *Node) startupExecutionSnapshotCanRebuildLocally(height uint64) bool {
	if n == nil || height == 0 {
		return false
	}
	n.commitMu.Lock()
	// `committedHeight` stores the value produced by this operation.
	committedHeight := n.committedHeight
	n.commitMu.Unlock()
	if committedHeight < height {
		return false
	}
	// `baseHeight` and `ok` store whether the related condition is satisfied.
	if _, baseHeight, ok := n.startupExecutionTrustedBaseSnapshot(height); ok {
		if baseHeight >= height {
			return true
		}
		if n.startupExecutionSnapshotHasBlockRange(baseHeight+1, height) {
			return true
		}
	}
	return n.startupExecutionSnapshotHasFullHistory(height)
}

// ensureDeterministicRegistryHistoryUpTo implements the ensure deterministic registry history up to helper.
func (n *Node) ensureDeterministicRegistryHistoryUpTo(height uint64) bool {
	if n == nil || height == 0 || n.DB == nil || n.DB.State == nil {
		return false
	}
	// `latest` and `ok` store whether the related condition is satisfied.
	if latest, ok := n.loadLatestValidatorRegistrySnapshotHeight(); ok && latest >= height {
		return true
	}
	if !n.startupExecutionSnapshotCanRebuildLocally(height) {
		return false
	}

	n.registryHistoryRebuildMu.Lock()
	// `latest` and `ok` store whether the related condition is satisfied.
	if latest, ok := n.loadLatestValidatorRegistrySnapshotHeight(); ok && latest >= height {
		n.registryHistoryRebuildReadyHeight = latest
		n.registryHistoryRebuildMu.Unlock()
		return true
	}
	if n.registryHistoryRebuildReadyHeight >= height {
		n.registryHistoryRebuildMu.Unlock()
		return true
	}
	if n.registryHistoryRebuildTarget >= height {
		n.registryHistoryRebuildMu.Unlock()
		return false
	}
	n.registryHistoryRebuildTarget = height
	n.registryHistoryRebuildMu.Unlock()

	// `err` stores the error produced by this operation.
	err := n.rebuildTrustedExecutionSnapshotsUpTo(height)

	n.registryHistoryRebuildMu.Lock()
	if n.registryHistoryRebuildTarget == height {
		n.registryHistoryRebuildTarget = 0
	}
	if err != nil {
		n.registryHistoryRebuildFailedHeight = height
		n.registryHistoryRebuildLastErr = err.Error()
		n.registryHistoryRebuildMu.Unlock()
		if n.shouldLogLivenessReason(fmt.Sprintf("registry_history_rebuild_failed:%d:%s", height, err.Error()), livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-HISTORY-REBUILD] height=%d status=failed err=%v", height, err)
		}
		return false
	}
	if height > n.registryHistoryRebuildReadyHeight {
		n.registryHistoryRebuildReadyHeight = height
	}
	n.registryHistoryRebuildFailedHeight = 0
	n.registryHistoryRebuildLastErr = ""
	n.registryHistoryRebuildMu.Unlock()

	if n.shouldLogLivenessReason(fmt.Sprintf("registry_history_rebuild_done:%d", height), livenessReasonLogCooldown) {
		log.Printf("[REGISTRY-HISTORY-REBUILD] height=%d status=ok", height)
	}
	// `latest` and `ok` store whether the related condition is satisfied.
	if latest, ok := n.loadLatestValidatorRegistrySnapshotHeight(); ok && latest >= height {
		return true
	}
	return n.registrySnapshotExists(height)
}

// `registryHistoryRebuildScheduleCooldown` defines the constant value used by this package.
const registryHistoryRebuildScheduleCooldown = 5 * time.Second

// maybeScheduleRegistryHistoryRebuild implements the maybe schedule registry history rebuild helper.
func (n *Node) maybeScheduleRegistryHistoryRebuild(height uint64, reason string) bool {
	if n == nil || height == 0 || n.DB == nil || n.DB.State == nil {
		return false
	}
	// `trimmedReason` stores the value produced by this operation.
	trimmedReason := strings.TrimSpace(reason)
	if trimmedReason == "" {
		trimmedReason = "unspecified"
	}

	// `target` stores the value produced by this operation.
	target := height
	if n.Blockchain != nil {
		// `chainHeight` stores the value produced by this operation.
		chainHeight := n.Blockchain.Height()
		if chainHeight > 0 && chainHeight > height {
			// `batch` stores the value produced by this operation.
			batch := syncDeltaReplayBatchBlocks()
			if batch == 0 {
				batch = 1024
			}
			if batch > 0 {
				// `maxUint` stores the value produced by this operation.
				maxUint := ^uint64(0)
				if height <= maxUint-(batch-1) {
					target = height + batch - 1
				}
			}
			if target > chainHeight {
				target = chainHeight
			}
		}
	}

	n.registryHistoryRebuildMu.Lock()
	// `readyHeight` stores the value produced by this operation.
	readyHeight := n.registryHistoryRebuildReadyHeight
	// `targetHeight` stores the value produced by this operation.
	targetHeight := n.registryHistoryRebuildTarget
	// `lastScheduledAt` stores the value produced by this operation.
	lastScheduledAt := n.registryHistoryRebuildLastScheduleAt
	// `lastScheduledHeight` stores the value produced by this operation.
	lastScheduledHeight := n.registryHistoryRebuildLastScheduledHeight
	// `failedHeight` stores the value produced by this operation.
	failedHeight := n.registryHistoryRebuildFailedHeight
	if readyHeight >= target || targetHeight >= target {
		n.registryHistoryRebuildMu.Unlock()
		return false
	}
	if lastScheduledHeight >= target && failedHeight != target {
		n.registryHistoryRebuildMu.Unlock()
		return false
	}
	if time.Since(lastScheduledAt) < registryHistoryRebuildScheduleCooldown {
		n.registryHistoryRebuildMu.Unlock()
		return false
	}
	if target > n.registryHistoryRebuildLastScheduledHeight {
		n.registryHistoryRebuildLastScheduledHeight = target
	}
	n.registryHistoryRebuildLastScheduleAt = time.Now()
	n.registryHistoryRebuildMu.Unlock()

	if n.shouldLogLivenessReason(fmt.Sprintf("registry_history_rebuild_schedule:%d:%s", target, trimmedReason), livenessReasonLogCooldown) {
		log.Printf("[REGISTRY-HISTORY-REBUILD] height=%d status=scheduled reason=%s", target, trimmedReason)
	}

	go func(target uint64, reason string) {
		if n.shouldLogLivenessReason(fmt.Sprintf("registry_history_rebuild_start:%d:%s", target, reason), livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-HISTORY-REBUILD] height=%d status=started reason=%s", target, reason)
		}
		// `ok` stores whether the related condition is satisfied.
		ok := n.ensureDeterministicRegistryHistoryUpTo(target)
		if ok {
			if n.shouldLogLivenessReason(fmt.Sprintf("registry_history_rebuild_ok:%d:%s", target, reason), livenessReasonLogCooldown) {
				log.Printf("[REGISTRY-HISTORY-REBUILD] height=%d status=ok reason=%s", target, reason)
			}
		} else {
			if n.shouldLogLivenessReason(fmt.Sprintf("registry_history_rebuild_failed:%d:%s", target, reason), livenessReasonLogCooldown) {
				log.Printf("[REGISTRY-HISTORY-REBUILD] height=%d status=failed reason=%s", target, reason)
			}
		}
	}(target, trimmedReason)
	return true
}

// startupExecutionSnapshotWaitingReason implements the startup execution snapshot waiting reason helper.
func startupExecutionSnapshotWaitingReason(finalized uint64) string {
	return fmt.Sprintf("startup_execution_snapshot_waiting_peers_h_%d", finalized)
}

// startupExecutionSnapshotSyncingReason implements the startup execution snapshot syncing reason helper.
func startupExecutionSnapshotSyncingReason(finalized uint64) string {
	return fmt.Sprintf("startup_execution_snapshot_syncing_h_%d", finalized)
}

// startupExecutionSnapshotRebuildPendingReason implements the startup execution snapshot rebuild pending reason helper.
func startupExecutionSnapshotRebuildPendingReason(finalized uint64) string {
	return fmt.Sprintf("startup_execution_snapshot_rebuild_pending_h_%d", finalized)
}

// `startupExecutionSnapshotRebuildScheduleCooldown` defines the constant value used by this package.
const startupExecutionSnapshotRebuildScheduleCooldown = 3 * time.Second

// `startupExecutionLegacyReplayMismatchWindow` defines the constant value used by this package.
const startupExecutionLegacyReplayMismatchWindow uint64 = 256

// startupExecutionSnapshotLedgerUnavailableErr implements the startup execution snapshot ledger unavailable err helper.
func startupExecutionSnapshotLedgerUnavailableErr(err error) bool {
	return err != nil && strings.Contains(err.Error(), "execution_snapshot_ledger_unavailable")
}

func startupExecutionSnapshotFailureNeedsNetworkRecovery(errText string) bool {
	return syncRecoveryReasonNeedsTrustedStateRepair(errText) ||
		strings.Contains(strings.ToLower(strings.TrimSpace(errText)), "trusted_execution_snapshot_missing")
}

// allowStartupExecutionLegacyReplayMismatch implements the allow startup execution legacy replay mismatch helper.
func allowStartupExecutionLegacyReplayMismatch(height uint64, block Block) bool {
	if height == 0 || height > startupExecutionLegacyReplayMismatchWindow {
		return false
	}
	if len(block.Transactions) > 0 {
		return false
	}
	return strings.TrimSpace(block.StateRoot) != ""
}

// maybeScheduleStartupExecutionSnapshotRebuild implements the maybe schedule startup execution snapshot rebuild helper.
func (n *Node) maybeScheduleStartupExecutionSnapshotRebuild(finalized uint64, reason string) bool {
	if n == nil || finalized == 0 || !n.startupExecutionSnapshotCanRebuildLocally(finalized) {
		return false
	}
	// `trimmedReason` stores the value produced by this operation.
	trimmedReason := strings.TrimSpace(reason)
	if trimmedReason == "" {
		trimmedReason = "startup_execution_snapshot_rebuild_pending"
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	n.executionSnapshotRebuildMu.Lock()
	if n.executionSnapshotRebuildReadyHeight >= finalized || n.executionSnapshotRebuildTarget >= finalized {
		n.executionSnapshotRebuildMu.Unlock()
		return false
	}
	if !n.executionSnapshotRebuildLastScheduleAt.IsZero() &&
		now.Sub(n.executionSnapshotRebuildLastScheduleAt) < startupExecutionSnapshotRebuildScheduleCooldown {
		n.executionSnapshotRebuildMu.Unlock()
		return false
	}
	n.executionSnapshotRebuildTarget = finalized
	n.executionSnapshotRebuildLastScheduleAt = now
	n.executionSnapshotRebuildMu.Unlock()

	if n.shouldLogLivenessReason(fmt.Sprintf("startup_execution_snapshot_rebuild_schedule:%d:%s", finalized, trimmedReason), livenessReasonLogCooldown) {
		log.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=rebuild schedule height=%d reason=%s", finalized, trimmedReason)
	}

	go func(target uint64, trigger string) {
		// `ok` and `rebuildReason` store whether the related condition is satisfied.
		ok, rebuildReason := n.ensureStartupTrustedExecutionSnapshotsInternal(target, true)
		n.executionSnapshotRebuildMu.Lock()
		if n.executionSnapshotRebuildTarget == target {
			n.executionSnapshotRebuildTarget = 0
		}
		n.executionSnapshotRebuildMu.Unlock()
		if ok {
			n.requestHeartbeatBroadcast(true)
			n.maybeBroadcastCurrentLeaderExecutionVote("startup_execution_snapshot_rebuilt")
			return
		}
		if n.shouldLogLivenessReason(fmt.Sprintf("startup_execution_snapshot_rebuild_async_wait:%d:%s", target, rebuildReason), livenessReasonLogCooldown) {
			log.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=rebuild async_wait height=%d trigger=%s reason=%s", target, trigger, rebuildReason)
		}
	}(finalized, trimmedReason)
	return true
}

// maybeStartStartupExecutionSnapshotRecovery implements the maybe start startup execution snapshot recovery helper.
func (n *Node) maybeStartStartupExecutionSnapshotRecovery(finalized uint64) (string, bool) {
	if n == nil || finalized == 0 || !n.startupExecutionSnapshotShouldPreferNetworkRecovery() {
		return "", false
	}
	if n.startupExecutionSnapshotPeerCount() == 0 {
		return startupExecutionSnapshotWaitingReason(finalized), true
	}
	n.forceSnapshotResyncNow(finalized, "startup_execution_snapshot_missing")
	return startupExecutionSnapshotSyncingReason(finalized), true
}

// startupExecutionSnapshotStatus implements the startup execution snapshot status helper.
func (n *Node) startupExecutionSnapshotStatus(finalized uint64) (bool, string) {
	if n == nil || finalized == 0 {
		return true, "ready"
	}
	if n.Blockchain != nil {
		// `block` and `ok` store whether the related condition is satisfied.
		if block, ok := n.Blockchain.GetBlock(finalized); !ok || strings.TrimSpace(block.StateRoot) == "" {
			return true, "ready"
		}
	}
	// `snap` and `ok` store whether the related condition is satisfied.
	if snap, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(finalized); ok && snap != nil {
		return true, "ready"
	}
	if n.authoritativeExecutionLedgerAvailable(finalized) {
		return true, "ready"
	}
	n.executionSnapshotRebuildMu.Lock()
	// `readyHeight` stores the value produced by this operation.
	readyHeight := n.executionSnapshotRebuildReadyHeight
	// `failedHeight` stores the value produced by this operation.
	failedHeight := n.executionSnapshotRebuildFailedHeight
	// `lastErr` stores the error produced by this operation.
	lastErr := strings.TrimSpace(n.executionSnapshotRebuildLastErr)
	n.executionSnapshotRebuildMu.Unlock()
	if readyHeight >= finalized {
		return true, "ready"
	}
	// `canRebuildLocally` stores the value produced by this operation.
	canRebuildLocally := n.startupExecutionSnapshotCanRebuildLocally(finalized)
	if failedHeight == finalized && lastErr != "" {
		if startupExecutionSnapshotFailureNeedsNetworkRecovery(lastErr) {
			if reason, recovering := n.maybeStartStartupExecutionSnapshotRecovery(finalized); recovering {
				return false, reason
			}
		}
		if canRebuildLocally {
			n.maybeScheduleStartupExecutionSnapshotRebuild(finalized, "prior_rebuild_failed_local_history_ready")
			return false, startupExecutionSnapshotRebuildPendingReason(finalized)
		}
		// `reason` and `recovering` store the value produced by this operation.
		if reason, recovering := n.maybeStartStartupExecutionSnapshotRecovery(finalized); recovering {
			return false, reason
		}
		return false, fmt.Sprintf("startup_execution_snapshot_rebuild_failed_h_%d", finalized)
	}
	if canRebuildLocally {
		n.maybeScheduleStartupExecutionSnapshotRebuild(finalized, "local_history_ready")
		return false, startupExecutionSnapshotRebuildPendingReason(finalized)
	}
	// `reason` and `recovering` store the value produced by this operation.
	if reason, recovering := n.maybeStartStartupExecutionSnapshotRecovery(finalized); recovering {
		return false, reason
	}
	return false, startupExecutionSnapshotWaitingReason(finalized)
}

// startupExecutionParentLedgerMatchesBlock implements the startup execution parent ledger matches block helper.
func (n *Node) startupExecutionParentLedgerMatchesBlock(parent Ledger, block Block) bool {
	if n == nil || block.ID == 0 || strings.TrimSpace(block.StateRoot) == "" {
		return false
	}
	// `nextLedger` and `err` store the error produced by this operation.
	nextLedger, err := ApplyBlockStateWithNode(n, parent, block)
	if err != nil {
		return false
	}
	// `expectedRoot` stores the digest used to identify or verify the related data.
	expectedRoot := ComputeExecHashVersioned(block, HashLedger(nextLedger), executionStateRootVersionForHeight(block.ID))
	return strings.EqualFold(strings.TrimSpace(expectedRoot), strings.TrimSpace(block.StateRoot))
}

// replayPostBlockEffectsToLedger implements the replay post block effects to ledger helper.
func (n *Node) replayPostBlockEffectsToLedger(block Block, base Ledger) Ledger {
	registry := n.validatorRegistrySnapshotForHeight(block.ID)
	return n.applyPostBlockEffectsToLedgerWithRegistry(block, base, registry)
}

// startupExecutionReplayPostBlockEffectsToLedger implements the startup execution replay post block effects to ledger helper.
func (n *Node) startupExecutionReplayPostBlockEffectsToLedger(block Block, base Ledger) Ledger {
	return n.replayPostBlockEffectsToLedger(block, base)
}

// startupExecutionParentLedgerAfterBlock implements the startup execution parent ledger after block helper.
func (n *Node) startupExecutionParentLedgerAfterBlock(block Block, committedLedger Ledger, nextHeight uint64) Ledger {
	if n == nil {
		return committedLedger.Clone()
	}
	// `postCommitLedger` stores the value produced by this operation.
	postCommitLedger := n.startupExecutionReplayPostBlockEffectsToLedger(block, committedLedger)
	if nextHeight == 0 {
		return postCommitLedger
	}
	// `nextBlock` and `ok` store whether the related condition is satisfied.
	nextBlock, ok := n.LoadBlock(int(nextHeight))
	if !ok && n.Blockchain != nil {
		nextBlock, ok = n.Blockchain.GetBlock(nextHeight)
	}
	if !ok || strings.TrimSpace(nextBlock.StateRoot) == "" {
		return postCommitLedger
	}
	// `rawMatches` stores the value produced by this operation.
	rawMatches := n.startupExecutionParentLedgerMatchesBlock(committedLedger, nextBlock)
	// `postMatches` stores the value produced by this operation.
	postMatches := n.startupExecutionParentLedgerMatchesBlock(postCommitLedger, nextBlock)
	if postMatches {
		return postCommitLedger
	}
	if rawMatches {
		if n.shouldLogLivenessReason(fmt.Sprintf("startup_execution_snapshot_rebuild_legacy_parent:%d:%d", block.ID, nextHeight), livenessReasonLogCooldown) {
			log.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=rebuild parent_model=legacy_raw_parent base=%d next=%d raw=%s post=%s",
				block.ID,
				nextHeight,
				ShortHash(HashLedger(committedLedger)),
				ShortHash(HashLedger(postCommitLedger)),
			)
		}
		return committedLedger.Clone()
	}
	return postCommitLedger
}

// rebuildTrustedExecutionSnapshotsUpTo implements the rebuild trusted execution snapshots up to helper.
func (n *Node) rebuildTrustedExecutionSnapshotsUpTo(height uint64) (err error) {
	// `started` stores the value produced by this operation.
	started := time.Now()
	// `replayedBlocks` stores the value produced by this operation.
	replayedBlocks := uint64(0)
	defer func() {
		n.observeReplayOperation(height, replayedBlocks, time.Since(started), err == nil)
	}()
	if n == nil {
		return fmt.Errorf("node_unavailable")
	}
	if height == 0 {
		return nil
	}
	// `startHeight` stores the value produced by this operation.
	startHeight := uint64(1)
	// `ledger` stores the value used by this operation.
	var ledger Ledger
	// `registrySnapshot` stores the value used by this operation.
	var registrySnapshot map[string]ValidatorRecord
	lastTrustedExecutionLedger := Ledger{}.Clone()
	// `baseSnap`, `baseHeight`, and `ok` store whether the related condition is satisfied.
	if baseSnap, baseHeight, ok := n.startupExecutionTrustedBaseSnapshot(height); ok && baseSnap != nil {
		if baseHeight >= height {
			if !n.registrySnapshotExists(height) && len(baseSnap.ValidatorRegistry) > 0 {
				if err := n.persistValidatorRegistrySnapshotFromSource(height, baseSnap.ValidatorRegistry); err != nil {
					return fmt.Errorf("persist_registry_snapshot_failed height=%d err=%w", height, err)
				}
			}
			n.cacheExecutionSnapshotLedger(height, baseSnap.Ledger)
			n.markExecutionSnapshotReadyHeight(height)
			return nil
		}
		// `baseBlock` and `ok` store whether the related condition is satisfied.
		baseBlock, ok := n.LoadBlock(int(baseHeight))
		if !ok {
			return fmt.Errorf("base_block_missing height=%d", baseHeight)
		}
		ledger = n.startupExecutionParentLedgerAfterBlock(baseBlock, baseSnap.Ledger, baseHeight+1)
		lastTrustedExecutionLedger = baseSnap.Ledger.Clone()
		registrySnapshot = copyValidatorRegistrySnapshot(baseSnap.ValidatorRegistry)
		// `storedRegistry` and `err` store the error produced by this operation.
		if storedRegistry, err := n.loadValidatorRegistrySnapshot(baseHeight); err == nil && len(storedRegistry) > 0 {
			registrySnapshot = copyValidatorRegistrySnapshot(storedRegistry)
		}
		if len(registrySnapshot) == 0 {
			registrySnapshot = n.startupExecutionBootstrapRegistrySnapshot(baseHeight)
		}
		startHeight = baseHeight + 1
		if n.shouldLogLivenessReason(fmt.Sprintf("startup_execution_snapshot_rebuild_resume:%d:%d", baseHeight, height), livenessReasonLogCooldown) {
			log.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=rebuild resume base=%d target=%d", baseHeight, height)
		}
	} else {
		// `err` stores the error produced by this operation.
		var err error
		ledger, err = n.buildStartupExecutionGenesisLedger()
		if err != nil {
			return err
		}
		lastTrustedExecutionLedger = ledger.Clone()
		registrySnapshot = n.startupExecutionBootstrapRegistrySnapshot(0)
	}
	// `h` stores the value produced by this operation.
	for h := startHeight; h <= height; h++ {
		replayedBlocks++
		// `storedRegistry` and `err` store the error produced by this operation.
		if storedRegistry, err := n.loadValidatorRegistrySnapshot(h); err == nil && len(storedRegistry) > 0 {
			registrySnapshot = copyValidatorRegistrySnapshot(storedRegistry)
		} else if len(registrySnapshot) == 0 {
			registrySnapshot = n.startupExecutionBootstrapRegistrySnapshot(h)
		}
		// `block` and `ok` store whether the related condition is satisfied.
		block, ok := n.LoadBlock(int(h))
		if !ok {
			return fmt.Errorf("block_missing height=%d", h)
		}
		if len(registrySnapshot) > 0 {
			// `err` stores the error produced by this operation.
			if err := n.deterministicPersistRegistrySnapshot(h, registrySnapshot, strings.TrimSpace(block.ValidatorRegistryHash)); err != nil {
				return fmt.Errorf("persist_registry_snapshot_failed height=%d err=%w", h, err)
			}
			// `storedRegistry` and `err` store the error produced by this operation.
			if storedRegistry, err := n.loadValidatorRegistrySnapshot(h); err == nil && len(storedRegistry) > 0 {
				registrySnapshot = copyValidatorRegistrySnapshot(storedRegistry)
			}
		}
		// `nextLedger` and `err` store the error produced by this operation.
		nextLedger, err := ApplyBlockStateWithNode(n, ledger, block)
		if err != nil {
			return fmt.Errorf("apply_block_failed height=%d err=%w", h, err)
		}
		// `snapshotStored` stores the value produced by this operation.
		snapshotStored := true
		// `err` stores the error produced by this operation.
		if err := n.createSnapshotWithLedger(h, strings.TrimSpace(block.BlockHash), nextLedger, snapshotLedgerStageExecution); err != nil {
			if startupExecutionSnapshotLedgerUnavailableErr(err) && allowStartupExecutionLegacyReplayMismatch(h, block) {
				if rawErr := n.createSnapshotWithLedger(h, strings.TrimSpace(block.BlockHash), ledger, snapshotLedgerStageExecution); rawErr == nil {
					nextLedger = ledger.Clone()
				} else {
					snapshotStored = false
					if n.shouldLogLivenessReason(fmt.Sprintf("startup_execution_legacy_replay_mismatch:%d", h), livenessReasonLogCooldown) {
						log.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=rebuild legacy_mismatch_skip height=%d target=%d block=%s", h, height, ShortHash(block.BlockHash))
					}
				}
			} else {
				return fmt.Errorf("create_snapshot_failed height=%d err=%w", h, err)
			}
		}
		if snapshotStored {
			lastTrustedExecutionLedger = nextLedger.Clone()
			// `cached` stores the value produced by this operation.
			if _, cached := n.cachedExecutionSnapshotLedger(h); !cached {
				n.cacheExecutionSnapshotLedger(h, nextLedger)
			}
			// `ok` stores whether the related condition is satisfied.
			if _, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(h); !ok {
				return fmt.Errorf("trusted_execution_snapshot_missing height=%d", h)
			}
			// `rebuiltSnapshot` and `err` store the error produced by this operation.
			if rebuiltSnapshot, err := n.GetSnapshot(h); err == nil && rebuiltSnapshot != nil && len(rebuiltSnapshot.ValidatorRegistry) > 0 {
				// `err` stores the error produced by this operation.
				if err := n.deterministicPersistRegistrySnapshot(h, rebuiltSnapshot.ValidatorRegistry, strings.TrimSpace(block.ValidatorRegistryHash)); err != nil {
					return fmt.Errorf("persist_rebuilt_registry_snapshot_failed height=%d err=%w", h, err)
				}
				registrySnapshot = copyValidatorRegistrySnapshot(rebuiltSnapshot.ValidatorRegistry)
			}
		}
		if !snapshotStored {
			ledger = lastTrustedExecutionLedger.Clone()
			continue
		}
		// Snapshot(h) commits the execution result for block h, while the
		// parent ledger for h+1 includes deterministic post-commit effects.
		ledger = n.startupExecutionParentLedgerAfterBlock(block, nextLedger, h+1)
	}
	// `ok` stores whether the related condition is satisfied.
	if _, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(height); !ok {
		return fmt.Errorf("trusted_execution_snapshot_missing height=%d", height)
	}
	return nil
}

// ensureStartupTrustedExecutionSnapshots implements the ensure startup trusted execution snapshots helper.
func (n *Node) ensureStartupTrustedExecutionSnapshots(finalized uint64) (bool, string) {
	return n.ensureStartupTrustedExecutionSnapshotsInternal(finalized, false)
}

// ensureStartupTrustedExecutionSnapshotsInternal implements the ensure startup trusted execution snapshots internal helper.
func (n *Node) ensureStartupTrustedExecutionSnapshotsInternal(finalized uint64, scheduledOwner bool) (bool, string) {
	if n == nil || finalized == 0 {
		return true, "ready"
	}
	// `applyTrustedExecutionSnapshot` stores the value produced by this operation.
	applyTrustedExecutionSnapshot := func(snapshot *StateSnapshot) {
		if snapshot == nil {
			return
		}
		// Startup readiness must not clobber the live post-commit execution
		// ledger while consensus is already advancing on the current tip.
		if !ledgerHasInitializedBacking(n.ExecutionLedger) {
			n.setExecutionLedger(snapshot.Ledger)
		}
		n.cacheExecutionSnapshotLedger(finalized, snapshot.Ledger)
		n.markExecutionSnapshotReadyHeight(finalized)
	}
	if n.Blockchain != nil {
		// `block` and `ok` store whether the related condition is satisfied.
		if block, ok := n.Blockchain.GetBlock(finalized); !ok || strings.TrimSpace(block.StateRoot) == "" {
			return true, "ready"
		}
	}
	// `snap` and `ok` store whether the related condition is satisfied.
	if snap, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(finalized); ok && snap != nil {
		applyTrustedExecutionSnapshot(snap)
		return true, "ready"
	}
	if source, recovered := n.recoverCommittedExecutionSnapshotFromPostCommit(finalized); recovered {
		if snap, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(finalized); ok && snap != nil {
			applyTrustedExecutionSnapshot(snap)
			if DebugConsensus {
				fmt.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=recover source=%s height=%d status=ready\n", source, finalized)
			}
			return true, "ready"
		}
	}
	if n.authoritativeExecutionLedgerAvailable(finalized) {
		n.markExecutionSnapshotReadyHeight(finalized)
		return true, "ready"
	}
	// `canRebuildLocally` stores the value produced by this operation.
	canRebuildLocally := n.startupExecutionSnapshotCanRebuildLocally(finalized)
	if !canRebuildLocally {
		// `source` and `repaired` store the value produced by this operation.
		if source, repaired := n.ensureCommittedTipStateSnapshot(finalized, "startup"); repaired {
			// `snap` and `ok` store whether the related condition is satisfied.
			if snap, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(finalized); ok && snap != nil {
				applyTrustedExecutionSnapshot(snap)
				if DebugConsensus {
					fmt.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=recover source=%s height=%d status=ok\n", source, finalized)
				}
				return true, "ready"
			}
		}
		// `reason` and `recovering` store the value produced by this operation.
		if reason, recovering := n.maybeStartStartupExecutionSnapshotRecovery(finalized); recovering {
			return false, reason
		}
	}

	n.executionSnapshotRebuildMu.Lock()
	// `rebuildFailed` stores the value produced by this operation.
	rebuildFailed := n.executionSnapshotRebuildFailedHeight == finalized && n.executionSnapshotRebuildLastErr != ""
	// `rebuildReadyHeight` stores the value produced by this operation.
	rebuildReadyHeight := n.executionSnapshotRebuildReadyHeight
	// `liveCommitHeight` stores the value produced by this operation.
	liveCommitHeight := n.executionSnapshotLiveCommitHeight
	// `rebuildLastErr` stores the value produced by this operation.
	rebuildLastErr := strings.TrimSpace(n.executionSnapshotRebuildLastErr)
	n.executionSnapshotRebuildMu.Unlock()

	if rebuildFailed && startupExecutionSnapshotFailureNeedsNetworkRecovery(rebuildLastErr) {
		if reason, recovering := n.maybeStartStartupExecutionSnapshotRecovery(finalized); recovering {
			return false, reason
		}
	}

	// A block verified and committed by this running process already crossed the
	// execution-state validation barrier. Do not require a checkpoint snapshot
	// for every subsequent live height; that turns the startup-only recovery
	// path into an expensive per-block replay loop. The marker is memory-only,
	// so a restarted process still has to recover from a trusted snapshot.
	if liveCommitHeight >= finalized &&
		n.Blockchain != nil &&
		n.Blockchain.Height() >= finalized &&
		n.localCommittedHistoryHeight() >= finalized {
		return true, "ready"
	}

	if rebuildFailed && !canRebuildLocally {
		// `source` and `repaired` store the value produced by this operation.
		if source, repaired := n.ensureCommittedTipStateSnapshot(finalized, "startup"); repaired {
			// `snap` and `ok` store whether the related condition is satisfied.
			if snap, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(finalized); ok && snap != nil {
				applyTrustedExecutionSnapshot(snap)
				n.executionSnapshotRebuildMu.Lock()
				n.executionSnapshotRebuildFailedHeight = 0
				n.executionSnapshotRebuildLastErr = ""
				n.executionSnapshotRebuildReadyHeight = finalized
				n.executionSnapshotRebuildMu.Unlock()
				if DebugConsensus {
					fmt.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=recover source=%s height=%d status=ok\n", source, finalized)
				}
				return true, "ready"
			}
		}
		// `reason` and `recovering` store the value produced by this operation.
		if reason, recovering := n.maybeStartStartupExecutionSnapshotRecovery(finalized); recovering {
			return false, reason
		}
		return false, fmt.Sprintf("startup_execution_snapshot_rebuild_failed_h_%d", finalized)
	}

	if rebuildReadyHeight >= finalized {
		// `snap` and `ok` store whether the related condition is satisfied.
		if snap, _, ok := n.resolveTrustedExecutionSnapshotFromStorage(finalized); ok && snap != nil {
			applyTrustedExecutionSnapshot(snap)
			n.executionSnapshotRebuildMu.Lock()
			n.executionSnapshotRebuildFailedHeight = 0
			n.executionSnapshotRebuildLastErr = ""
			n.executionSnapshotRebuildMu.Unlock()
			return true, "ready"
		}
	}
	if !canRebuildLocally {
		return false, startupExecutionSnapshotWaitingReason(finalized)
	}

	// `targetOwned` stores the value produced by this operation.
	targetOwned := false
	n.executionSnapshotRebuildMu.Lock()
	if n.executionSnapshotRebuildReadyHeight >= finalized {
		n.executionSnapshotRebuildMu.Unlock()
		return true, "ready"
	}
	if n.executionSnapshotRebuildTarget >= finalized {
		if !scheduledOwner || n.executionSnapshotRebuildTarget != finalized {
			n.executionSnapshotRebuildMu.Unlock()
			return false, startupExecutionSnapshotRebuildPendingReason(finalized)
		}
	} else {
		n.executionSnapshotRebuildTarget = finalized
		targetOwned = true
	}
	n.executionSnapshotRebuildMu.Unlock()
	if targetOwned {
		defer func() {
			n.executionSnapshotRebuildMu.Lock()
			if n.executionSnapshotRebuildTarget == finalized {
				n.executionSnapshotRebuildTarget = 0
			}
			n.executionSnapshotRebuildMu.Unlock()
		}()
	}

	if n.shouldLogLivenessReason(fmt.Sprintf("startup_execution_snapshot_rebuild_begin:%d", finalized), livenessReasonLogCooldown) {
		log.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=rebuild begin height=%d", finalized)
	}
	// `err` stores the error produced by this operation.
	if err := n.rebuildTrustedExecutionSnapshotsUpTo(finalized); err != nil {
		n.executionSnapshotRebuildMu.Lock()
		n.executionSnapshotRebuildFailedHeight = finalized
		n.executionSnapshotRebuildLastErr = err.Error()
		// `lastErr` stores the error produced by this operation.
		lastErr := n.executionSnapshotRebuildLastErr
		n.executionSnapshotRebuildMu.Unlock()
		if n.shouldLogLivenessReason(fmt.Sprintf("startup_execution_snapshot_rebuild_failed:%d:%s", finalized, lastErr), livenessReasonLogCooldown) {
			log.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=rebuild status=failed height=%d err=%s", finalized, lastErr)
		}
		// `reason` and `recovering` store the value produced by this operation.
		if reason, recovering := n.maybeStartStartupExecutionSnapshotRecovery(finalized); recovering {
			return false, reason
		}
		return false, fmt.Sprintf("startup_execution_snapshot_rebuild_failed_h_%d", finalized)
	}

	n.executionSnapshotRebuildMu.Lock()
	n.executionSnapshotRebuildReadyHeight = finalized
	n.executionSnapshotRebuildFailedHeight = 0
	n.executionSnapshotRebuildLastErr = ""
	n.executionSnapshotRebuildMu.Unlock()
	if n.shouldLogLivenessReason(fmt.Sprintf("startup_execution_snapshot_rebuild_done:%d", finalized), livenessReasonLogCooldown) {
		log.Printf("[STARTUP-EXECUTION-SNAPSHOT] action=rebuild status=ok height=%d", finalized)
	}
	return false, fmt.Sprintf("startup_execution_snapshot_rebuilt_h_%d", finalized)
}

// startupResolvedValidatorSetHash implements the startup resolved validator set hash helper.
func (n *Node) startupResolvedValidatorSetHash(height uint64) ([]string, string, string, bool) {
	if n == nil || height == 0 {
		return nil, "", "none", false
	}
	// `validators`, `hash`, `source`, and `ok` store whether the related condition is satisfied.
	if validators, hash, source, ok := n.resolveCommittedValidatorSetForHeight(height); ok && len(validators) > 0 {
		hash = strings.TrimSpace(hash)
		if hash == "" {
			hash = strings.TrimSpace(n.preferredValidatorSetHashForHeight(height, validators, nil))
		}
		if hash == "" {
			hash = strings.TrimSpace(ValidatorSetHash(validators))
		}
		if hash != "" {
			return canonicalValidatorIDs(validators), hash, normalizeCommittedValidatorAuthoritySource(source), true
		}
	}
	// `validators`, `source`, and `ok` store whether the related condition is satisfied.
	if validators, source, ok := n.chainDerivedValidatorAuthorityForHeight(height); ok && len(validators) > 0 {
		// `hash` stores the digest used to identify or verify the related data.
		hash := strings.TrimSpace(n.preferredValidatorSetHashForHeight(height, validators, nil))
		if hash == "" {
			hash = strings.TrimSpace(ValidatorSetHash(validators))
		}
		if hash != "" {
			return canonicalValidatorIDs(validators), hash, normalizeCommittedValidatorAuthoritySource(source), true
		}
	}
	return nil, "", "none", false
}

// startupValidatorSetLegacySelfCheck implements the startup validator set legacy self check helper.
func (n *Node) startupValidatorSetLegacySelfCheck(finalized uint64) (bool, string) {
	// `expected` stores the value produced by this operation.
	expected := ""
	if n.Blockchain != nil {
		// `b` and `ok` store whether the related condition is satisfied.
		if b, ok := n.Blockchain.GetBlock(finalized); ok {
			expected = strings.TrimSpace(b.ValidatorSetHash)
		}
	}
	if expected == "" {
		expected = strings.TrimSpace(n.expectedValidatorSetHash(finalized))
	}
	if expected == "" {
		// `reason` stores the value produced by this operation.
		reason := fmt.Sprintf("startup_validator_set_expected_unresolved_h_%d", finalized)
		n.setValidatorStartupCheckStatus(false, finalized, "", "", reason)
		n.recordValidatorAutohealWait(reason, finalized, "", "")
		return false, reason
	}
	// `chainHash` stores the digest used to identify or verify the related data.
	chainHash := ""
	// `hash` and `ok` store whether the related condition is satisfied.
	if hash, ok := n.chainValidatorSetHash(finalized); ok {
		chainHash = strings.TrimSpace(hash)
	}

	// `localHash` stores the digest used to identify or verify the related data.
	localHash := ""
	// `frozen` and `ok` store whether the related condition is satisfied.
	if frozen, ok := n.frozenValidatorSetHash(finalized); ok {
		localHash = strings.TrimSpace(frozen)
	}
	if localHash == "" {
		// `hint` stores the value produced by this operation.
		hint := n.consensusValidatorsForHeight(finalized)
		// `vals` stores the value currently being processed.
		if vals := n.freezeValidatorSetForHeight(finalized, hint); len(vals) > 0 {
			localHash = ValidatorSetHash(vals)
		}
	}
	if localHash == "" && chainHash != "" {
		localHash = chainHash
	}
	if localHash != "" &&
		chainHash != "" &&
		strings.EqualFold(expected, chainHash) &&
		!strings.EqualFold(expected, localHash) {
		if n.reconcileFrozenValidatorSetHash(finalized, expected) {
			// `reconciledHash` stores the digest used to identify or verify the related data.
			reconciledHash, _ := n.frozenValidatorSetHash(finalized)
			if strings.TrimSpace(reconciledHash) == "" {
				reconciledHash = expected
			}
			n.setValidatorStartupCheckStatus(true, finalized, expected, reconciledHash, "startup_validator_set_hash_reconciled")
			// `progressHeight` stores the value produced by this operation.
			progressHeight := finalized
			if n.Blockchain != nil && n.Blockchain.Height() > progressHeight {
				progressHeight = n.Blockchain.Height()
			}
			n.recordValidatorAutohealSuccess(progressHeight, "startup_validator_set_hash_reconciled")
			return true, "ready"
		}
		n.setValidatorStartupCheckStatus(true, finalized, expected, chainHash, "startup_validator_set_chain_authoritative")
		// `progressHeight` stores the value produced by this operation.
		progressHeight := finalized
		if n.Blockchain != nil && n.Blockchain.Height() > progressHeight {
			progressHeight = n.Blockchain.Height()
		}
		n.recordValidatorAutohealSuccess(progressHeight, "startup_validator_set_chain_authoritative")
		return true, "ready"
	}
	if localHash == "" {
		// `reason` stores the value produced by this operation.
		reason := fmt.Sprintf("startup_validator_set_frozen_unresolved_h_%d", finalized)
		n.setValidatorStartupCheckStatus(false, finalized, expected, "", reason)
		n.recordValidatorAutohealWait(reason, finalized, expected, "")
		return false, reason
	}
	if strings.EqualFold(expected, localHash) {
		n.setValidatorStartupCheckStatus(true, finalized, expected, localHash, "startup_validator_set_ok")
		return true, "ready"
	}
	if n.maybeAdoptCoreQuorumValidatorSetHash(finalized, expected, localHash) {
		// `reconciledHash` stores the digest used to identify or verify the related data.
		reconciledHash := strings.TrimSpace(n.expectedValidatorSetHash(finalized))
		if reconciledHash == "" {
			reconciledHash = strings.TrimSpace(localHash)
		}
		n.setValidatorStartupCheckStatus(true, finalized, reconciledHash, reconciledHash, "startup_validator_set_hash_reconciled_validator_quorum")
		// `progressHeight` stores the value produced by this operation.
		progressHeight := finalized
		if n.Blockchain != nil && n.Blockchain.Height() > progressHeight {
			progressHeight = n.Blockchain.Height()
		}
		n.recordValidatorAutohealSuccess(progressHeight, "startup_validator_set_hash_reconciled_validator_quorum")
		return true, "ready"
	}
	if n.reconcileFrozenValidatorSetHash(finalized, expected) {
		// `reconciledHash` stores the digest used to identify or verify the related data.
		reconciledHash, _ := n.frozenValidatorSetHash(finalized)
		if strings.TrimSpace(reconciledHash) == "" {
			reconciledHash = expected
		}
		n.setValidatorStartupCheckStatus(true, finalized, expected, reconciledHash, "startup_validator_set_hash_reconciled")
		// `progressHeight` stores the value produced by this operation.
		progressHeight := finalized
		if n.Blockchain != nil && n.Blockchain.Height() > progressHeight {
			progressHeight = n.Blockchain.Height()
		}
		n.recordValidatorAutohealSuccess(progressHeight, "startup_validator_set_hash_reconciled")
		return true, "ready"
	}

	// `reason` stores the value produced by this operation.
	reason := fmt.Sprintf("startup_validator_set_mismatch_h_%d", finalized)
	n.setValidatorStartupCheckStatus(false, finalized, expected, localHash, reason)
	n.recordValidatorAutohealWait(reason, finalized, expected, localHash)
	n.requestConsensusRecomputePause(finalized, "startup_validator_set_self_check")

	if n.tryRepairValidatorSetHash(finalized, expected) {
		// `repairedHash` stores the digest used to identify or verify the related data.
		repairedHash := ""
		// `frozen` and `ok` store whether the related condition is satisfied.
		if frozen, ok := n.frozenValidatorSetHash(finalized); ok {
			repairedHash = strings.TrimSpace(frozen)
		}
		if repairedHash == "" {
			// `vals` stores the value currently being processed.
			if vals := n.freezeValidatorSetForHeight(finalized, n.consensusValidatorsForHeight(finalized)); len(vals) > 0 {
				repairedHash = ValidatorSetHash(vals)
			}
		}
		if repairedHash != "" && strings.EqualFold(expected, repairedHash) {
			n.setValidatorStartupCheckStatus(true, finalized, expected, repairedHash, "startup_validator_set_autohealed")
			// `progressHeight` stores the value produced by this operation.
			progressHeight := finalized
			if n.Blockchain != nil && n.Blockchain.Height() > progressHeight {
				progressHeight = n.Blockchain.Height()
			}
			n.recordValidatorAutohealSuccess(progressHeight, "startup_validator_set_autohealed")
			return true, "ready"
		}
	}
	return false, reason
}

// startupValidatorSetLegacyFallbackAllowed implements the startup validator set legacy fallback allowed helper.
func (n *Node) startupValidatorSetLegacyFallbackAllowed(finalized uint64) bool {
	if n == nil || finalized == 0 {
		return false
	}
	if n.Blockchain == nil {
		return true
	}
	// `block` and `ok` store whether the related condition is satisfied.
	block, ok := n.Blockchain.GetBlock(finalized)
	if !ok {
		return true
	}
	return strings.TrimSpace(block.NextValidatorSetHash) == "" && strings.TrimSpace(block.ValidatorSetHash) != ""
}

// startupValidatorSetSelfCheck implements the startup validator set self check helper.
func (n *Node) startupValidatorSetSelfCheck() (bool, string) {
	if n == nil {
		return false, "node_unavailable"
	}
	// `localCommitted` stores the value produced by this operation.
	localCommitted := n.localCommittedHistoryHeight()
	if localCommitted == 0 && n.freshLateJoinSnapshotAnchorPending() {
		// `waitHeight` stores the value produced by this operation.
		waitHeight := n.getFinalizedHeight()
		// `lateJoin` stores the value produced by this operation.
		if lateJoin := n.lateJoinAuthoritySnapshot(); lateJoin.Active && lateJoin.Height > waitHeight {
			waitHeight = lateJoin.Height
		}
		// `reason` stores the value produced by this operation.
		reason := "late_join_snapshot_anchor_pending"
		n.setValidatorStartupCheckStatus(false, waitHeight, "", "", reason)
		n.recordValidatorAutohealWait(reason, waitHeight, "", "")
		return false, reason
	}
	// `finalized` stores the value produced by this operation.
	finalized := localCommitted
	if finalized == 0 {
		n.setValidatorStartupCheckStatus(true, 0, "", "", "genesis_bootstrap")
		return true, "ready"
	}
	// `ok` and `reason` store whether the related condition is satisfied.
	if ok, reason := n.ensureStartupTrustedExecutionSnapshots(finalized); !ok {
		n.setValidatorStartupCheckStatus(false, finalized, "", "", reason)
		n.recordValidatorAutohealWait(reason, finalized, "", "")
		return false, reason
	}
	if validatorSetCommitmentV2EnabledAt(finalized) {
		// `checkHeight` stores the value produced by this operation.
		checkHeight := finalized + 1
		// `expected` and `expectedSource` store the value produced by this operation.
		expected, expectedSource := n.expectedValidatorSetHashWithSource(checkHeight)
		expected = strings.TrimSpace(expected)
		if expected == "" {
			if n.startupValidatorSetLegacyFallbackAllowed(finalized) {
				return n.startupValidatorSetLegacySelfCheck(finalized)
			}
			// `reason` stores the value produced by this operation.
			reason := fmt.Sprintf("startup_validator_set_expected_unresolved_h_%d", checkHeight)
			n.setValidatorStartupCheckStatus(false, checkHeight, "", "", reason)
			n.recordValidatorAutohealWait(reason, checkHeight, "", "")
			return false, reason
		}
		n.logStartupCommitmentCheck(checkHeight, expected, expectedSource)
		if n.DB != nil && n.DB.State != nil {
			// `snap` and `err` store the error produced by this operation.
			if snap, err := n.GetSnapshot(finalized); err == nil && snap != nil {
				// `snapshotValidators` stores the value produced by this operation.
				if snapshotValidators := validatorsFromSnapshot(snap); len(snapshotValidators) > 0 {
					// `match` stores the value produced by this operation.
					if _, match := n.validatorSetCandidateMatchesTarget(checkHeight, expected, snapshotValidators, validatorRegistrySnapshotFromStateSnapshot(snap)); !match {
						// `reason` stores the value produced by this operation.
						reason := fmt.Sprintf("startup_validator_set_mismatch_h_%d", checkHeight)
						// `got` stores the value produced by this operation.
						got := strings.TrimSpace(n.preferredValidatorSetHashForHeight(checkHeight, snapshotValidators, validatorRegistrySnapshotFromStateSnapshot(snap)))
						if got == "" {
							got = strings.TrimSpace(ValidatorSetHash(snapshotValidators))
						}
						n.setValidatorStartupCheckStatus(false, checkHeight, expected, got, reason)
						n.recordValidatorAutohealWait(reason, checkHeight, expected, got)
						n.requestConsensusRecomputePause(checkHeight, "startup_validator_set_snapshot_mismatch")
						return false, reason
					}
				}
			}
		}
		// `localHash`, `localSource`, and `ok` store whether the related condition is satisfied.
		_, localHash, localSource, ok := n.startupResolvedValidatorSetHash(checkHeight)
		if !ok || strings.TrimSpace(localHash) == "" {
			// `source` and `repaired` store the value produced by this operation.
			if source, repaired := n.ensureCommittedTipStateSnapshot(finalized, "startup"); repaired {
				if DebugConsensus {
					fmt.Printf("[STARTUP-VALIDATOR-SET] check_h=%d action=repair_retry source=%s\n", checkHeight, normalizeCommittedValidatorAuthoritySource(source))
				}
				_, localHash, localSource, ok = n.startupResolvedValidatorSetHash(checkHeight)
			}
		}
		if !ok || strings.TrimSpace(localHash) == "" {
			if n.startupValidatorSetLegacyFallbackAllowed(finalized) {
				return n.startupValidatorSetLegacySelfCheck(finalized)
			}
			// `reason` stores the value produced by this operation.
			reason := fmt.Sprintf("startup_validator_set_unresolved_h_%d", checkHeight)
			n.setValidatorStartupCheckStatus(false, checkHeight, expected, "", reason)
			n.recordValidatorAutohealWait(reason, checkHeight, expected, "")
			return false, reason
		}
		if !strings.EqualFold(expected, localHash) {
			// `reason` stores the value produced by this operation.
			reason := fmt.Sprintf("startup_validator_set_mismatch_h_%d", checkHeight)
			n.setValidatorStartupCheckStatus(false, checkHeight, expected, localHash, reason)
			n.recordValidatorAutohealWait(reason, checkHeight, expected, localHash)
			n.requestConsensusRecomputePause(checkHeight, "startup_validator_set_self_check")
			if DebugConsensus {
				fmt.Printf("[STARTUP-VALIDATOR-SET] check_h=%d expected=%s got=%s expected_source=%s resolved_source=%s detail=full_set_unavailable_from_header_snapshot_recovery_required\n",
					checkHeight,
					ShortHash(expected),
					ShortHash(localHash),
					displayExpectedValidatorSetSource(expectedSource),
					displayCommittedValidatorAuthoritySource(localSource),
				)
			}
			return false, reason
		}
		// `statusReason` stores the value produced by this operation.
		statusReason := "startup_validator_set_verified_" + strings.TrimSpace(localSource)
		n.setValidatorStartupCheckStatus(true, checkHeight, expected, localHash, statusReason)
		n.recordValidatorAutohealSuccess(finalized, statusReason)
		return true, "ready"
	}
	return n.startupValidatorSetLegacySelfCheck(finalized)
}

// shouldSkipStartupFailClosedSnapshotResync implements the should skip startup fail closed snapshot resync helper.
func shouldSkipStartupFailClosedSnapshotResync(reason string) bool {
	reason = strings.TrimSpace(reason)
	return strings.HasPrefix(reason, "startup_execution_snapshot_rebuild_") ||
		strings.HasPrefix(reason, "startup_execution_snapshot_syncing_") ||
		strings.HasPrefix(reason, "startup_execution_snapshot_waiting_peers_")
}

type snapshotSyncSourcePolicy string

const (
	// `snapshotSyncSourceLocalOrTrusted` defines the constant value used by this package.
	snapshotSyncSourceLocalOrTrusted snapshotSyncSourcePolicy = "local_or_trusted"
	// `snapshotSyncSourceTrustedOnly` defines the constant value used by this package.
	snapshotSyncSourceTrustedOnly snapshotSyncSourcePolicy = "trusted_only"
)

// applySnapshotForSyncHeight applies snapshot for sync height.
func (n *Node) applySnapshotForSyncHeight(targetHeight uint64) bool {
	return n.applySnapshotForSyncHeightInternal(targetHeight, false, snapshotSyncSourceLocalOrTrusted, 0)
}

// applySnapshotForSyncHeightInternal applies snapshot for sync height internal.
func (n *Node) applySnapshotForSyncHeightInternal(targetHeight uint64, allowReapply bool, sourcePolicy snapshotSyncSourcePolicy, minHeightOverride uint64) bool {
	if targetHeight == 0 {
		return false
	}
	// `transitionActive` and `transitionHeight` store the value produced by this operation.
	if transitionActive, transitionHeight := n.validatorSetTransitionActiveNow(); transitionActive {
		if DebugConsensus || DebugSync {
			fmt.Printf("[SYNC-LOCK] blocked=snapshot_apply transition_h=%d local=%d target=%d\n",
				transitionHeight, n.Blockchain.Height(), targetHeight)
		}
		return false
	}
	// `frozenTarget` and `frozen` store the value produced by this operation.
	if frozenTarget, frozen := n.snapshotSessionFrozenTarget(n.Blockchain.Height()); frozen {
		targetHeight = frozenTarget
	}
	if sourcePolicy == "" {
		sourcePolicy = snapshotSyncSourceLocalOrTrusted
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := n.Blockchain.Height()
	if targetHeight < localHeight {
		// Never roll back chain height due to sync path.
		return true
	}
	// `applied` stores the value produced by this operation.
	applied := false
	// `reapplyTrustedAttempted` stores the value produced by this operation.
	reapplyTrustedAttempted := false
	// `reapplyTrustedFailed` stores the value produced by this operation.
	reapplyTrustedFailed := false
	// `pipelineStage` stores the value produced by this operation.
	pipelineStage := syncCatchupStage(localHeight, targetHeight)
	if !syncStageUsesSnapshotTransfer(pipelineStage) {
		pipelineStage = "snapshot_delta"
	}
	// `setSnapshotProgress` stores the value produced by this operation.
	setSnapshotProgress := func(height uint64, baseAction string) {
		// `action` stores the value produced by this operation.
		action := syncSnapshotProgressAction(pipelineStage, baseAction)
		n.setSyncAction(pipelineStage, syncLagBlocks(height, targetHeight), action)
	}
	// `applyVerifiedSnapshot` applies a snapshot that has already passed the
	// trusted/local validation path. SnapshotManager verifies and returns the
	// object, but it does not mutate chain state by itself.
	applyVerifiedSnapshot := func(snap *StateSnapshot, trusted bool) bool {
		if snap == nil || snap.Height == 0 {
			return false
		}
		populateSnapshotDerivedFields(snap)
		if !n.snapshotSessionApplyAttemptAllowed(strings.TrimSpace(snap.SnapshotHash), localHeight, targetHeight) {
			n.recordSnapshotSessionStrictResult("", "same_snapshot_reapply")
			n.snapshotSessionMarkFailure("same_snapshot_reapply")
			n.rotateSnapshotProvider()
			n.persistSnapshotSessionState("same_snapshot_reapply_blocked")
			return false
		}
		if snap.Height < targetHeight {
			n.retargetSnapshotSessionLowerAvailable(targetHeight, snap.Height, snapshotCheckpointHeightFor(snap.Height), "snapshot_lower_available_applied")
		}
		n.setSnapshotSessionStage(SnapshotSyncStageApplySnapshot)
		recoveryApply := allowReapply && snap.Height <= localHeight
		if recoveryApply {
			if !n.ApplySnapshotForRecovery(*snap) {
				n.recordSnapshotSessionStrictResult("", "snapshot_apply_noop")
				n.snapshotSessionMarkFailure("snapshot_apply_noop")
				return false
			}
		} else {
			if !n.ApplySnapshotForSync(*snap) {
				n.recordSnapshotSessionStrictResult("", "snapshot_apply_noop")
				n.snapshotSessionMarkFailure("snapshot_apply_noop")
				return false
			}
		}
		n.noteSnapshotApplied(snap.Height)
		n.markSnapshotSessionApplied(snap, 0)
		setSnapshotProgress(snap.Height, "snapshot_applied")
		localHeight = n.Blockchain.Height()
		applied = true
		if DebugConsensus {
			source := "trusted"
			if !trusted {
				source = "local"
			}
			mode := "sync"
			if recoveryApply {
				mode = "recovery"
			}
			fmt.Printf("Applied %s snapshot height=%d mode=%s\n", source, snap.Height, mode)
		}
		return true
	}

	// Snapshot is last resort for near-range catch-up; prefer direct block sync first.
	if !allowReapply && targetHeight > localHeight && targetHeight-localHeight <= 32 {
		n.setSyncAction("range_fetch", syncLagBlocks(localHeight, targetHeight), "range_fetch")
		if n.syncBlocksFromPeers(targetHeight) {
			return true
		}
		localHeight = n.Blockchain.Height()
		if targetHeight <= localHeight {
			return true
		}
	}

	// Forced re-sync should prefer trusted peer snapshots so a node can recover
	// from a divergent local snapshot at the same height.
	if allowReapply {
		setSnapshotProgress(localHeight, "snapshot_fetch_verify")
		n.setSnapshotSessionStage(SnapshotSyncStageCollectProofs)
		reapplyTrustedAttempted = sourcePolicy == snapshotSyncSourceTrustedOnly
		// `managerMinHeight` stores the value produced by this operation.
		managerMinHeight := localHeight
		if minHeightOverride > 0 && minHeightOverride < managerMinHeight {
			managerMinHeight = minHeightOverride
		}
		// `manager` stores the value produced by this operation.
		manager := NewSnapshotManager(n, targetHeight, managerMinHeight, sourcePolicy == snapshotSyncSourceTrustedOnly)
		// `snap` and `err` store the error produced by this operation.
		snap, _, err := manager.StartSession(true)
		if err == nil && snap != nil {
			if DebugConsensus {
				fmt.Printf("RECOVERY trusted snapshot height=%d checkpoint=%d proofs=%d\n", snap.Height, manager.CheckpointHeight, len(manager.Proofs))
			}
			if !applyVerifiedSnapshot(snap, true) {
				return false
			}
			if n.Blockchain.Height() >= targetHeight {
				return true
			}
		} else if reapplyTrustedAttempted {
			reapplyTrustedFailed = true
		}
	}

	if reapplyTrustedAttempted && reapplyTrustedFailed && !applied {
		// Avoid duplicate strict fetch cycles in one loop; next watchdog/tick will retry.
		return false
	}

	// `tryLocal` stores the value produced by this operation.
	tryLocal := func(snap *StateSnapshot) bool {
		if snap == nil || snap.Height == 0 {
			return false
		}
		populateSnapshotDerivedFields(snap)
		if snap.Height < localHeight {
			return false
		}
		// Catch-up guard: when we are behind target, re-applying the exact same
		// local snapshot height causes an infinite recovery loop and blocks peer
		// snapshot fetch/apply paths.
		if allowReapply && snap.Height == localHeight && targetHeight > localHeight {
			return false
		}
		if !allowReapply && snap.Height == localHeight {
			return false
		}
		if GenesisHash != "" {
			if snap.GenesisHash == "" || snap.GenesisHash != GenesisHash {
				return false
			}
		}
		// `ledgerHash` stores the digest used to identify or verify the related data.
		ledgerHash := HashLedger(snap.Ledger)
		if snap.LedgerHash == "" || ledgerHash != snap.LedgerHash {
			return false
		}
		if snap.StateRoot == "" || snap.BlockHash == "" {
			return false
		}
		if !snapshotHasValidMetadata(snap) {
			return false
		}
		// `registryHash` stores the digest used to identify or verify the related data.
		registryHash := strings.TrimSpace(snapshotValidatorRegistryHash(snap))
		if registryHash == "" {
			return false
		}
		// `expectedRegistry` stores the value produced by this operation.
		if expectedRegistry, _ := n.expectedValidatorRegistryHashWithSource(snap.Height + 1); expectedRegistry != "" &&
			!strings.EqualFold(registryHash, strings.TrimSpace(expectedRegistry)) {
			return false
		}
		// `blk` and `ok` store whether the related condition is satisfied.
		if blk, ok := n.LoadBlock(int(snap.Height)); ok {
			if blk.BlockHash != snap.BlockHash {
				return false
			}
			// `expectedSetHash` stores the digest used to identify or verify the related data.
			expectedSetHash := strings.TrimSpace(blk.NextValidatorSetHash)
			if expectedSetHash == "" {
				expectedSetHash = strings.TrimSpace(blk.ValidatorSetHash)
			}
			if expectedSetHash != "" && !strings.EqualFold(strings.TrimSpace(snapshotValidatorSetHash(snap)), expectedSetHash) {
				return false
			}
			if strings.TrimSpace(blk.StateRoot) == "" || strings.TrimSpace(snap.StateRoot) == "" {
				return false
			}
			if !strings.EqualFold(strings.TrimSpace(blk.StateRoot), strings.TrimSpace(snap.StateRoot)) {
				return false
			}
		}
		return applyVerifiedSnapshot(snap, false)
	}

	if sourcePolicy != snapshotSyncSourceTrustedOnly {
		// `snap` and `err` store the error produced by this operation.
		if snap, err := n.GetSnapshot(targetHeight); err == nil && snap != nil {
			if tryLocal(snap) {
				return n.Blockchain.Height() >= targetHeight
			}
		}
		// `snap` and `err` store the error produced by this operation.
		if snap, err := n.GetSnapshotAtOrBelow(targetHeight); err == nil && snap != nil {
			if tryLocal(snap) {
				return n.Blockchain.Height() >= targetHeight
			}
		}
	}

	if !applied {
		if n.runEnterpriseSnapshotPipeline(targetHeight, allowReapply) {
			// `currentHeight` stores the value produced by this operation.
			currentHeight := n.Blockchain.Height()
			if currentHeight > localHeight || (allowReapply && currentHeight == localHeight) {
				n.setSnapshotSessionStage(SnapshotSyncStageApplySnapshot)
				setSnapshotProgress(currentHeight, "snapshot_applied")
				applied = true
			}
			if currentHeight >= targetHeight {
				return true
			}
		}
	}

	if !applied {
		// `minHeight` stores the value produced by this operation.
		minHeight := localHeight + 1
		if allowReapply {
			minHeight = localHeight
		}
		if minHeightOverride > 0 {
			minHeight = minHeightOverride
		}
		setSnapshotProgress(localHeight, "snapshot_fetch_verify")
		n.setSnapshotSessionStage(SnapshotSyncStageCollectProofs)
		// `manager` stores the value produced by this operation.
		manager := NewSnapshotManager(n, targetHeight, minHeight, sourcePolicy == snapshotSyncSourceTrustedOnly)
		// `snap` and `err` store the error produced by this operation.
		snap, _, err := manager.StartSession(allowReapply)
		if err == nil && snap != nil && (snap.Height > localHeight || (allowReapply && snap.Height <= localHeight)) {
			if DebugConsensus {
				if allowReapply && snap.Height <= localHeight {
					fmt.Printf("RECOVERY trusted snapshot height=%d checkpoint=%d proofs=%d\n", snap.Height, manager.CheckpointHeight, len(manager.Proofs))
				} else {
					fmt.Printf("Applied trusted snapshot height=%d checkpoint=%d proofs=%d\n", snap.Height, manager.CheckpointHeight, len(manager.Proofs))
				}
			}
			if !applyVerifiedSnapshot(snap, true) {
				return false
			}
		}
	}

	// `currentHeight` stores the value produced by this operation.
	currentHeight := n.Blockchain.Height()
	if currentHeight < targetHeight {
		// Snapshot-first late-join guard:
		// a fresh node (height=0) must not replay historical blocks before
		// obtaining a trusted snapshot from live validators. Genesis bootstrap
		// remains the only block-replay exception.
		if !applied && currentHeight == 0 && targetHeight > 1 {
			if DebugSync || DebugConsensus {
				fmt.Printf("[SYNC] waiting for trusted snapshot | local=%d target=%d\n", currentHeight, targetHeight)
			}
			return false
		}
		n.setSyncAction(pipelineStage, syncLagBlocks(currentHeight, targetHeight), "delta_replay")
		n.setSnapshotSessionStage(SnapshotSyncStageDeltaReplay)
		if n.syncDeltaReplayFromPeers(targetHeight) {
			return true
		}
	}
	return n.Blockchain.Height() >= targetHeight
}

type snapshotChunkResumeState struct {
	// `Height` stores the value associated with this record.
	Height uint64 `json:"height"`
	// `SnapshotHash` stores the digest used to identify or verify the related data.
	SnapshotHash string `json:"snapshot_hash"`
	// `StateRoot` stores the digest used to identify or verify the related data.
	StateRoot string `json:"state_root,omitempty"`
	// `StateMerkleRoot` stores the digest used to identify or verify the related data.
	StateMerkleRoot string `json:"state_merkle_root,omitempty"`
	// `ValidatorSetHash` stores whether the related condition is satisfied.
	ValidatorSetHash string `json:"validator_set_hash,omitempty"`
	// `ValidatorRegistryHash` stores whether the related condition is satisfied.
	ValidatorRegistryHash string `json:"validator_registry_hash,omitempty"`
	// `PromotionWindowHash` stores the digest used to identify or verify the related data.
	PromotionWindowHash string `json:"promotion_window_hash,omitempty"`
	// `ManifestHash` stores the digest used to identify or verify the related data.
	ManifestHash string `json:"manifest_hash,omitempty"`
	// `ChunkSize` stores the measured quantity used by this operation.
	ChunkSize uint64 `json:"chunk_size"`
	// `TotalChunks` stores the measured quantity used by this operation.
	TotalChunks uint64 `json:"total_chunks"`
	// `Received` stores the value associated with this record.
	Received map[uint64]bool `json:"received"`
	// `Providers` stores the value associated with this record.
	Providers []string `json:"providers,omitempty"`
	// `VerifyStage` stores the value associated with this record.
	VerifyStage string `json:"verify_stage,omitempty"`
	// `ResumeState` stores the result produced by this operation.
	ResumeState string `json:"resume_state,omitempty"`
	// `UpdatedAt` stores the value associated with this record.
	UpdatedAt int64 `json:"updated_at"`
}

const (
	maxSnapshotSyncPathTokenBytes  = 96
	maxSnapshotResumeStateBytes   = 4 << 20
)

// sanitizeSyncPathToken implements the sanitize sync path token helper.
func sanitizeSyncPathToken(v string) string {
	v = strings.TrimSpace(v)
	if v == "" {
		return "unknown"
	}
	// Snapshot hashes originate from peers. Keep filesystem component lengths
	// bounded; hash oversized tokens instead of truncating them and creating
	// attacker-controlled path collisions.
	if len(v) > maxSnapshotSyncPathTokenBytes {
		sum := sha256.Sum256([]byte(v))
		return hex.EncodeToString(sum[:])
	}
	v = strings.ToLower(v)
	// `b` stores the value used by this operation.
	var b strings.Builder
	b.Grow(len(v))
	// `r` tracks the current values while iterating.
	for _, r := range v {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			b.WriteRune(r)
			continue
		}
		b.WriteByte('_')
	}
	// `out` stores the result produced by this operation.
	out := strings.Trim(b.String(), "_")
	if out == "" {
		return "unknown"
	}
	return out
}

// snapshotSyncWorkDir implements the snapshot sync work dir helper.
func (n *Node) snapshotSyncWorkDir() string {
	// `base` stores the value produced by this operation.
	base := strings.TrimSpace(n.DataDir)
	if base == "" {
		base = "."
	}
	// `dir` stores the value produced by this operation.
	dir := filepath.Join(base, "sync_snapshots")
	_ = os.MkdirAll(dir, 0o700)
	return dir
}

// snapshotResumePaths implements the snapshot resume paths helper.
func (n *Node) snapshotResumePaths(height uint64, snapshotHash string) (string, string) {
	// `name` stores the value produced by this operation.
	name := fmt.Sprintf("%d_%s", height, sanitizeSyncPathToken(snapshotHash))
	// `base` stores the value produced by this operation.
	base := filepath.Join(n.snapshotSyncWorkDir(), name)
	return base + ".json", base + "_chunks"
}

// loadSnapshotChunkResumeState implements the load snapshot chunk resume state helper.
func loadSnapshotChunkResumeState(path string) (*snapshotChunkResumeState, error) {
	// Resume state is local, but it can be left corrupt or unexpectedly large by
	// a crash. Read through a hard limit so startup cannot allocate from an
	// unbounded file before the manifest has been validated.
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	raw, err := io.ReadAll(io.LimitReader(file, int64(maxSnapshotResumeStateBytes)+1))
	if err != nil {
		return nil, err
	}
	if len(raw) == 0 || len(raw) > maxSnapshotResumeStateBytes {
		return nil, fmt.Errorf("snapshot resume state size invalid")
	}
	// `state` stores the value used by this operation.
	var state snapshotChunkResumeState
	// `err` stores the error produced by this operation.
	if err := json.Unmarshal(raw, &state); err != nil {
		return nil, err
	}
	if state.Received == nil {
		state.Received = make(map[uint64]bool)
	}
	if state.TotalChunks > maxSnapshotTransferChunkCount {
		return nil, fmt.Errorf("snapshot resume chunk count invalid")
	}
	for idx, received := range state.Received {
		if !received || (state.TotalChunks > 0 && idx >= state.TotalChunks) {
			delete(state.Received, idx)
		}
	}
	return &state, nil
}

// saveSnapshotChunkResumeState implements the save snapshot chunk resume state helper.
func saveSnapshotChunkResumeState(path string, state *snapshotChunkResumeState) {
	if state == nil {
		return
	}
	state.UpdatedAt = time.Now().Unix()
	// `raw` and `err` store the error produced by this operation.
	raw, err := json.Marshal(state)
	if err != nil || len(raw) > maxSnapshotResumeStateBytes {
		return
	}
	_ = writeFileAtomic(path, raw, 0o600)
}

// isSyncTimeoutError implements the is sync timeout error helper.
func isSyncTimeoutError(err error) bool {
	if err == nil {
		return false
	}
	// `phaseErr` stores the error produced by this operation.
	var phaseErr *blockRequestPhaseError
	if errors.As(err, &phaseErr) {
		return phaseErr.Timeout
	}
	// `msg` stores the value produced by this operation.
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "timeout") || strings.Contains(msg, "deadline exceeded")
}

// snapshotProvidersForManifest implements the snapshot providers for manifest helper.
func (n *Node) snapshotProvidersForManifest(manifest *SnapshotManifest, primary peer.ID, peers []peer.ID) []peer.ID {
	if manifest == nil {
		if strings.TrimSpace(primary.String()) == "" {
			return nil
		}
		return []peer.ID{primary}
	}
	normalizeSnapshotManifest(manifest)
	if !syncSnapshotDistributionEnabled() {
		if strings.TrimSpace(primary.String()) == "" {
			return nil
		}
		return []peer.ID{primary}
	}
	// `unique` stores the value produced by this operation.
	unique := make(map[string]peer.ID, len(peers)+1)
	if strings.TrimSpace(primary.String()) != "" {
		unique[primary.String()] = primary
	}
	// `candidate` tracks the current values while iterating.
	for _, candidate := range peers {
		// `pid` stores the value produced by this operation.
		pid := candidate
		if strings.TrimSpace(pid.String()) == "" {
			continue
		}
		n.peerStateMu.Lock()
		// `validatorID` stores whether the related condition is satisfied.
		validatorID := normalizeValidatorID(n.peerToValidator[pid.String()])
		n.peerStateMu.Unlock()
		if validatorID == "" {
			continue
		}
		// `ok` stores whether the related condition is satisfied.
		if _, ok := unique[pid.String()]; ok {
			continue
		}
		// `meta` and `err` store the error produced by this operation.
		meta, err := n.requestSnapshotMetaFromPeer(pid, manifest.Height)
		if err != nil || meta == nil || !meta.Available {
			continue
		}
		if !snapshotManifestMatches(manifest, snapshotManifestFromMeta(meta)) {
			continue
		}
		unique[pid.String()] = pid
	}
	if len(unique) == 0 {
		return nil
	}
	// `providers` stores the value produced by this operation.
	providers := make([]peer.ID, 0, len(unique))
	// `pid` tracks the current values while iterating.
	for _, pid := range unique {
		providers = append(providers, pid)
	}
	sort.SliceStable(providers, func(i, j int) bool {
		// `pi` stores the current position in the related collection.
		pi := n.snapshotProviderPreferenceValue(manifest.Height, manifest.SnapshotHash, providers[i].String())
		// `pj` stores the current position in the related collection.
		pj := n.snapshotProviderPreferenceValue(manifest.Height, manifest.SnapshotHash, providers[j].String())
		if pi != pj {
			return pi > pj
		}
		// `chunki` stores the current position in the related collection.
		chunki := n.snapshotChunkGossipProviderScore(manifest.Height, manifest.SnapshotHash, providers[i].String())
		// `chunkj` stores the current position in the related collection.
		chunkj := n.snapshotChunkGossipProviderScore(manifest.Height, manifest.SnapshotHash, providers[j].String())
		if chunki != chunkj {
			return chunki > chunkj
		}
		// `si` stores the current position in the related collection.
		si := n.syncPeerScoreValue(providers[i].String())
		// `sj` stores the current position in the related collection.
		sj := n.syncPeerScoreValue(providers[j].String())
		if si == sj {
			if providers[i] == primary {
				return true
			}
			if providers[j] == primary {
				return false
			}
			return providers[i].String() < providers[j].String()
		}
		return si > sj
	})
	return providers
}

// fetchSnapshotFromManifestChunks implements the fetch snapshot from manifest chunks helper.
func (n *Node) fetchSnapshotFromManifestChunks(manifest *SnapshotManifest, providers []peer.ID, minHeight uint64) (*StateSnapshot, error) {
	if manifest == nil {
		return nil, fmt.Errorf("snapshot manifest unavailable")
	}
	normalizeSnapshotManifest(manifest)
	if !snapshotManifestBasicValid(manifest, manifest.Height, minHeight) {
		return nil, fmt.Errorf("invalid snapshot manifest")
	}
	if len(providers) == 0 {
		return nil, fmt.Errorf("snapshot providers unavailable")
	}

	// `manifestPath` and `chunksDir` store the value produced by this operation.
	manifestPath, chunksDir := n.snapshotResumePaths(manifest.Height, manifest.SnapshotHash)
	// `err` stores the error produced by this operation.
	if err := os.MkdirAll(chunksDir, 0o700); err != nil {
		return nil, err
	}

	// `manifestHash` stores the digest used to identify or verify the related data.
	manifestHash := snapshotManifestHash(manifest)
	// `state` and `err` store the error produced by this operation.
	state, err := loadSnapshotChunkResumeState(manifestPath)
	// `resumeState` stores the result produced by this operation.
	resumeState := "fresh"
	if err != nil || state == nil ||
		state.Height != manifest.Height ||
		!strings.EqualFold(state.SnapshotHash, manifest.SnapshotHash) ||
		state.TotalChunks != manifest.ChunkCount ||
		state.ChunkSize != manifest.ChunkSize ||
		!strings.EqualFold(state.ManifestHash, manifestHash) {
		if err == nil && state != nil {
			resumeState = "reset"
		}
		state = &snapshotChunkResumeState{
			Height:                manifest.Height,
			SnapshotHash:          manifest.SnapshotHash,
			StateRoot:             manifest.StateRoot,
			StateMerkleRoot:       manifest.StateMerkleRoot,
			ValidatorSetHash:      manifest.ValidatorSetHash,
			ValidatorRegistryHash: manifest.ValidatorRegistryHash,
			PromotionWindowHash:   manifest.PromotionWindowHash,
			ManifestHash:          manifestHash,
			ChunkSize:             manifest.ChunkSize,
			TotalChunks:           manifest.ChunkCount,
			Received:              make(map[uint64]bool),
			VerifyStage:           "manifest_verified",
			ResumeState:           resumeState,
		}
	} else {
		resumeState = "restored"
		if state.Received == nil {
			state.Received = make(map[uint64]bool)
		}
		state.StateRoot = manifest.StateRoot
		state.StateMerkleRoot = manifest.StateMerkleRoot
		state.ValidatorSetHash = manifest.ValidatorSetHash
		state.ValidatorRegistryHash = manifest.ValidatorRegistryHash
		state.PromotionWindowHash = manifest.PromotionWindowHash
		state.ManifestHash = manifestHash
		state.VerifyStage = "manifest_verified"
		state.ResumeState = resumeState
	}

	// `pid` tracks the current values while iterating.
	for _, pid := range providers {
		// `id` stores the current position in the related collection.
		id := strings.TrimSpace(pid.String())
		if id == "" {
			continue
		}
		// `seen` stores the value produced by this operation.
		seen := false
		// `existing` tracks the current values while iterating.
		for _, existing := range state.Providers {
			if existing == id {
				seen = true
				break
			}
		}
		if !seen {
			state.Providers = append(state.Providers, id)
		}
	}

	// `idx` stores the current position in the related collection.
	for idx := uint64(0); idx < manifest.ChunkCount; idx++ {
		// `chunkPath` stores the value produced by this operation.
		chunkPath := filepath.Join(chunksDir, fmt.Sprintf("%08d.chunk", idx))
		// `raw` and `err` store the error produced by this operation.
		raw, err := os.ReadFile(chunkPath)
		if err != nil || len(raw) == 0 {
			delete(state.Received, idx)
			continue
		}
		if !snapshotManifestChunkDataValid(manifest, idx, raw) ||
			idx >= uint64(len(manifest.ChunkHashes)) ||
			!strings.EqualFold(snapshotChunkHash(raw), manifest.ChunkHashes[idx]) {
			_ = os.Remove(chunkPath)
			delete(state.Received, idx)
			continue
		}
		state.Received[idx] = true
	}
	saveSnapshotChunkResumeState(manifestPath, state)
	n.setSnapshotDownloadStatus(manifest, uint64(len(state.Received)), state.Providers, state.VerifyStage, state.ResumeState)

	// `missing` stores the value produced by this operation.
	missing := make([]uint64, 0, manifest.ChunkCount)
	// `idx` stores the current position in the related collection.
	for idx := uint64(0); idx < manifest.ChunkCount; idx++ {
		if !state.Received[idx] {
			missing = append(missing, idx)
		}
	}

	if len(missing) > 0 {
		var (
			// `stateMu` stores the synchronization state protecting shared data.
			stateMu sync.Mutex
			// `firstErr` stores the error produced by this operation.
			firstErr error
		)
		// `idxCh` stores the current position in the related collection.
		idxCh := make(chan uint64, len(missing))
		// `workers` stores the value produced by this operation.
		workers := snapshotChunkWorkerCount(len(missing))
		// `orderedProviders` stores the value produced by this operation.
		orderedProviders := append([]peer.ID{}, providers...)
		// `wg` stores the value used by this operation.
		var wg sync.WaitGroup
		// `i` stores the current position in the related collection.
		for i := 0; i < workers; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				// `idx` tracks the current position in the related collection.
				for idx := range idxCh {
					stateMu.Lock()
					if firstErr != nil {
						stateMu.Unlock()
						return
					}
					stateMu.Unlock()

					// `data`, `pid`, and `err` store the error produced by this operation.
					data, pid, err := n.fetchReplicatedSnapshotChunk(manifest, orderedProviders, idx)
					if err != nil {
						var (
							// `downloaded` stores the value used by this operation.
							downloaded uint64
							// `providerList` stores the value used by this operation.
							providerList []string
						)
						stateMu.Lock()
						if firstErr == nil {
							firstErr = fmt.Errorf("snapshot chunk unavailable index=%d", idx)
						}
						state.VerifyStage = "chunk_retry"
						state.ResumeState = "partial"
						saveSnapshotChunkResumeState(manifestPath, state)
						downloaded = uint64(len(state.Received))
						providerList = copyStringSlice(state.Providers)
						stateMu.Unlock()
						n.setSnapshotDownloadStatus(manifest, downloaded, providerList, "chunk_retry", "partial")
						return
					}
					// `chunkPath` stores the value produced by this operation.
					chunkPath := filepath.Join(chunksDir, fmt.Sprintf("%08d.chunk", idx))
					// `err` stores the error produced by this operation.
					if err := os.WriteFile(chunkPath, data, 0o600); err != nil {
						var (
							// `downloaded` stores the value used by this operation.
							downloaded uint64
							// `providerList` stores the value used by this operation.
							providerList []string
						)
						stateMu.Lock()
						if firstErr == nil {
							firstErr = err
						}
						state.VerifyStage = "chunk_retry"
						state.ResumeState = "partial"
						saveSnapshotChunkResumeState(manifestPath, state)
						downloaded = uint64(len(state.Received))
						providerList = copyStringSlice(state.Providers)
						stateMu.Unlock()
						n.setSnapshotDownloadStatus(manifest, downloaded, providerList, "chunk_retry", "partial")
						return
					}
					stateMu.Lock()
					state.Received[idx] = true
					state.VerifyStage = "download"
					state.ResumeState = resumeState
					saveSnapshotChunkResumeState(manifestPath, state)
					// `downloaded` stores the value produced by this operation.
					downloaded := uint64(len(state.Received))
					// `providerList` stores the value produced by this operation.
					providerList := copyStringSlice(state.Providers)
					stateMu.Unlock()
					n.setSnapshotDownloadStatus(manifest, downloaded, providerList, "download", resumeState)
					if DebugSync {
						fmt.Printf("[SNAPSHOT-CHUNK] applied height=%d idx=%d provider=%s downloaded=%d/%d\n",
							manifest.Height, idx, pid.String(), downloaded, manifest.ChunkCount)
					}
				}
			}()
		}
		// `idx` tracks the current position in the related collection.
		for _, idx := range missing {
			idxCh <- idx
		}
		close(idxCh)
		wg.Wait()
		if firstErr != nil {
			return nil, firstErr
		}
	}

	state.VerifyStage = "assemble"
	state.ResumeState = "verifying"
	saveSnapshotChunkResumeState(manifestPath, state)
	n.setSnapshotDownloadStatus(manifest, manifest.ChunkCount, state.Providers, "assemble", "verifying")

	// `merged` stores the value used by this operation.
	var merged bytes.Buffer
	// `idx` stores the current position in the related collection.
	for idx := uint64(0); idx < manifest.ChunkCount; idx++ {
		// `chunkPath` stores the value produced by this operation.
		chunkPath := filepath.Join(chunksDir, fmt.Sprintf("%08d.chunk", idx))
		// `raw` and `err` store the error produced by this operation.
		raw, err := os.ReadFile(chunkPath)
		if err != nil {
			return nil, err
		}
		if !strings.EqualFold(snapshotChunkHash(raw), manifest.ChunkHashes[idx]) {
			return nil, fmt.Errorf("assembled chunk mismatch index=%d", idx)
		}
		merged.Write(raw)
	}

	// `snap` and `err` store the error produced by this operation.
	snap, err := verifySnapshotPayloadAgainstManifest(merged.Bytes(), manifest, minHeight)
	if err != nil {
		return nil, err
	}
	n.mergeSnapshotProofsFromManifest(snap, manifest)
	// `valid`, `required`, and `ok` store whether the related condition is satisfied.
	if valid, required, ok := n.verifySnapshotCheckpointProofPolicy(snap); !ok {
		return nil, fmt.Errorf("snapshot checkpoint proof quorum unavailable valid=%d required=%d", valid, required)
	}
	state.VerifyStage = "verified"
	state.ResumeState = "verified"
	saveSnapshotChunkResumeState(manifestPath, state)
	n.setSnapshotDownloadStatus(manifest, manifest.ChunkCount, state.Providers, "verified", "verified")
	if DebugSync || DebugConsensus {
		fmt.Printf("[SNAPSHOT-MANIFEST] accepted height=%d hash=%s providers=%d chunks=%d\n",
			manifest.Height, ShortHash(manifest.SnapshotHash), len(state.Providers), manifest.ChunkCount)
	}
	return snap, nil
}

// fetchSnapshotFromPeerChunks implements the fetch snapshot from peer chunks helper.
func (n *Node) fetchSnapshotFromPeerChunks(pid peer.ID, targetHeight uint64, minHeight uint64) (*StateSnapshot, error) {
	// `meta` and `err` store the error produced by this operation.
	meta, err := n.requestSnapshotMetaFromPeer(pid, targetHeight)
	if err != nil {
		return nil, err
	}
	if meta == nil || !meta.Available {
		return nil, fmt.Errorf("snapshot meta unavailable")
	}
	if meta.Height == 0 || meta.Height > targetHeight {
		return nil, fmt.Errorf("invalid snapshot meta height=%d target=%d", meta.Height, targetHeight)
	}
	if minHeight > 0 && meta.Height < minHeight {
		return nil, fmt.Errorf("snapshot height %d below required minimum %d", meta.Height, minHeight)
	}
	if meta.TotalChunks == 0 || meta.ChunkSize == 0 || strings.TrimSpace(meta.SnapshotHash) == "" {
		return nil, fmt.Errorf("invalid snapshot meta payload")
	}
	if !snapshotChunkLayoutValid(meta.ChunkSize, meta.TotalChunks, 0) {
		return nil, fmt.Errorf("invalid snapshot meta chunk layout")
	}
	// `manifest` stores the value produced by this operation.
	manifest := snapshotManifestFromMeta(meta)
	if snapshotManifestBasicValid(manifest, targetHeight, minHeight) {
		// `providers` stores the value produced by this operation.
		providers := n.snapshotProvidersForManifest(manifest, pid, n.Host.Network().Peers())
		if len(providers) > 0 {
			return n.fetchSnapshotFromManifestChunks(manifest, providers, minHeight)
		}
	}

	// `manifestPath` and `chunksDir` store the value produced by this operation.
	manifestPath, chunksDir := n.snapshotResumePaths(meta.Height, meta.SnapshotHash)
	// `err` stores the error produced by this operation.
	if err := os.MkdirAll(chunksDir, 0o700); err != nil {
		return nil, err
	}

	// `state` and `stateErr` store the error produced by this operation.
	state, stateErr := loadSnapshotChunkResumeState(manifestPath)
	if stateErr != nil || state == nil ||
		state.Height != meta.Height ||
		!strings.EqualFold(state.SnapshotHash, meta.SnapshotHash) ||
		state.TotalChunks != meta.TotalChunks {
		state = &snapshotChunkResumeState{
			Height:              meta.Height,
			SnapshotHash:        meta.SnapshotHash,
			StateMerkleRoot:     strings.TrimSpace(meta.StateMerkleRoot),
			PromotionWindowHash: strings.TrimSpace(meta.PromotionWindowHash),
			ChunkSize:           meta.ChunkSize,
			TotalChunks:         meta.TotalChunks,
			Received:            make(map[uint64]bool),
			ResumeState:         "legacy",
			VerifyStage:         "download",
		}
	}
	state.StateRoot = strings.TrimSpace(meta.StateRoot)
	state.StateMerkleRoot = strings.TrimSpace(meta.StateMerkleRoot)
	state.ValidatorSetHash = strings.TrimSpace(meta.ValidatorSetHash)
	state.ValidatorRegistryHash = strings.TrimSpace(meta.ValidatorRegistryHash)
	state.PromotionWindowHash = strings.TrimSpace(meta.PromotionWindowHash)
	// `provider` stores the value produced by this operation.
	provider := strings.TrimSpace(pid.String())
	if provider != "" {
		// `seen` stores the value produced by this operation.
		seen := false
		// `existing` tracks the current values while iterating.
		for _, existing := range state.Providers {
			if existing == provider {
				seen = true
				break
			}
		}
		if !seen {
			state.Providers = append(state.Providers, provider)
		}
	}
	// `idx` stores the current position in the related collection.
	for idx := uint64(0); idx < meta.TotalChunks; idx++ {
		if state.Received[idx] {
			continue
		}
		// `chunkPath` stores the value produced by this operation.
		chunkPath := filepath.Join(chunksDir, fmt.Sprintf("%08d.chunk", idx))
		// `st` and `err` store the error produced by this operation.
		legacyLayout := &SnapshotManifest{ChunkSize: meta.ChunkSize, ChunkCount: meta.TotalChunks}
		if st, err := os.Stat(chunkPath); err == nil && st.Size() > 0 &&
			snapshotManifestChunkLengthValid(legacyLayout, idx, uint64(st.Size())) {
			state.Received[idx] = true
		}
	}
	saveSnapshotChunkResumeState(manifestPath, state)
	n.setSnapshotDownloadStatus(&SnapshotManifest{
		Height:                meta.Height,
		SnapshotHash:          meta.SnapshotHash,
		StateRoot:             meta.StateRoot,
		StateMerkleRoot:       meta.StateMerkleRoot,
		ValidatorSetHash:      meta.ValidatorSetHash,
		ValidatorRegistryHash: meta.ValidatorRegistryHash,
		PromotionWindowHash:   meta.PromotionWindowHash,
		ChunkSize:             meta.ChunkSize,
		ChunkCount:            meta.TotalChunks,
	}, uint64(len(state.Received)), state.Providers, "legacy_download", "legacy")

	// `missing` stores the value produced by this operation.
	missing := make([]uint64, 0, meta.TotalChunks)
	// `idx` stores the current position in the related collection.
	for idx := uint64(0); idx < meta.TotalChunks; idx++ {
		if !state.Received[idx] {
			missing = append(missing, idx)
		}
	}

	if len(missing) > 0 {
		// `stateMu` stores the synchronization state protecting shared data.
		var stateMu sync.Mutex
		// `firstErr` stores the error produced by this operation.
		var firstErr error
		// `idxCh` stores the current position in the related collection.
		idxCh := make(chan uint64, len(missing))
		// `workers` stores the value produced by this operation.
		workers := syncSnapshotParallelChunks()
		if workers > len(missing) {
			workers = len(missing)
		}
		if workers <= 0 {
			workers = 1
		}
		// `wg` stores the value used by this operation.
		var wg sync.WaitGroup
		// `i` stores the current position in the related collection.
		for i := 0; i < workers; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				// `idx` tracks the current position in the related collection.
				for idx := range idxCh {
					stateMu.Lock()
					if firstErr != nil {
						stateMu.Unlock()
						return
					}
					stateMu.Unlock()

					// `started` stores the value produced by this operation.
					started := time.Now()
					// `resp` and `err` store the error produced by this operation.
					resp, err := n.requestSnapshotChunkFromPeer(pid, meta.Height, idx)
					// `elapsed` stores the value produced by this operation.
					elapsed := time.Since(started)
					if err != nil {
						n.recordSyncPeerSnapshotResult(pid.String(), false, elapsed, 0, isSyncTimeoutError(err))
						stateMu.Lock()
						if firstErr == nil {
							firstErr = err
						}
						stateMu.Unlock()
						return
					}
					if resp == nil || resp.Height != meta.Height || resp.Index != idx {
						n.recordSyncPeerSnapshotResult(pid.String(), false, elapsed, 0, false)
						stateMu.Lock()
						if firstErr == nil {
							firstErr = fmt.Errorf("invalid snapshot chunk response index=%d", idx)
						}
						stateMu.Unlock()
						return
					}
					if !strings.EqualFold(strings.TrimSpace(resp.SnapshotHash), strings.TrimSpace(meta.SnapshotHash)) {
						n.recordSyncPeerSnapshotResult(pid.String(), false, elapsed, len(resp.Data), false)
						stateMu.Lock()
						if firstErr == nil {
							firstErr = fmt.Errorf("snapshot hash mismatch for chunk %d", idx)
						}
						stateMu.Unlock()
						return
					}
					legacyLayout := &SnapshotManifest{ChunkSize: meta.ChunkSize, ChunkCount: meta.TotalChunks}
					if !snapshotManifestChunkDataValid(legacyLayout, idx, resp.Data) {
						n.recordSyncPeerSnapshotResult(pid.String(), false, elapsed, len(resp.Data), false)
						stateMu.Lock()
						if firstErr == nil {
							firstErr = fmt.Errorf("snapshot chunk size mismatch index=%d", idx)
						}
						stateMu.Unlock()
						return
					}
					if !strings.EqualFold(strings.TrimSpace(resp.ChunkHash), snapshotChunkHash(resp.Data)) {
						n.recordSyncPeerSnapshotResult(pid.String(), false, elapsed, len(resp.Data), false)
						stateMu.Lock()
						if firstErr == nil {
							firstErr = fmt.Errorf("chunk hash mismatch index=%d", idx)
						}
						stateMu.Unlock()
						return
					}

					// `chunkPath` stores the value produced by this operation.
					chunkPath := filepath.Join(chunksDir, fmt.Sprintf("%08d.chunk", idx))
					// `err` stores the error produced by this operation.
					if err := os.WriteFile(chunkPath, resp.Data, 0o600); err != nil {
						n.recordSyncPeerSnapshotResult(pid.String(), false, elapsed, len(resp.Data), false)
						stateMu.Lock()
						if firstErr == nil {
							firstErr = err
						}
						stateMu.Unlock()
						return
					}
					n.recordSyncPeerSnapshotResult(pid.String(), true, elapsed, len(resp.Data), false)
					stateMu.Lock()
					state.Received[idx] = true
					stateMu.Unlock()
				}
			}()
		}
		// `idx` tracks the current position in the related collection.
		for _, idx := range missing {
			idxCh <- idx
		}
		close(idxCh)
		wg.Wait()
		if firstErr != nil {
			saveSnapshotChunkResumeState(manifestPath, state)
			return nil, firstErr
		}
		saveSnapshotChunkResumeState(manifestPath, state)
	}

	// `merged` stores the value used by this operation.
	var merged bytes.Buffer
	// `idx` stores the current position in the related collection.
	for idx := uint64(0); idx < meta.TotalChunks; idx++ {
		// `chunkPath` stores the value produced by this operation.
		chunkPath := filepath.Join(chunksDir, fmt.Sprintf("%08d.chunk", idx))
		// `raw` and `err` store the error produced by this operation.
		raw, err := os.ReadFile(chunkPath)
		if err != nil {
			return nil, err
		}
		legacyLayout := &SnapshotManifest{ChunkSize: meta.ChunkSize, ChunkCount: meta.TotalChunks}
		if !snapshotManifestChunkDataValid(legacyLayout, idx, raw) {
			return nil, fmt.Errorf("snapshot chunk size mismatch index=%d", idx)
		}
		merged.Write(raw)
	}
	// `payload` stores the value produced by this operation.
	payload := merged.Bytes()
	// `snap` stores the value used by this operation.
	var snap StateSnapshot
	// `err` stores the error produced by this operation.
	if err := json.Unmarshal(payload, &snap); err != nil {
		return nil, err
	}
	if len(snap.CheckpointProof) == 0 && len(meta.CheckpointProof) > 0 {
		snap.CheckpointProof = make(map[string]string, len(meta.CheckpointProof))
		// `id` and `sig` track the current position in the related collection.
		for id, sig := range meta.CheckpointProof {
			snap.CheckpointProof[id] = sig
		}
	}
	if manifest != nil {
		n.mergeSnapshotProofsFromManifest(&snap, manifest)
	}
	populateSnapshotDerivedFields(&snap)
	if !strings.EqualFold(strings.TrimSpace(snap.SnapshotHash), strings.TrimSpace(meta.SnapshotHash)) {
		return nil, fmt.Errorf("snapshot metadata hash mismatch")
	}
	state.VerifyStage = "verified"
	state.ResumeState = "legacy_verified"
	saveSnapshotChunkResumeState(manifestPath, state)
	n.setSnapshotDownloadStatus(&SnapshotManifest{
		Height:                meta.Height,
		SnapshotHash:          meta.SnapshotHash,
		StateRoot:             strings.TrimSpace(snap.StateRoot),
		StateMerkleRoot:       strings.TrimSpace(snap.StateMerkleRoot),
		ValidatorSetHash:      strings.TrimSpace(snapshotValidatorSetHash(&snap)),
		ValidatorRegistryHash: strings.TrimSpace(snapshotValidatorRegistryHash(&snap)),
		PromotionWindowHash:   strings.TrimSpace(snapshotPromotionWindowHash(&snap)),
		ChunkSize:             meta.ChunkSize,
		ChunkCount:            meta.TotalChunks,
	}, meta.TotalChunks, state.Providers, "legacy_verified", "legacy_verified")
	return &snap, nil
}

// trustedSnapshotProofRequirement keeps strict recovery tied to authority quorum.
func trustedSnapshotProofRequirement(required int, reachableValidators int, strictCoreQuorum bool) int {
	if required <= 0 {
		required = 1
	}
	if strictCoreQuorum || reachableValidators <= 0 || required <= reachableValidators {
		return required
	}
	adjusted := execQuorumRequired(reachableValidators)
	if adjusted <= 0 {
		return 1
	}
	return adjusted
}

// fetchTrustedSnapshot implements the fetch trusted snapshot helper.
func (n *Node) fetchTrustedSnapshot(height uint64, minHeight uint64, strictCoreQuorum bool) (*StateSnapshot, *ExecPoolSnapshot, error) {
	if n.Host == nil {
		return nil, nil, fmt.Errorf("host not initialized")
	}
	// Remote snapshot trust is always quorum-backed on metadata identity:
	// height + snapshot_hash + state_root + state_merkle_root + validator_set_hash + registry_hash.
	requireMetadataQuorum := true
	// `requestedHeight` stores the request data being processed.
	requestedHeight := height
	// `peers` stores the value produced by this operation.
	peers := n.Host.Network().Peers()
	if len(peers) == 0 {
		return nil, nil, fmt.Errorf("no peers available")
	}
	// `authorityIDs` stores the value produced by this operation.
	authorityIDs := n.validatorAuthorityIDsForQuorum(height)
	if len(authorityIDs) == 0 {
		authorityIDs = n.snapshotBootstrapAuthorityIDsForQuorum(height)
		if DebugConsensus && len(authorityIDs) > 0 {
			fmt.Printf("[SNAPSHOT-BOOTSTRAP-AUTHORITY] target=%d validators=%v source=local_fallback\n", height, authorityIDs)
		}
	}
	if strictCoreQuorum && len(authorityIDs) == 0 {
		return nil, nil, fmt.Errorf("validator_quorum: authority set unavailable target=%d", height)
	}
	// `required` stores the request data being processed.
	required := execQuorumRequired(len(n.GetConsensusValidators(int(height))))
	if len(authorityIDs) > 0 {
		required = execQuorumRequired(len(authorityIDs))
	}
	if required <= 0 {
		required = 1
	}
	// `checkpointHeight` stores the value produced by this operation.
	checkpointHeight := snapshotCheckpointHeightFor(height)
	// `session` stores the value produced by this operation.
	session := n.snapshotSessionSnapshot()
	if session.Active && !session.StartedAt.IsZero() && time.Since(session.StartedAt) > syncSnapshotSessionTTL() {
		// `provider` stores the value produced by this operation.
		if provider := strings.TrimSpace(session.CurrentProvider); provider != "" {
			n.recordSyncPeerSnapshotResult(provider, false, 0, 0, true)
			n.setSyncAvoidProviderOnce(provider)
		}
		n.closeSnapshotSession(false, "snapshot_session_ttl_exceeded")
		return nil, nil, fmt.Errorf("snapshot session ttl exceeded")
	}
	if requireMetadataQuorum && session.Active {
		if session.CheckpointHeight > 0 {
			checkpointHeight = session.CheckpointHeight
		}
		if !session.Deadline.IsZero() && time.Now().After(session.Deadline) {
			if strings.TrimSpace(session.CurrentProvider) != "" {
				n.recordSyncPeerSnapshotResult(session.CurrentProvider, false, 0, 0, true)
			}
			n.snapshotSessionMarkFailure("snapshot_anchor_timeout")
			// `nextProvider` stores the value produced by this operation.
			nextProvider := n.rotateSnapshotProvider()
			fmt.Printf("[SYNC-PROOF-TIMEOUT] checkpoint=%d target=%d provider=%s next=%s action=provider_rotate\n",
				checkpointHeight,
				height,
				strings.TrimSpace(session.CurrentProvider),
				strings.TrimSpace(nextProvider))
			session = n.snapshotSessionSnapshot()
			if !session.Active {
				return nil, nil, fmt.Errorf("snapshot_session_timeout_retries_exhausted")
			}
			checkpointHeight = session.CheckpointHeight
		}
	}
	if requireMetadataQuorum && len(authorityIDs) > 0 {
		required = execQuorumRequired(len(authorityIDs))
		if required <= 0 {
			required = 1
		}
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := uint64(0)
	if n.Blockchain != nil {
		localHeight = n.Blockchain.Height()
	}
	// `sameHeightStartupRefresh` stores the value produced by this operation.
	sameHeightStartupRefresh := requestedHeight > 0 && localHeight == requestedHeight && minHeight == 1

	// `bestSnap` stores the value used by this operation.
	var bestSnap *StateSnapshot
	// `bestExecPool` stores the value used by this operation.
	var bestExecPool *ExecPoolSnapshot
	// `bestHeight` stores the value produced by this operation.
	bestHeight := uint64(0)
	// `bestVotes` stores the value produced by this operation.
	bestVotes := 0
	// `quorumReached` stores the value produced by this operation.
	quorumReached := false
	// `strictVerificationFailed` stores the value produced by this operation.
	strictVerificationFailed := false
	// `selfID` stores the local consensus identity selected from the authority set.
	selfID := n.localConsensusValidatorIDForSet(authorityIDs)

	type trustedPeer struct {
		// `pid` stores the value associated with this record.
		pid peer.ID
		// `vid` stores the value associated with this record.
		vid string
	}
	// `trustedPeers` stores the value produced by this operation.
	trustedPeers := make([]trustedPeer, 0, len(peers))
	// `uniqueValidators` stores the value produced by this operation.
	uniqueValidators := make(map[string]struct{}, len(peers))
	// `authoritySet` stores the value produced by this operation.
	authoritySet := make(map[string]struct{}, len(authorityIDs))
	// `id` tracks the current position in the related collection.
	for _, id := range authorityIDs {
		// `norm` stores the value produced by this operation.
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		authoritySet[norm] = struct{}{}
	}
	// `enforceAuthoritySet` stores the value produced by this operation.
	enforceAuthoritySet := len(authoritySet) > 0

	if requireMetadataQuorum && enforceAuthoritySet {
		if selfID != "" {
			// `ok` stores whether the related condition is satisfied.
			if _, ok := authoritySet[selfID]; ok {
				// `localSnap` and `err` store the error produced by this operation.
				if localSnap, err := n.GetSnapshot(height); err == nil && localSnap != nil && localSnap.Height == height {
					if minHeight == 0 || localSnap.Height >= minHeight {
						populateSnapshotDerivedFields(localSnap)
						// `key` stores the key used to access the related value.
						if key := snapshotTrustKey(localSnap); key != "" &&
							snapshotMatchesCheckpointHeight(localSnap, checkpointHeight) &&
							n.verifySnapshotAgainstLocalBlock(localSnap) &&
							n.verifySnapshotCheckpointProofForValidator(localSnap, selfID) {
							// `vote` stores the value produced by this operation.
							vote := snapshotVoteFromSnapshot(selfID, localSnap)
							// `votes` and `accepted` store the value produced by this operation.
							votes, accepted, _ := n.updateSnapshotSessionVote(vote)
							if accepted {
								if votes > bestVotes {
									bestVotes = votes
								}
								if DebugConsensus {
									fmt.Printf("[SNAPSHOT-QUORUM] checkpoint=%d hash=%s votes=%d/%d source=local\n",
										checkpointHeight, ShortHash(vote.SnapshotHash), votes, required)
								}
								if votes >= required {
									quorumReached = true
									bestSnap = localSnap
									bestHeight = localSnap.Height
								}
							}
						}
					}
				}
			}
		}
	}

	// `trustConsidered` stores the value produced by this operation.
	trustConsidered := 0
	// `trustSkippedQuarantined` stores the value produced by this operation.
	trustSkippedQuarantined := 0
	// `trustSkippedMissingValidator` stores the value produced by this operation.
	trustSkippedMissingValidator := 0
	// `trustSkippedNotAllowed` stores whether the related condition is satisfied.
	trustSkippedNotAllowed := 0
	// `pid` tracks the current values while iterating.
	for _, pid := range peers {
		trustConsidered++
		if n.isPeerQuarantined(pid.String()) {
			trustSkippedQuarantined++
			continue
		}
		n.peerStateMu.Lock()
		// `vid` stores the value produced by this operation.
		vid := n.peerToValidator[pid.String()]
		n.peerStateMu.Unlock()
		vid = strings.TrimSpace(vid)
		if vid == "" {
			trustSkippedMissingValidator++
			continue
		}

		// `allowed` stores whether the related condition is satisfied.
		allowed := false
		if requireMetadataQuorum && enforceAuthoritySet {
			_, allowed = authoritySet[normalizeValidatorID(vid)]
		} else {
			allowed = n.isValidatorInSetForHeight(vid, height)
			if !allowed && height > 1 {
				// Allow previous-height membership for boundary transitions.
				allowed = n.isValidatorInSetForHeight(vid, height-1)
			}
		}
		if !allowed {
			trustSkippedNotAllowed++
			continue
		}
		trustedPeers = append(trustedPeers, trustedPeer{pid: pid, vid: vid})
		uniqueValidators[strings.ToUpper(vid)] = struct{}{}
	}
	if requireMetadataQuorum {
		// `proofObservations` and `proofVotes` store the value produced by this operation.
		proofObservations, proofVotes := n.cachedSnapshotProofObservations(requestedHeight, minHeight, nil, required)
		// `vote` tracks the current values while iterating.
		for _, vote := range proofVotes {
			// `votes` and `accepted` store the value produced by this operation.
			votes, accepted, _ := n.updateSnapshotSessionVote(vote)
			if accepted && votes > bestVotes {
				bestVotes = votes
			}
		}
		// `proofQuorum` stores the value produced by this operation.
		proofQuorum, _ := selectStrictSnapshotMetaCandidate(proofObservations, required)
		if proofQuorum != nil {
			// `selectedKey` stores the key used to access the related value.
			selectedKey := strictSnapshotMetaCandidateKey(proofQuorum)
			// `connectedPeers` stores the value produced by this operation.
			connectedPeers := make(map[string]peer.ID, len(peers))
			// `pid` tracks the current values while iterating.
			for _, pid := range peers {
				connectedPeers[pid.String()] = pid
			}
			// `seenProviders` stores the value produced by this operation.
			seenProviders := make(map[string]struct{}, len(trustedPeers))
			// `tp` tracks the current values while iterating.
			for _, tp := range trustedPeers {
				seenProviders[tp.pid.String()] = struct{}{}
			}
			// `added` stores the value produced by this operation.
			added := 0
			// `observation` tracks the current values while iterating.
			for _, observation := range proofObservations {
				if observation.Candidate == nil || strictSnapshotMetaCandidateKey(observation.Candidate) != selectedKey {
					continue
				}
				// `providerID` stores the value produced by this operation.
				providerID := strings.TrimSpace(observation.Provider)
				// `validatorID` stores whether the related condition is satisfied.
				validatorID := normalizeValidatorID(observation.ValidatorID)
				if providerID == "" || validatorID == "" {
					continue
				}
				if enforceAuthoritySet {
					// `ok` stores whether the related condition is satisfied.
					if _, ok := authoritySet[validatorID]; !ok {
						continue
					}
				}
				if n.isPeerQuarantined(providerID) {
					continue
				}
				// `pid` and `ok` store whether the related condition is satisfied.
				pid, ok := connectedPeers[providerID]
				if !ok {
					// `decoded` and `err` store the error produced by this operation.
					decoded, err := peer.Decode(providerID)
					if err != nil {
						continue
					}
					// `connected` and `connectedOK` store whether the related condition is satisfied.
					if connected, connectedOK := connectedPeers[decoded.String()]; connectedOK {
						pid = connected
					} else {
						continue
					}
				}
				// `duplicate` stores the value produced by this operation.
				if _, duplicate := seenProviders[pid.String()]; duplicate {
					continue
				}
				trustedPeers = append(trustedPeers, trustedPeer{pid: pid, vid: validatorID})
				seenProviders[pid.String()] = struct{}{}
				uniqueValidators[strings.ToUpper(validatorID)] = struct{}{}
				added++
			}
			if DebugConsensus && added > 0 {
				fmt.Printf("[SNAPSHOT-QUORUM] checkpoint=%d target=%d action=trusted_proof_providers added=%d votes=%d/%d\n",
					proofQuorum.CheckpointHeight,
					requestedHeight,
					added,
					len(proofQuorum.Validators),
					required)
			}
		}
	}
	sort.SliceStable(trustedPeers, func(i, j int) bool {
		// `ri` stores the current position in the related collection.
		ri := n.syncPeerReputationValue(trustedPeers[i].pid.String())
		// `rj` stores the current position in the related collection.
		rj := n.syncPeerReputationValue(trustedPeers[j].pid.String())
		if ri != rj {
			return ri > rj
		}
		// `si` stores the current position in the related collection.
		si := n.syncPeerScoreValue(trustedPeers[i].pid.String())
		// `sj` stores the current position in the related collection.
		sj := n.syncPeerScoreValue(trustedPeers[j].pid.String())
		if si == sj {
			return trustedPeers[i].pid.String() < trustedPeers[j].pid.String()
		}
		return si > sj
	})
	// `providers` stores the value produced by this operation.
	providers := make([]string, 0, len(trustedPeers))
	// `tp` tracks the current values while iterating.
	for _, tp := range trustedPeers {
		providers = append(providers, tp.pid.String())
	}
	n.updateSnapshotSessionProviders(providers)
	if len(trustedPeers) == 0 {
		if requireMetadataQuorum {
			fmt.Printf("[SNAPSHOT-TRUSTED-PEERS] unavailable target=%d checkpoint=%d peers=%d authority=%v considered=%d missing_validator=%d quarantined=%d not_allowed=%d enforce_authority=%t\n",
				height,
				checkpointHeight,
				len(peers),
				authorityIDs,
				trustConsidered,
				trustSkippedMissingValidator,
				trustSkippedQuarantined,
				trustSkippedNotAllowed,
				enforceAuthoritySet,
			)
		}
		if requireMetadataQuorum && bestVotes > 0 {
			if DebugConsensus {
				fmt.Printf("[SNAPSHOT-QUORUM] waiting checkpoint=%d votes=%d/%d reason=no_trusted_peers\n",
					checkpointHeight, bestVotes, required)
			}
			return nil, nil, fmt.Errorf("validator_quorum: insufficient votes %d/%d", bestVotes, required)
		}
		return nil, nil, fmt.Errorf("trusted snapshot peers unavailable")
	}
	// Non-strict sync may adapt to the reachable validator set. Auto-heal strict
	// recovery keeps the authority-set quorum and fails closed during isolation.
	required = trustedSnapshotProofRequirement(required, len(uniqueValidators), strictCoreQuorum)
	if required == 0 {
		required = 1
	}

	if requireMetadataQuorum {
		// `validatorProviders` stores whether the related condition is satisfied.
		validatorProviders := make(map[string]string, len(trustedPeers))
		// `tp` tracks the current values while iterating.
		for _, tp := range trustedPeers {
			// `validatorID` stores whether the related condition is satisfied.
			validatorID := normalizeValidatorID(tp.vid)
			if validatorID == "" {
				continue
			}
			validatorProviders[validatorID] = tp.pid.String()
		}
		// `proofObservations` and `proofVotes` store the value produced by this operation.
		proofObservations, proofVotes := n.cachedSnapshotProofObservations(requestedHeight, minHeight, validatorProviders, required)
		// `vote` tracks the current values while iterating.
		for _, vote := range proofVotes {
			// `votes` and `accepted` store the value produced by this operation.
			votes, accepted, _ := n.updateSnapshotSessionVote(vote)
			if accepted && votes > bestVotes {
				bestVotes = votes
			}
		}
		// `proofQuorum` and `proofBest` store the value produced by this operation.
		proofQuorum, proofBest := selectStrictSnapshotMetaCandidate(proofObservations, required)

		// `latestAvailabilityByValidator` stores the value produced by this operation.
		latestAvailabilityByValidator := make(map[string]strictSnapshotMetaAvailability, len(trustedPeers))
		// `availability` tracks the current values while iterating.
		for _, availability := range n.cachedSnapshotMetaAvailabilities(requestedHeight, minHeight, validatorProviders) {
			// `validatorID` stores whether the related condition is satisfied.
			validatorID := normalizeValidatorID(availability.ValidatorID)
			if validatorID == "" || availability.Candidate == nil {
				continue
			}
			latestAvailabilityByValidator[validatorID] = availability
		}
		// `tp` tracks the current values while iterating.
		for _, tp := range trustedPeers {
			// `validatorID` stores whether the related condition is satisfied.
			validatorID := normalizeValidatorID(tp.vid)
			// `existing` and `hasExisting` store the value produced by this operation.
			existing, hasExisting := latestAvailabilityByValidator[validatorID]
			// `meta` and `err` store the error produced by this operation.
			meta, err := n.requestSnapshotMetaFromPeer(tp.pid, 0)
			if err != nil || meta == nil || !meta.Available {
				if !hasExisting {
					n.recordSnapshotSessionStrictResult(tp.pid.String(), "meta_unavailable")
				}
				continue
			}
			// `observation` and `reason` store the value produced by this operation.
			observation, reason := n.strictSnapshotMetaObservationForTarget(meta, tp.pid.String(), tp.vid, 0, minHeight, false)
			if observation == nil && sameHeightStartupRefresh && reason == "checkpoint_proof_invalid" {
				observation, reason = n.relaxedSameHeightSnapshotMetaObservationForTarget(meta, tp.pid.String(), tp.vid, requestedHeight, minHeight)
			}
			if observation == nil {
				if !hasExisting {
					n.recordSnapshotSessionStrictResult(tp.pid.String(), reason)
				}
				continue
			}
			// `fresh` stores the value produced by this operation.
			fresh := strictSnapshotMetaAvailability{
				Provider:    tp.pid.String(),
				ValidatorID: tp.vid,
				Meta:        meta,
				Candidate:   observation.Candidate,
			}
			if !hasExisting || betterStrictSnapshotCandidate(fresh.Candidate, existing.Candidate) {
				latestAvailabilityByValidator[validatorID] = fresh
			}
		}

		// `latestAvailabilities` stores the value produced by this operation.
		latestAvailabilities := make([]strictSnapshotMetaAvailability, 0, len(latestAvailabilityByValidator))
		// `availability` tracks the current values while iterating.
		for _, availability := range latestAvailabilityByValidator {
			latestAvailabilities = append(latestAvailabilities, availability)
		}

		// `candidateHeights` stores the value produced by this operation.
		candidateHeights := strictSnapshotCandidateHeights(latestAvailabilities)
		if requestedHeight > 0 {
			// `dedupHeights` stores the value produced by this operation.
			dedupHeights := make([]uint64, 0, len(candidateHeights)+1)
			// `seenHeights` stores the value produced by this operation.
			seenHeights := make(map[uint64]struct{}, len(candidateHeights)+1)
			dedupHeights = append(dedupHeights, requestedHeight)
			seenHeights[requestedHeight] = struct{}{}
			// `candidateHeight` tracks the current values while iterating.
			for _, candidateHeight := range candidateHeights {
				// `seen` stores the value produced by this operation.
				if _, seen := seenHeights[candidateHeight]; seen {
					continue
				}
				if candidateHeight > requestedHeight {
					continue
				}
				seenHeights[candidateHeight] = struct{}{}
				dedupHeights = append(dedupHeights, candidateHeight)
			}
			candidateHeights = dedupHeights
		}
		var (
			// `quorumCandidate` stores the value used by this operation.
			quorumCandidate *strictSnapshotMetaCandidate
			// `bestCandidate` stores the value used by this operation.
			bestCandidate *strictSnapshotMetaCandidate
			// `selectedExact` stores the value used by this operation.
			selectedExact []strictSnapshotMetaObservation
		)
		if proofBest != nil && betterStrictSnapshotCandidate(proofBest, bestCandidate) {
			bestCandidate = proofBest
		}
		// `candidateHeight` tracks the current values while iterating.
		for _, candidateHeight := range candidateHeights {
			// `exactObservations` stores the value produced by this operation.
			exactObservations := make([]strictSnapshotMetaObservation, 0, len(latestAvailabilities))
			// `availability` tracks the current values while iterating.
			for _, availability := range latestAvailabilities {
				if availability.Candidate == nil || availability.Candidate.Height < candidateHeight {
					continue
				}
				// `meta` stores the value produced by this operation.
				meta := availability.Meta
				if availability.Candidate.Height != candidateHeight {
					// `err` stores the error produced by this operation.
					var err error
					meta, err = n.requestSnapshotMetaFromPeer(peer.ID(availability.Provider), candidateHeight)
					if err != nil || meta == nil || !meta.Available {
						n.recordSnapshotSessionStrictResult(availability.Provider, "meta_unavailable")
						continue
					}
				}
				// `observation` and `reason` store the value produced by this operation.
				observation, reason := n.strictSnapshotMetaObservationForTarget(meta, availability.Provider, availability.ValidatorID, candidateHeight, minHeight, true)
				if observation == nil && sameHeightStartupRefresh && reason == "checkpoint_proof_invalid" {
					observation, reason = n.relaxedSameHeightSnapshotMetaObservationForTarget(meta, availability.Provider, availability.ValidatorID, candidateHeight, minHeight)
				}
				if observation == nil {
					n.recordSnapshotSessionStrictResult(availability.Provider, reason)
					continue
				}
				exactObservations = append(exactObservations, *observation)
			}
			// `exactQuorum` and `exactBest` store the value produced by this operation.
			exactQuorum, exactBest := selectStrictSnapshotMetaCandidate(exactObservations, required)
			if exactBest != nil && betterStrictSnapshotCandidate(exactBest, bestCandidate) {
				bestCandidate = exactBest
			}
			if exactQuorum != nil {
				quorumCandidate = exactQuorum
				selectedExact = exactObservations
				break
			}
		}
		if quorumCandidate == nil && proofQuorum != nil {
			quorumCandidate = proofQuorum
			selectedExact = append([]strictSnapshotMetaObservation{}, proofObservations...)
		}

		if bestCandidate != nil {
			n.setSnapshotSessionCandidate(bestCandidate.Height, bestCandidate.CheckpointHeight)
		} else {
			n.setSnapshotSessionCandidate(0, 0)
		}
		if quorumCandidate == nil {
			if bestCandidate != nil && (session.FreezeHeight != bestCandidate.Height || session.CheckpointHeight != bestCandidate.CheckpointHeight) {
				if !n.retargetSnapshotSessionLowerAvailable(requestedHeight, bestCandidate.Height, bestCandidate.CheckpointHeight, "snapshot_anchor_lower_available_pending") {
					n.retargetSnapshotSessionCandidate(bestCandidate.Height, bestCandidate.CheckpointHeight, "snapshot_anchor_candidate_pending")
				}
				session = n.snapshotSessionSnapshot()
				checkpointHeight = bestCandidate.CheckpointHeight
			}
			n.recordSnapshotSessionStrictResult("", "snapshot_anchor_unreachable")
			n.snapshotSessionMarkFailure("snapshot_anchor_unreachable")
			session = n.snapshotSessionSnapshot()
			// `bestCandidateHeight` stores the value produced by this operation.
			bestCandidateHeight := uint64(0)
			// `bestCandidateCheckpoint` stores the value produced by this operation.
			bestCandidateCheckpoint := checkpointHeight
			if bestCandidate != nil {
				bestCandidateHeight = bestCandidate.Height
				bestCandidateCheckpoint = bestCandidate.CheckpointHeight
			}
			if DebugConsensus {
				// `proofCache` stores the value produced by this operation.
				proofCache := proofBest != nil
				fmt.Printf("[SNAPSHOT-QUORUM] waiting checkpoint=%d votes=%d/%d reason=snapshot_anchor_unreachable frozen=%d candidate=%d target=%d retries=%d proof_cache=%t strict=%v\n",
					bestCandidateCheckpoint,
					bestVotes,
					required,
					session.FreezeHeight,
					bestCandidateHeight,
					requestedHeight,
					session.RetryCount,
					proofCache,
					session.StrictReasonCounts,
				)
			}
			return nil, nil, fmt.Errorf("validator_quorum: no quorum-reachable snapshot candidate")
		}

		// `selectedCandidateKey` stores the key used to access the related value.
		selectedCandidateKey := strictSnapshotMetaCandidateKey(quorumCandidate)
		// `obs` tracks the current values while iterating.
		for _, obs := range selectedExact {
			if obs.Candidate == nil {
				continue
			}
			if strictSnapshotMetaCandidateKey(obs.Candidate) != selectedCandidateKey {
				n.recordSnapshotSessionStrictResult(obs.Provider, "meta_conflict")
			}
		}

		if session.FreezeHeight != quorumCandidate.Height || session.CheckpointHeight != quorumCandidate.CheckpointHeight {
			if DebugConsensus {
				fmt.Printf("[SNAPSHOT-QUORUM] retarget frozen=%d checkpoint=%d candidate=%d candidate_checkpoint=%d\n",
					session.FreezeHeight, session.CheckpointHeight, quorumCandidate.Height, quorumCandidate.CheckpointHeight)
			}
			if !n.retargetSnapshotSessionLowerAvailable(requestedHeight, quorumCandidate.Height, quorumCandidate.CheckpointHeight, "snapshot_anchor_lower_available_retargeted") {
				n.retargetSnapshotSessionCandidate(quorumCandidate.Height, quorumCandidate.CheckpointHeight, "snapshot_anchor_retargeted")
			}
			session = n.snapshotSessionSnapshot()
		} else {
			n.setSnapshotSessionCandidate(quorumCandidate.Height, quorumCandidate.CheckpointHeight)
		}

		height = quorumCandidate.Height
		checkpointHeight = quorumCandidate.CheckpointHeight
		// `selectedProviders` stores the value produced by this operation.
		selectedProviders := make(map[string]struct{}, len(quorumCandidate.Providers))
		// `provider` tracks the current values while iterating.
		for _, provider := range quorumCandidate.Providers {
			selectedProviders[provider] = struct{}{}
		}
		// `filteredTrustedPeers` stores the value produced by this operation.
		filteredTrustedPeers := make([]trustedPeer, 0, len(trustedPeers))
		// `tp` tracks the current values while iterating.
		for _, tp := range trustedPeers {
			// `ok` stores whether the related condition is satisfied.
			if _, ok := selectedProviders[tp.pid.String()]; ok {
				filteredTrustedPeers = append(filteredTrustedPeers, tp)
			}
		}
		trustedPeers = filteredTrustedPeers
		providers = providers[:0]
		// `tp` tracks the current values while iterating.
		for _, tp := range trustedPeers {
			providers = append(providers, tp.pid.String())
		}
		n.updateSnapshotSessionProviders(providers)

		if selfID != "" && height != requestedHeight {
			if !enforceAuthoritySet || func() bool {
				// `ok` stores whether the related condition is satisfied.
				_, ok := authoritySet[selfID]
				return ok
			}() {
				// `localSnap` and `err` store the error produced by this operation.
				if localSnap, err := n.GetSnapshot(height); err == nil && localSnap != nil && localSnap.Height == height {
					if minHeight == 0 || localSnap.Height >= minHeight {
						populateSnapshotDerivedFields(localSnap)
						if snapshotMatchesCheckpointHeight(localSnap, checkpointHeight) &&
							n.verifySnapshotAgainstLocalBlock(localSnap) &&
							n.verifySnapshotCheckpointProofForValidator(localSnap, selfID) {
							// `vote` stores the value produced by this operation.
							vote := snapshotVoteFromSnapshot(selfID, localSnap)
							// `votes` and `accepted` store the value produced by this operation.
							votes, accepted, _ := n.updateSnapshotSessionVote(vote)
							if accepted && votes > bestVotes {
								bestVotes = votes
							}
						}
					}
				}
			}
		}
	}

	// Non-strict sync may adapt to the reachable validator set. Auto-heal strict
	// recovery must never turn one reachable validator into a trusted quorum.
	required = trustedSnapshotProofRequirement(required, len(uniqueValidators), strictCoreQuorum)
	if required == 0 {
		required = 1
	}
	if requireMetadataQuorum {
		n.snapshotSessionMu.Lock()
		if n.snapshotSession.Active {
			n.snapshotSession.Required = required
			n.snapshotSession.RequiredVotes = required
			if n.snapshotSession.CheckpointHeight == 0 {
				n.snapshotSession.CheckpointHeight = checkpointHeight
			}
			n.snapshotSession.Stage = SnapshotSyncStageCollectProofs
		}
		n.snapshotSessionMu.Unlock()
	}

	// `tp` tracks the current values while iterating.
	for _, tp := range trustedPeers {
		// `pid` stores the value produced by this operation.
		pid := tp.pid
		// `vid` stores the value produced by this operation.
		vid := tp.vid
		n.setSyncProvider(pid.String())
		n.setSnapshotSessionProvider(pid.String())
		// `snap` stores the value used by this operation.
		var snap *StateSnapshot
		// `execPool` stores the value used by this operation.
		var execPool *ExecPoolSnapshot

		// `started` stores the value produced by this operation.
		started := time.Now()
		// `chunkSnap` and `chunkErr` store the error produced by this operation.
		chunkSnap, chunkErr := n.fetchSnapshotFromPeerChunks(pid, height, minHeight)
		if chunkErr == nil && chunkSnap != nil {
			snap = chunkSnap
		} else {
			// `fetchedSnap`, `fetchedExecPool`, and `err` store the error produced by this operation.
			_, fetchedSnap, fetchedExecPool, err := n.requestBlocksFromPeer(pid, height, height, true, height)
			if err != nil || fetchedSnap == nil {
				n.recordSyncPeerSnapshotResult(pid.String(), false, time.Since(started), 0, isSyncTimeoutError(err))
				continue
			}
			snap = fetchedSnap
			execPool = fetchedExecPool
		}
		n.recordSyncPeerSnapshotResult(pid.String(), true, time.Since(started), 0, false)
		if snap.Height == 0 || snap.Height > height {
			if requireMetadataQuorum {
				n.recordSnapshotSessionStrictResult(pid.String(), "meta_conflict")
			}
			continue
		}
		if minHeight > 0 && snap.Height < minHeight {
			if requireMetadataQuorum {
				n.recordSnapshotSessionStrictResult(pid.String(), "meta_below_min_height")
			}
			continue
		}
		populateSnapshotDerivedFields(snap)
		if requireMetadataQuorum && !snapshotMatchesCheckpointHeight(snap, checkpointHeight) {
			n.recordSnapshotSessionStrictResult(pid.String(), "meta_conflict")
			continue
		}
		if n.snapshotCheckpointProofRequired() && strings.TrimSpace(snap.SnapshotHash) == "" {
			if requireMetadataQuorum {
				n.recordSnapshotSessionStrictResult(pid.String(), "checkpoint_proof_invalid")
			}
			n.recordSyncPeerInvalidProof(pid.String())
			continue
		}
		if GenesisHash != "" {
			if snap.GenesisHash == "" || snap.GenesisHash != GenesisHash {
				if requireMetadataQuorum {
					n.recordSnapshotSessionStrictResult(pid.String(), "genesis_hash_mismatch")
				}
				if DebugConsensus {
					fmt.Printf("[SNAPSHOT-VERIFY] reject height=%d provider=%s reason=genesis_hash_mismatch\n",
						snap.Height, ShortID(vid))
				}
				n.recordSyncPeerInvalidProof(pid.String())
				continue
			}
		}
		// Snapshot verification pipeline:
		// 1) verify state_root + validator_set_root
		// 2) verify checkpoint signatures
		if ok, rejectReason := n.verifySnapshotStateAndValidatorRootsDetailed(pid, snap); !ok {
			if strings.TrimSpace(rejectReason) == "" {
				rejectReason = "state_or_validator_root_mismatch"
			}
			if requireMetadataQuorum {
				n.recordSnapshotSessionStrictResult(pid.String(), rejectReason)
			}
			if DebugConsensus {
				fmt.Printf("[SNAPSHOT-VERIFY] reject height=%d provider=%s reason=%s\n",
					snap.Height, ShortID(vid), rejectReason)
			}
			if shouldPenalizeSnapshotPeerForRejectReason(rejectReason) {
				n.recordSyncPeerInvalidProof(pid.String())
			}
			continue
		}
		if !n.verifySnapshotCheckpointProofForValidator(snap, vid) &&
			!(sameHeightStartupRefresh && n.sameHeightStartupSnapshotMatchesLocalAnchor(snap.Height, snap.StateRoot, snapshotValidatorSetHash(snap), snapshotValidatorRegistryHash(snap))) {
			if requireMetadataQuorum {
				n.recordSnapshotSessionStrictResult(pid.String(), "checkpoint_proof_invalid")
			}
			n.recordSyncPeerInvalidProof(pid.String())
			continue
		}
		// `key` stores the key used to access the related value.
		key := snapshotTrustKey(snap)
		if key == "" {
			continue
		}
		// `vote` stores the value produced by this operation.
		vote := snapshotVoteFromSnapshot(vid, snap)
		if requireMetadataQuorum && vote.Height != checkpointHeight {
			continue
		}
		var (
			// `votes` stores the value used by this operation.
			votes int
			// `cacheKey` stores the key used to access the related value.
			cacheKey string
			// `accepted` stores the value used by this operation.
			accepted bool
		)
		if requireMetadataQuorum {
			// `conflict` stores the value used by this operation.
			var conflict bool
			votes, accepted, conflict = n.updateSnapshotSessionVote(vote)
			if !accepted {
				if conflict {
					n.recordSnapshotSessionStrictResult(pid.String(), "meta_conflict")
					n.recordSyncPeerInvalidProof(pid.String())
				}
				continue
			}
		} else {
			votes, cacheKey = n.recordSnapshotVote(vid, snap)
		}
		if votes > bestVotes {
			bestVotes = votes
		}
		if requireMetadataQuorum && votes >= required {
			quorumReached = true
		}
		if requireMetadataQuorum && DebugConsensus {
			fmt.Printf("[SNAPSHOT-QUORUM] checkpoint=%d hash=%s votes=%d/%d provider=%s\n",
				checkpointHeight, ShortHash(vote.SnapshotHash), votes, required, ShortID(vid))
		}
		if requireMetadataQuorum && votes < required {
			continue
		}
		if requireMetadataQuorum && votes >= required {
			n.setSnapshotSessionStage(SnapshotSyncStageVerifyQuorum)
			// `verified` stores the value produced by this operation.
			verified := false
			// `rejectReason` stores the value produced by this operation.
			rejectReason := ""
			// `ok` and `reason` store whether the related condition is satisfied.
			if ok, reason := n.verifySnapshotAgainstBlockDetailed(pid, snap); ok {
				verified = true
			} else {
				rejectReason = reason
				// `ok` and `localReason` store whether the related condition is satisfied.
				if ok, localReason := n.verifySnapshotAgainstLocalBlockDetailed(snap); ok {
					verified = true
					rejectReason = ""
				} else if strings.TrimSpace(localReason) != "" {
					rejectReason = mergeSnapshotVerifyRejectReason(rejectReason, localReason)
				}
			}
			// `fallbackApplied` stores the value produced by this operation.
			fallbackApplied := false
			if !verified && n.snapshotSessionHasQuorumForSnapshot(snap, required) {
				// Mainnet-safe fallback: quorum-signed identical snapshot payload can progress
				// even if transient block-verify RPC path fails.
				rejectNorm := strings.ToLower(strings.TrimSpace(rejectReason))
				if !n.shouldTrackLateJoinAuthority() ||
					rejectNorm == "anchor_block_unavailable" ||
					rejectNorm == "anchor_fetch_failed" {
					verified = true
					fallbackApplied = true
				}
			}
			if verified {
				if snap.Height >= bestHeight {
					bestSnap = snap
					bestExecPool = execPool
				}
				if DebugConsensus {
					// `mode` stores the value produced by this operation.
					mode := "block_verify"
					if fallbackApplied {
						mode = "quorum_fallback"
					}
					fmt.Printf("[SNAPSHOT-QUORUM] verified checkpoint=%d height=%d votes=%d/%d mode=%s\n",
						checkpointHeight, snap.Height, votes, required, mode)
				}
				if bestSnap != nil {
					n.promoteLateJoinAuthorityFromSnapshot(bestSnap)
				}
				return bestSnap, bestExecPool, nil
			}
			strictVerificationFailed = true
			if strings.TrimSpace(rejectReason) == "" {
				rejectReason = "anchor_verify_failed"
			}
			n.recordSnapshotSessionStrictResult(pid.String(), rejectReason)
			if DebugConsensus {
				// `quorumVotes` stores the value produced by this operation.
				quorumVotes := n.snapshotSessionQuorumForSnapshot(snap, required)
				fmt.Printf("[SNAPSHOT-QUORUM] verify_failed checkpoint=%d height=%d votes=%d/%d provider=%s quorum_match=%d/%d reason=%s\n",
					checkpointHeight, snap.Height, votes, required, ShortID(vid), quorumVotes, required, rejectReason)
			}
			if shouldPenalizeSnapshotPeerForRejectReason(rejectReason) {
				n.recordSyncPeerInvalidProof(pid.String())
			}
			continue
		}
		if cacheKey != "" && votes >= required {
			// `cached` stores the value produced by this operation.
			cached := n.getSnapshotByKey(cacheKey)
			if cached == nil {
				cached = snap
			}
			if cached != nil {
				// `verified` stores the value produced by this operation.
				verified := n.verifySnapshotAgainstBlock(pid, cached)
				if requireMetadataQuorum && !verified {
					verified = n.verifySnapshotAgainstLocalBlock(cached)
				}
				if !requireMetadataQuorum && !verified {
					verified = n.verifySnapshotAgainstLocalBlock(cached)
				}
				if verified {
					if cached.Height >= bestHeight {
						bestSnap = cached
						bestExecPool = execPool
						bestHeight = cached.Height
					}
					if requireMetadataQuorum && bestSnap != nil {
						if DebugConsensus {
							fmt.Printf("[AUTOHEAL] validator_quorum applied height=%d\n", bestSnap.Height)
						}
						n.promoteLateJoinAuthorityFromSnapshot(bestSnap)
						return bestSnap, bestExecPool, nil
					}
				} else if requireMetadataQuorum {
					strictVerificationFailed = true
				}
			}
			if bestHeight == height && bestSnap != nil {
				if requireMetadataQuorum {
					n.promoteLateJoinAuthorityFromSnapshot(bestSnap)
				}
				return bestSnap, bestExecPool, nil
			}
		}
		if !requireMetadataQuorum && snap.Height >= bestHeight {
			bestSnap = snap
			bestExecPool = execPool
			bestHeight = snap.Height
		}
	}

	if requireMetadataQuorum {
		if bestSnap != nil && bestVotes >= required {
			n.promoteLateJoinAuthorityFromSnapshot(bestSnap)
			return bestSnap, bestExecPool, nil
		}
		if quorumReached && strictVerificationFailed {
			n.snapshotSessionMarkFailure("quorum_verification_failed")
			return nil, nil, fmt.Errorf("validator_quorum: quorum reached but verification failed")
		}
		if DebugConsensus {
			fmt.Printf("[SNAPSHOT-QUORUM] waiting checkpoint=%d votes=%d/%d\n", checkpointHeight, bestVotes, required)
		}
		return nil, nil, fmt.Errorf("validator_quorum: insufficient votes %d/%d", bestVotes, required)
	}

	if bestSnap != nil {
		// `key` stores the key used to access the related value.
		key := snapshotTrustKey(bestSnap)
		if key != "" {
			n.snapshotTrustMu.Lock()
			// `votes` stores the value produced by this operation.
			votes := 0
			if n.snapshotVotes != nil {
				votes = len(n.snapshotVotes[key])
			}
			n.snapshotTrustMu.Unlock()
			if votes >= required {
				n.promoteLateJoinAuthorityFromSnapshot(bestSnap)
				return bestSnap, bestExecPool, nil
			}
			// Testnet bootstrap fallback:
			// if only one live trusted validator is ahead (others still at genesis),
			// allow progress from a single verified snapshot instead of stalling.
			if protocolIsTestnet() && bestSnap.Height >= minHeight && votes >= 1 {
				if DebugConsensus {
					fmt.Printf("TESTNET snapshot fallback accepted | height=%d votes=%d required=%d\n",
						bestSnap.Height, votes, required)
				}
				n.promoteLateJoinAuthorityFromSnapshot(bestSnap)
				return bestSnap, bestExecPool, nil
			}
		}
	}
	return nil, nil, fmt.Errorf("trusted snapshot not found")
}

// verifySnapshotAgainstBlock verifies snapshot against block.
func (n *Node) verifySnapshotAgainstBlock(pid peer.ID, snapshot *StateSnapshot) bool {
	// `ok` stores whether the related condition is satisfied.
	ok, _ := n.verifySnapshotAgainstBlockDetailed(pid, snapshot)
	return ok
}

// verifySnapshotAgainstBlockDetailed verifies snapshot against block detailed.
func (n *Node) verifySnapshotAgainstBlockDetailed(pid peer.ID, snapshot *StateSnapshot) (bool, string) {
	// `reason` stores the value produced by this operation.
	if reason := snapshotMetadataRejectReason(snapshot); reason != "" {
		return false, reason
	}
	if GenesisHash != "" && (snapshot.GenesisHash == "" || snapshot.GenesisHash != GenesisHash) {
		return false, "genesis_hash_mismatch"
	}
	// `ledgerHash` stores the digest used to identify or verify the related data.
	ledgerHash := HashLedger(snapshot.Ledger)
	if snapshot == nil || snapshot.LedgerHash == "" || snapshot.LedgerHash != ledgerHash {
		return false, "ledger_hash_mismatch"
	}
	if snapshot.StateRoot == "" {
		return false, "state_root_mismatch"
	}

	// `blocks` and `err` store the error produced by this operation.
	blocks, _, _, err := n.requestBlocksFromPeer(pid, snapshot.Height, snapshot.Height, false, 0)
	if err != nil || len(blocks) == 0 {
		return false, "anchor_fetch_failed"
	}
	// `b` stores the value produced by this operation.
	b := blocks[0]
	if b.BlockHash != snapshot.BlockHash {
		return false, "block_hash_mismatch"
	}
	// `expectedSetHash` stores the digest used to identify or verify the related data.
	expectedSetHash := strings.TrimSpace(b.NextValidatorSetHash)
	if expectedSetHash == "" {
		expectedSetHash = strings.TrimSpace(b.ValidatorSetHash)
	}
	if expectedSetHash != "" && !strings.EqualFold(strings.TrimSpace(snapshotValidatorSetHash(snapshot)), expectedSetHash) {
		return false, "validator_set_hash_mismatch"
	}
	if strings.TrimSpace(b.StateRoot) == "" || strings.TrimSpace(snapshot.StateRoot) == "" {
		return false, "state_root_mismatch"
	}
	if !strings.EqualFold(strings.TrimSpace(b.StateRoot), strings.TrimSpace(snapshot.StateRoot)) {
		return false, "state_root_mismatch"
	}
	n.StoreBlock(b)
	return true, ""
}

// verifySnapshotStateAndValidatorRoots verifies snapshot state and validator roots.
func (n *Node) verifySnapshotStateAndValidatorRoots(pid peer.ID, snapshot *StateSnapshot) bool {
	// `ok` stores whether the related condition is satisfied.
	ok, _ := n.verifySnapshotStateAndValidatorRootsDetailed(pid, snapshot)
	return ok
}

// verifySnapshotStateAndValidatorRootsDetailed verifies snapshot state and validator roots detailed.
func (n *Node) verifySnapshotStateAndValidatorRootsDetailed(pid peer.ID, snapshot *StateSnapshot) (bool, string) {
	if snapshot == nil {
		return false, "snapshot_metadata_invalid"
	}
	// Pipeline step 1+2:
	// - validator_set_root must be consistent with snapshot validator set
	// - state_root must match committed anchor block state root
	if reason := snapshotMetadataRejectReason(snapshot); reason != "" {
		return false, reason
	}
	if GenesisHash != "" && (snapshot.GenesisHash == "" || snapshot.GenesisHash != GenesisHash) {
		return false, "genesis_hash_mismatch"
	}
	if strings.TrimSpace(snapshotValidatorRegistryHash(snapshot)) == "" {
		return false, "registry_hash_mismatch"
	}
	// `expectedRegistry` stores the value produced by this operation.
	if expectedRegistry, _ := n.expectedValidatorRegistryHashWithSource(snapshot.Height + 1); expectedRegistry != "" &&
		!strings.EqualFold(strings.TrimSpace(snapshotValidatorRegistryHash(snapshot)), strings.TrimSpace(expectedRegistry)) {
		return false, "registry_hash_mismatch"
	}
	// `ok` stores whether the related condition is satisfied.
	if ok, _ := n.verifySnapshotAgainstBlockDetailed(pid, snapshot); ok {
		return true, ""
	}
	// `ok` and `reason` store whether the related condition is satisfied.
	if ok, reason := n.verifySnapshotAgainstLocalBlockDetailed(snapshot); ok {
		return true, ""
	} else if strings.TrimSpace(reason) == "anchor_block_unavailable" && pid != "" {
		if n.materializeSnapshotAnchorBlock(pid, snapshot) {
			// `ok` and `retryReason` store whether the related condition is satisfied.
			if ok, retryReason := n.verifySnapshotAgainstLocalBlockDetailed(snapshot); ok {
				return true, ""
			} else if strings.TrimSpace(retryReason) != "" {
				return false, retryReason
			}
		}
	} else if strings.TrimSpace(reason) != "" {
		return false, reason
	}
	return false, "state_or_validator_root_mismatch"
}

// verifySnapshotAgainstLocalBlock verifies snapshot against local block.
func (n *Node) verifySnapshotAgainstLocalBlock(snapshot *StateSnapshot) bool {
	// `ok` stores whether the related condition is satisfied.
	ok, _ := n.verifySnapshotAgainstLocalBlockDetailed(snapshot)
	return ok
}

// materializeSnapshotAnchorBlock implements the materialize snapshot anchor block helper.
func (n *Node) materializeSnapshotAnchorBlock(pid peer.ID, snapshot *StateSnapshot) bool {
	if n == nil || snapshot == nil || pid == "" || snapshot.Height == 0 {
		return false
	}
	// `blocks` and `err` store the error produced by this operation.
	blocks, _, _, err := n.requestBlocksFromPeer(pid, snapshot.Height, snapshot.Height, false, 0)
	if err != nil || len(blocks) == 0 {
		return false
	}
	// `block` stores the synchronization state protecting shared data.
	block := blocks[0]
	if block.ID != snapshot.Height {
		return false
	}
	if strings.TrimSpace(snapshot.BlockHash) != "" &&
		!strings.EqualFold(strings.TrimSpace(block.BlockHash), strings.TrimSpace(snapshot.BlockHash)) {
		return false
	}
	n.StoreBlock(block)
	return true
}

// verifySnapshotAgainstLocalBlockDetailed verifies snapshot against local block detailed.
func (n *Node) verifySnapshotAgainstLocalBlockDetailed(snapshot *StateSnapshot) (bool, string) {
	// `reason` stores the value produced by this operation.
	if reason := snapshotMetadataRejectReason(snapshot); reason != "" {
		return false, reason
	}
	if GenesisHash != "" && (snapshot.GenesisHash == "" || snapshot.GenesisHash != GenesisHash) {
		return false, "genesis_hash_mismatch"
	}
	// `ledgerHash` stores the digest used to identify or verify the related data.
	ledgerHash := HashLedger(snapshot.Ledger)
	if snapshot == nil || snapshot.LedgerHash == "" || snapshot.LedgerHash != ledgerHash {
		return false, "ledger_hash_mismatch"
	}
	if snapshot.StateRoot == "" || snapshot.BlockHash == "" {
		return false, "state_root_mismatch"
	}
	// `candidates` stores the value produced by this operation.
	candidates := n.localSnapshotAnchorCandidates(snapshot.Height)
	if len(candidates) == 0 {
		return false, "anchor_block_unavailable"
	}
	// `matchedBlockHash` stores the digest used to identify or verify the related data.
	matchedBlockHash := false
	// `matchedValidatorSet` stores the value produced by this operation.
	matchedValidatorSet := false
	// `blk` tracks the current values while iterating.
	for _, blk := range candidates {
		if !strings.EqualFold(strings.TrimSpace(blk.BlockHash), strings.TrimSpace(snapshot.BlockHash)) {
			continue
		}
		matchedBlockHash = true
		// `expectedSetHash` stores the digest used to identify or verify the related data.
		expectedSetHash := strings.TrimSpace(blk.NextValidatorSetHash)
		if expectedSetHash == "" {
			expectedSetHash = strings.TrimSpace(blk.ValidatorSetHash)
		}
		if expectedSetHash != "" && !strings.EqualFold(strings.TrimSpace(snapshotValidatorSetHash(snapshot)), expectedSetHash) {
			continue
		}
		matchedValidatorSet = true
		if strings.TrimSpace(blk.StateRoot) == "" || strings.TrimSpace(snapshot.StateRoot) == "" {
			continue
		}
		// `computedRoot` stores the digest used to identify or verify the related data.
		computedRoot := ComputeExecHashVersioned(blk, ledgerHash, executionStateRootVersionForHeight(blk.ID))
		if !strings.EqualFold(strings.TrimSpace(computedRoot), strings.TrimSpace(snapshot.StateRoot)) {
			continue
		}
		if strings.EqualFold(strings.TrimSpace(blk.StateRoot), strings.TrimSpace(snapshot.StateRoot)) {
			return true, ""
		}
	}
	if !matchedBlockHash {
		return false, "block_hash_mismatch"
	}
	if !matchedValidatorSet {
		return false, "validator_set_hash_mismatch"
	}
	return false, "state_root_mismatch"
}

// preflightDeltaReplayBatch implements the preflight delta replay batch helper.
func preflightDeltaReplayBatch(start uint64, blocks []Block) error {
	if start == 0 || len(blocks) == 0 {
		return fmt.Errorf("delta_replay_batch_empty")
	}

	type result struct {
		// `index` stores the current position in the related collection.
		index int
		// `err` stores the error produced by this operation.
		err error
	}
	// `workers` stores the value produced by this operation.
	workers := deltaReplayVerifyWorkerCount(len(blocks))
	// `jobs` stores the current position in the related collection.
	jobs := make(chan int, len(blocks))
	// `results` stores the result produced by this operation.
	results := make(chan result, len(blocks))
	// `worker` stores the value produced by this operation.
	for worker := 0; worker < workers; worker++ {
		go func() {
			// `idx` tracks the current position in the related collection.
			for idx := range jobs {
				// `block` stores the synchronization state protecting shared data.
				block := blocks[idx]
				// `expectedHeight` stores the value produced by this operation.
				expectedHeight := start + uint64(idx)
				switch {
				case block.ID != expectedHeight:
					results <- result{index: idx, err: fmt.Errorf("height_mismatch index=%d got=%d want=%d", idx, block.ID, expectedHeight)}
				case strings.TrimSpace(block.BlockHash) == "":
					results <- result{index: idx, err: fmt.Errorf("missing_block_hash index=%d height=%d", idx, block.ID)}
				case strings.TrimSpace(block.PrevHash) == "":
					results <- result{index: idx, err: fmt.Errorf("missing_prev_hash index=%d height=%d", idx, block.ID)}
				default:
					results <- result{index: idx}
				}
			}
		}()
	}
	// `idx` tracks the current position in the related collection.
	for idx := range blocks {
		jobs <- idx
	}
	close(jobs)

	// `errs` stores the error produced by this operation.
	errs := make([]error, len(blocks))
	for range blocks {
		// `res` stores the result produced by this operation.
		res := <-results
		errs[res.index] = res.err
	}
	// `err` tracks the error produced by this operation.
	for _, err := range errs {
		if err != nil {
			return err
		}
	}
	// `idx` stores the current position in the related collection.
	for idx := 1; idx < len(blocks); idx++ {
		if blocks[idx].PrevHash != blocks[idx-1].BlockHash {
			return fmt.Errorf("prev_hash_mismatch index=%d height=%d", idx, blocks[idx].ID)
		}
	}
	return nil
}

// computeAdaptiveSyncFetchWindow computes adaptive sync fetch window.
func computeAdaptiveSyncFetchWindow(lag uint64) uint64 {
	switch {
	case lag > 10000:
		return 4096
	case lag > 5000:
		return 2048
	case lag > 1000:
		return 1024
	case lag > 200:
		return 512
	case lag > 100:
		return 256
	default:
		return 128
	}
}

// `syncRangeAssignmentMaxBlocks` defines the constant value used by this package.
const syncRangeAssignmentMaxBlocks = 100

// syncParallelFetchPeerLimit implements the sync parallel fetch peer limit helper.
func syncParallelFetchPeerLimit(lag uint64) int {
	switch {
	case lag > 10000:
		return 5
	case lag > 5000:
		return 4
	case lag > 1000:
		return 3
	case lag > 200:
		return 2
	case lag > 100:
		return 2
	default:
		return 1
	}
}

type syncSingleBlockResult struct {
	// `peer` stores the value associated with this record.
	peer peer.ID
	// `blocks` stores the block data handled by this operation.
	blocks []Block
	// `elapsed` stores the value associated with this record.
	elapsed time.Duration
	// `timeout` stores the result produced by this operation.
	timeout bool
	// `err` stores the error produced by this operation.
	err error
}

// requestSingleBlockFast implements the request single block fast helper.
func (n *Node) requestSingleBlockFast(height uint64, peers []peer.ID, preflightDelta bool) (Block, peer.ID, map[peer.ID]struct{}, error) {
	// `failedPeers` stores the value produced by this operation.
	failedPeers := make(map[peer.ID]struct{})
	if n == nil || n.Host == nil || height == 0 || len(peers) == 0 {
		return Block{}, "", failedPeers, fmt.Errorf("single_block_fetch_unavailable")
	}

	// `results` stores the result produced by this operation.
	results := make(chan syncSingleBlockResult, len(peers))
	// `pid` tracks the current values while iterating.
	for _, pid := range peers {
		// `pid` stores the value produced by this operation.
		pid := pid
		go func() {
			// `started` stores the value produced by this operation.
			started := time.Now()
			// `blocks` and `err` store the error produced by this operation.
			blocks, _, _, err := n.requestBlocksFromPeer(pid, height, height, false, 0)
			results <- syncSingleBlockResult{
				peer:    pid,
				blocks:  blocks,
				elapsed: time.Since(started),
				timeout: isSyncTimeoutError(err),
				err:     err,
			}
		}()
	}

	var (
		// `winner` stores the value used by this operation.
		winner Block
		// `winnerPeer` stores the value used by this operation.
		winnerPeer peer.ID
		// `found` stores whether the related condition is satisfied.
		found bool
	)
	// `i` stores the current position in the related collection.
	for i := 0; i < len(peers); i++ {
		// `result` stores the result produced by this operation.
		result := <-results
		if result.err != nil || len(result.blocks) == 0 {
			n.recordSyncPeerBlockResult(result.peer.String(), false, result.elapsed, 0, result.timeout)
			failedPeers[result.peer] = struct{}{}
			continue
		}
		if len(result.blocks) != 1 ||
			result.blocks[0].ID != height ||
			strings.TrimSpace(result.blocks[0].BlockHash) == "" ||
			strings.TrimSpace(result.blocks[0].PrevHash) == "" {
			n.recordSyncPeerBlockResult(result.peer.String(), false, result.elapsed, len(MustJSON(result.blocks)), false)
			failedPeers[result.peer] = struct{}{}
			continue
		}
		if preflightDelta {
			// `err` stores the error produced by this operation.
			if err := preflightDeltaReplayBatch(height, result.blocks); err != nil {
				n.recordSyncPeerBlockResult(result.peer.String(), false, result.elapsed, len(MustJSON(result.blocks)), false)
				failedPeers[result.peer] = struct{}{}
				continue
			}
		}
		n.recordSyncPeerBlockResult(result.peer.String(), true, result.elapsed, len(MustJSON(result.blocks)), false)
		if !found {
			winner = result.blocks[0]
			winnerPeer = result.peer
			found = true
		}
	}

	if !found {
		return Block{}, "", failedPeers, fmt.Errorf("single_block_fetch_failed")
	}
	return winner, winnerPeer, failedPeers, nil
}

// requestSingleBlockFirstValid returns as soon as any peer serves a valid block.
// It is used for gap recovery where waiting for every slow peer can keep a
// validator out of quorum even though one healthy peer has the missing block.
func (n *Node) requestSingleBlockFirstValid(height uint64, peers []peer.ID, preflightDelta bool, timeout time.Duration) (Block, peer.ID, map[peer.ID]struct{}, error) {
	return n.requestSingleBlockFirstValidContext(context.Background(), height, peers, preflightDelta, timeout)
}

func (n *Node) requestSingleBlockFirstValidContext(ctx context.Context, height uint64, peers []peer.ID, preflightDelta bool, timeout time.Duration) (Block, peer.ID, map[peer.ID]struct{}, error) {
	failedPeers := make(map[peer.ID]struct{})
	if n == nil || n.Host == nil || height == 0 || len(peers) == 0 {
		return Block{}, "", failedPeers, fmt.Errorf("single_block_fetch_unavailable")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	if timeout <= 0 {
		timeout = 6500 * time.Millisecond
	}
	requestCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	results := make(chan syncSingleBlockResult, len(peers))
	for _, pid := range peers {
		pid := pid
		go func() {
			started := time.Now()
			blocks, _, _, err := n.requestBlocksFromPeerWithContext(requestCtx, pid, height, height, false, 0)
			results <- syncSingleBlockResult{
				peer:    pid,
				blocks:  blocks,
				elapsed: time.Since(started),
				timeout: isSyncTimeoutError(err),
				err:     err,
			}
		}()
	}

	for received := 0; received < len(peers); received++ {
		select {
		case result := <-results:
			if result.err != nil || len(result.blocks) == 0 {
				n.recordSyncPeerBlockResult(result.peer.String(), false, result.elapsed, 0, result.timeout)
				failedPeers[result.peer] = struct{}{}
				continue
			}
			if len(result.blocks) != 1 ||
				result.blocks[0].ID != height ||
				strings.TrimSpace(result.blocks[0].BlockHash) == "" ||
				strings.TrimSpace(result.blocks[0].PrevHash) == "" {
				n.recordSyncPeerBlockResult(result.peer.String(), false, result.elapsed, len(MustJSON(result.blocks)), false)
				failedPeers[result.peer] = struct{}{}
				continue
			}
			if preflightDelta {
				if err := preflightDeltaReplayBatch(height, result.blocks); err != nil {
					n.recordSyncPeerBlockResult(result.peer.String(), false, result.elapsed, len(MustJSON(result.blocks)), false)
					failedPeers[result.peer] = struct{}{}
					continue
				}
			}
			n.recordSyncPeerBlockResult(result.peer.String(), true, result.elapsed, len(MustJSON(result.blocks)), false)
			return result.blocks[0], result.peer, failedPeers, nil
		case <-requestCtx.Done():
			cancel()
			grace := time.NewTimer(250 * time.Millisecond)
			for ; received < len(peers); received++ {
				select {
				case <-results:
				case <-grace.C:
					return Block{}, "", failedPeers, fmt.Errorf("single_block_fetch_timeout")
				}
			}
			if !grace.Stop() {
				select {
				case <-grace.C:
				default:
				}
			}
			return Block{}, "", failedPeers, fmt.Errorf("single_block_fetch_timeout")
		}
	}
	return Block{}, "", failedPeers, fmt.Errorf("single_block_fetch_failed")
}

