// HighFeePendingTxs implements the high fee pending txs helper.
func HighFeePendingTxs(

	block Block,

	mempoolTxs []Transaction,

) []Transaction {

	// `included` stores the current position in the related collection.
	included := make(map[string]bool)

	// `tx` tracks the transaction data handled by this operation.
	for _, tx := range block.Transactions {

		included[tx.ID] = true

	}

	if len(block.Transactions) == 0 {

		return nil

	}

	// `feeThreshold` stores the value produced by this operation.
	feeThreshold := block.Transactions[len(block.Transactions)-1].Fee

	// `out` stores the result produced by this operation.
	var out []Transaction

	// `tx` tracks the transaction data handled by this operation.
	for _, tx := range mempoolTxs {

		if included[tx.ID] {

			continue

		}

		if tx.Fee >= feeThreshold {

			out = append(out, tx)

		}

	}

	return out

}

