// RewardValidatorReputation implements the reward validator reputation helper.
func (n *Node) RewardValidatorReputation(addr string) {

	participationMu.Lock()

	defer participationMu.Unlock()

	// `p` and `ok` store whether the related condition is satisfied.
	p, ok := Participation[addr]

	if !ok {

		p = &ParticipationScore{

			LastSeen: time.Now(),

			Reputation: 100,
		}

		Participation[addr] = p

	}

	p.ValidBlocks++

	p.Reputation += 1

	p.LastSeen = time.Now()

}

// sameStringSlice implements the same string slice helper.
func sameStringSlice(a, b []string) bool {

	if len(a) != len(b) {

		return false

	}

	// `i` tracks the current position in the related collection.
	for i := range a {

		if a[i] != b[i] {

			return false

		}

	}

	return true

}

// validatorsFromSnapshot implements the validators from snapshot helper.
func validatorsFromSnapshot(snapshot *StateSnapshot) []string {

	if snapshot == nil || len(snapshot.Validators) == 0 {

		return nil

	}

	// `out` stores the result produced by this operation.
	out := make([]string, 0, len(snapshot.Validators))

	// `id` tracks the current position in the related collection.
	for id := range snapshot.Validators {

		out = append(out, id)

	}

	return canonicalValidatorIDs(out)

}

// GetValidatorRegistry returns validator registry.
func (n *Node) GetValidatorRegistry() []string {

	if protocolDynamicValidatorSelectionEnabledFlag() && n != nil {
		// `height` stores the value produced by this operation.
		height := uint64(1)
		if n.Blockchain != nil {
			height = n.Blockchain.Height() + 1
		}
		// `snap` stores the value produced by this operation.
		snap := n.validatorRegistrySnapshotForHeight(height)
		// `list` stores the value produced by this operation.
		list := canonicalValidatorIDsFromMapKeys(snap)
		if len(list) > 0 {
			return list
		}
	}

	validatorPubKeysMu.RLock()
	// `list` stores the value produced by this operation.
	list := canonicalValidatorIDsFromMapKeys(ValidatorPubKeys)
	validatorPubKeysMu.RUnlock()

	return list

}

