// consensusValidatorsForHeight implements the consensus validators for height helper.
func (n *Node) consensusValidatorsForHeight(height uint64) []string {
	if n == nil || height == 0 {
		return nil
	}
	// `chainHeight` stores the value produced by this operation.
	chainHeight := uint64(0)
	if n.Blockchain != nil {
		chainHeight = n.Blockchain.Height()
	}
	// `expectedHash` stores the digest used to identify or verify the related data.
	expectedHash := ""
	if height > 1 && validatorSetCommitmentV2EnabledAt(height-1) {
		// `committed` and `ok` store whether the related condition is satisfied.
		if committed, ok := n.chainParentCommittedValidatorSetHash(height); ok {
			expectedHash = strings.TrimSpace(committed)
		}
	}
	// `localHash` stores the digest used to identify or verify the related data.
	localHash := ""
	// `localHashSource` stores the value produced by this operation.
	localHashSource := "none"
	// `snapshotMissing` stores the value produced by this operation.
	snapshotMissing := false
	// `finalize` stores the value produced by this operation.
	finalize := func(values []string, knownHash string, hashSource string, registrySnapshot map[string]ValidatorRecord) []string {
		// `canonical` stores the value produced by this operation.
		canonical := canonicalValidatorIDs(values)
		if len(canonical) == 0 {
			return nil
		}
		localHash = strings.TrimSpace(knownHash)
		localHashSource = strings.TrimSpace(hashSource)
		if localHash == "" && len(registrySnapshot) > 0 {
			localHash = strings.TrimSpace(validatorSetHashFromSnapshotForHeight(height, canonical, registrySnapshot))
			if localHash != "" && localHashSource == "" {
				localHashSource = "snapshot"
			}
		}
		if localHash == "" {
			localHash = n.validatorSetHashFromFinalizedSnapshot(height, canonical)
			if localHash != "" && localHashSource == "" {
				localHashSource = "snapshot"
			}
		}
		if strings.TrimSpace(localHash) == "" {
			snapshotMissing = true
			localHash = ValidatorSetHash(canonical)
			if localHashSource == "" {
				localHashSource = "ids"
			}
		} else if localHashSource == "" {
			localHashSource = "snapshot"
		}
		if expectedHash != "" && !strings.EqualFold(localHash, expectedHash) {
			return nil
		}
		return n.applyCoreConsensusFilter(height, canonical)
	}

	if GenesisValidatorSetFrozen && (height <= 1 || chainHeight == 0) {
		// `genesis` stores the value produced by this operation.
		if genesis := canonicalValidatorIDs(n.GenesisValidators); len(genesis) > 0 {
			return finalize(genesis, "", "genesis_frozen", nil)
		}
	}

	if expectedHash != "" {
		// `frozen` and `ok` store whether the related condition is satisfied.
		if frozen, ok := n.committedFrozenValidatorSetCandidate(expectedHash, height, height-1); ok {
			return finalize(frozen, expectedHash, "chain_parent_commitment", nil)
		}
	}

	// Rule 1: lock validator-set by finalized height H-1.
	prevHeight := height - 1
	if prevHeight > 0 && n.DB != nil && n.DB.State != nil {
		// `snap` and `err` store the error produced by this operation.
		if snap, err := n.GetSnapshot(prevHeight); err == nil && snap != nil {
			// `out`, `resolvedHash`, `source`, and `ok` store whether the related condition is satisfied.
			if out, resolvedHash, source, ok := n.validatorSetCandidateFromSnapshot(height, expectedHash, snap); ok {
				return finalize(out, resolvedHash, source, validatorRegistrySnapshotFromStateSnapshot(snap))
			}
			// In deterministic mode never derive set from registry heuristics:
			// only finalized snapshot validator-set is authoritative.
			if !protocolDeterministicValidatorSelectionEnabled() && protocolDynamicValidatorSelectionEnabledFlag() && len(snap.ValidatorRegistry) > 0 {
				// `target` stores the value produced by this operation.
				target := n.activeSetTarget()
				// `out` stores the result produced by this operation.
				if out := SelectValidatorsFromRegistrySnapshot(height, target, snap.ValidatorRegistry); len(out) > 0 {
					return finalize(out, "", "snapshot_registry_heuristic", snap.ValidatorRegistry)
				}
			}
		}
	}

	// Chain-native fallback: a committed block carries the active validator set
	// in `Signatures` and binds it via `validator_set_hash`.
	if n.Blockchain != nil {
		// `resolved`, `resolvedHash`, `source`, and `ok` store whether the related condition is satisfied.
		if resolved, resolvedHash, source, ok := n.resolveCommittedValidatorSetForHeight(height); ok {
			return finalize(resolved, resolvedHash, source, nil)
		}
		// Runtime maps/local in-memory snapshots are never authoritative once
		// chain history exists; this prevents restart drift from poisoning
		// expected validator-set resolution.
		if chainHeight > 0 {
			// `validators`, `validatorHash`, `source`, and `ok` store whether the related condition is satisfied.
			if validators, validatorHash, source, ok := n.legacyFrozenValidatorAuthorityForHeight(height); ok {
				return finalize(validators, validatorHash, source, nil)
			}
			if height > chainHeight+1 && strings.TrimSpace(expectedHash) == "" {
				if DebugConsensus {
					if n.shouldLogLivenessReason(fmt.Sprintf("consensus_set_pending:%d", height), livenessReasonLogCooldown) {
						fmt.Printf("[SET-PENDING] height=%d chain_height=%d reason=future_height\n", height, chainHeight)
					}
				}
				return nil
			}
			// `historyPruned` stores the value produced by this operation.
			historyPruned := prevHeight > 0 && n.stateHistoryPrunedForHeight(prevHeight)
			if prevHeight > 0 && n.DB != nil && n.DB.State != nil && !historyPruned {
				n.maybeScheduleRegistryHistoryRebuild(prevHeight, "consensus_set_unresolved")
				// `latest` and `ok` store whether the related condition is satisfied.
				if latest, ok := n.loadLatestValidatorRegistrySnapshotHeight(); ok && latest >= prevHeight {
					// `snap` and `err` store the error produced by this operation.
					if snap, err := n.GetSnapshot(prevHeight); err == nil && snap != nil {
						// `out`, `resolvedHash`, `source`, and `ok` store whether the related condition is satisfied.
						if out, resolvedHash, source, ok := n.validatorSetCandidateFromSnapshot(height, expectedHash, snap); ok {
							return finalize(out, resolvedHash, source, validatorRegistrySnapshotFromStateSnapshot(snap))
						}
					}
				}
			}
			if DebugConsensus {
				if historyPruned {
					if n.shouldLogLivenessReason(fmt.Sprintf("consensus_set_pruned:%d", height/1024), livenessReasonLogCooldown) {
						fmt.Printf("[SET-PRUNED] height=%d chain_height=%d expected_hash=%s reason=state_history_compacted\n",
							height, chainHeight, ShortHash(expectedHash))
					}
				} else if n.shouldLogLivenessReason(fmt.Sprintf("consensus_set_nil:%d", height), livenessReasonLogCooldown) {
					fmt.Printf("[WARN] consensus validator set unresolved height=%d chain_height=%d expected_hash=%s local_hash=%s local_source=%s snapshot_missing=%t\n",
						height, chainHeight, ShortHash(expectedHash), ShortHash(localHash), localHashSource, snapshotMissing)
				}
			}
			return nil
		}
	}

	// Bootstrap-only allowance at genesis: derive from genesis file state only.
	// Local runtime memory is not authoritative.
	if chainHeight == 0 {
		// `boot` stores the value produced by this operation.
		if boot := n.currentValidatorSetSnapshot(); len(boot) > 0 {
			return finalize(boot, "", "genesis_bootstrap", nil)
		}
	}
	if len(n.GenesisValidators) > 0 {
		return finalize(append([]string{}, n.GenesisValidators...), "", "genesis", nil)
	}
	if DebugConsensus {
		if n.shouldLogLivenessReason(fmt.Sprintf("consensus_set_nil:%d", height), livenessReasonLogCooldown) {
			fmt.Printf("[WARN] consensus validator set unresolved height=%d chain_height=%d expected_hash=%s local_hash=%s local_source=%s snapshot_missing=%t\n",
				height, chainHeight, ShortHash(expectedHash), ShortHash(localHash), localHashSource, snapshotMissing)
		}
	}
	return nil
}

// snapshotEpochValidators freezes the validator set for a specific block height.

// This must be called after scheduled updates are applied, before the next block starts.

// snapshotEpochValidators implements the snapshot epoch validators helper.
func (n *Node) snapshotEpochValidators(height uint64) {

	if height == 0 {

		return
	}
	// `chainHeight` stores the value produced by this operation.
	chainHeight := uint64(0)
	if n.Blockchain != nil {
		chainHeight = n.Blockchain.Height()
	}

	// Consensus source must be chain/snapshot committed state.
	snapshot := n.consensusValidatorsForHeight(height)
	if len(snapshot) == 0 && protocolDynamicValidatorSelectionEnabledFlag() && !protocolDeterministicValidatorSelectionEnabled() {
		// Legacy non-deterministic mode compatibility only.
		snapshot = n.GetDynamicValidators(int(height))
	}

	if len(snapshot) == 0 && len(n.GenesisValidators) > 0 && chainHeight == 0 {

		snapshot = append([]string{}, n.GenesisValidators...)

	}

	sort.Strings(snapshot)

	n.validatorSetMu.Lock()

	defer n.validatorSetMu.Unlock()

	if n.epochValidators == nil {

		n.epochValidators = make(map[uint64][]string)

	}

	n.epochValidators[height] = snapshot
	n.validatorSetHeight = height

}

// isValidatorInSetForHeight implements the is validator in set for height helper.
func (n *Node) isValidatorInSetForHeight(id string, height uint64) bool {

	id = normalizeValidatorID(id)
	if id == "" {

		return false

	}

	// `validators` stores whether the related condition is satisfied.
	validators := n.GetConsensusValidators(int(height))

	// `v` tracks the current values while iterating.
	for _, v := range validators {
		v = normalizeValidatorID(v)
		if v == "" {
			continue
		}
		if v == id {

			return true

		}

	}

	return false

}

// isValidatorInSet implements the is validator in set helper.
func (n *Node) isValidatorInSet(id string) bool {

	return n.isValidatorInSetForHeight(id, n.currentEpoch())

}

// addPendingValidator implements the add pending validator helper.
func (n *Node) addPendingValidator(id string) {

	if id == "" {

		return

	}

	// Validator set is height-locked (no gossip-based changes).

	for _, v := range n.GenesisValidators {

		if v == id {

			return

		}

	}

}

// queuePendingValidator implements the queue pending validator helper.
func (n *Node) queuePendingValidator(id string, activationHeight uint64) {

	id = normalizeValidatorID(id)
	if id == "" || activationHeight == 0 {

		return

	}
	if GenesisValidatorSetFrozen && !validatorHasGenesisPubKey(id) {
		// `rec` and `ok` store whether the related condition is satisfied.
		rec, ok := GlobalValidatorRegistry.Get(id)
		if !ok || rec == nil || !validatorPassesStakeGate(id, rec.Stake) || normalizeConsensusPubKeyHex(rec.ConsensusPubKey) == "" {
			if DebugConsensus {
				fmt.Printf("[ONBOARDING-LOCKED] id=%s scheduled=%d reason=missing_stake_or_consensus_key_under_genesis_freeze\n", id, activationHeight)
			}
			return
		}
	}

	n.validatorSetMu.Lock()

	// `resolveKey` stores the key used to access the related value.
	resolveKey := func(m map[string]uint64, want string) string {
		// `key` tracks the key used to access the related value.
		for key := range m {
			if normalizeValidatorID(key) == want {
				return key
			}
		}
		return want
	}

	if n.pendingValidators == nil {

		n.pendingValidators = make(map[string]uint64)

	}

	if n.pendingValidatorRemovals == nil {

		n.pendingValidatorRemovals = make(map[string]uint64)

	}

	// `normalizeActivationMap` stores the value produced by this operation.
	normalizeActivationMap := func(m map[string]uint64) {
		// `key` and `act` track the key used to access the related value.
		for key, act := range m {
			// `norm` stores the value produced by this operation.
			norm := normalizeValidatorID(key)
			if norm == "" {
				delete(m, key)
				continue
			}
			if norm == key {
				continue
			}
			// `existing` and `ok` store whether the related condition is satisfied.
			if existing, ok := m[norm]; !ok || act < existing {
				m[norm] = act
			}
			delete(m, key)
		}
	}
	normalizeActivationMap(n.pendingValidators)
	normalizeActivationMap(n.pendingValidatorRemovals)

	// `key` stores the key used to access the related value.
	key := normalizeValidatorID(resolveKey(n.pendingValidators, id))

	// `existing` and `ok` store whether the related condition is satisfied.
	if existing, ok := n.pendingValidators[key]; !ok || activationHeight < existing {

		n.pendingValidators[key] = activationHeight

	}

	// `removeKey` stores the key used to access the related value.
	removeKey := normalizeValidatorID(resolveKey(n.pendingValidatorRemovals, id))
	delete(n.pendingValidatorRemovals, removeKey)

	n.validatorSetMu.Unlock()

}

// queuePendingValidatorRemoval implements the queue pending validator removal helper.
func (n *Node) queuePendingValidatorRemoval(id string, activationHeight uint64) {

	id = normalizeValidatorID(id)
	if id == "" || activationHeight == 0 {

		return

	}

	n.validatorSetMu.Lock()

	// `resolveKey` stores the key used to access the related value.
	resolveKey := func(m map[string]uint64, want string) string {
		// `key` tracks the key used to access the related value.
		for key := range m {
			if normalizeValidatorID(key) == want {
				return key
			}
		}
		return want
	}

	if n.pendingValidatorRemovals == nil {

		n.pendingValidatorRemovals = make(map[string]uint64)

	}

	// `normalizeActivationMap` stores the value produced by this operation.
	normalizeActivationMap := func(m map[string]uint64) {
		// `key` and `act` track the key used to access the related value.
		for key, act := range m {
			// `norm` stores the value produced by this operation.
			norm := normalizeValidatorID(key)
			if norm == "" {
				delete(m, key)
				continue
			}
			if norm == key {
				continue
			}
			// `existing` and `ok` store whether the related condition is satisfied.
			if existing, ok := m[norm]; !ok || act < existing {
				m[norm] = act
			}
			delete(m, key)
		}
	}
	normalizeActivationMap(n.pendingValidatorRemovals)
	if n.pendingValidators != nil {
		normalizeActivationMap(n.pendingValidators)
	}

	// `key` stores the key used to access the related value.
	key := normalizeValidatorID(resolveKey(n.pendingValidatorRemovals, id))
	// `existing` and `ok` store whether the related condition is satisfied.
	if existing, ok := n.pendingValidatorRemovals[key]; !ok || activationHeight < existing {

		n.pendingValidatorRemovals[key] = activationHeight

	}

	if n.pendingValidators != nil {

		// `addKey` stores the key used to access the related value.
		addKey := normalizeValidatorID(resolveKey(n.pendingValidators, id))
		delete(n.pendingValidators, addKey)

	}

	n.validatorSetMu.Unlock()

}

// clearPendingValidator implements the clear pending validator helper.
func (n *Node) clearPendingValidator(id string) {

	id = normalizeValidatorID(id)
	if id == "" {

		return

	}

	n.validatorSetMu.Lock()

	if n.pendingValidators != nil {

		// `key` tracks the key used to access the related value.
		for key := range n.pendingValidators {
			if normalizeValidatorID(key) == id {
				delete(n.pendingValidators, key)
				break
			}
		}

	}

	n.validatorSetMu.Unlock()

}

// candidateBanDuration implements the candidate ban duration helper.
func candidateBanDuration(strikes int) uint64 {

	switch strikes {

	case 1:

		return CandidateBanFirst

	case 2:

		return CandidateBanSecond

	default:

		return 0

	}

}

// recordCandidateMisbehaviorLocked implements the record candidate misbehavior locked helper.
func (n *Node) recordCandidateMisbehaviorLocked(id string, cand *CandidateStatus, height uint64, reason string) {

	_ = reason

	if cand == nil {

		return

	}

	cand.Strikes++

	if cand.Promoted {

		// Post-promotion SRP warnings: schedule removal after the limit.

		if cand.Strikes > CandidateWarningLimit {

			// `activationHeight` stores the value produced by this operation.
			activationHeight := height + validatorSetActivationDelayBlocks()
			n.queuePendingValidatorRemoval(id, activationHeight)

			cand.PermanentBan = true

			cand.BanUntil = 0

			fmt.Printf("DEMOTE validator %s height=%d activate_height=%d warnings=%d/%d\n", id, height, activationHeight, cand.Strikes, CandidateWarningLimit)

		} else {

			fmt.Printf("WARN validator %s SRP warning %d/%d (reason=%s)\n", id, cand.Strikes, CandidateWarningLimit, reason)

		}

	} else {

		// Pre-promotion candidate bans.

		if cand.Strikes >= 3 {

			cand.PermanentBan = true

			cand.BanUntil = 0

		} else {

			cand.BanUntil = height + candidateBanDuration(cand.Strikes)

		}

	}

	cand.ObservedEpochs = 0

	cand.MatchedEpochs = 0

	cand.HeartbeatGood = 0

	cand.HeartbeatTotal = 0

	cand.ObservationStartHeight = 0

	cand.LastObservedHeight = 0

	cand.DiversityConsecutive = 0

	cand.LastDiversityRatio = 0

	cand.DiversitySum = 0

	cand.GossipTimely = 0

	cand.GossipTotal = 0

	cand.GossipMissing = 0

	cand.SRPScore = 0

	if cand.ExecHashes != nil {

		cand.ExecHashes = make(map[uint64]string)

	}

	if cand.PendingMatch != nil {

		cand.PendingMatch = make(map[uint64]bool)

	}

	// Ensure a misbehaving candidate is not pending promotion.

	if n.pendingValidators != nil {

		delete(n.pendingValidators, id)

	}

}

// candidateDiversityDetailsForEpoch implements the candidate diversity details for epoch helper.
func (n *Node) candidateDiversityDetailsForEpoch(epoch uint64, block Block) (float64, []string, []string, int, bool) {

	// `validators` stores whether the related condition is satisfied.
	validators := n.GetConsensusValidators(int(epoch))

	// `total` stores the measured quantity used by this operation.
	total := len(validators)

	if total == 0 || block.StateRoot == "" {

		return 0, nil, validators, total, false

	}

	// `allowed` stores whether the related condition is satisfied.
	allowed := make(map[string]bool, total)

	// `v` tracks the current values while iterating.
	for _, v := range validators {

		allowed[v] = true

	}

	// `proposalKey` stores the key used to access the related value.
	proposalKey := proposalVoteKey(block.ID, block.Round, block.BlockHash, block.MempoolRoot, block.StateRoot)
	// `signers` and `ok` store whether the related condition is satisfied.
	_, signers, _, ok := getExecResultsGlobal(epoch, proposalKey, block.StateRoot, block.MempoolRoot)

	if !ok {

		return 0, nil, validators, total, false

	}

	// `observed` stores the value produced by this operation.
	observed := make([]string, 0, len(signers))

	// `observedSet` stores the value produced by this operation.
	observedSet := make(map[string]bool, len(signers))

	// `s` tracks the current values while iterating.
	for _, s := range signers {

		if allowed[s] {

			observed = append(observed, s)

			observedSet[s] = true

		}

	}

	// `missing` stores the value produced by this operation.
	missing := make([]string, 0, total)

	// `v` tracks the current values while iterating.
	for _, v := range validators {

		if !observedSet[v] {

			missing = append(missing, v)

		}

	}

	// `count` stores the measured quantity used by this operation.
	count := len(observed)

	if count > total {

		count = total

	}

	return float64(count) / float64(total), observed, missing, total, true

}

// candidateDiversityRatioForEpoch implements the candidate diversity ratio for epoch helper.
func (n *Node) candidateDiversityRatioForEpoch(epoch uint64, block Block) float64 {

	// `ratio` and `ok` store whether the related condition is satisfied.
	ratio, _, _, _, ok := n.candidateDiversityDetailsForEpoch(epoch, block)

	if !ok {

		return 0

	}

	return ratio

}

// updateCandidateSRPScore implements the update candidate srp score helper.
func updateCandidateSRPScore(prev float64, score float64) float64 {

	if score < 0 {

		score = 0

	}

	if score > 1 {

		score = 1

	}

	if prev == 0 {

		return score

	}

	return prev*(1.0-CandidateSRPAlpha) + score*CandidateSRPAlpha

}

// candidateDCSScore implements the candidate dcs score helper.
func candidateDCSScore(correctness float64, uptime float64, diversity float64, gossipTimeliness float64) float64 {

	// `score` stores the value produced by this operation.
	score := 0.4*correctness + 0.3*uptime + 0.2*diversity + 0.1*gossipTimeliness

	if score < 0 {

		return 0

	}

	if score > 1 {

		return 1

	}

	return score

}

// allowPromotionAtEpoch implements the allow promotion at epoch helper.
func (n *Node) allowPromotionAtEpoch(epoch uint64) bool {

	if PromotionWindowSize <= 0 {

		return true

	}

	// `window` stores the value produced by this operation.
	window := epoch / PromotionWindowSize

	if n.promotionWindowIdx != window {

		n.promotionWindowIdx = window

		n.promotionsInWindow = 0

	}

	if n.promotionsInWindow >= MaxPromotionsPerWindow {

		return false

	}

	n.promotionsInWindow++

	return true

}

// promotionWindowAllows implements the promotion window allows helper.
func (n *Node) promotionWindowAllows(epoch uint64) bool {

	if PromotionWindowSize <= 0 {

		return true

	}

	// `window` stores the value produced by this operation.
	window := epoch / PromotionWindowSize

	if n.promotionWindowIdx != window {

		return true

	}

	return n.promotionsInWindow < MaxPromotionsPerWindow

}

// observeDeterministicOnboardingCandidatesOnCommit implements the observe deterministic onboarding candidates on commit helper.
func (n *Node) observeDeterministicOnboardingCandidatesOnCommit(block Block) {
	if n == nil || block.ID == 0 || !protocolDeterministicValidatorSelectionEnabled() {
		return
	}
	// `committeeHeight` stores the value produced by this operation.
	committeeHeight := block.ID + 1
	// `registrySnapshot` stores the value produced by this operation.
	registrySnapshot := n.validatorRegistrySnapshotForHeight(committeeHeight)
	if len(registrySnapshot) == 0 {
		return
	}

	// `authoritativeSet` stores the committed validator authority for the next
	// height. Candidate admission must compare against chain-derived authority,
	// not registry-small-set projections that may already contain the candidate.
	authoritativeSet, _, _ := n.chainDerivedValidatorAuthorityForHeight(committeeHeight)
	authoritativeSet = canonicalValidatorIDs(authoritativeSet)
	if len(authoritativeSet) == 0 {
		authoritativeSet = canonicalValidatorIDs(n.plannedValidatorSetForHeightFromChain(committeeHeight))
	}
	if len(authoritativeSet) == 0 {
		authoritativeSet = canonicalValidatorIDs(n.consensusValidatorsForHeight(committeeHeight))
	}

	// `baseForOnboarding` stores the value produced by this operation.
	baseForOnboarding := canonicalValidatorIDs(n.GetConsensusValidators(int(committeeHeight)))
	// `fromRegistry` stores the value produced by this operation.
	if fromRegistry := selectAllStakedValidatorsFromSnapshot(committeeHeight, registrySnapshot); len(fromRegistry) > 0 {
		baseForOnboarding = canonicalValidatorIDs(fromRegistry)
	}
	if len(baseForOnboarding) == 0 {
		return
	}

	// `candidateBase` stores the value produced by this operation.
	candidateBase := make([]string, 0, len(baseForOnboarding))
	// `id` tracks the current position in the related collection.
	for _, id := range baseForOnboarding {
		// `norm` stores the value produced by this operation.
		norm := normalizeValidatorID(id)
		if norm == "" || containsNormalizedValidatorID(authoritativeSet, norm) {
			continue
		}
		candidateBase = append(candidateBase, norm)
	}
	if len(candidateBase) == 0 {
		return
	}

	// `window` stores the value produced by this operation.
	window := validatorSelectionActivityWindowBlocks()
	// `minSigned` stores the value produced by this operation.
	minSigned := validatorSelectionMinSignedBlocks()
	if minSigned == 0 {
		minSigned = 1
	}
	// `signedCounts` stores the value produced by this operation.
	signedCounts := n.recentSignedCountFromFinalizedChain(block.ID, window)

	// `admitted` stores the value produced by this operation.
	admitted := make([]string, 0)
	// `admittedSeen` stores the value produced by this operation.
	admittedSeen := make(map[string]struct{})
	// `appendAdmitted` stores the value produced by this operation.
	appendAdmitted := func(ids []string) {
		// `id` tracks the current position in the related collection.
		for _, id := range ids {
			// `norm` stores the value produced by this operation.
			norm := normalizeValidatorID(id)
			if norm == "" {
				continue
			}
			// `ok` stores whether the related condition is satisfied.
			if _, ok := admittedSeen[norm]; ok {
				continue
			}
			admittedSeen[norm] = struct{}{}
			admitted = append(admitted, norm)
		}
	}

	// `slots` stores the value produced by this operation.
	if slots := validatorOnboardingMaxNewSlots(); slots > 0 {
		// `regular` stores the value produced by this operation.
		regular, _, _ := computeValidatorOnboardingAdmissions(
			candidateBase,
			signedCounts,
			minSigned,
			committeeHeight,
			registrySnapshot,
			slots,
		)
		appendAdmitted(regular)
	}
	// `slots` stores the value produced by this operation.
	if slots := validatorOnboardingBootstrapMaxNewSlots(); slots > 0 && validatorOnboardingBootstrapLaneEnabled() {
		// `lane` stores the value produced by this operation.
		lane, _, _ := computeValidatorBootstrapLaneAdmissions(
			candidateBase,
			signedCounts,
			minSigned,
			committeeHeight,
			registrySnapshot,
			slots,
		)
		appendAdmitted(lane)
	}
	if GenesisValidatorSetFrozen {
		// `capacity` stores the value produced by this operation.
		capacity := len(candidateBase)
		// `target` stores the value produced by this operation.
		if target := n.activeSetTarget(); target >= 0 {
			capacity = target - len(authoritativeSet)
			if capacity < 0 {
				capacity = 0
			}
		}
		// `id` tracks the current position in the related collection.
		for _, id := range candidateBase {
			if len(admitted) >= capacity {
				break
			}
			// `norm` stores the value produced by this operation.
			norm := normalizeValidatorID(id)
			if norm == "" || containsNormalizedValidatorID(authoritativeSet, norm) {
				continue
			}
			if containsNormalizedValidatorID(n.GenesisValidators, norm) || validatorHasGenesisPubKey(norm) {
				continue
			}
			// `seen` stores the value produced by this operation.
			if _, seen := admittedSeen[norm]; seen {
				continue
			}
			// `eval` stores the value currently being processed.
			eval := evaluateValidatorOnboardingFromSnapshot(norm, committeeHeight, registrySnapshot)
			if !eval.Eligible && !eval.BootstrapEligible {
				continue
			}
			appendAdmitted([]string{norm})
		}
	}
	if len(admitted) == 0 {
		return
	}

	// `scheduledHeight` stores the value produced by this operation.
	scheduledHeight := block.ID + validatorSetActivationDelayBlocks()
	if scheduledHeight == 0 || scheduledHeight <= block.ID {
		return
	}

	// `id` tracks the current position in the related collection.
	for _, id := range admitted {
		// `norm` stores the value produced by this operation.
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		if containsNormalizedValidatorID(authoritativeSet, norm) {
			continue
		}

		// `ready` and `reason` store the value produced by this operation.
		ready, reason := n.onboardingActivationReady(norm, committeeHeight, registrySnapshot)
		if !ready && GenesisValidatorSetFrozen &&
			!containsNormalizedValidatorID(n.GenesisValidators, norm) &&
			!validatorHasGenesisPubKey(norm) {
			// `eval` stores the value currently being processed.
			eval := evaluateValidatorOnboardingFromSnapshot(norm, committeeHeight, registrySnapshot)
			if eval.Eligible || eval.BootstrapEligible {
				ready = true
				reason = strings.TrimSpace(eval.Reason)
				if reason == "" || reason == "grace_expired" {
					reason = "bootstrap_lane"
				}
			}
		}
		if !ready {
			continue
		}

		// `pendingBefore` stores the value produced by this operation.
		pendingBefore := n.onboardingPendingAddHeight(norm)
		n.queuePendingValidator(norm, scheduledHeight)
		// `pendingAfter` stores the value produced by this operation.
		pendingAfter := n.onboardingPendingAddHeight(norm)

		// `pubKey` stores the key used to access the related value.
		pubKey := []byte(nil)
		// `rec` and `ok` store whether the related condition is satisfied.
		if rec, ok := validatorRegistryRecordFromSnapshot(registrySnapshot, norm); ok {
			pubKey = validatorRecordPubKeyBytes(rec, norm)
		}

		n.candidateMu.Lock()
		// `cand` stores the value produced by this operation.
		if cand := n.candidates[norm]; cand != nil {
			cand.Promoted = true
			if len(cand.PubKey) == ed25519.PublicKeySize {
				pubKey = append([]byte(nil), cand.PubKey...)
			}
		}
		n.candidateMu.Unlock()

		if len(pubKey) == ed25519.PublicKeySize {
			validatorPubKeysMu.Lock()
			ValidatorPubKeys[norm] = append(ed25519.PublicKey(nil), pubKey...)
			validatorPubKeysMu.Unlock()
		}

		if DebugConsensus && pendingAfter > 0 && pendingAfter != pendingBefore {
			// `effectiveHeight` stores the value produced by this operation.
			effectiveHeight := validatorSetTransitionActivationHeightAt(pendingAfter, committeeHeight)
			fmt.Printf("[ONBOARDING-QUEUE] id=%s height=%d scheduled=%d effective=%d reason=%s source=deterministic_registry_admission\n",
				norm,
				block.ID,
				pendingAfter,
				effectiveHeight,
				reason,
			)
		}
	}
}

// observeCandidatesOnCommit implements the observe candidates on commit helper.
func (n *Node) observeCandidatesOnCommit(block Block) {

	if block.ID == 0 {

		return

	}
	if protocolDeterministicValidatorSelectionEnabled() {
		n.observeDeterministicOnboardingCandidatesOnCommit(block)
		return

	}

	if protocolCandidateIsolationEnabled() {

		// Production hard rule: candidate observation can remain enabled for
		// telemetry, but candidates must not influence validator-set transitions.
		return

	}

	// `toPromote` stores the value produced by this operation.
	toPromote := make([]string, 0)

	n.candidateMu.Lock()

	// `id` and `cand` track the current position in the related collection.
	for id, cand := range n.candidates {

		if cand == nil || cand.Promoted || cand.PermanentBan {

			continue

		}

		if cand.BanUntil > 0 {

			if block.ID < cand.BanUntil {

				continue

			}

			cand.BanUntil = 0

		}

		if cand.ObservationStartHeight == 0 {

			// `start` stores the value produced by this operation.
			start := cand.LastReportedHeight

			if cand.LastFinalizedHeight > 0 && (start == 0 || cand.LastFinalizedHeight < start) {

				start = cand.LastFinalizedHeight

			}

			if start == 0 {

				continue

			}

			cand.ObservationStartHeight = start

		}

		if block.ID < cand.ObservationStartHeight {

			continue

		}

		// `observedThrough` stores the value produced by this operation.
		observedThrough := cand.LastFinalizedHeight

		if cand.LastReportedHeight > observedThrough {

			observedThrough = cand.LastReportedHeight

		}

		if observedThrough < cand.ObservationStartHeight {

			continue

		}

		// `maxHeight` stores the value produced by this operation.
		maxHeight := observedThrough

		if block.ID < maxHeight {

			maxHeight = block.ID

		}

		// `startHeight` stores the value produced by this operation.
		startHeight := cand.ObservationStartHeight

		if cand.LastObservedHeight+1 > startHeight {

			startHeight = cand.LastObservedHeight + 1

		}

		if startHeight > maxHeight {

			continue

		}

		// `h` stores the value produced by this operation.
		for h := startHeight; h <= maxHeight; h++ {

			// `blk` and `ok` store whether the related condition is satisfied.
			blk, ok := n.Blockchain.GetBlock(h)

			if !ok {

				continue

			}

			// `hash` stores the digest used to identify or verify the related data.
			hash := ""

			if cand.ExecHashes != nil {

				hash = cand.ExecHashes[h]

			}

			if hash == "" {

				// Candidate hasn't provided an exec hash for this height yet.

				// Advance the cursor so we don't stall, but don't count it.

				cand.LastObservedHeight = h

				cand.DiversityConsecutive = 0

				cand.GossipTotal++

				cand.GossipMissing++

				if id == "F" || id == "G" {

					fmt.Printf("DBG candidate %s exec_hash_missing height=%d last_obs=%d gossip_missing=%d\n",

						id,

						h,

						cand.LastObservedHeight,

						cand.GossipMissing,
					)

				}

				continue

			}

			cand.ObservedEpochs++

			cand.GossipTotal++

			cand.GossipTimely++

			if hash == blk.StateRoot {

				cand.MatchedEpochs++

				if id == "F" || id == "G" {

					fmt.Printf("DBG candidate %s exec_match height=%d hash=%s\n",

						id,

						h,

						ShortHash(hash),
					)

				}

				// `diversityRatio`, `observedVals`, `missingVals`, `totalVals`, and `ok` store whether the related condition is satisfied.
				diversityRatio, observedVals, missingVals, totalVals, ok := n.candidateDiversityDetailsForEpoch(h, blk)

				cand.LastDiversityRatio = diversityRatio

				cand.DiversitySum += diversityRatio

				if diversityRatio >= CandidateDiversityPctMin {

					cand.DiversityConsecutive++

				} else {

					cand.DiversityConsecutive = 0

				}

				if id == "F" || id == "G" {

					if !ok {

						fmt.Printf("DBG candidate %s exec_results_missing height=%d exec_hash=%s tx=%s validators=%v\n",

							id,

							h,

							ShortHash(blk.StateRoot),

							ShortHash(blk.MempoolRoot),

							n.GetConsensusValidators(int(h)),
						)

					} else if diversityRatio < CandidateDiversityPctMin {

						fmt.Printf("DBG candidate %s diversity_low height=%d observed=%v missing=%v total=%d ratio=%.2f%%\n",

							id,

							h,

							observedVals,

							missingVals,

							totalVals,

							diversityRatio*100,
						)

					}

				}

			} else {

				if id == "F" || id == "G" {

					fmt.Printf("DBG candidate %s exec_mismatch height=%d expected=%s got=%s\n",

						id,

						h,

						ShortHash(blk.StateRoot),

						ShortHash(hash),
					)

				}

				n.recordCandidateMisbehaviorLocked(id, cand, h, "exec_mismatch")

				// Candidate got reset; stop processing this candidate for now.

				break

			}

			delete(cand.ExecHashes, h)

			cand.LastObservedHeight = h

		}

		// `correctness` stores the value produced by this operation.
		correctness := 0.0

		// `diversityAvg` stores the value produced by this operation.
		diversityAvg := 0.0

		// `gossipTimeliness` stores the value produced by this operation.
		gossipTimeliness := 0.0

		// `uptime` stores the value produced by this operation.
		uptime := 0.0

		if cand.ObservedEpochs > 0 {

			correctness = float64(cand.MatchedEpochs) / float64(cand.ObservedEpochs)

			diversityAvg = cand.DiversitySum / float64(cand.ObservedEpochs)

		}

		if cand.HeartbeatTotal > 0 {

			uptime = float64(cand.HeartbeatGood) / float64(cand.HeartbeatTotal)

		}

		if cand.GossipTotal > 0 {

			gossipTimeliness = float64(cand.GossipTimely) / float64(cand.GossipTotal)

		}

		// `dcs` stores the value produced by this operation.
		dcs := candidateDCSScore(correctness, uptime, diversityAvg, gossipTimeliness)

		cand.SRPScore = updateCandidateSRPScore(cand.SRPScore, dcs)

		if id == "F" || id == "G" {

			// `reasons` stores the value produced by this operation.
			reasons := make([]string, 0, 6)

			if cand.ObservedEpochs < CandidateObservationEpochs {

				reasons = append(reasons, "obs")

			}

			if cand.DiversityConsecutive < CandidateDiversityEpochs {

				reasons = append(reasons, "div")

			}

			if dcs < CandidateDCSMin {

				reasons = append(reasons, "dcs")

			}

			if uptime < CandidateUptimeMin {

				reasons = append(reasons, "uptime")

			}

			if cand.SRPScore < CandidateSRPMin {

				reasons = append(reasons, "srp")

			}

			// `windowOK` stores whether the related condition is satisfied.
			windowOK := n.promotionWindowAllows(block.ID)

			if !windowOK {

				reasons = append(reasons, "rate")

			}

			// `reasonStr` stores the value produced by this operation.
			reasonStr := "ok"

			if len(reasons) > 0 {

				reasonStr = strings.Join(reasons, ",")

			}

			fmt.Printf("DBG candidate %s height=%d obs=%d/%d match=%d dcs=%.4f uptime=%.2f%% div=%.2f%% gossip=%.2f%% div_seq=%d/%d srp=%.4f window_ok=%t reasons=%s\n",

				id,

				block.ID,

				cand.ObservedEpochs,

				CandidateObservationEpochs,

				cand.MatchedEpochs,

				dcs,

				uptime*100,

				diversityAvg*100,

				gossipTimeliness*100,

				cand.DiversityConsecutive,

				CandidateDiversityEpochs,

				cand.SRPScore,

				windowOK,

				reasonStr,
			)

			if gossipTimeliness < 0.9 {

				fmt.Printf("DBG candidate %s gossip_low total=%d timely=%d missing_exec_hash=%d timeliness=%.2f%%\n",

					id,

					cand.GossipTotal,

					cand.GossipTimely,

					cand.GossipMissing,

					gossipTimeliness*100,
				)

			}

		}

		// `shouldPromote` stores the value produced by this operation.
		shouldPromote := false

		if TestingRelaxedPromotion {

			if cand.ObservedEpochs > 0 && diversityAvg > 0 && gossipTimeliness > 0 {

				shouldPromote = true

			}

		} else if cand.ObservedEpochs >= CandidateObservationEpochs && cand.DiversityConsecutive >= CandidateDiversityEpochs {

			if dcs >= CandidateDCSMin && uptime >= CandidateUptimeMin && cand.SRPScore >= CandidateSRPMin {

				shouldPromote = true

			}

		}

		if shouldPromote {

			// Production-safety: promotion requires minimum stake.

			rec, ok := GlobalValidatorRegistry.Get(id)

			if !ok || rec == nil || !validatorPassesStakeGate(id, rec.Stake) {

				if DebugConsensus {

					fmt.Printf("PROMO blocked: candidate %s missing stake (stake=%d min=%d)\n",

						id,

						func() int64 {

							if rec == nil {

								return 0

							}

							return rec.Stake

						}(),

						ConsensusValidatorMinStake,
					)

				}

				continue

			}

			if !n.allowPromotionAtEpoch(block.ID) {

				continue

			}

			cand.Promoted = true

			// `activationHeight` stores the value produced by this operation.
			activationHeight := block.ID + validatorSetActivationDelayBlocks()

			fmt.Printf("PROMOTE candidate %s height=%d activate_height=%d dcs=%.4f uptime=%.2f%% diversity=%.2f%% gossip=%.2f%% srp=%.4f\n",

				id,

				block.ID,

				activationHeight,

				dcs,

				uptime*100,

				diversityAvg*100,

				gossipTimeliness*100,

				cand.SRPScore,
			)

			toPromote = append(toPromote, id)

		}

	}

	n.candidateMu.Unlock()

	if len(toPromote) == 0 {

		return

	}

	n.validatorSetMu.Lock()

	// `id` tracks the current position in the related collection.
	for _, id := range toPromote {
		id = normalizeValidatorID(id)
		if id == "" {
			continue
		}

		if n.isValidatorInSet(id) {

			continue

		}

		// `activationHeight` stores the value produced by this operation.
		activationHeight := block.ID + validatorSetActivationDelayBlocks()

		// `existing` and `ok` store whether the related condition is satisfied.
		if existing, ok := n.pendingValidators[id]; ok {

			if existing > activationHeight {

				n.pendingValidators[id] = activationHeight

			}

		} else {

			n.pendingValidators[id] = activationHeight

		}

		delete(n.pendingValidatorRemovals, id)

		// `cand` and `ok` store whether the related condition is satisfied.
		if cand, ok := n.candidates[id]; ok && cand != nil && len(cand.PubKey) == ed25519.PublicKeySize {
			validatorPubKeysMu.Lock()
			ValidatorPubKeys[id] = cand.PubKey
			validatorPubKeysMu.Unlock()
		}

	}

	n.validatorSetMu.Unlock()

}

// applyValidatorUpdatesFromBlock applies validator updates from block.
func (n *Node) applyValidatorUpdatesFromBlock(block Block) {
	if n == nil || block.ID == 0 {
		return
	}
	// `validators` and `ok` store whether the related condition is satisfied.
	validators, ok := n.blockValidatorSetFromSignatures(block)
	if !ok || len(validators) == 0 {
		return
	}
	// `setHash` stores the digest used to identify or verify the related data.
	setHash := strings.TrimSpace(block.ValidatorSetHash)
	if setHash == "" {
		setHash = n.validatorSetHashFromFinalizedSnapshot(block.ID, validators)
	}
	if setHash == "" {
		setHash = ValidatorSetHash(validators)
	}
	// `plannedNextValidators` stores the value produced by this operation.
	plannedNextValidators := []string(nil)
	// `plannedNextHash` stores the digest used to identify or verify the related data.
	plannedNextHash := ""
	// `activationHeight` stores the value produced by this operation.
	activationHeight := blockActivationHeight(block)
	if activationHeight == block.ID+1 {
		// `nextHash` stores the digest used to identify or verify the related data.
		nextHash := strings.TrimSpace(block.NextValidatorSetHash)
		if nextHash != "" && !strings.EqualFold(nextHash, setHash) {
			// `ctx` stores the context controlling this operation.
			if ctx := n.blockValidatorUpdatePlanContext(block); ctx != nil {
				// `planned` stores the value produced by this operation.
				if planned := ctx.plannedValidatorsForHeight(block.ID + 1); len(planned) > 0 {
					// `hash` stores the digest used to identify or verify the related data.
					hash := strings.TrimSpace(validatorSetHashFromSnapshotForHeight(block.ID+1, planned, ctx.registrySnapshot))
					if hash != "" && strings.EqualFold(hash, nextHash) {
						plannedNextValidators = append([]string{}, planned...)
						plannedNextHash = hash
					}
				}
			}
			if len(plannedNextValidators) == 0 {
				// `reconstructed`, `source`, and `ok` store whether the related condition is satisfied.
				if reconstructed, _, source, ok := n.authoritativeNextValidatorSetCandidateForBlock(block, nextHash); ok && len(reconstructed) > 0 {
					plannedNextValidators = append([]string{}, reconstructed...)
					plannedNextHash = nextHash
					if DebugConsensus {
						fmt.Printf("[SET-FREEZE-NEXT] height=%d source=%s hash=%s size=%d\n",
							block.ID+1, source, ShortHash(nextHash), len(reconstructed))
					}
				}
			}
		}
	}

	// `updated` stores the value produced by this operation.
	updated := false
	n.validatorSetMu.Lock()
	if n.epochValidators == nil {
		n.epochValidators = make(map[uint64][]string)
	}
	if n.frozenValidatorsByHeight == nil {
		n.frozenValidatorsByHeight = make(map[uint64][]string)
	}
	if n.frozenValidatorHashByHeight == nil {
		n.frozenValidatorHashByHeight = make(map[uint64]string)
	}
	if n.pendingValidators == nil {
		n.pendingValidators = make(map[string]uint64)
	}
	if n.pendingValidatorRemovals == nil {
		n.pendingValidatorRemovals = make(map[string]uint64)
	}

	// `currentHash` stores the digest used to identify or verify the related data.
	currentHash := strings.TrimSpace(n.frozenValidatorHashByHeight[block.ID])
	if n.validatorSetHeight < block.ID || !strings.EqualFold(currentHash, setHash) {
		n.validatorSetHeight = block.ID
		updated = true
	}

	n.epochValidators[block.ID] = append([]string{}, validators...)
	n.frozenValidatorsByHeight[block.ID] = append([]string{}, validators...)
	n.frozenValidatorHashByHeight[block.ID] = setHash
	if activationHeight == block.ID+1 {
		// `nextValidators` stores the value produced by this operation.
		nextValidators := append([]string{}, validators...)
		if len(plannedNextValidators) > 0 {
			nextValidators = append([]string{}, plannedNextValidators...)
			setHash = plannedNextHash
		}
		if len(nextValidators) > 0 {
			n.epochValidators[block.ID+1] = append([]string{}, nextValidators...)
			n.frozenValidatorsByHeight[block.ID+1] = append([]string{}, nextValidators...)
			n.frozenValidatorHashByHeight[block.ID+1] = strings.TrimSpace(block.NextValidatorSetHash)
			if n.frozenValidatorHashByHeight[block.ID+1] == "" {
				n.frozenValidatorHashByHeight[block.ID+1] = setHash
			}
		}
	}

	// Post-fork membership is committed by chain blocks. Clear due pending
	// transitions only after commit-time application, never on runtime planning.
	deleteActivationKey := func(m map[string]uint64, want string) {
		// `key` tracks the key used to access the related value.
		for key := range m {
			if normalizeValidatorID(key) == want {
				delete(m, key)
			}
		}
	}
	// `processedAdds` stores the value produced by this operation.
	processedAdds := make([]string, 0)
	// `id` and `act` track the current position in the related collection.
	for id, act := range n.pendingValidators {
		// `effectiveActivation` stores the value produced by this operation.
		effectiveActivation := validatorSetTransitionActivationHeightAt(act, block.ID)
		if effectiveActivation == 0 || effectiveActivation > block.ID {
			continue
		}
		processedAdds = append(processedAdds, normalizeValidatorID(id))
	}
	// `id` tracks the current position in the related collection.
	for _, id := range processedAdds {
		if id == "" {
			continue
		}
		deleteActivationKey(n.pendingValidators, id)
	}
	// `processedRemovals` stores the value produced by this operation.
	processedRemovals := make([]string, 0)
	// `id` and `act` track the current position in the related collection.
	for id, act := range n.pendingValidatorRemovals {
		// `effectiveActivation` stores the value produced by this operation.
		effectiveActivation := validatorSetTransitionActivationHeightAt(act, block.ID)
		if effectiveActivation == 0 || effectiveActivation > block.ID {
			continue
		}
		processedRemovals = append(processedRemovals, normalizeValidatorID(id))
	}
	// `id` tracks the current position in the related collection.
	for _, id := range processedRemovals {
		if id == "" {
			continue
		}
		deleteActivationKey(n.pendingValidatorRemovals, id)
	}
	if n.transitionPlan.Active && n.transitionPlan.UpdateHeight <= block.ID {
		n.clearTransitionPlanLocked()
	}
	n.pruneCommitteeStateLocked(block.ID)
	n.validatorSetMu.Unlock()

	if updated && DebugConsensus {
		fmt.Printf("[SET-COMMIT] height=%d hash=%s validators=%d source=block_signatures\n",
			block.ID, ShortHash(setHash), len(validators))
	}
	if updated {
		n.requestHeartbeatBroadcast(true)
	}
}

// clearPendingValidatorUpdatesUpTo implements the clear pending validator updates up to helper.
func (n *Node) clearPendingValidatorUpdatesUpTo(height uint64) {

	n.validatorSetMu.Lock()

	defer n.validatorSetMu.Unlock()

	// `id` and `act` track the current position in the related collection.
	for id, act := range n.pendingValidators {

		if act <= height {

			delete(n.pendingValidators, id)

		}

	}

	// `id` and `act` track the current position in the related collection.
	for id, act := range n.pendingValidatorRemovals {

		if act <= height {

			delete(n.pendingValidatorRemovals, id)

		}

	}

}

// applyQueuedValidatorSetUpdate applies queued validator set update.
func (n *Node) applyQueuedValidatorSetUpdate(height uint64) bool {

	if protocolDeterministicValidatorSelectionEnabled() {

		// Gossip-based validator set updates are disabled in deterministic mode.

		// Drop any queued updates to avoid stale growth.

		n.validatorSetMu.Lock()

		if n.queuedValidatorSetUpdates != nil {

			delete(n.queuedValidatorSetUpdates, height)

		}

		n.validatorSetMu.Unlock()

		return false

	}

	n.validatorSetMu.Lock()

	// `update` and `ok` store whether the related condition is satisfied.
	update, ok := n.queuedValidatorSetUpdates[height]

	if !ok {

		n.validatorSetMu.Unlock()

		return false

	}

	delete(n.queuedValidatorSetUpdates, height)

	// `next` stores the value produced by this operation.
	next := append([]string{}, update.Validators...)

	next = canonicalValidatorIDs(next)
	if len(next) < minActiveValidatorsFloor() {
		n.validatorSetMu.Unlock()
		if DebugConsensus {
			fmt.Printf("Ã¢Å¡Â Ã¯Â¸Â Ignoring validator set update (gossip): would reduce active validators below minimum (%d < %d)\n",
				len(next), minActiveValidatorsFloor())
		}
		return false
	}

	n.currentValidators = next

	n.validatorSetHeight = height

	n.validatorSetMu.Unlock()

	fmt.Printf("Ã¢Å“â€¦ Validator set updated (gossip): height=%d hash=%s validators=%d\n",

		height,

		ValidatorSetHash(next)[:8],

		len(next),
	)

	n.requestConsensusRecomputePause(height, "validator_set_update_gossip")
	n.snapshotEpochValidators(height + 1)

	return true

}

// sanitizeBPS implements the sanitize bps helper.
func sanitizeBPS(v uint64) uint64 {
	if v > 10000 {
		return 10000
	}
	return v
}

// burnValidatorStakeByBPS implements the burn validator stake by bps helper.
func (n *Node) burnValidatorStakeByBPS(validatorID string, burnBPS uint64) int {
	if n == nil {
		return 0
	}
	validatorID = normalizeValidatorID(validatorID)
	burnBPS = sanitizeBPS(burnBPS)
	if validatorID == "" || burnBPS == 0 {
		return 0
	}

	// `burnedTotal` stores the measured quantity used by this operation.
	burnedTotal := 0
	n.Lock()
	// `ledger` stores the value produced by this operation.
	ledger := n.currentExecutionLedgerClone()
	// `remainingBurn` stores the value produced by this operation.
	remainingBurn := burnCapacityForCoin(&ledger, CoinSymbol)
	if remainingBurn <= 0 {
		n.Unlock()
		return 0
	}
	// `keys` stores the key used to access the related value.
	keys := make([]string, 0, len(ledger.Stakes))
	// `key` and `rec` track the key used to access the related value.
	for key, rec := range ledger.Stakes {
		if rec.Amount <= 0 {
			continue
		}
		// `target` stores the value produced by this operation.
		target := normalizeValidatorID(rec.ValidatorID)
		if target == "" {
			// `parts` stores the value produced by this operation.
			parts := strings.SplitN(key, "|", 2)
			if len(parts) == 2 {
				target = normalizeValidatorID(parts[1])
			}
		}
		if target != validatorID {
			continue
		}
		keys = append(keys, key)
	}
	sort.Strings(keys)
	// `key` tracks the key used to access the related value.
	for _, key := range keys {
		if remainingBurn <= 0 {
			break
		}
		// `rec` and `ok` store whether the related condition is satisfied.
		rec, ok := ledger.Stakes[key]
		if !ok || rec.Amount <= 0 {
			continue
		}
		// `burn` stores the value produced by this operation.
		burn := int((int64(rec.Amount) * int64(burnBPS)) / 10000)
		if burn <= 0 {
			burn = 1
		}
		if burn > rec.Amount {
			burn = rec.Amount
		}
		if int64(burn) > remainingBurn {
			burn = int(remainingBurn)
		}
		if burn <= 0 {
			continue
		}

		rec.Amount -= burn
		rec.Burned += burn
		if rec.Amount <= 0 {
			delete(ledger.Stakes, key)
		} else {
			ledger.Stakes[key] = rec
		}
		burnedTotal += burn
		remainingBurn -= int64(burn)
	}
	n.Unlock()
	n.setExecutionLedger(ledger)

	return burnedTotal
}

// applyOfflineInactivityPenalty applies offline inactivity penalty.
func (n *Node) applyOfflineInactivityPenalty(validatorID string, height uint64) {
	validatorID = normalizeValidatorID(validatorID)
	if n == nil || validatorID == "" || height == 0 {
		return
	}
	// `isolated` stores the current position in the related collection.
	if isolated, _ := n.validatorSyncIsolationState(height); isolated {
		return
	}

	if !MarkValidatorInactivityPenalty(validatorID, height) {
		return
	}

	// `offenses` stores the value produced by this operation.
	offenses := uint64(1)
	// `rec` and `ok` store whether the related condition is satisfied.
	if rec, ok := GlobalValidatorRegistry.Get(validatorID); ok && rec != nil && rec.InactivityPenalties > 0 {
		offenses = rec.InactivityPenalties
	}
	// `tier` stores the value produced by this operation.
	tier := inactivityPenaltyTier(offenses)

	ApplyValidatorPenalty(validatorID, "offline_inactive", height)

	// `burnBPS` stores the value produced by this operation.
	burnBPS := inactivityPenaltyBurnBPSForCount(offenses)
	// `burned` stores the value produced by this operation.
	burned := n.burnValidatorStakeByBPS(validatorID, burnBPS)
	if burned > 0 {
		ApplyValidatorStake(validatorID, -int64(burned), height)
	}

	if DebugConsensus {
		fmt.Printf("Ã¢Å¡â€“Ã¯Â¸Â Inactivity penalty applied: validator=%s height=%d tier=%d offenses=%d burned=%d bps=%d\n",
			validatorID, height, tier, offenses, burned, sanitizeBPS(burnBPS))
	}
}

// queueDeterministicInactiveRemovals derives inactive removals from finalized
// chain data only. This keeps validator-set transitions identical on all nodes.
func (n *Node) queueDeterministicInactiveRemovals(currentHeight uint64) {
	_ = n
	_ = currentHeight
	// Exact individual inactivity is not committed in the canonical block
	// identity. Consensus validator removals must wait for a committed activity
	// root/bitmap, otherwise honest nodes can schedule different removals.
}

// recentActiveValidatorsFromFinalizedChain implements the recent active validators from finalized chain helper.
func (n *Node) recentActiveValidatorsFromFinalizedChain(tipHint uint64, window uint64) map[string]struct{} {
	// `active` stores the value produced by this operation.
	active := make(map[string]struct{})
	if n == nil || n.Blockchain == nil || window == 0 {
		return active
	}

	// `tip` stores the value produced by this operation.
	tip := tipHint
	if tip == 0 {
		tip = n.getFinalizedHeight()
		if tip == 0 {
			tip = n.Blockchain.FinalizedHeight()
			if tip == 0 {
				tip = n.Blockchain.Height()
			}
		}
	}
	if tip == 0 {
		return active
	}

	// `start` stores the value produced by this operation.
	start := uint64(1)
	if tip >= window {
		start = tip - window + 1
	}

	// `h` stores the value produced by this operation.
	for h := start; h <= tip; h++ {
		validators, ok := n.canonicalActivityValidatorsForFinalizedHeight(h)
		if !ok {
			return map[string]struct{}{}
		}
		// `id` tracks the current position in the related collection.
		for _, id := range validators {
			active[id] = struct{}{}
		}
	}

	return active
}

// recentSignedCountFromFinalizedChain implements the recent signed count from finalized chain helper.
func (n *Node) recentSignedCountFromFinalizedChain(tipHint uint64, window uint64) map[string]uint64 {
	// `counts` stores the measured quantity used by this operation.
	counts := make(map[string]uint64)
	if n == nil || n.Blockchain == nil || window == 0 {
		return counts
	}

	// `tip` stores the value produced by this operation.
	tip := tipHint
	if tip == 0 {
		tip = n.getFinalizedHeight()
		if tip == 0 {
			tip = n.Blockchain.FinalizedHeight()
			if tip == 0 {
				tip = n.Blockchain.Height()
			}
		}
	}
	if tip == 0 {
		return counts
	}

	// `start` stores the value produced by this operation.
	start := uint64(1)
	if tip >= window {
		start = tip - window + 1
	}

	// `h` stores the value produced by this operation.
	for h := start; h <= tip; h++ {
		validators, ok := n.canonicalActivityValidatorsForFinalizedHeight(h)
		if !ok {
			return map[string]uint64{}
		}
		// `id` tracks the current position in the related collection.
		for _, id := range validators {
			counts[id]++
		}
	}
	return counts
}

// recentFinalitySignerCountFromFinalizedChain returns recent finalized quorum
// witness counts for validator-set transition barriers. This intentionally uses
// finality/block signature evidence, while activity-style liveness can use
// proposer-based evidence via recentSignedCountFromFinalizedChain.
func (n *Node) recentFinalitySignerCountFromFinalizedChain(tipHint uint64, window uint64) map[string]uint64 {
	counts := make(map[string]uint64)
	if n == nil || n.Blockchain == nil || window == 0 {
		return counts
	}

	tip := tipHint
	if tip == 0 {
		tip = n.getFinalizedHeight()
		if tip == 0 {
			tip = n.Blockchain.FinalizedHeight()
			if tip == 0 {
				tip = n.Blockchain.Height()
			}
		}
	}
	if tip == 0 {
		return counts
	}

	start := uint64(1)
	if tip >= window {
		start = tip - window + 1
	}
	for h := start; h <= tip; h++ {
		block, ok := n.Blockchain.GetBlock(h)
		if !ok {
			return map[string]uint64{}
		}
		signers := finalitySignersForBlock(block)
		if len(signers) == 0 {
			return map[string]uint64{}
		}
		for _, id := range signers {
			if id = normalizeValidatorID(id); id != "" {
				counts[id]++
			}
		}
	}
	return counts
}

// canonicalActivityValidatorsForFinalizedHeight returns the committed validator
// set that is safe to use for deterministic activity-style status calculations.
func (n *Node) canonicalActivityValidatorsForFinalizedHeight(height uint64) ([]string, bool) {
	if n == nil || n.Blockchain == nil || height == 0 {
		return nil, false
	}
	// `block` and `ok` store whether the related condition is satisfied.
	block, ok := n.Blockchain.GetBlock(height)
	if !ok {
		return nil, false
	}
	if proposer := normalizeValidatorID(block.Proposer); proposer != "" {
		return []string{proposer}, true
	}
	// `validators` stores the value produced by this operation.
	if validators, _, ok := n.chainDerivedValidatorAuthorityForHeight(height); ok && len(validators) > 0 {
		return canonicalValidatorIDs(validators), true
	}
	if validators := canonicalValidatorIDs(n.consensusValidatorsForHeight(height)); len(validators) > 0 {
		return validators, true
	}
	// `registrySnapshot` stores the value produced by this operation.
	registrySnapshot := n.validatorRegistrySnapshotForHeight(height)
	validators := protocolRewardValidatorsFromRegistrySnapshot(height, registrySnapshot)
	if len(validators) == 0 {
		return nil, false
	}
	return validators, true
}

// snapshotLiveValidatorIDsForSetSafety implements the snapshot live validator i ds for set safety helper.
func (n *Node) snapshotLiveValidatorIDsForSetSafety(currentHeight uint64) map[string]struct{} {
	if n == nil {
		return nil
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `localFinalized` stores the value produced by this operation.
	localFinalized := n.getFinalizedHeight()
	if localFinalized == 0 {
		localFinalized = currentHeight
	}

	// `live` stores the value produced by this operation.
	live := make(map[string]struct{})
	n.validatorMu.RLock()
	// `id` and `st` track the current position in the related collection.
	for id, st := range n.validatorStatus {
		if st == nil {
			continue
		}
		// `norm` stores the value produced by this operation.
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		if !n.isValidatorLiveForConsensusLocked(norm, st, now, localFinalized) {
			continue
		}
		live[norm] = struct{}{}
	}
	n.validatorMu.RUnlock()
	return live
}

// validatorSetQuorumSafety implements the validator set quorum safety helper.
func validatorSetQuorumSafety(validators []string, live map[string]struct{}) (bool, int, int) {
	if len(validators) == 0 {
		return false, 0, 0
	}
	// `required` stores the request data being processed.
	required := execQuorumRequired(len(validators))
	if required == 0 {
		return true, 0, 0
	}
	// No live snapshot yet: do not deadlock activation during bootstrap.
	if len(live) == 0 {
		return true, 0, required
	}
	// `liveCount` stores the measured quantity used by this operation.
	liveCount := 0
	// `id` tracks the current position in the related collection.
	for _, id := range validators {
		// `norm` stores the value produced by this operation.
		norm := strings.ToUpper(strings.TrimSpace(id))
		if norm == "" {
			continue
		}
		// `ok` stores whether the related condition is satisfied.
		if _, ok := live[norm]; ok {
			liveCount++
		}
	}
	return liveCount >= required, liveCount, required
}

// validatorSetTransitionQuorum implements the validator set transition quorum helper.
func (n *Node) validatorSetTransitionQuorum(updateHeight uint64, transitionValidators []string, nextValidators []string) (bool, int, int, int) {
	if n == nil || updateHeight == 0 || len(nextValidators) == 0 {
		return false, 0, 0, 0
	}
	// `current` stores the value produced by this operation.
	current := canonicalValidatorIDs(transitionValidators)
	if len(current) == 0 {
		current = canonicalValidatorIDs(n.GetConsensusValidators(int(updateHeight)))
	}
	if len(current) == 0 {
		return true, 0, 0, 0
	}
	// `next` stores the value produced by this operation.
	next := canonicalValidatorIDs(nextValidators)
	if len(next) == 0 {
		return false, 0, 0, 0
	}

	// `requiredReports` stores the request data being processed.
	requiredReports := execQuorumRequired(len(current))
	if requiredReports == 0 {
		requiredReports = 1
	}
	// `requiredMatches` stores the request data being processed.
	requiredMatches := execQuorumRequired(len(next))
	if requiredMatches == 0 {
		requiredMatches = 1
	}

	// `localFinalized` stores the value produced by this operation.
	localFinalized := n.getFinalizedHeight()
	if localFinalized == 0 && n.Blockchain != nil {
		localFinalized = n.Blockchain.FinalizedHeight()
		if localFinalized == 0 {
			localFinalized = n.Blockchain.Height()
		}
	}
	if localFinalized < updateHeight {
		return false, 0, 0, requiredMatches
	}

	// `window` stores the value produced by this operation.
	window := transitionBarrierCheckpointInterval()
	if window == 0 {
		window = 32
	}
	// `signedCounts` stores finalized quorum witness counts for validator-set
	// transition safety. Do not use proposer-only activity evidence here.
	signedCounts := n.recentFinalitySignerCountFromFinalizedChain(updateHeight, window)
	// `registrySnapshot` stores the value produced by this operation.
	registrySnapshot := n.validatorRegistrySnapshotForHeight(updateHeight)

	// `currentSet` stores the value produced by this operation.
	currentSet := make(map[string]struct{}, len(current))
	// `reportSeen` stores the value produced by this operation.
	reportSeen := make(map[string]struct{}, len(current))
	// `reports` stores the value produced by this operation.
	reports := 0
	// `raw` tracks the current values while iterating.
	for _, raw := range current {
		// `id` stores the current position in the related collection.
		id := normalizeValidatorID(raw)
		if id == "" {
			continue
		}
		currentSet[id] = struct{}{}
		// `ok` stores whether the related condition is satisfied.
		if _, ok := reportSeen[id]; ok {
			continue
		}
		reportSeen[id] = struct{}{}
		if signedCounts[id] > 0 {
			reports++
		}
	}

	// `matchSeen` stores the value produced by this operation.
	matchSeen := make(map[string]struct{}, len(next))
	// `matches` stores the value produced by this operation.
	matches := 0
	// `raw` tracks the current values while iterating.
	for _, raw := range next {
		// `id` stores the current position in the related collection.
		id := normalizeValidatorID(raw)
		if id == "" {
			continue
		}
		// `ok` stores whether the related condition is satisfied.
		if _, ok := matchSeen[id]; ok {
			continue
		}
		matchSeen[id] = struct{}{}
		// `inCurrent` stores the current position in the related collection.
		if _, inCurrent := currentSet[id]; inCurrent {
			if signedCounts[id] > 0 {
				matches++
			}
			continue
		}
		// New entrants are evaluated from deterministic on-chain registry state only.
		if validatorPassesReentrySnapshotChecks(id, updateHeight, registrySnapshot) {
			matches++
		}
	}

	if reports >= requiredReports && matches >= requiredMatches {
		return true, matches, reports, requiredMatches
	}
	return false, matches, reports, requiredMatches
}

// plannedValidatorSetForHeightFromChain implements the planned validator set for height from chain helper.
func (n *Node) plannedValidatorSetForHeightFromChain(height uint64) []string {
	if n == nil || height == 0 || height == 1 {
		return nil
	}
	// `snapshot` and `ok` store whether the related condition is satisfied.
	snapshot, _, ok := n.committedParentProjectionSnapshot(height)
	if !ok || snapshot == nil {
		return nil
	}
	// `current` stores the value produced by this operation.
	current := []string(nil)
	if validatorEpochSetV1EnabledAt(height) {
		current = validatorsFromSnapshot(snapshot)
	} else {
		current = activeRegistrySmallValidatorSetFromSnapshot(height, snapshot.ValidatorRegistry, true)
		if len(current) == 0 {
			current = validatorsFromSnapshot(snapshot)
		}
	}
	if len(current) == 0 {
		return nil
	}
	// `set` stores the value produced by this operation.
	set := make(map[string]struct{}, len(current))
	// `id` tracks the current position in the related collection.
	for _, id := range current {
		// `norm` stores the value produced by this operation.
		norm := strings.TrimSpace(strings.ToUpper(id))
		if norm == "" {
			continue
		}
		set[norm] = struct{}{}
	}
	// `id` and `act` track the current position in the related collection.
	for id, act := range snapshot.PendingValidators {
		if !validatorSetTransitionVisibleInChildSetAt(act, height) {
			continue
		}
		// `norm` stores the value produced by this operation.
		norm := strings.TrimSpace(strings.ToUpper(id))
		if norm == "" {
			continue
		}
		set[norm] = struct{}{}
	}
	// `id` and `act` track the current position in the related collection.
	for id, act := range snapshot.PendingValidatorRemovals {
		if !validatorSetTransitionVisibleInChildSetAt(act, height) {
			continue
		}
		// `norm` stores the value produced by this operation.
		norm := strings.TrimSpace(strings.ToUpper(id))
		if norm == "" {
			continue
		}
		delete(set, norm)
	}
	// `next` stores the value produced by this operation.
	next := make([]string, 0, len(set))
	// `id` tracks the current position in the related collection.
	for id := range set {
		next = append(next, id)
	}
	if validatorEpochSetV1EnabledAt(height) {
		return selectEpochActiveValidatorSet(height, current, snapshot.ValidatorRegistry)
	}
	return canonicalValidatorIDs(next)
}

// plannedValidatorSetForHeight implements the planned validator set for height helper.
func (n *Node) plannedValidatorSetForHeight(height uint64) []string {
	if n == nil || height == 0 {
		return nil
	}
	if height > 1 && validatorSetCommitmentV2EnabledAt(height-1) {
		// `planned` stores the value produced by this operation.
		if planned := n.plannedValidatorSetForHeightFromChain(height); len(planned) > 0 {
			return canonicalValidatorIDs(planned)
		}
		return canonicalValidatorIDs(n.GetConsensusValidators(int(height)))
	}
	// `targetFinalized` stores the value produced by this operation.
	targetFinalized := uint64(0)
	if height > 0 {
		targetFinalized = height - 1
	}

	n.validatorSetMu.RLock()
	// `pendingAdds` stores the value produced by this operation.
	pendingAdds := make(map[string]uint64, len(n.pendingValidators))
	// `id` and `act` track the current position in the related collection.
	for id, act := range n.pendingValidators {
		pendingAdds[id] = act
	}
	// `pendingRemovals` stores the value produced by this operation.
	pendingRemovals := make(map[string]uint64, len(n.pendingValidatorRemovals))
	// `id` and `act` track the current position in the related collection.
	for id, act := range n.pendingValidatorRemovals {
		pendingRemovals[id] = act
	}
	n.validatorSetMu.RUnlock()

	// `current` stores the value produced by this operation.
	current := n.plannedValidatorSetForHeightFromChain(height)
	if len(current) == 0 {
		current = append([]string{}, n.GetConsensusValidators(int(height))...)
	}
	if len(current) == 0 {
		return nil
	}

	// `set` stores the value produced by this operation.
	set := make(map[string]struct{}, len(current))
	// `id` tracks the current position in the related collection.
	for _, id := range current {
		// `norm` stores the value produced by this operation.
		norm := strings.TrimSpace(strings.ToUpper(id))
		if norm == "" {
			continue
		}
		set[norm] = struct{}{}
	}

	// `id` and `act` track the current position in the related collection.
	for id, act := range pendingAdds {
		// `effectiveActivation` stores the value produced by this operation.
		effectiveActivation := effectiveValidatorSetActivationHeightAt(act, height)
		if effectiveActivation == 0 || effectiveActivation > targetFinalized {
			continue
		}
		// `norm` stores the value produced by this operation.
		norm := strings.TrimSpace(strings.ToUpper(id))
		if norm == "" {
			continue
		}
		// `ok` stores whether the related condition is satisfied.
		if _, ok := set[norm]; ok {
			continue
		}
		set[norm] = struct{}{}
		current = append(current, norm)
	}

	if len(pendingRemovals) > 0 {
		// `rem` stores the value produced by this operation.
		rem := make(map[string]struct{})
		// `id` and `act` track the current position in the related collection.
		for id, act := range pendingRemovals {
			// `effectiveActivation` stores the value produced by this operation.
			effectiveActivation := effectiveValidatorSetActivationHeightAt(act, height)
			if effectiveActivation == 0 || effectiveActivation > targetFinalized {
				continue
			}
			// `norm` stores the value produced by this operation.
			norm := strings.TrimSpace(strings.ToUpper(id))
			if norm == "" {
				continue
			}
			rem[norm] = struct{}{}
		}
		if len(rem) > 0 {
			// `next` stores the value produced by this operation.
			next := make([]string, 0, len(current))
			// `id` tracks the current position in the related collection.
			for _, id := range current {
				// `norm` stores the value produced by this operation.
				norm := strings.TrimSpace(strings.ToUpper(id))
				if norm == "" {
					continue
				}
				// `drop` stores the value produced by this operation.
				if _, drop := rem[norm]; drop {
					continue
				}
				next = append(next, norm)
			}
			if len(next) > 0 {
				current = next
			}
		}
	}

	return canonicalValidatorIDs(current)
}

// pendingValidatorRemovalsSnapshot implements the pending validator removals snapshot helper.
func (n *Node) pendingValidatorRemovalsSnapshot() map[string]uint64 {
	if n == nil {
		return nil
	}
	n.validatorSetMu.RLock()
	defer n.validatorSetMu.RUnlock()
	if len(n.pendingValidatorRemovals) == 0 {
		return nil
	}
	// `out` stores the result produced by this operation.
	out := make(map[string]uint64, len(n.pendingValidatorRemovals))
	// `id` and `act` track the current position in the related collection.
	for id, act := range n.pendingValidatorRemovals {
		// `norm` stores the value produced by this operation.
		norm := normalizeValidatorID(id)
		if norm == "" || act == 0 {
			continue
		}
		// `existing` and `ok` store whether the related condition is satisfied.
		if existing, ok := out[norm]; !ok || act < existing {
			out[norm] = act
		}
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// scheduledTransitionValidatorsLocked resolves the baseline validator set for
// post-commit transition bookkeeping while validatorSetMu is already held.
// It must not call helpers that re-enter validatorSetMu.
func (n *Node) scheduledTransitionValidatorsLocked(height uint64) []string {
	if n == nil || height == 0 {
		return nil
	}
	// `planned` stores the value produced by this operation.
	if planned := n.plannedValidatorSetForHeightFromChain(height); len(planned) > 0 {
		return canonicalValidatorIDs(planned)
	}
	if n.Blockchain != nil {
		// `block` and `ok` store whether the related condition is satisfied.
		if block, ok := n.Blockchain.GetBlock(height); ok {
			// `committed` and `ok` store whether the related condition is satisfied.
			if committed, ok := n.blockValidatorSetFromSignaturesLocked(block); ok && len(committed) > 0 {
				return canonicalValidatorIDs(committed)
			}
		}
		if height > 1 {
			// `parent` and `ok` store whether the related condition is satisfied.
			if parent, ok := n.Blockchain.GetBlock(height - 1); ok {
				// `committed` and `ok` store whether the related condition is satisfied.
				if committed, ok := n.blockValidatorSetFromSignaturesLocked(parent); ok && len(committed) > 0 {
					return canonicalValidatorIDs(committed)
				}
			}
		}
		if n.Blockchain.Height() == 0 && len(n.GenesisValidators) > 0 {
			return canonicalValidatorIDs(append([]string{}, n.GenesisValidators...))
		}
	}
	if n.epochValidators != nil {
		// `validators` stores whether the related condition is satisfied.
		if validators := n.epochValidators[height]; len(validators) > 0 {
			return canonicalValidatorIDs(append([]string{}, validators...))
		}
	}
	if height > 1 && n.frozenValidatorsByHeight != nil {
		// `validators` stores whether the related condition is satisfied.
		if validators := n.frozenValidatorsByHeight[height-1]; len(validators) > 0 {
			return canonicalValidatorIDs(append([]string{}, validators...))
		}
	}
	return nil
}

// applyScheduledValidatorUpdates activates pending validator changes after the configured delay.

// Call this after a block is finalized, passing the current finalized height.

// applyScheduledValidatorUpdates applies scheduled validator updates.
func (n *Node) applyScheduledValidatorUpdates(currentHeight uint64) {
	if currentHeight == 0 {
		return
	}

	// `traceStage` and `traceProvider` store the value produced by this operation.
	traceStage, traceProvider := n.syncDiagnosticContext()
	// `updateHeight` stores the value produced by this operation.
	updateHeight := currentHeight
	var (
		// `updated` stores the value used by this operation.
		updated bool
		// `plannedOnly` stores the value used by this operation.
		plannedOnly bool
		// `updateBlocked` stores the value used by this operation.
		updateBlocked bool
		// `updateList` stores the value used by this operation.
		updateList []string
		// `processedAdds` stores the value used by this operation.
		processedAdds []string
		// `processedRemove` stores the value used by this operation.
		processedRemove []string
		// `syncDeferredIDs` stores the value used by this operation.
		syncDeferredIDs []string
		// `retryClear` stores the value used by this operation.
		retryClear []transitionBarrierRetryKey
		// `nextTransitionHeight` stores the value used by this operation.
		nextTransitionHeight uint64
		// `dueTransition` stores the value used by this operation.
		dueTransition bool
		// `deferForSync` stores the value used by this operation.
		deferForSync bool
		// `transitionValidators` stores the value used by this operation.
		transitionValidators []string
		// `nextValidators` stores the value used by this operation.
		nextValidators []string
	)
	// `logStep` stores the value produced by this operation.
	logStep := func(step string) {
		logScheduledUpdateTrace(traceStage, traceProvider, scheduledUpdateTraceState{
			CurrentHeight:        currentHeight,
			UpdateHeight:         updateHeight,
			Step:                 step,
			DueTransition:        dueTransition,
			DeferForSync:         deferForSync,
			UpdateBlocked:        updateBlocked,
			PlannedOnly:          plannedOnly,
			Updated:              updated,
			ProcessedAdds:        len(processedAdds),
			ProcessedRemoves:     len(processedRemove),
			NextTransitionHeight: nextTransitionHeight,
			TransitionValidators: len(transitionValidators),
			NextValidators:       len(nextValidators),
		})
	}

	logStep("queue_inactive_removals_begin")
	// Deterministic mode: derive inactivity removals from finalized blocks only.
	n.queueDeterministicInactiveRemovals(currentHeight)
	logStep("queue_inactive_removals_done")

	logStep("sync_gate_snapshot_state_begin")
	// `syncingNow` stores the value produced by this operation.
	syncingNow := n.nodeSyncingForActivationGate()
	// `snapshotSyncLocked` stores the value produced by this operation.
	snapshotSyncLocked := n.snapshotSessionActive()
	logStep("sync_gate_snapshot_state_done")

	logStep("apply_queued_set_update_begin")
	if n.applyQueuedValidatorSetUpdate(updateHeight) {
		logStep("apply_queued_set_update_done")
		n.clearPendingValidatorUpdatesUpTo(currentHeight)
		logStep("snapshot_epoch_validators_begin")
		n.snapshotEpochValidators(currentHeight + 1)
		logStep("snapshot_epoch_validators_done")
		return
	}
	logStep("apply_queued_set_update_done")

	logStep("validator_set_lock_begin")
	n.validatorSetMu.Lock()
	logStep("validator_set_lock_acquired")
	if n.pendingValidators == nil {
		n.pendingValidators = make(map[string]uint64)
	}
	if n.pendingValidatorRemovals == nil {
		n.pendingValidatorRemovals = make(map[string]uint64)
	}

	logStep("compute_next_transition_height_begin")
	// `act` tracks the current values while iterating.
	for _, act := range n.pendingValidators {
		// `effectiveActivation` stores the value produced by this operation.
		effectiveActivation := validatorSetTransitionActivationHeightAt(act, currentHeight)
		if effectiveActivation == 0 {
			continue
		}
		if nextTransitionHeight == 0 || effectiveActivation < nextTransitionHeight {
			nextTransitionHeight = effectiveActivation
		}
	}
	// `act` tracks the current values while iterating.
	for _, act := range n.pendingValidatorRemovals {
		// `effectiveActivation` stores the value produced by this operation.
		effectiveActivation := validatorSetTransitionActivationHeightAt(act, currentHeight)
		if effectiveActivation == 0 {
			continue
		}
		if nextTransitionHeight == 0 || effectiveActivation < nextTransitionHeight {
			nextTransitionHeight = effectiveActivation
		}
	}
	if nextTransitionHeight > 0 && nextTransitionHeight <= currentHeight {
		// Strict parent->child commitment mode reconciles against the current
		// finalized height once a committed transition is due. Legacy mode keeps
		// the earlier deterministic transition boundary.
		if validatorSetCommitmentV2EnabledAt(currentHeight - 1) {
			updateHeight = currentHeight
		} else {
			updateHeight = nextTransitionHeight
		}
	}
	if !snapshotSyncLocked &&
		(nextTransitionHeight == 0 || nextTransitionHeight > currentHeight) &&
		n.transitionPlan.Active &&
		n.transitionPlan.UpdateHeight <= currentHeight {
		n.clearTransitionPlanLocked()
	}
	logStep("compute_next_transition_height_done")

	logStep("due_transition_eval_begin")
	dueTransition = nextTransitionHeight > 0 && nextTransitionHeight <= currentHeight
	if !dueTransition && n.transitionPlan.Active && n.transitionPlan.UpdateHeight > 0 && n.transitionPlan.UpdateHeight <= currentHeight {
		dueTransition = true
		updateHeight = n.transitionPlan.UpdateHeight
	}
	logStep("due_transition_eval_done")

	logStep("defer_for_sync_eval_begin")
	deferForSync = dueTransition && syncingNow
	if snapshotSyncLocked && dueTransition {
		deferForSync = true
		updateBlocked = true
		// `id` tracks the current position in the related collection.
		for id := range n.pendingValidators {
			// `norm` stores the value produced by this operation.
			norm := normalizeValidatorID(id)
			if norm == "" {
				continue
			}
			syncDeferredIDs = append(syncDeferredIDs, norm)
		}
		if len(syncDeferredIDs) == 0 && n.transitionPlan.Active && n.transitionPlan.UpdateHeight == updateHeight {
			// `id` tracks the current position in the related collection.
			for _, id := range n.transitionPlan.ProcessedAdds {
				// `norm` stores the value produced by this operation.
				norm := normalizeValidatorID(id)
				if norm == "" {
					continue
				}
				syncDeferredIDs = append(syncDeferredIDs, norm)
			}
		}
		if DebugConsensus {
			fmt.Printf("[SET-BARRIER] deferred reason=snapshot_session_active height=%d\n", updateHeight)
		}
	}
	if deferForSync && !updateBlocked {
		updateBlocked = true
		// `id` tracks the current position in the related collection.
		for id := range n.pendingValidators {
			// `norm` stores the value produced by this operation.
			norm := normalizeValidatorID(id)
			if norm == "" {
				continue
			}
			syncDeferredIDs = append(syncDeferredIDs, norm)
		}
		if DebugConsensus {
			fmt.Printf("[SET-BARRIER] deferred reason=sync_incomplete height=%d\n", updateHeight)
		}
	}
	logStep("defer_for_sync_eval_done")

	logStep("scheduled_transition_validators_begin")
	if !deferForSync {
		transitionValidators = n.scheduledTransitionValidatorsLocked(updateHeight)
		if len(transitionValidators) == 0 && n.epochValidators != nil {
			transitionValidators = append([]string{}, n.epochValidators[updateHeight]...)
		}
		if len(transitionValidators) == 0 && updateHeight > 1 && n.frozenValidatorsByHeight != nil {
			transitionValidators = append([]string{}, n.frozenValidatorsByHeight[updateHeight-1]...)
		}
		if len(transitionValidators) == 0 && n.Blockchain != nil && n.Blockchain.Height() == 0 {
			transitionValidators = append([]string{}, n.GenesisValidators...)
		}
		transitionValidators = canonicalValidatorIDs(transitionValidators)
	}
	logStep("scheduled_transition_validators_done")

	logStep("build_next_validators_begin")
	// `usePlannedSet` stores the value produced by this operation.
	usePlannedSet := false
	if !deferForSync {
		nextValidators = make([]string, 0, len(transitionValidators))

		if n.transitionPlan.Active && n.transitionPlan.UpdateHeight == updateHeight && len(n.transitionPlan.NextValidators) > 0 {
			nextValidators = canonicalValidatorIDs(append([]string{}, n.transitionPlan.NextValidators...))
			processedAdds = canonicalValidatorIDs(append([]string{}, n.transitionPlan.ProcessedAdds...))
			processedRemove = canonicalValidatorIDs(append([]string{}, n.transitionPlan.ProcessedRemoves...))
			updated = true
			usePlannedSet = true
		} else {
			// `currentSet` stores the value produced by this operation.
			currentSet := make(map[string]struct{}, len(transitionValidators))
			// `id` tracks the current position in the related collection.
			for _, id := range transitionValidators {
				currentSet[id] = struct{}{}
			}
			nextValidators = append(nextValidators, transitionValidators...)

			// `id` and `act` track the current position in the related collection.
			for id, act := range n.pendingValidators {
				// `effectiveActivation` stores the value produced by this operation.
				effectiveActivation := validatorSetTransitionActivationHeightAt(act, updateHeight)
				if effectiveActivation == 0 || effectiveActivation > updateHeight {
					continue
				}
				id = normalizeValidatorID(id)
				if id == "" {
					continue
				}

				// `exists` stores whether the related condition is satisfied.
				if _, exists := currentSet[id]; !exists {
					if protocolDeterministicValidatorSelectionEnabled() {
						// Deterministic mode: activation is chain-scheduled at commit time.
						// Do not apply local runtime eligibility checks here.
						nextValidators = append(nextValidators, id)
						currentSet[id] = struct{}{}
						updated = true
					} else if IsValidatorEligible(id, int(currentHeight)) {
						nextValidators = append(nextValidators, id)
						currentSet[id] = struct{}{}
						updated = true
					}
				}
				processedAdds = append(processedAdds, id)
			}

			if len(n.pendingValidatorRemovals) > 0 {
				// `removeSet` stores the value produced by this operation.
				removeSet := make(map[string]struct{})
				// `id` and `act` track the current position in the related collection.
				for id, act := range n.pendingValidatorRemovals {
					// `effectiveActivation` stores the value produced by this operation.
					effectiveActivation := validatorSetTransitionActivationHeightAt(act, updateHeight)
					if effectiveActivation > 0 && effectiveActivation <= updateHeight {
						// `norm` stores the value produced by this operation.
						norm := normalizeValidatorID(id)
						if norm == "" {
							continue
						}
						removeSet[norm] = struct{}{}
					}
				}
				if len(removeSet) > 0 {
					// `remain` stores the value produced by this operation.
					remain := make([]string, 0, len(nextValidators))
					// `id` tracks the current position in the related collection.
					for _, id := range nextValidators {
						id = normalizeValidatorID(id)
						if id == "" {
							continue
						}
						// `remove` stores the value produced by this operation.
						if _, remove := removeSet[id]; remove {
							continue
						}
						remain = append(remain, id)
					}

					// Never allow validator set below configured safety floor.
					if len(remain) < minActiveValidatorsFloor() {
						if DebugConsensus {
							fmt.Printf("?? Skipping validator removals: would reduce active validators below minimum (%d < %d)\n",
								len(remain), minActiveValidatorsFloor())
						}
					} else {
						nextValidators = remain
						// `id` tracks the current position in the related collection.
						for id := range removeSet {
							processedRemove = append(processedRemove, id)
						}
						updated = true
					}
				}
			}
		}
		nextValidators = canonicalValidatorIDs(nextValidators)
		// Due adds/removals can collapse to the same effective set
		// (for example, removing a validator that is already absent).
		// Treat those transitions as no-ops so we skip the heavier barrier
		// and broadcast pipeline while still clearing the due pending entries.
		if updated && sameStringSlice(nextValidators, transitionValidators) {
			postForkChainMode := updateHeight > 0 && validatorSetCommitmentV2EnabledAt(updateHeight-1)
			frozenCurrent := canonicalValidatorIDs(n.frozenValidatorsByHeight[updateHeight])
			if !postForkChainMode || len(frozenCurrent) == 0 || sameStringSlice(frozenCurrent, nextValidators) {
				updated = false
			}
		}
	}
	logStep("build_next_validators_done")

	logStep("transition_quorum_begin")
	if !deferForSync && updated {
		nextValidators = canonicalValidatorIDs(nextValidators)
		processedAdds = canonicalValidatorIDs(processedAdds)
		processedRemove = canonicalValidatorIDs(processedRemove)
		// `postForkChainMode` stores the value produced by this operation.
		postForkChainMode := updateHeight > 0 && validatorSetCommitmentV2EnabledAt(updateHeight-1)
		if protocolDeterministicValidatorSelectionEnabled() {
			// `nextHash` stores the digest used to identify or verify the related data.
			nextHash := n.validatorSetHashFromFinalizedSnapshot(updateHeight, nextValidators)
			if strings.TrimSpace(nextHash) == "" {
				nextHash = ValidatorSetHash(nextValidators)
			}
			if !usePlannedSet {
				n.transitionPlan = validatorSetTransitionPlan{
					Active:           true,
					UpdateHeight:     updateHeight,
					NextSetHash:      nextHash,
					NextValidators:   append([]string{}, nextValidators...),
					ProcessedAdds:    append([]string{}, processedAdds...),
					ProcessedRemoves: append([]string{}, processedRemove...),
					LockedAt:         time.Now(),
				}
			} else if n.transitionPlan.Active && n.transitionPlan.UpdateHeight == updateHeight {
				if len(n.transitionPlan.NextValidators) > 0 {
					nextValidators = canonicalValidatorIDs(append([]string{}, n.transitionPlan.NextValidators...))
				}
				if strings.TrimSpace(n.transitionPlan.NextSetHash) != "" {
					nextHash = strings.TrimSpace(n.transitionPlan.NextSetHash)
				}
				if len(n.transitionPlan.ProcessedAdds) > 0 {
					processedAdds = canonicalValidatorIDs(append([]string{}, n.transitionPlan.ProcessedAdds...))
				}
				if len(n.transitionPlan.ProcessedRemoves) > 0 {
					processedRemove = canonicalValidatorIDs(append([]string{}, n.transitionPlan.ProcessedRemoves...))
				}
			}

			if !postForkChainMode {
				// `interval` stores the value currently being processed.
				interval := transitionBarrierCheckpointInterval()
				if interval > 1 && updateHeight%interval != 0 {
					updateBlocked = true
					updated = false
					if DebugConsensus {
						fmt.Printf("[SET-BARRIER] deferred reason=checkpoint_boundary_pending height=%d interval=%d\n", updateHeight, interval)
					}
				}
			}

			// `safeModeActive` stores the value produced by this operation.
			safeModeActive := false
			if !updateBlocked && ConsensusPostBlockSafeModeEnabled {
				// `gateArmed` stores the value produced by this operation.
				gateArmed := n.postBlockSafeModeGateActiveForHeight(updateHeight)
				// `until` stores the value produced by this operation.
				until := time.Time{}
				if n.safeModeUntilByHeight != nil {
					until = n.safeModeUntilByHeight[updateHeight]
				}
				if until.IsZero() {
					safeModeActive = gateArmed
				} else {
					safeModeActive = !time.Now().After(until)
				}
			}
			if safeModeActive {
				updateBlocked = true
				updated = false
				if DebugConsensus {
					fmt.Printf("[SET-BARRIER] deferred reason=safe_mode_active height=%d\n", updateHeight)
				}
			} else if !updateBlocked {
				// `ok`, `matches`, `reports`, and `required` store whether the related condition is satisfied.
				ok, matches, reports, required := n.validatorSetTransitionQuorum(updateHeight, transitionValidators, nextValidators)
				if n.transitionPlan.Active && n.transitionPlan.UpdateHeight == updateHeight {
					n.transitionPlan.Matches = matches
					n.transitionPlan.Reports = reports
					n.transitionPlan.Required = required
				}
				if !ok {
					updateBlocked = true
					updated = false
					// `shouldAttempt`, `tupleChanged`, and `nextRetryHeight` store the value produced by this operation.
					shouldAttempt, tupleChanged, nextRetryHeight := n.shouldAttemptTransitionBarrierRetry(
						"validator_set_transition_barrier",
						updateHeight,
						currentHeight,
						nextHash,
						matches,
						reports,
						required,
					)
					if shouldAttempt {
						// `shouldPause` stores the value produced by this operation.
						shouldPause := n.shouldRequestTransitionBarrierPause(
							"validator_set_transition_barrier",
							updateHeight,
							nextHash,
							matches,
							reports,
							required,
						)
						if DebugConsensus {
							// `trigger` stores the value produced by this operation.
							trigger := normalizeTransitionBarrierRetryMode(TransitionBarrierRetryMode)
							if tupleChanged {
								trigger = "tuple_change"
							} else if trigger == transitionBarrierRetryModeHybrid {
								trigger = "boundary"
							}
							fmt.Printf("[SET-BARRIER] retry_fail height=%d hash=%s matches=%d reports=%d required=%d trigger=%s next_retry=%d pause=%t validators=%d\n",
								updateHeight, ShortHash(nextHash), matches, reports, required, trigger, nextRetryHeight, shouldPause, len(nextValidators))
						}
						if shouldPause {
							n.requestConsensusRecomputePause(updateHeight, "validator_set_transition_barrier")
						}
					}
				} else {
					retryClear = append(retryClear, transitionBarrierRetryStateKey("validator_set_transition_barrier", updateHeight, nextHash))
				}
			}
		}
	}
	logStep("transition_quorum_done")

	logStep("transition_plan_write_begin")
	if !deferForSync && updated {
		// `postForkChainMode` stores the value produced by this operation.
		postForkChainMode := updateHeight > 0 && validatorSetCommitmentV2EnabledAt(updateHeight-1)
		if protocolDeterministicValidatorSelectionEnabled() && postForkChainMode {
			plannedOnly = true
			updateList = append([]string{}, nextValidators...)
			if n.epochValidators == nil {
				n.epochValidators = make(map[uint64][]string)
			}
			if n.frozenValidatorsByHeight == nil {
				n.frozenValidatorsByHeight = make(map[uint64][]string)
			}
			if n.frozenValidatorHashByHeight == nil {
				n.frozenValidatorHashByHeight = make(map[uint64]string)
			}
			// `nextHash` stores the digest used to identify or verify the related data.
			nextHash := n.validatorSetHashFromFinalizedSnapshot(updateHeight, nextValidators)
			if strings.TrimSpace(nextHash) == "" {
				nextHash = ValidatorSetHash(nextValidators)
			}
			n.epochValidators[updateHeight] = append([]string{}, nextValidators...)
			n.frozenValidatorsByHeight[updateHeight] = append([]string{}, nextValidators...)
			n.frozenValidatorHashByHeight[updateHeight] = nextHash
		} else {
			// Legacy cache-only write; consensus authority is chain/snapshot commitments.
			n.currentValidators = append([]string{}, nextValidators...)
			n.validatorSetHeight = updateHeight
			updateList = append([]string{}, nextValidators...)
			n.clearTransitionPlanLocked()
		}
	}
	logStep("transition_plan_write_done")

	logStep("finalize_pending_maps_begin")
	if !updateBlocked && !plannedOnly {
		// `deleteActivationKey` stores the key used to access the related value.
		deleteActivationKey := func(m map[string]uint64, want string) {
			// `key` tracks the key used to access the related value.
			for key := range m {
				if normalizeValidatorID(key) == want {
					delete(m, key)
				}
			}
		}
		// `id` tracks the current position in the related collection.
		for _, id := range processedAdds {
			deleteActivationKey(n.pendingValidators, id)
		}
		// `id` tracks the current position in the related collection.
		for _, id := range processedRemove {
			deleteActivationKey(n.pendingValidatorRemovals, id)
		}
	}
	logStep("finalize_pending_maps_done")

	logStep("active_transition_heights_begin")
	// `activeTransitionHeights` stores the value produced by this operation.
	activeTransitionHeights := make(map[uint64]struct{})
	// `act` tracks the current values while iterating.
	for _, act := range n.pendingValidators {
		// `effectiveActivation` stores the value produced by this operation.
		effectiveActivation := validatorSetTransitionActivationHeightAt(act, currentHeight)
		if effectiveActivation == 0 {
			continue
		}
		activeTransitionHeights[effectiveActivation] = struct{}{}
	}
	// `act` tracks the current values while iterating.
	for _, act := range n.pendingValidatorRemovals {
		// `effectiveActivation` stores the value produced by this operation.
		effectiveActivation := validatorSetTransitionActivationHeightAt(act, currentHeight)
		if effectiveActivation == 0 {
			continue
		}
		activeTransitionHeights[effectiveActivation] = struct{}{}
	}
	if n.transitionPlan.Active && !snapshotSyncLocked {
		// `ok` stores whether the related condition is satisfied.
		if len(activeTransitionHeights) == 0 {
			n.clearTransitionPlanLocked()
		} else if _, ok := activeTransitionHeights[n.transitionPlan.UpdateHeight]; !ok && n.transitionPlan.UpdateHeight <= currentHeight {
			n.clearTransitionPlanLocked()
		}
	}
	logStep("active_transition_heights_done")

	n.validatorSetMu.Unlock()
	logStep("validator_set_unlock")

	logStep("retry_clear_begin")
	// `key` tracks the key used to access the related value.
	for _, key := range retryClear {
		n.clearTransitionBarrierRetry(key.Reason, key.UpdateHeight, key.NextSetHash)
	}
	logStep("retry_clear_done")
	logStep("prune_retry_begin")
	n.pruneTransitionBarrierRetry(activeTransitionHeights)
	logStep("prune_retry_done")
	logStep("onboarding_tracker_begin")
	if deferForSync {
		// `deferReason` stores the value produced by this operation.
		deferReason := "sync_incomplete"
		if snapshotSyncLocked {
			deferReason = "snapshot_session_active"
		}
		// `id` tracks the current position in the related collection.
		for _, id := range syncDeferredIDs {
			n.upsertOnboardingTracker(id, OnboardingStateAwaitingSync, deferReason, updateHeight)
		}
	} else if updated && !plannedOnly {
		// `id` tracks the current position in the related collection.
		for _, id := range processedAdds {
			n.upsertOnboardingTracker(id, OnboardingStateActive, "active", updateHeight)
		}
	} else if plannedOnly {
		// `id` tracks the current position in the related collection.
		for _, id := range processedAdds {
			n.upsertOnboardingTracker(id, OnboardingStateActivating, "planned_chain_commitment", updateHeight)
		}
	} else if updateBlocked {
		// `id` tracks the current position in the related collection.
		for _, id := range processedAdds {
			n.upsertOnboardingTracker(id, OnboardingStateActivating, "transition_barrier_pending", updateHeight)
		}
	}
	logStep("onboarding_tracker_done")

	logStep("broadcast_validator_info_begin")
	if updated || updateBlocked {
		n.requestHeartbeatBroadcast(true)
	}
	logStep("broadcast_validator_info_done")

	logStep("final_update_log_begin")
	if updated {
		// `updateHash` stores the digest used to identify or verify the related data.
		updateHash := n.validatorSetHashFromFinalizedSnapshot(updateHeight, updateList)
		if strings.TrimSpace(updateHash) == "" {
			updateHash = ValidatorSetHash(updateList)
		}
		if plannedOnly {
			fmt.Printf("[SET-PLAN] height=%d hash=%s validators=%d source=chain_commitment\n",
				updateHeight,
				ShortHash(updateHash),
				len(updateList),
			)
		} else {
			// `logHash` stores the digest used to identify or verify the related data.
			logHash := updateHash
			if len(logHash) > 8 {
				logHash = logHash[:8]
			}
			fmt.Printf("? Validator set updated: height=%d hash=%s validators=%d\n",
				updateHeight,
				logHash,
				len(updateList),
			)
			n.requestConsensusRecomputePause(updateHeight, "validator_set_update")
			go n.broadcastValidatorSetUpdate(updateHeight, updateList)
		}
	}
	logStep("final_update_log_done")

	// Always snapshot for the next block height so consensus uses a frozen list.
	logStep("snapshot_epoch_validators_begin")
	n.snapshotEpochValidators(currentHeight + 1)
	logStep("snapshot_epoch_validators_done")
}

// broadcastValidatorSetUpdate implements the broadcast validator set update helper.
func (n *Node) broadcastValidatorSetUpdate(height uint64, validators []string) {

	if n.ValidatorTopic == nil || len(validators) == 0 {

		return

	}

	if protocolDeterministicValidatorSelectionEnabled() {

		return

	}

	sort.Strings(validators)

	// `hash` stores the digest used to identify or verify the related data.
	hash := ValidatorSetHash(validators)

	// `update` stores the value produced by this operation.
	update := ValidatorSetUpdate{

		From: n.ID,

		Height: height,

		Validators: validators,

		Hash: hash,
	}

	if GenesisHash != "" {

		update.GenesisHash = GenesisHash

	}

	// `msg` stores the value produced by this operation.
	msg := Message{

		Type: MsgValidatorSetUpdate,

		Data: MustJSON(update),
	}

	// `data` and `err` store the error produced by this operation.
	data, err := MarshalP2PMessage(msg)

	if err != nil {

		return

	}

	_ = n.ValidatorTopic.Publish(context.Background(), data)

}

// handleValidatorSetUpdate handles validator set update.
func (n *Node) handleValidatorSetUpdate(update ValidatorSetUpdate) {

	if protocolDeterministicValidatorSelectionEnabled() {

		return

	}

	if update.Height == 0 || len(update.Validators) == 0 {

		return

	}

	if update.From == "" {

		return

	}

	if GenesisHash != "" && update.GenesisHash != "" && update.GenesisHash != GenesisHash {

		return

	}

	if update.Hash != "" {

		// `hash` stores the digest used to identify or verify the related data.
		hash := ValidatorSetHash(update.Validators)

		if hash != update.Hash {

			return

		}

	}

	if protocolRequiresStrictConsensusSignatures() && !n.isValidatorInSetForHeight(update.From, update.Height) {

		return

	}

	n.commitMu.Lock()

	// `committed` stores the value produced by this operation.
	committed := n.committedHeight

	n.commitMu.Unlock()

	if update.Height > committed {

		n.validatorSetMu.Lock()

		if n.queuedValidatorSetUpdates == nil {

			n.queuedValidatorSetUpdates = make(map[uint64]ValidatorSetUpdate)

		}

		n.queuedValidatorSetUpdates[update.Height] = update

		n.validatorSetMu.Unlock()

		return

	}

	n.validatorSetMu.Lock()

	if update.Height < n.validatorSetHeight {

		n.validatorSetMu.Unlock()

		return

	}

	// `next` stores the value produced by this operation.
	next := append([]string{}, update.Validators...)

	sort.Strings(next)

	n.currentValidators = next

	n.validatorSetHeight = update.Height

	n.validatorSetMu.Unlock()

	fmt.Printf("Ã¢Å“â€¦ Validator set updated (gossip): height=%d hash=%s validators=%d\n",

		update.Height,

		ValidatorSetHash(next)[:8],

		len(next),
	)

	n.requestConsensusRecomputePause(update.Height, "validator_set_update_gossip")
	n.snapshotEpochValidators(update.Height + 1)

	n.clearPendingValidatorUpdatesUpTo(update.Height)

}

// GetConsensusLeaderFromList returns consensus leader from list.
func GetConsensusLeaderFromList(validators []string, height int) string {

	if len(validators) == 0 {

		return ""

	}

	if height < 0 {

		height = 0

	}

	return LeaderForHeight(uint64(height), validators)

}

// GetConsensusLeaderForRound returns consensus leader for round.
func GetConsensusLeaderForRound(validators []string, height int, round uint32) string {

	if len(validators) == 0 {

		return ""

	}

	if height < 0 {

		height = 0

	}

	return LeaderForHeight(uint64(height)+uint64(round), validators)

}

// ProcessBlock implements the process block helper.
func (n *Node) ProcessBlock(block Block, bc *Blockchain) error {

	// =====================================================

	// =====================================================

	blocksMu.Lock()

	defer blocksMu.Unlock()

	// `currentHeight` stores the value produced by this operation.
	currentHeight := bc.Height()

	// =====================================================

	// =====================================================

	if block.ID != uint64(currentHeight+1) {

		return errors.New("invalid_height")

	}

	// =====================================================

	// =====================================================

	executionLedger, _, ok := n.executionLedgerForBlock(block)

	if !ok {

		return errors.New("execution_snapshot_ledger_unavailable")

	}

	// =====================================================

	// =====================================================

	n.setExecutionLedger(executionLedger)

	bc.AddBlock(block)

	n.StoreBlock(block)
	n.Mempool.RemoveIncluded(block.Transactions)

	if DebugConsensus {

	}

	return nil

}

// applyPostBlockEffects applies post block effects.
func (n *Node) applyPostBlockEffects(block Block) Ledger {
	registry := n.validatorRegistrySnapshotForHeight(block.ID)
	return n.applyPostBlockEffectsWithRegistry(block, registry)
}

// applyPostBlockEffectsWithRegistry uses the validator view captured before
// block execution changes any runtime registry state.
func (n *Node) applyPostBlockEffectsWithRegistry(block Block, registry map[string]ValidatorRecord) Ledger {
	if n == nil {
		return Ledger{}.Clone()
	}
	base := n.committedExecutionLedgerForPostBlockEffects(block)
	// `ledger` stores the value produced by this operation.
	ledger, audit, err := n.applyPostBlockEffectsToLedgerWithRegistryChecked(block, base, registry)
	if err != nil {
		log.Printf("[SUPPLY-INVARIANT] rejecting post-block effects height=%d block=%s err=%v",
			block.ID,
			ShortHash(block.BlockHash),
			err,
		)
		return base.Clone()
	}
	n.setExecutionLedger(ledger)
	n.recordSupplyTransition(audit)

	n.Mempool.RemoveIncluded(block.Transactions)

	return ledger.Clone()
}

// applyPostBlockEffectsToLedger applies post block effects to ledger.
func (n *Node) applyPostBlockEffectsToLedger(block Block, base Ledger) Ledger {
	registry := n.validatorRegistrySnapshotForHeight(block.ID)
	return n.applyPostBlockEffectsToLedgerWithRegistry(block, base, registry)
}

// applyPostBlockEffectsToLedgerWithRegistry applies rewards using one explicit,
// immutable registry authority for the entire state transition.
func (n *Node) applyPostBlockEffectsToLedgerWithRegistry(
	block Block,
	base Ledger,
	registry map[string]ValidatorRecord,
) Ledger {
	ledger, _, err := n.applyPostBlockEffectsToLedgerWithRegistryChecked(block, base, registry)
	if err != nil {
		log.Printf("[SUPPLY-INVARIANT] post-block replay rejected height=%d block=%s err=%v",
			block.ID,
			ShortHash(block.BlockHash),
			err,
		)
		return base.Clone()
	}
	return ledger.Clone()
}

// applyPostBlockEffectsToLedgerWithRegistryChecked applies rewards and validates
// the explicit mint/burn transition before any caller persists the result.
func (n *Node) applyPostBlockEffectsToLedgerWithRegistryChecked(
	block Block,
	base Ledger,
	registry map[string]ValidatorRecord,
) (Ledger, SupplyTransitionAudit, error) {
	var audit SupplyTransitionAudit
	if n == nil {
		return base.Clone(), audit, nil
	}
	// `ledger` stores the value produced by this operation.
	ledger := base.Clone()
	change := SupplyChange{}

	// Quorum signer subsets are certificate evidence, not canonical chain
	// identity: honest nodes may observe different valid subsets for the same
	// finalized block. Reward the deterministic eligible set from the committed
	// registry snapshot instead of block.Signatures/ExecutionResults.
	validators := n.postBlockRewardValidators(block, registry)
	// Reward eligibility is evaluated against one explicit committed registry
	// view for the entire replay. It must never leak through process-global
	// mutable state into another concurrent block execution.
	rewardAuthority := newValidatorRewardAuthority(registry)
	if block.Type == BlockTypeWork || block.Type == BlockTypeTask ||
		(protocolUnifiedTeamRewardEnabledFlag() && block.Type == BlockTypeTime) {
		change.Add(distributeBlockRewardWithAuthority(
			&ledger,
			block,
			block.Proposer,
			validators,
			OWNER_ADDRESS,
			rewardAuthority,
		))
	}

	// Scheduled emission is independent from tx-fee reward and now applies to
	// both tx blocks and empty time blocks.
	if block.Type == BlockTypeWork || block.Type == BlockTypeTask || block.Type == BlockTypeTime {
		change.Add(distributeScheduledEmissionRewardWithAuthority(
			&ledger,
			block,
			validators,
			rewardAuthority,
		))
	}
	if repaired := applySupplyCapRepair(&ledger, block.ID); repaired > 0 {
		change.Burned += repaired
	}

	audit, err := validateSupplyTransition(block.ID, &base, &ledger, change)
	audit.BlockHash = strings.TrimSpace(block.BlockHash)
	if err != nil {
		return base.Clone(), audit, err
	}
	return ledger.Clone(), audit, nil
}

// postBlockRewardValidators implements the post block reward validators helper.
func (n *Node) postBlockRewardValidators(
	block Block,
	validatorRegistry map[string]ValidatorRecord,
) []string {
	_ = n
	return protocolRewardValidatorsFromRegistrySnapshot(block.ID, validatorRegistry)
}

// runPostBlockEffects implements the run post block effects helper.
func (n *Node) runPostBlockEffects(block Block, ledger Ledger) {
	if n == nil {
		return
	}

	n.RewardValidatorReputation(block.Proposer)

	// `committedHeight` stores the value produced by this operation.
	committedHeight := block.ID
	n.commitMu.Lock()
	if n.committedHeight > committedHeight {
		committedHeight = n.committedHeight
	}
	n.commitMu.Unlock()

	// Persist only the newest known committed ledger snapshot so older async
	// tasks cannot overwrite a newer ledger state on disk.
	if block.ID >= committedHeight {
		// `err` stores the error produced by this operation.
		if err := SaveNodeLedger(
			n.ID,
			n.DataDir,
			ledger.Clone(),
		); err != nil && DebugConsensus {
			log.Printf("[WARN] persist post-commit ledger failed height=%d err=%v", block.ID, err)
		}
	}

	if n.Consensus != nil {
		n.Consensus.Cleanup(committedHeight)
	}
}

// runPostBlockEffectsAsync implements the run post block effects async helper.
func (n *Node) runPostBlockEffectsAsync(block Block, ledger Ledger) {
	if n == nil {
		return
	}
	ledger = ledger.Clone()
	if !n.scheduleExecutionTask(func() {
		if n == nil {
			return
		}
		if n.shutdownCh != nil {
			select {
			case <-n.shutdownCh:
				return
			default:
			}
		}
		n.postCommitEffectsMu.Lock()
		defer n.postCommitEffectsMu.Unlock()
		n.runPostBlockEffects(block, ledger)
	}) {
		return
	}
}

// PostBlockEffects implements the post block effects helper.
func (n *Node) PostBlockEffects(block Block) {
	// `ledger` stores the value produced by this operation.
	ledger := n.applyPostBlockEffects(block)
	n.cachePostCommitLedger(block.ID, ledger)
	n.runPostBlockEffects(block, ledger)
}

// RemoveIncluded removes included.
func (m *Mempool) RemoveIncluded(included []Transaction) {

	if len(included) == 0 {

		return

	}

	m.mu.Lock()

	defer m.mu.Unlock()
	m.ensureIndexesLocked()

	// Build fast lookup set

	includedSet := make(map[string]struct{}, len(included))

	// `tx` tracks the transaction data handled by this operation.
	for _, tx := range included {

		includedSet[tx.ID] = struct{}{}

	}

	// Filter mempool

	filtered := m.Transactions[:0]

	// `tx` tracks the transaction data handled by this operation.
	for _, tx := range m.Transactions {

		// `found` stores whether the related condition is satisfied.
		if _, found := includedSet[tx.ID]; found {

			// `amount` stores the value produced by this operation.
			if amount := pendingSpendAmount(tx); amount > 0 {

				rollbackPendingSpend(normalizeCoin(tx.Coin), tx.From, amount)

			}

			continue

		}

		filtered = append(filtered, tx)

	}

	m.Transactions = filtered
	m.rebuildIndexesLocked()

}

// ApplyBlockState replays blocks that do not require node-specific committed
// validator authority. Consensus callers use ApplyBlockStateWithNode or pass an
// explicit committed registry to applyBlockStateWithValidatorRegistry.
func ApplyBlockState(

	ledger Ledger,

	block Block,

) (Ledger, error) {
	return applyBlockStateWithValidatorRegistry(ledger, block, map[string]ValidatorRecord{})
}

// applyBlockStateWithValidatorRegistry executes a block against an explicit
// validator-registry view. Consensus replay callers should provide the
// committed parent/snapshot registry instead of reading mutable runtime state.
func applyBlockStateWithValidatorRegistry(

	ledger Ledger,

	block Block,

	validatorRegistry map[string]ValidatorRecord,

) (Ledger, error) {
	validatorRegistry = copyValidatorRegistrySnapshot(validatorRegistry)

	// -------------------------------------------------

	// -------------------------------------------------

	newLedger := Ledger{

		Balances: make(map[string]int),

		Nonces: make(map[string]int),

		Stakes: make(map[string]StakeLock),

		ValidatorRewardWallets: make(map[string]string),

		DTL: cloneDTLState(ledger.DTL),
	}

	// `k` and `v` track the current values while iterating.
	for k, v := range ledger.Balances {

		newLedger.Balances[k] = v

	}

	// `k` and `v` track the current values while iterating.
	for k, v := range ledger.Nonces {

		newLedger.Nonces[k] = v

	}

	// `k` and `v` track the current values while iterating.
	for k, v := range ledger.Stakes {

		newLedger.Stakes[k] = v

	}

	// `k` and `v` track the current values while iterating.
	for k, v := range ledger.ValidatorRewardWallets {

		newLedger.ValidatorRewardWallets[k] = v

	}

	// -------------------------------------------------

	// -------------------------------------------------

	totalFees := make(map[string]int)

	// `tx` tracks the transaction data handled by this operation.
	for txIndex := 0; txIndex < len(block.Transactions); txIndex++ {
		if applied, err := tryApplyParallelDTLBatch(
			block,
			block.Transactions,
			txIndex,
			&newLedger,
			totalFees,
		); err != nil {
			return ledger, err
		} else if applied > 0 {
			txIndex += applied - 1
			continue
		}

		tx := block.Transactions[txIndex]
		normalizeIncomingTx(&tx)
		if err := validateRemovedVMEnvelope(tx); err != nil {
			return ledger, fmt.Errorf("%s: %s", err.Error(), tx.ID)
		}
		if !isProtocolChainID(tx.ChainID) {
			return ledger, fmt.Errorf("invalid chain id: %s", tx.ChainID)
		}

		// `coin` stores the value produced by this operation.
		coin := normalizeCoin(tx.Coin)

		if !isProtocolCoinAllowed(coin) {

			return ledger, fmt.Errorf("unsupported coin: %s", coin)

		}

		if tx.Type == TxValidatorUpdate {

			return ledger, fmt.Errorf("validator updates disabled: %s", tx.ID)

		}
		// `requiredFee` stores the request data being processed.
		requiredFee := requiredFeeForTx(tx)

		if tx.Type == TxDTL {

			// `err` stores the error produced by this operation.
			if err := validateDTLFeeBounds(tx.Fee, requiredFee); err != nil {

				return ledger, fmt.Errorf("invalid fee: %s", tx.ID)

			}

		} else if tx.Fee != requiredFee {

			return ledger, fmt.Errorf("invalid fee: %s", tx.ID)

		}

		// `expectedNonce` stores the value produced by this operation.
		expectedNonce := getNonce(newLedger, tx.From) + 1

		if tx.Nonce != expectedNonce {

			return ledger, fmt.Errorf("invalid nonce: %s", tx.From)

		}

		switch tx.Type {

		case TxStake:

			// `validatorID` stores whether the related condition is satisfied.
			validatorID := strings.TrimSpace(tx.To)

			if validatorID == "" {

				return ledger, fmt.Errorf("missing validator id: %s", tx.ID)

			}

			// `other` and `ok` store whether the related condition is satisfied.
			if other, ok := walletBoundValidator(&newLedger, tx.From, validatorID); ok {

				return ledger, fmt.Errorf("wallet already bound to validator %s", other)

			}

			// `lockEpochs` stores the synchronization state protecting shared data.
			lockEpochs := tx.StakeEpochs

			if lockEpochs == 0 {

				lockEpochs = DefaultStakeLockEpochs

			}

			// `minEpochs` stores the value produced by this operation.
			minEpochs := minUnstakeEpochs()

			if lockEpochs < minEpochs {

				return ledger, fmt.Errorf("stake lock too short: %s", tx.ID)

			}
			// `consensusPubKey` and `err` store the error produced by this operation.
			consensusPubKey, err := validateStakeConsensusPubKey(tx, validatorRegistry)
			if err != nil {

				return ledger, err

			}

			// `totalCost` stores the measured quantity used by this operation.
			totalCost := tx.Amount + requiredFee

			if getBalance(newLedger, coin, tx.From) < totalCost {

				return ledger, fmt.Errorf("insufficient balance: %s", tx.From)

			}

			addBalance(&newLedger, coin, tx.From, -totalCost)

			addBalance(&newLedger, coin, TREASURY_ADDRESS, requiredFee)

			// `lockUntil` stores the synchronization state protecting shared data.
			lockUntil := block.ID + lockEpochs

			// `key` stores the key used to access the related value.
			key := stakeKey(tx.From, validatorID)

			// `rec` stores the value produced by this operation.
			rec := newLedger.Stakes[key]

			rec.ValidatorID = validatorID
			// `normalizedPubKey` stores the key used to access the related value.
			if normalizedPubKey := normalizeConsensusPubKeyHex(consensusPubKey); normalizedPubKey != "" {
				rec.ConsensusPubKey = normalizedPubKey
			}

			rec.Amount += tx.Amount

			if lockUntil > rec.LockedUntil {

				rec.LockedUntil = lockUntil

			}

			newLedger.Stakes[key] = rec
			setValidatorRewardWallet(&newLedger, validatorID, tx.From)
			refreshValidatorRewardWalletBinding(&newLedger, validatorID)

		case TxUnstake:

			// `validatorID` stores whether the related condition is satisfied.
			validatorID := strings.TrimSpace(tx.To)

			if validatorID == "" {

				return ledger, fmt.Errorf("missing validator id: %s", tx.ID)

			}

			// `key` stores the key used to access the related value.
			key := stakeKey(tx.From, validatorID)

			// `rec` and `ok` store whether the related condition is satisfied.
			rec, ok := newLedger.Stakes[key]

			if !ok || rec.Amount < tx.Amount {

				return ledger, fmt.Errorf("insufficient staked balance: %s", tx.From)

			}

			if block.ID < rec.LockedUntil {

				return ledger, fmt.Errorf("stake still locked: %s", tx.From)

			}

			if tx.Amount <= requiredFee {

				return ledger, fmt.Errorf("unstake amount must exceed fee: %s", tx.ID)

			}

			rec.Amount -= tx.Amount

			if rec.Amount <= 0 {

				delete(newLedger.Stakes, key)

			} else {

				newLedger.Stakes[key] = rec

			}

			addBalance(&newLedger, coin, tx.From, tx.Amount-requiredFee)

			addBalance(&newLedger, coin, TREASURY_ADDRESS, requiredFee)
			refreshValidatorRewardWalletBinding(&newLedger, validatorID)

		case TxDTL:

			// `err` stores the error produced by this operation.
			if err := validateDTLTransaction(&newLedger, tx, block.ID); err != nil {

				return ledger, fmt.Errorf("invalid dtl payload: %w", err)

			}

			if getBalance(newLedger, coin, tx.From) < requiredFee {

				return ledger, fmt.Errorf("insufficient balance: %s", tx.From)

			}

			// `err` stores the error produced by this operation.
			if err := applyDTLTransaction(&newLedger, tx, int(block.ID)); err != nil {

				return ledger, fmt.Errorf("dtl execution failed: %w", err)

			}

			addBalance(&newLedger, coin, tx.From, -requiredFee)

			addBalance(&newLedger, coin, TREASURY_ADDRESS, requiredFee)

		default:

			// `totalCost` stores the measured quantity used by this operation.
			totalCost := tx.Amount + requiredFee

			if getBalance(newLedger, coin, tx.From) < totalCost {

				return ledger, fmt.Errorf("insufficient balance: %s", tx.From)

			}

			addBalance(&newLedger, coin, tx.From, -totalCost)

			addBalance(&newLedger, coin, tx.To, tx.Amount)

			addBalance(&newLedger, coin, TREASURY_ADDRESS, requiredFee)

		}

		setNonce(&newLedger, tx.From, tx.Nonce)

		totalFees[coin] += requiredFee

	}

	// -------------------------------------------------

	// -------------------------------------------------

	// Quorum signer lists are not canonical chain identity. Fee rewards use the
	// full deterministic eligible set from the committed registry snapshot.
	eligibleValidators := protocolRewardValidatorsFromRegistrySnapshot(
		block.ID,
		validatorRegistry,
	)

	// `feeCoins` stores the deterministic coin order used for fee rewards.
	feeCoins := make([]string, 0, len(totalFees))
	for coin := range totalFees {
		feeCoins = append(feeCoins, coin)
	}
	sort.Strings(feeCoins)

	// `coin` tracks the current value while iterating.
	for _, coin := range feeCoins {
		fees := totalFees[coin]

		if fees <= 0 {

			continue

		}

		// `userPart` stores the value produced by this operation.
		userPart := fees * FeeSplitUser / 100

		// `proposerPart` stores the value produced by this operation.
		proposerPart := fees * FeeSplitProposer / 100

		// `validatorsPart` stores whether the related condition is satisfied.
		validatorsPart := fees * FeeSplitValidators / 100

		// `ownerPart` stores the value produced by this operation.
		ownerPart := fees - (userPart + proposerPart + validatorsPart)

		// Cashback to senders (proportional to fee)

		if userPart > 0 {

			userDistributed := 0

			// `tx` tracks the transaction data handled by this operation.
			for _, tx := range block.Transactions {

				if normalizeCoin(tx.Coin) != coin {

					continue

				}

				// `share` stores the value produced by this operation.
				share := userPart * requiredFeeForTx(tx) / fees

				if share > 0 {

					addBalance(&newLedger, coin, tx.From, share)
					userDistributed += share

				}

			}
			if rem := userPart - userDistributed; rem > 0 {
				addBalance(&newLedger, coin, OWNER_ADDRESS, rem)
			}

		}

		// `proposerRecipient` stores the value produced by this operation.
		proposerRecipient := resolveConsensusValidatorRecipient(&newLedger, block.Proposer)
		addBalance(&newLedger, coin, proposerRecipient, proposerPart)

		validatorDistributed := 0
		if len(eligibleValidators) == 0 {

			addBalance(&newLedger, coin, proposerRecipient, validatorsPart)
			validatorDistributed = validatorsPart

		} else {

			// `perValidator` stores the value produced by this operation.
			perValidator := validatorsPart / len(eligibleValidators)

			// `v` tracks the current values while iterating.
			for _, v := range eligibleValidators {

				addBalance(&newLedger, coin, resolveConsensusValidatorRecipient(&newLedger, v), perValidator)
				validatorDistributed += perValidator

			}

		}
		if rem := validatorsPart - validatorDistributed; rem > 0 {
			addBalance(&newLedger, coin, OWNER_ADDRESS, rem)
		}

		addBalance(&newLedger, coin, OWNER_ADDRESS, ownerPart)

		addBalance(&newLedger, coin, TREASURY_ADDRESS, -fees)

	}

	if _, err := validateSupplyTransition(block.ID, &ledger, &newLedger, SupplyChange{}); err != nil {
		return ledger, err
	}
	return newLedger, nil

}

// =====================================================

// NEW QUEUE MANAGEMENT FUNCTIONS

// =====================================================

// QueueFutureBlock implements the queue future block helper.
func (n *Node) QueueFutureBlock(block Block) bool {

	if n != nil && n.hasCommittedDifferentHash(block.ID, block.BlockHash) {
		n.recordFinalizedHashConflictEvidence(block.ID, block.Round, "", block.BlockHash, "queued_fork_finalized_height")
		return false
	}

	// Initialize map if needed

	n.forkMu.Lock()

	defer n.forkMu.Unlock()

	if n.ForkBlocks == nil {

		n.ForkBlocks = make(map[uint64][]Block)

	}

	// Check if we already have this block at this height

	for i, existing := range n.ForkBlocks[block.ID] {

		if existing.BlockHash != block.BlockHash {
			continue
		}
		if block.Round > existing.Round {
			n.ForkBlocks[block.ID][i] = block
			goto queued
		}
		return false // Already queued
	}

	// Add to queue

	n.ForkBlocks[block.ID] = append(n.ForkBlocks[block.ID], block)

queued:
	if len(n.ForkBlocks[block.ID]) > maxQueuedForkBlocksPerHeight {
		sort.SliceStable(n.ForkBlocks[block.ID], func(i, j int) bool {
			if n.ForkBlocks[block.ID][i].Round != n.ForkBlocks[block.ID][j].Round {
				return n.ForkBlocks[block.ID][i].Round > n.ForkBlocks[block.ID][j].Round
			}
			return n.ForkBlocks[block.ID][i].BlockHash < n.ForkBlocks[block.ID][j].BlockHash
		})
		n.ForkBlocks[block.ID] = append([]Block(nil), n.ForkBlocks[block.ID][:maxQueuedForkBlocksPerHeight]...)
	}
	// `queueTip` stores the value produced by this operation.
	queueTip := block.ID
	// `h` and `queued` track the current values while iterating.
	for h, queued := range n.ForkBlocks {
		if h > queueTip && len(queued) > 0 {
			queueTip = h
		}
	}
	// `stage` and `provider` store the value produced by this operation.
	stage, provider := n.syncDiagnosticContext()
	// `localHeight` stores the value produced by this operation.
	localHeight := uint64(0)
	if n.Blockchain != nil {
		localHeight = n.Blockchain.Height()
	}
	fmt.Printf("[SYNC-QUEUE-ADD] stage=%s provider=%s local=%d next=%d queued_height=%d queued_at_height=%d queue_tip=%d proposer=%s hash=%s prev=%s\n",
		stage,
		ShortID(provider),
		localHeight,
		localHeight+1,
		block.ID,
		len(n.ForkBlocks[block.ID]),
		queueTip,
		ShortID(block.Proposer),
		ShortHash(block.BlockHash),
		ShortHash(block.PrevHash),
	)

	return true

}

// syncDiagnosticContext implements the sync diagnostic context helper.
func (n *Node) syncDiagnosticContext() (stage string, provider string) {
	if n == nil {
		return "", ""
	}
	n.syncMu.Lock()
	stage = strings.TrimSpace(n.syncStage)
	provider = strings.TrimSpace(n.syncProvider)
	n.syncMu.Unlock()
	if stage == "" {
		stage = "idle"
	}
	return stage, provider
}

// `syncQueueApplyFailureEscalationThreshold` defines the constant value used by this package.
const syncQueueApplyFailureEscalationThreshold uint64 = 5

// recordSyncApplyFailure implements the record sync apply failure helper.
func (n *Node) recordSyncApplyFailure(localHeight uint64, block Block, reason string) uint64 {
	if n == nil {
		return 0
	}
	reason = strings.TrimSpace(reason)
	if block.ID == 0 || strings.TrimSpace(block.BlockHash) == "" || reason == "" {
		return 0
	}

	n.syncMu.Lock()
	defer n.syncMu.Unlock()

	// `sameFailure` stores the value produced by this operation.
	sameFailure := n.syncApplyFailureHeight == block.ID &&
		strings.EqualFold(strings.TrimSpace(n.syncApplyFailureBlockHash), strings.TrimSpace(block.BlockHash)) &&
		strings.EqualFold(strings.TrimSpace(n.syncApplyFailureReason), reason)
	if sameFailure {
		n.syncApplyFailureCount++
	} else {
		n.syncApplyFailureHeight = block.ID
		n.syncApplyFailureLocalHeight = localHeight
		n.syncApplyFailureBlockHash = strings.TrimSpace(block.BlockHash)
		n.syncApplyFailurePrevHash = strings.TrimSpace(block.PrevHash)
		n.syncApplyFailureReason = reason
		n.syncApplyFailureProposer = normalizeValidatorID(block.Proposer)
		n.syncApplyFailureCount = 1
	}
	n.syncApplyFailureAt = time.Now()
	return n.syncApplyFailureCount
}

// syncApplyFailure implements the sync apply failure helper.
func (n *Node) syncApplyFailure(height uint64, blockHash string) (reason string, count uint64, ok bool) {
	if n == nil || height == 0 || strings.TrimSpace(blockHash) == "" {
		return "", 0, false
	}
	n.syncMu.Lock()
	defer n.syncMu.Unlock()
	if n.syncApplyFailureHeight != height ||
		!strings.EqualFold(strings.TrimSpace(n.syncApplyFailureBlockHash), strings.TrimSpace(blockHash)) {
		return "", 0, false
	}
	return strings.TrimSpace(n.syncApplyFailureReason), n.syncApplyFailureCount, true
}

// clearSyncApplyFailure implements the clear sync apply failure helper.
func (n *Node) clearSyncApplyFailure(height uint64, blockHash string) {
	if n == nil || height == 0 || strings.TrimSpace(blockHash) == "" {
		return
	}
	n.syncMu.Lock()
	defer n.syncMu.Unlock()
	if n.syncApplyFailureHeight != height ||
		!strings.EqualFold(strings.TrimSpace(n.syncApplyFailureBlockHash), strings.TrimSpace(blockHash)) {
		return
	}
	n.syncApplyFailureHeight = 0
	n.syncApplyFailureLocalHeight = 0
	n.syncApplyFailureBlockHash = ""
	n.syncApplyFailurePrevHash = ""
	n.syncApplyFailureReason = ""
	n.syncApplyFailureProposer = ""
	n.syncApplyFailureCount = 0
	n.syncApplyFailureAt = time.Time{}
}

// forceSnapshotSyncAfterCurrentSync implements the force snapshot sync after current sync helper.
func (n *Node) forceSnapshotSyncAfterCurrentSync(targetHeight uint64, reason string) {
	if n == nil || targetHeight == 0 {
		return
	}
	go func() {
		// `deadline` stores the value produced by this operation.
		deadline := time.Now().Add(5 * time.Second)
		for time.Now().Before(deadline) {
			if n.Blockchain != nil && n.Blockchain.Height() >= targetHeight {
				return
			}
			// `inFlight` stores the current position in the related collection.
			inFlight := false
			if n.Consensus != nil {
				n.Consensus.mu.Lock()
				inFlight = n.Consensus.syncInFlight
				n.Consensus.mu.Unlock()
			}
			if !inFlight {
				break
			}
			time.Sleep(100 * time.Millisecond)
		}
		if n.Blockchain != nil && n.Blockchain.Height() >= targetHeight {
			return
		}
		n.forceSnapshotSyncToHeight(targetHeight, reason)
	}()
}

type scheduledUpdateTraceState struct {
	// `CurrentHeight` stores the value associated with this record.
	CurrentHeight uint64
	// `UpdateHeight` stores the value associated with this record.
	UpdateHeight uint64
	// `Step` stores the value associated with this record.
	Step string
	// `DueTransition` stores the value associated with this record.
	DueTransition bool
	// `DeferForSync` stores the value associated with this record.
	DeferForSync bool
	// `UpdateBlocked` stores the value associated with this record.
	UpdateBlocked bool
	// `PlannedOnly` stores the value associated with this record.
	PlannedOnly bool
	// `Updated` stores the value associated with this record.
	Updated bool
	// `ProcessedAdds` stores the value associated with this record.
	ProcessedAdds int
	// `ProcessedRemoves` stores the value associated with this record.
	ProcessedRemoves int
	// `NextTransitionHeight` stores the value associated with this record.
	NextTransitionHeight uint64
	// `TransitionValidators` stores the value associated with this record.
	TransitionValidators int
	// `NextValidators` stores the value associated with this record.
	NextValidators int
}

// `scheduledUpdateTraceOutput` stores the result produced by this operation.
var scheduledUpdateTraceOutput io.Writer

// logScheduledUpdateTrace implements the log scheduled update trace helper.
func logScheduledUpdateTrace(stage string, provider string, state scheduledUpdateTraceState) {
	// `step` stores the value produced by this operation.
	step := strings.TrimSpace(state.Step)
	if step == "" {
		return
	}
	stage = strings.TrimSpace(stage)
	if stage == "" {
		stage = "idle"
	}
	// `writer` stores the value produced by this operation.
	writer := scheduledUpdateTraceOutput
	if writer == nil {
		if !DebugSync && !DebugConsensus {
			return
		}
		writer = os.Stdout
	}
	fmt.Fprintf(writer, "[SYNC-SCHEDULED-UPDATES] stage=%s provider=%s current_height=%d step=%s update_height=%d due_transition=%t defer_for_sync=%t update_blocked=%t planned_only=%t updated=%t processed_adds=%d processed_removes=%d next_transition_height=%d transition_validators=%d next_validators=%d\n",
		stage,
		ShortID(provider),
		state.CurrentHeight,
		step,
		state.UpdateHeight,
		state.DueTransition,
		state.DeferForSync,
		state.UpdateBlocked,
		state.PlannedOnly,
		state.Updated,
		state.ProcessedAdds,
		state.ProcessedRemoves,
		state.NextTransitionHeight,
		state.TransitionValidators,
		state.NextValidators,
	)
}

// queuedFutureHeightsSummary implements the queued future heights summary helper.
func (n *Node) queuedFutureHeightsSummary(localHeight uint64, limit int) string {
	if n == nil {
		return "none"
	}
	n.forkMu.RLock()
	defer n.forkMu.RUnlock()

	type queuedHeight struct {
		// `height` stores the value associated with this record.
		height uint64
		// `count` stores the measured quantity used by this operation.
		count int
	}
	// `items` stores the current position in the related collection.
	items := make([]queuedHeight, 0, len(n.ForkBlocks))
	// `h` and `blocks` track the block data handled by this operation.
	for h, blocks := range n.ForkBlocks {
		if h <= localHeight || len(blocks) == 0 {
			continue
		}
		items = append(items, queuedHeight{height: h, count: len(blocks)})
	}
	if len(items) == 0 {
		return "none"
	}
	sort.Slice(items, func(i, j int) bool { return items[i].height < items[j].height })
	if limit <= 0 || limit > len(items) {
		limit = len(items)
	}
	// `parts` stores the value produced by this operation.
	parts := make([]string, 0, limit+1)
	// `item` tracks the current position in the related collection.
	for _, item := range items[:limit] {
		parts = append(parts, fmt.Sprintf("%d(%d)", item.height, item.count))
	}
	if limit < len(items) {
		parts = append(parts, fmt.Sprintf("+%d_more", len(items)-limit))
	}
	return strings.Join(parts, ",")
}

// queuedBlocksAtHeightSummary implements the queued blocks at height summary helper.
func (n *Node) queuedBlocksAtHeightSummary(height uint64, limit int) string {
	if n == nil || height == 0 {
		return "none"
	}
	n.forkMu.RLock()
	// `blocks` stores the block data handled by this operation.
	blocks := append([]Block(nil), n.ForkBlocks[height]...)
	n.forkMu.RUnlock()
	if len(blocks) == 0 {
		return "none"
	}
	if limit <= 0 || limit > len(blocks) {
		limit = len(blocks)
	}
	// `parts` stores the value produced by this operation.
	parts := make([]string, 0, limit+1)
	// `block` tracks the synchronization state protecting shared data.
	for _, block := range blocks[:limit] {
		parts = append(parts, fmt.Sprintf("%s/%s", ShortHash(block.BlockHash), ShortHash(block.PrevHash)))
	}
	if limit < len(blocks) {
		parts = append(parts, fmt.Sprintf("+%d_more", len(blocks)-limit))
	}
	return strings.Join(parts, ",")
}

// logSyncQueueStall implements the log sync queue stall helper.
func (n *Node) logSyncQueueStall(reason string, localHeight uint64, nextHeight uint64, queueTip uint64, extra string) {
	if n == nil || queueTip <= localHeight {
		return
	}
	// `stage` and `provider` store the value produced by this operation.
	stage, provider := n.syncDiagnosticContext()
	// `line` stores the value produced by this operation.
	line := fmt.Sprintf("[SYNC-QUEUE-STALL] stage=%s provider=%s reason=%s local=%d next=%d queue_tip=%d queued_heights=%s queued_next=%s",
		stage,
		ShortID(provider),
		strings.TrimSpace(reason),
		localHeight,
		nextHeight,
		queueTip,
		n.queuedFutureHeightsSummary(localHeight, 5),
		n.queuedBlocksAtHeightSummary(nextHeight, 4),
	)
	if extra = strings.TrimSpace(extra); extra != "" {
		line += " " + extra
	}
	fmt.Println(line)
}

// maxQueuedFutureHeight returns the maximum queued future height.
func (n *Node) maxQueuedFutureHeight(localHeight uint64) uint64 {
	if n == nil {
		return 0
	}
	n.forkMu.RLock()

	// `maxHeight` stores the value produced by this operation.
	maxHeight := uint64(0)
	// `h` and `blocks` track the block data handled by this operation.
	for h, blocks := range n.ForkBlocks {
		if h <= localHeight || len(blocks) == 0 {
			continue
		}
		if h > maxHeight {
			maxHeight = h
		}
	}
	n.forkMu.RUnlock()
	if voteHeight, _, _ := n.maxQueuedFutureExecutionVoteHeight(localHeight); voteHeight > maxHeight {
		maxHeight = voteHeight
	}
	return maxHeight
}

// maxQueuedFutureExecutionVoteHeight returns the highest future height with
// enough queued execution votes from active validators to justify catch-up.
func (n *Node) maxQueuedFutureExecutionVoteHeight(localHeight uint64) (uint64, int, int) {
	if n == nil {
		return 0, 0, 0
	}

	// `counts` stores unique active-validator signers seen for each future height.
	counts := make(map[uint64]map[string]struct{})
	n.execResultsMu.Lock()
	for key, msgs := range n.queuedExecVotes {
		if len(msgs) == 0 {
			continue
		}
		// `keyHeight` stores the parsed height from the queue key.
		keyHeight, _ := strconv.ParseUint(strings.TrimSpace(key), 10, 64)
		for _, msg := range msgs {
			// `height` stores the vote height, preferring the message hint over the queue key.
			height := msg.HeightHint
			if height == 0 {
				height = keyHeight
			}
			if height <= localHeight {
				continue
			}
			signer := normalizeValidatorID(msg.Signer)
			if signer == "" {
				continue
			}
			if counts[height] == nil {
				counts[height] = make(map[string]struct{})
			}
			counts[height][signer] = struct{}{}
		}
	}
	n.execResultsMu.Unlock()

	// `bestHeight`, `bestVotes`, and `bestRequired` store the strongest target.
	bestHeight := uint64(0)
	bestVotes := 0
	bestRequired := 0
	for height, signers := range counts {
		validators := n.queuedFutureVoteValidatorSet(localHeight, height)
		if len(validators) == 0 {
			continue
		}
		allowed := make(map[string]struct{}, len(validators))
		for _, validatorID := range validators {
			allowed[normalizeValidatorID(validatorID)] = struct{}{}
		}
		votes := 0
		for signer := range signers {
			if _, ok := allowed[signer]; ok {
				votes++
			}
		}
		required := execQuorumRequired(len(validators))
		if required == 0 || votes < required {
			continue
		}
		if height > bestHeight {
			bestHeight = height
			bestVotes = votes
			bestRequired = required
		}
	}
	return bestHeight, bestVotes, bestRequired
}

// trustedQueuedFutureExecutionTarget turns already-verified, quorum-backed
// future execution votes into a catch-up signal. Blocks still pass normal
// snapshot and committed-quorum verification before they are applied.
func (n *Node) trustedQueuedFutureExecutionTarget(localHeight uint64) (uint64, int) {
	height, votes, required := n.maxQueuedFutureExecutionVoteHeight(localHeight)
	if height <= localHeight || required <= 0 || votes < required {
		return 0, 0
	}
	return height, votes
}

// queuedFutureVoteValidatorSet returns the safest locally-known validator set
// for treating future execution votes as a catch-up signal. The target blocks
// are still verified before apply; this set only decides whether sync should
// wake up when the local node is too far behind to resolve the future H-1 set.
func (n *Node) queuedFutureVoteValidatorSet(localHeight uint64, futureHeight uint64) []string {
	if n == nil {
		return nil
	}
	if validators := canonicalValidatorIDs(n.GetConsensusValidators(int(futureHeight))); len(validators) > 0 {
		return validators
	}
	if localHeight > 0 {
		if validators := canonicalValidatorIDs(n.GetConsensusValidators(int(localHeight + 1))); len(validators) > 0 {
			return validators
		}
		if validators := canonicalValidatorIDs(n.frozenValidatorsForHeight(localHeight + 1)); len(validators) > 0 {
			return validators
		}
	}
	if validators := canonicalValidatorIDs(n.GenesisValidators); len(validators) > 0 {
		return validators
	}
	return nil
}

// handleQueuedSyncStall handles queued sync stall.
func (n *Node) handleQueuedSyncStall(reason string, localHeight uint64, queueTip uint64) {
	if n == nil || queueTip <= localHeight {
		return
	}

	n.maybeSyncToBestObservedHeight(reason)

	targetHeight := n.promoteRecoveryTarget(localHeight, queueTip)
	if targetHeight <= localHeight {
		return
	}

	// Escalate to forced snapshot only when commit is clearly stalled.
	if n.commitStallDuration() < execQuorumEmergencyStallTimeout {
		return
	}
	if targetHeight <= localHeight+1 {
		return
	}
	n.maybeForceQueueSnapshotSync(targetHeight, reason)
}

// promoteRecoveryTarget lifts a local queue target to the freshest trusted
// runtime target we already know about, so recovery does not stall at an old
// future-block queue tip while peers have moved further ahead.
func (n *Node) promoteRecoveryTarget(localHeight uint64, targetHeight uint64) uint64 {
	if n == nil {
		return targetHeight
	}
	if targetHeight <= localHeight {
		if queued := n.maxQueuedFutureHeight(localHeight); queued > targetHeight {
			targetHeight = queued
		}
	}
	if followup := n.bestFollowupSyncTarget(localHeight); followup > targetHeight {
		targetHeight = followup
	}
	runtime := n.runtimeStatusSnapshot()
	if runtime.NetworkBestHeight > targetHeight {
		targetHeight = runtime.NetworkBestHeight
	}
	if runtime.SyncTarget > targetHeight {
		targetHeight = runtime.SyncTarget
	}
	if queued := n.maxQueuedFutureHeight(localHeight); queued > targetHeight {
		targetHeight = queued
	}
	return targetHeight
}

// maybeForceQueueSnapshotSync implements the maybe force queue snapshot sync helper.
func (n *Node) maybeForceQueueSnapshotSync(targetHeight uint64, reason string) {
	if n == nil || targetHeight == 0 {
		return
	}
	localHeight := uint64(0)
	if n.Blockchain != nil {
		localHeight = n.Blockchain.Height()
	}
	targetHeight = n.promoteRecoveryTarget(localHeight, targetHeight)
	if targetHeight == 0 || targetHeight <= localHeight {
		return
	}
	// `inFlight` stores the current position in the related collection.
	inFlight := false
	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		inFlight = n.Consensus.syncInFlight
		n.Consensus.mu.Unlock()
	}

	// `queueForceCooldown` defines the constant value used by this package.
	const queueForceCooldown = 12 * time.Second
	// `now` stores the value produced by this operation.
	now := time.Now()

	n.syncMu.Lock()
	if !n.lastQueueForceSyncAt.IsZero() &&
		now.Sub(n.lastQueueForceSyncAt) < queueForceCooldown &&
		targetHeight <= n.lastQueueForceSyncTarget {
		n.syncMu.Unlock()
		return
	}
	n.lastQueueForceSyncAt = now
	n.lastQueueForceSyncTarget = targetHeight
	n.syncMu.Unlock()

	if DebugSync || DebugConsensus {
		// `mode` stores the value produced by this operation.
		mode := "snapshot"
		if inFlight {
			mode = "deferred_snapshot"
		}
		fmt.Printf("[SYNC-FORCE-QUEUE] reason=%s target=%d mode=%s\n", reason, targetHeight, mode)
	}
	if inFlight {
		forceReason := "queue_stall_" + reason
		if !syncReasonPreemptsInFlight(forceReason) {
			n.forceSnapshotSyncAfterCurrentSync(targetHeight, forceReason)
			return
		}
	}
	go n.forceSnapshotSyncToHeight(targetHeight, "queue_stall_"+reason)
}

// ProcessQueuedBlocks implements the process queued blocks helper.
func (n *Node) ProcessQueuedBlocks() {

	// `currentHeight` stores the value produced by this operation.
	currentHeight := n.Blockchain.Height()

	// `nextHeight` stores the value produced by this operation.
	nextHeight := currentHeight + 1

	// `processed` stores the value produced by this operation.
	processed := 0

	// `maxProcess` stores the value produced by this operation.
	maxProcess := 10 // Limit to prevent infinite loops

	for processed < maxProcess {

		n.forkMu.RLock()

		// `blocks` and `exists` store whether the related condition is satisfied.
		blocks, exists := n.ForkBlocks[nextHeight]

		if exists {

			blocks = append([]Block(nil), blocks...)

		}

		n.forkMu.RUnlock()

		if !exists || len(blocks) == 0 {
			// `queueTip` stores the value produced by this operation.
			queueTip := n.maxQueuedFutureHeight(currentHeight)
			if queueTip > currentHeight {
				n.logSyncQueueStall("queue_gap", currentHeight, nextHeight, queueTip, "")
				n.maybeRecoverMissingBlock(nextHeight, "queue_gap")
				n.handleQueuedSyncStall("queue_gap", currentHeight, queueTip)
			}

			break

		}

		// Find a block that connects to our chain

		lastBlock := n.Blockchain.LastBlock()

		// `validBlock` stores whether the related condition is satisfied.
		var validBlock *Block

		// `i` and `block` track the synchronization state protecting shared data.
		for i, block := range blocks {

			if block.PrevHash == lastBlock.BlockHash {

				validBlock = &blocks[i]

				break

			}

		}

		if validBlock == nil {

			// No connecting block found
			queueTip := n.maxQueuedFutureHeight(currentHeight)
			// `expectedPrev` stores the value produced by this operation.
			expectedPrev := ShortHash(lastBlock.BlockHash)
			n.logSyncQueueStall("queue_prevhash_mismatch", currentHeight, nextHeight, queueTip,
				fmt.Sprintf("expected_prev=%s", expectedPrev))
			n.handleQueuedSyncStall("queue_prevhash_mismatch", currentHeight, queueTip)

			break

		}

		// Process the valid block

		_ = n.ReceiveBlock(*validBlock, n.Blockchain)

		if n.Blockchain.Height() != validBlock.ID {

			// Could not apply (missing quorum / invalid / still behind). Keep it queued.
			queueTip := n.maxQueuedFutureHeight(currentHeight)
			if queueTip < validBlock.ID {
				queueTip = validBlock.ID
			}
			// `rejectReason`, `failCount`, and `haveRejectReason` store the measured quantity used by this operation.
			rejectReason, failCount, haveRejectReason := n.syncApplyFailure(validBlock.ID, validBlock.BlockHash)
			if !haveRejectReason {
				rejectReason = "process_block_incomplete"
				// `seenKey` stores the key used to access the related value.
				if seenKey := blockSeenKey(*validBlock); seenKey != "" {
					n.unmarkBlockSeen(seenKey)
				}
				failCount = n.recordSyncApplyFailure(currentHeight, *validBlock, rejectReason)
				haveRejectReason = true
			}
			// `extra` stores the value produced by this operation.
			extra := fmt.Sprintf("candidate_hash=%s candidate_prev=%s proposer=%s",
				ShortHash(validBlock.BlockHash), ShortHash(validBlock.PrevHash), ShortID(validBlock.Proposer))
			if haveRejectReason {
				extra += fmt.Sprintf(" reject_reason=%s fail_count=%d", rejectReason, failCount)
			}
			n.logSyncQueueStall("queue_apply_failed", currentHeight, nextHeight, queueTip, extra)
			if haveRejectReason && failCount >= syncQueueApplyFailureEscalationThreshold {
				// `stage` and `provider` store the value produced by this operation.
				stage, provider := n.syncDiagnosticContext()
				if strings.TrimSpace(provider) != "" {
					n.setSyncAvoidProviderOnce(provider)
				}
				fmt.Printf("[SYNC-FAILURE-CONTROLLER] stage=%s provider=%s local=%d next=%d target=%d fail_count=%d reason=%s action=provider_rotate_snapshot\n",
					stage,
					ShortID(provider),
					currentHeight,
					nextHeight,
					queueTip,
					failCount,
					rejectReason,
				)
				// `forceTarget` stores the value produced by this operation.
				forceTarget := queueTip
				// `followup` stores the value produced by this operation.
				if followup := n.bestFollowupSyncTarget(currentHeight); followup > forceTarget {
					forceTarget = followup
				}
				n.maybeForceQueueSnapshotSync(forceTarget, "queue_apply_failed_"+rejectReason)
			}
			n.handleQueuedSyncStall("queue_apply_failed", currentHeight, queueTip)

			break

		}

		// Remove this block from queue

		n.RemoveFromQueue(nextHeight, validBlock.BlockHash)

		// Update for next iteration

		currentHeight = n.Blockchain.Height()

		nextHeight = currentHeight + 1
		n.replayQueuedLeaderBlocksForCurrentEpoch()

		processed++

		// Small delay to prevent tight loop

		time.Sleep(10 * time.Millisecond)

	}

	if processed > 0 {
		n.maybeExitSyncMode("queued_blocks_applied")

	}

}

// RemoveFromQueue removes from queue.
func (n *Node) RemoveFromQueue(height uint64, blockHash string) {

	n.forkMu.Lock()

	defer n.forkMu.Unlock()

	// `blocks` and `exists` store whether the related condition is satisfied.
	blocks, exists := n.ForkBlocks[height]

	if !exists {

		return

	}

	// `newBlocks` stores the value produced by this operation.
	newBlocks := []Block{}

	// `block` tracks the synchronization state protecting shared data.
	for _, block := range blocks {

		if block.BlockHash != blockHash {

			newBlocks = append(newBlocks, block)

		}

	}

	if len(newBlocks) == 0 {

		delete(n.ForkBlocks, height)

	} else {

		n.ForkBlocks[height] = newBlocks

	}

}

// maxUint64 returns the maximum uint64.
func maxUint64(a, b uint64) uint64 {

	if a > b {

		return a

	}

	return b

}

// ComputeExpectedMempoolRoot computes expected mempool root.
func ComputeExpectedMempoolRoot(height int) string {

	// NOTE:

	// This is CONSENSUS-NEUTRAL.

	// Used ONLY for fork scoring / diagnostics.

	// Collect pending tx IDs deterministically

	txIDs := make([]string, 0, len(GlobalMempoolSnapshot))

	// `tx` tracks the transaction data handled by this operation.
	for _, tx := range GlobalMempoolSnapshot {

		txIDs = append(txIDs, tx.ID)

	}

	sort.Strings(txIDs)

	// Height binding (prevents reuse across heights)

	data := strconv.Itoa(height) + "|" + strings.Join(txIDs, ",")

	// `hash` stores the digest used to identify or verify the related data.
	hash := sha256.Sum256([]byte(data))

	return hex.EncodeToString(hash[:])

}

// HandleFork handles fork.
func (n *Node) HandleFork(

	newBlock Block,

	existingBlock Block,

) {

	// =====================================================

	// =====================================================

	expectedRoot := ComputeExpectedMempoolRoot(

		int(n.Blockchain.Height()),
	)

	// =====================================================

	// =====================================================

	scoreNew := ScoreFork(newBlock, expectedRoot)

	// `scoreOld` stores the value produced by this operation.
	scoreOld := ScoreFork(existingBlock, expectedRoot)

	if DebugConsensus {

		fmt.Printf(

			"   Fork scores | new(c=%d m=%d s=%d) old(c=%d m=%d s=%d)\n",

			scoreNew.CensorshipScore,

			scoreNew.MempoolDistance,

			scoreNew.SignatureWeight,

			scoreOld.CensorshipScore,

			scoreOld.MempoolDistance,

			scoreOld.SignatureWeight,
		)

	}

	// =====================================================

	// =====================================================

	winnerScore := PreferFork(scoreNew, scoreOld)

	// `winnerBlock` stores the synchronization state protecting shared data.
	var winnerBlock Block

	if winnerScore.BlockHash == newBlock.BlockHash {

		winnerBlock = newBlock

	} else {

		winnerBlock = existingBlock

	}

	n.SwitchToFork(winnerBlock)

}

// PreferFork implements the prefer fork helper.
func PreferFork(a, b ForkScore) ForkScore {

	// =====================================================

	// =====================================================

	if a.TotalScore > b.TotalScore {

		return a

	}

	if b.TotalScore > a.TotalScore {

		return b

	}

	// =====================================================

	// =====================================================

	if a.Timestamp > b.Timestamp {

		return a

	}

	if b.Timestamp > a.Timestamp {

		return b

	}

	// =====================================================

	// =====================================================

	if a.BlockHash < b.BlockHash {

		return a

	}

	return b

}

// ScoreFork implements the score fork helper.
func ScoreFork(

	block Block,

	expectedStateRoot string,

) ForkScore {

	// `score` stores the value produced by this operation.
	score := ForkScore{}

	score.Timestamp = int64(SystemTimeUnits(block.BlockTime))

	// =====================================================

	// =====================================================

	if block.ResultHash == nil || len(block.ExecutionResults) == 0 {

		return score // zero score = dead fork

	}

	score.ExecutionScore = len(block.ExecutionResults) * 10

	// =====================================================

	// =====================================================

	if block.StateRoot == expectedStateRoot {

		score.StateScore = 100

	}

	// =====================================================

	// =====================================================

	cScore := int(ValidatorCensorshipScore(

		block.Proposer,

		int(block.ID),
	))

	score.CensorshipScore = -cScore * 20

	// =====================================================

	// =====================================================

	if !ResultGossipOnly {

		// `age` stores the value produced by this operation.
		age := time.Now().Unix() - block.Timestamp

		if age < 0 {

			age = 0

		}

		score.FreshnessScore = int(maxInt64(0, 30-age))

	}

	// =====================================================

	// =====================================================

	score.TotalScore =

		score.ExecutionScore +

			score.StateScore +

			score.CensorshipScore +

			score.FreshnessScore

	return score

}

