// maxInt64 returns the maximum int64.
func maxInt64(a, b int64) int64 {

	if a > b {

		return a

	}

	return b

}

// SwitchToFork implements the switch to fork helper.
func (n *Node) SwitchToFork(newBlock Block) {

	// =====================================================

	// =====================================================

	if n == nil || n.Blockchain == nil {
		return
	}

	if n.hasCommittedDifferentHash(newBlock.ID, newBlock.BlockHash) {
		n.recordFinalizedHashConflictEvidence(newBlock.ID, newBlock.Round, "", newBlock.BlockHash, "switch_to_fork_finalized_height")
		return
	}

	// NOTE: Full reorg requires snapshot history.

	// For now, only allow switching if height matches tip.

	if newBlock.ID != n.Blockchain.Height() {

		return

	}

	// =====================================================

	// =====================================================

	n.Blockchain.mu.Lock()

	if int(newBlock.ID) >= len(n.Blockchain.Blocks) {

		n.Blockchain.mu.Unlock()

		return

	}

	n.Blockchain.Blocks[newBlock.ID] = newBlock

	n.Blockchain.mu.Unlock()

	// =====================================================

	// =====================================================

	n.seenBlockMu.Lock()

	n.SeenBlockHashes = make(map[string]bool)

	n.seenBlockQueue = nil

	n.seenBlockHead = 0

	n.seenBlockMu.Unlock()

	// =====================================================

	// =====================================================

	n.RebuildLedgerFromGenesis()

}

// GenesisLedger implements the genesis ledger helper.
func GenesisLedger() Ledger {

	// `l` stores the value produced by this operation.
	l := Ledger{

		Balances: make(map[string]int),

		Nonces: make(map[string]int),

		Stakes: make(map[string]StakeLock),

		ValidatorRewardWallets: make(map[string]string),
	}

	// =====================================================

	// =====================================================

	for _, bucket := range tokenomicsBuckets(FixedTotalSupply) {

		addBalance(&l, CoinSymbol, bucket.Address, int(bucket.Allocation))

	}

	ensureTreasuryAndRewards(&l)

	return l

}

// RebuildLedgerFromGenesis implements the rebuild ledger from genesis helper.
func (n *Node) RebuildLedgerFromGenesis() {

	// `genesisLedger` stores the value produced by this operation.
	genesisLedger := GenesisLedger()

	n.setExecutionLedger(genesisLedger)

	n.Blockchain.mu.RLock()

	// `blocks` stores the block data handled by this operation.
	blocks := append([]Block(nil), n.Blockchain.Blocks...)

	n.Blockchain.mu.RUnlock()

	// `height` stores the value produced by this operation.
	height := uint64(0)

	if len(blocks) > 0 {

		height = blocks[len(blocks)-1].ID

	}

	// `i` stores the current position in the related collection.
	for i := uint64(1); i <= height; i++ {

		if int(i) >= len(blocks) {

			return

		}

		// `block` stores the synchronization state protecting shared data.
		block := blocks[i]

		// `newLedger` and `err` store the error produced by this operation.
		newLedger, err := ApplyBlockStateWithNode(n, n.currentExecutionLedgerClone(), block)

		if err != nil {

			return

		}

		n.setExecutionLedger(newLedger)

	}

}

