// cleanupInactiveValidators implements the cleanup inactive validators helper.
func (n *Node) cleanupInactiveValidators() {

	// `ticker` stores the value produced by this operation.
	ticker := time.NewTicker(15 * time.Second)

	defer ticker.Stop()

	for {

		select {

		case <-n.shutdownCh:

			return

		case <-ticker.C:

			inactiveBlocks := protocolValidatorInactiveBlocksValue()
			if inactiveBlocks == 0 {

				continue

			}

			// Deterministic mode computes inactivity from finalized blocks inside
			// applyScheduledValidatorUpdates at commit time.
			if protocolDeterministicValidatorSelectionEnabled() {

				continue

			}

			// `height` stores the value produced by this operation.
			height := uint64(0)

			if n.Blockchain != nil {

				height = n.Blockchain.FinalizedHeight()

				if height == 0 {

					height = n.Blockchain.Height()

				}

			}

			if height == 0 {

				n.commitMu.Lock()

				height = n.committedHeight

				n.commitMu.Unlock()

			}

			if height == 0 {

				height = 1

			}

			// `toRemove` stores the value used by this operation.
			var toRemove []string

			n.validatorMu.Lock()
			selfID := n.localConsensusValidatorID()

			// `id` and `st` track the current position in the related collection.
			for id, st := range n.validatorStatus {

				if normalizeValidatorID(id) == selfID {

					continue

				}

				// `refHeight` stores the value produced by this operation.
				refHeight := st.FinalizedHeight

				if refHeight == 0 {

					refHeight = st.ReportedHeight

				}

				if refHeight == 0 {

					refHeight = st.Height

				}

				if refHeight == 0 {

					continue

				}

				if height > refHeight && height-refHeight >= inactiveBlocks {

					toRemove = append(toRemove, id)

				}

			}

			n.validatorMu.Unlock()

			if len(toRemove) == 0 {

				continue

			}

			toRemove = canonicalValidatorIDs(toRemove)
			// `id` tracks the current position in the related collection.
			for _, id := range toRemove {
				n.applyOfflineInactivityPenalty(id, height)
			}

			// `activeNow` stores the value produced by this operation.
			activeNow := len(n.consensusValidatorsForHeight(height + 1))
			if activeNow == 0 {
				activeNow = len(n.GetConsensusValidators(int(height + 1)))
			}
			// `maxRemovals` stores the value produced by this operation.
			maxRemovals := activeNow - minActiveValidatorsFloor()
			if maxRemovals <= 0 {
				if DebugConsensus {
					fmt.Printf("Ã¢Å¡Â Ã¯Â¸Â Skipping inactive removals: active validators at minimum (%d)\n", minActiveValidatorsFloor())
				}
				continue
			}
			if len(toRemove) > maxRemovals {
				toRemove = toRemove[:maxRemovals]
			}

			if protocolValidatorInactivePermanentRemoveEnabled() {

				GlobalValidatorRegistry.mu.Lock()

				// `id` tracks the current position in the related collection.
				for _, id := range toRemove {

					// `rec` stores the value produced by this operation.
					rec := ensureValidatorRecordLocked(id, height)

					if rec == nil {

						continue

					}

					rec.Status = ValidatorRemoved

					rec.JailUntilHeight = 0

					rec.JoinHeight = 0

				}

				GlobalValidatorRegistry.mu.Unlock()

			}

			// `activationHeight` stores the value produced by this operation.
			activationHeight := height + validatorSetActivationDelayBlocks()

			// `id` tracks the current position in the related collection.
			for _, id := range toRemove {
				n.queuePendingValidatorRemoval(id, activationHeight)

			}

		}

	}

}

