// startInteractiveCLI implements the start interactive cli helper.
func startInteractiveCLI(node *Node) {

	// `reader` stores the value produced by this operation.
	reader := bufio.NewReader(os.Stdin)

	for {

		fmt.Printf("msc[%s]> ", node.ID)

		// `line` and `err` store the error produced by this operation.
		line, err := reader.ReadString('\n')

		if err != nil {
			log.Printf("[WARN] interactive CLI input closed; node keeps running: %v", err)
			return

		}

		// `cmd` stores the value produced by this operation.
		cmd := strings.TrimSpace(line)

		if cmd == "" {

			continue

		}

		// `args` stores the value produced by this operation.
		args := strings.Split(cmd, " ")

		switch args[0] {

		case "help":

			printCLIHelp()

		case "network":

			node.startNetworkCLI()

		case "status":

		case "balance":

			if len(args) < 2 || len(args) > 3 {

				fmt.Println("usage: balance <address> [coin]")

				continue

			}

			// `addr` stores the address used by this operation.
			addr := args[1]

			// `coin` stores the value produced by this operation.
			coin := CoinSymbol

			if len(args) == 3 {

				coin = args[2]

			}

			fmt.Printf("balance %s (%s): %d\n", addr, coin, getBalance(node.Ledger, coin, addr))

		case "validators":

			// `v` tracks the current values while iterating.
			for _, v := range node.GetActiveValidators() {

				fmt.Println(v)

			}

		case "validatorset":

			// `current` stores the value produced by this operation.
			current := node.GetConsensusValidators(int(node.Blockchain.Height() + 1))
			node.validatorSetMu.RLock()

			// `pendingAdds` stores the value produced by this operation.
			pendingAdds := make([]string, 0, len(node.pendingValidators))

			// `id` and `act` track the current position in the related collection.
			for id, act := range node.pendingValidators {

				pendingAdds = append(pendingAdds, fmt.Sprintf("%s@%d", id, act))

			}

			// `pendingRemoves` stores the value produced by this operation.
			pendingRemoves := make([]string, 0, len(node.pendingValidatorRemovals))

			// `id` and `act` track the current position in the related collection.
			for id, act := range node.pendingValidatorRemovals {

				pendingRemoves = append(pendingRemoves, fmt.Sprintf("%s@%d", id, act))

			}

			node.validatorSetMu.RUnlock()

			sort.Strings(current)

			sort.Strings(pendingAdds)

			sort.Strings(pendingRemoves)

			fmt.Printf("validator_set_hash=%s\n", ValidatorSetHash(current)[:8])

			fmt.Printf("validators (%d):\n", len(current))

			// `v` tracks the current values while iterating.
			for _, v := range current {

				fmt.Println(v)

			}

			if len(pendingAdds) > 0 || len(pendingRemoves) > 0 {

				fmt.Println("pending_updates:")

				if len(pendingAdds) > 0 {

					fmt.Printf("  add: %s\n", strings.Join(pendingAdds, ", "))

				}

				if len(pendingRemoves) > 0 {

					fmt.Printf("  remove: %s\n", strings.Join(pendingRemoves, ", "))

				}

			}

		case "validator-pending":

			node.validatorSetMu.RLock()

			// `pendingAdds` stores the value produced by this operation.
			pendingAdds := make([]string, 0, len(node.pendingValidators))

			// `id` and `act` track the current position in the related collection.
			for id, act := range node.pendingValidators {

				pendingAdds = append(pendingAdds, fmt.Sprintf("%s@%d", id, act))

			}

			// `pendingRemoves` stores the value produced by this operation.
			pendingRemoves := make([]string, 0, len(node.pendingValidatorRemovals))

			// `id` and `act` track the current position in the related collection.
			for id, act := range node.pendingValidatorRemovals {

				pendingRemoves = append(pendingRemoves, fmt.Sprintf("%s@%d", id, act))

			}

			node.validatorSetMu.RUnlock()

			sort.Strings(pendingAdds)

			sort.Strings(pendingRemoves)

			if len(pendingAdds) == 0 && len(pendingRemoves) == 0 {

				fmt.Println("no pending validator updates")

				continue

			}

			if len(pendingAdds) > 0 {

				fmt.Printf("pending add: %s\n", strings.Join(pendingAdds, ", "))

			}

			if len(pendingRemoves) > 0 {

				fmt.Printf("pending remove: %s\n", strings.Join(pendingRemoves, ", "))

			}

		case "candidates":

			node.candidateMu.RLock()

			if len(node.candidates) == 0 {

				node.candidateMu.RUnlock()

				fmt.Println("no candidates")

				continue

			}

			// `ids` stores the current position in the related collection.
			ids := make([]string, 0, len(node.candidates))

			// `id` tracks the current position in the related collection.
			for id := range node.candidates {

				ids = append(ids, id)

			}

			sort.Strings(ids)

			fmt.Printf("candidates (%d):\n", len(ids))

			// `id` tracks the current position in the related collection.
			for _, id := range ids {

				// `cand` stores the value produced by this operation.
				cand := node.candidates[id]

				if cand == nil {

					continue

				}

				// `observed` stores the value produced by this operation.
				observed := cand.ObservedEpochs

				// `matched` stores the value produced by this operation.
				matched := cand.MatchedEpochs

				// `dcs` stores the value produced by this operation.
				dcs := 0.0

				// `uptime` stores the value produced by this operation.
				uptime := 0.0

				// `diversityAvg` stores the value produced by this operation.
				diversityAvg := 0.0

				// `gossipTimeliness` stores the value produced by this operation.
				gossipTimeliness := 0.0

				if observed > 0 {

					dcs = float64(matched) / float64(observed)

					diversityAvg = cand.DiversitySum / float64(observed)

				}

				if cand.HeartbeatTotal > 0 {

					uptime = float64(cand.HeartbeatGood) / float64(cand.HeartbeatTotal)

				}

				if cand.GossipTotal > 0 {

					gossipTimeliness = float64(cand.GossipTimely) / float64(cand.GossipTotal)

				}

				// `ban` stores the value produced by this operation.
				ban := "none"

				if cand.PermanentBan {

					ban = "permanent"

				} else if cand.BanUntil > 0 {

					ban = fmt.Sprintf("until %d", cand.BanUntil)

				}

				fmt.Printf("  %s observed=%d matched=%d dcs=%.4f uptime=%.2f%% diversity=%.2f%% gossip=%.2f%% strikes=%d ban=%s promoted=%v\n",

					id,

					observed,

					matched,

					dcs,

					uptime*100,

					diversityAvg*100,

					gossipTimeliness*100,

					cand.Strikes,

					ban,

					cand.Promoted,
				)

			}

			node.candidateMu.RUnlock()

		case "validator":

			fmt.Println("validator updates are disabled")

		case "send":

			if len(args) < 3 || len(args) > 4 {

				fmt.Println("usage: send <to> <amount> [coin]")

				continue

			}

			// `to` stores the value produced by this operation.
			to := args[1]

			// `amt` and `err` store the error produced by this operation.
			amt, err := strconv.Atoi(args[2])

			if err != nil || amt <= 0 {

				continue

			}

			// `coin` stores the value produced by this operation.
			coin := CoinSymbol

			if len(args) == 4 {

				coin = args[3]

			}

			// `reader` stores the value produced by this operation.
			reader := bufio.NewReader(os.Stdin)

			fmt.Print("Wallet password: ")

			// `password` stores the value produced by this operation.
			password, _ := reader.ReadString('\n')

			password = strings.TrimSpace(password)

			// `wallet` and `err` store the error produced by this operation.
			wallet, err := LoadSecureWallet()

			if err != nil {

				continue

			}

			// `tx` and `err` store the error produced by this operation.
			tx, err := BuildSignedTxSecure(

				wallet,

				password,

				to,

				amt,

				0,

				coin,
			)

			if err != nil {

				continue

			}

			// `body` stores the value produced by this operation.
			body, _ := json.Marshal(tx)

			// `resp` and `err` store the error produced by this operation.
			resp, err := http.Post(

				"http://localhost:8080/sendTx",

				"application/json",

				bytes.NewReader(body),
			)

			if err != nil {

				continue

			}

			_ = resp.Body.Close()

		case "stake":

			if len(args) < 3 || len(args) > 6 {

				fmt.Println("usage: stake <validator_id> <amount> [lock_epochs|coin|validator_pubkey] [coin|validator_pubkey] [validator_pubkey]")

				continue

			}

			// `validatorID` stores whether the related condition is satisfied.
			validatorID := strings.TrimSpace(args[1])

			// `amt` and `err` store the error produced by this operation.
			amt, err := strconv.Atoi(args[2])

			if err != nil || amt <= 0 {

				fmt.Println("invalid amount")

				continue

			}

			// `lockEpochs` stores the synchronization state protecting shared data.
			lockEpochs := DefaultStakeLockEpochs

			// `coin` stores the value produced by this operation.
			coin := CoinSymbol
			// `validatorPubKey` stores whether the related condition is satisfied.
			validatorPubKey := ""
			// `invalidStakeArg` stores the current position in the related collection.
			invalidStakeArg := false

			// `extra` tracks the current values while iterating.
			for _, extra := range args[3:] {

				extra = strings.TrimSpace(extra)

				if extra == "" {

					continue

				}

				// `v` and `err` store the error produced by this operation.
				if v, err := strconv.ParseUint(extra, 10, 64); err == nil {

					lockEpochs = v

					continue

				}

				// `normalized` stores the value produced by this operation.
				if normalized := normalizeConsensusPubKeyHex(extra); normalized != "" {

					validatorPubKey = normalized

					continue

				}

				// `normCoin` stores the value produced by this operation.
				normCoin := normalizeCoin(extra)

				if isProtocolCoinAllowed(normCoin) {

					coin = normCoin

					continue

				}

				fmt.Println("invalid stake argument:", extra)
				invalidStakeArg = true
				break

			}
			if invalidStakeArg {
				continue
			}

			fmt.Print("Wallet password: ")

			// `password` stores the value produced by this operation.
			password, _ := reader.ReadString('\n')

			password = strings.TrimSpace(password)

			// `wallet` and `err` store the error produced by this operation.
			wallet, err := LoadSecureWallet()

			if err != nil {

				fmt.Println("secure wallet not found")

				continue

			}

			// `currentNonce` stores the value produced by this operation.
			currentNonce := getNonce(node.Ledger, wallet.Address)

			// `tx` and `err` store the error produced by this operation.
			tx, err := BuildSignedStakeTxSecure(

				wallet,

				password,

				validatorID,

				validatorPubKey,

				amt,

				currentNonce,

				coin,

				lockEpochs,
			)

			if err != nil {

				fmt.Println("stake tx build failed:", err)

				continue

			}

			if !node.ReceiveTransaction(tx) {

				fmt.Println("stake transaction rejected")

				continue

			}

			fmt.Printf("stake tx accepted | id=%s validator=%s amount=%d lock_epochs=%d coin=%s validator_pubkey=%s\n",

				tx.ID,

				validatorID,

				amt,

				lockEpochs,

				tx.Coin,

				strings.TrimSpace(tx.ValidatorPubKey),
			)

		case "unstake":

			if len(args) < 3 || len(args) > 4 {

				fmt.Println("usage: unstake <validator_id> <amount> [coin]")

				continue

			}

			// `validatorID` stores whether the related condition is satisfied.
			validatorID := strings.TrimSpace(args[1])

			// `amt` and `err` store the error produced by this operation.
			amt, err := strconv.Atoi(args[2])

			if err != nil || amt <= 0 {

				fmt.Println("invalid amount")

				continue

			}

			// `coin` stores the value produced by this operation.
			coin := CoinSymbol

			if len(args) == 4 {

				coin = args[3]

			}

			fmt.Print("Wallet password: ")

			// `password` stores the value produced by this operation.
			password, _ := reader.ReadString('\n')

			password = strings.TrimSpace(password)

			// `wallet` and `err` store the error produced by this operation.
			wallet, err := LoadSecureWallet()

			if err != nil {

				fmt.Println("secure wallet not found")

				continue

			}

			// `currentNonce` stores the value produced by this operation.
			currentNonce := getNonce(node.Ledger, wallet.Address)

			// `tx` and `err` store the error produced by this operation.
			tx, err := BuildSignedUnstakeTxSecure(

				wallet,

				password,

				validatorID,

				amt,

				currentNonce,

				coin,
			)

			if err != nil {

				fmt.Println("unstake tx build failed:", err)

				continue

			}

			if !node.ReceiveTransaction(tx) {

				fmt.Println("unstake transaction rejected")

				continue

			}

			fmt.Printf("unstake tx accepted | id=%s validator=%s amount=%d coin=%s\n",

				tx.ID,

				validatorID,

				amt,

				tx.Coin,
			)

		case "exit", "quit":

			return

		default:

		}

	}

}

// printCLIHelp implements the print cli help helper.
func printCLIHelp() {

	fmt.Print(`Available commands:



  help              Show this help



  status            Node status



  balance <addr> [coin]  Check balance



  send <to> <amount> [coin]  Send transaction

  stake <validator_id> <amount> [lock_epochs|coin|validator_pubkey] [coin|validator_pubkey] [validator_pubkey]  Stake coins for validator

  unstake <validator_id> <amount> [coin]  Unstake coins from validator


  validatorset      Show current validator set + hash + pending updates



  validator-pending Show pending validator updates



  candidates        Show candidate admission status



  validators        List active validators

  network           Open network CLI

  exit              Quit CLI



`)

}

// warnIfSelfHealMinPeersImpossible implements the warn if self heal min peers impossible helper.
func warnIfSelfHealMinPeersImpossible(selfBaseAddr string) {
	if !SelfHealEnabled || SelfHealMinPeers < 1 {
		return
	}
	// `combined` stores the value produced by this operation.
	combined := append([]string{}, ConfigSeeds...)
	combined = append(combined, ConfigPersistentPeers...)
	if len(combined) == 0 {
		return
	}
	// `unique` stores the value produced by this operation.
	unique := make(map[string]struct{}, len(combined))
	// `addr` tracks the address used by this operation.
	for _, addr := range combined {
		// `base` stores the value produced by this operation.
		base := strings.TrimSpace(stripP2PComponent(addr))
		if base == "" {
			base = strings.TrimSpace(addr)
		}
		if base == "" {
			continue
		}
		unique[base] = struct{}{}
	}
	if strings.TrimSpace(selfBaseAddr) != "" {
		delete(unique, strings.TrimSpace(selfBaseAddr))
	}
	// `maxPeers` stores the value produced by this operation.
	maxPeers := len(unique)
	if maxPeers == 0 {
		return
	}
	if SelfHealMinPeers > maxPeers {
		fmt.Printf("[WARN] self_heal_min_peers=%d exceeds configured peers=%d; local cluster can only reach %d peers from p2p.seeds/persistent_peers. Consider network.self_heal_min_peers=%d\n",
			SelfHealMinPeers,
			maxPeers,
			maxPeers,
			maxPeers,
		)
	}
}

// StartNode starts node.
func StartNode(

	nodeID string,

	dataDir string,

	listenPort int,

	peerMultiaddrs []string,

	role string,

) *Node {
	// `requestedRole` stores the request data being processed.
	requestedRole := normalizeRequestedNodeRole(role)
	role = requestedRole

	// =====================================================

	// =====================================================

	nodeDBPath := nodeDataPath(dataDir, nodeID)

	// `err` stores the error produced by this operation.
	if err := os.MkdirAll(nodeDBPath, 0700); err != nil {
		log.Printf("[WARN] failed to create node data dir %s: %v", nodeDBPath, err)
		// `fallbackPath` stores the value produced by this operation.
		fallbackPath := filepath.Join(os.TempDir(), "msc-chain", "node_"+nodeID)
		// `mkErr` stores the error produced by this operation.
		if mkErr := os.MkdirAll(fallbackPath, 0700); mkErr != nil {
			log.Printf("[WARN] fallback node data dir creation failed %s: %v", fallbackPath, mkErr)
		} else {
			log.Printf("[WARN] using fallback node data dir: %s", fallbackPath)
			nodeDBPath = fallbackPath
		}

	}
	if err := ensureNodeRuntimeSkeleton(nodeDBPath, nodeID); err != nil {
		log.Printf("[WARN] failed to prepare node runtime skeleton %s: %v", nodeDBPath, err)
	}

	// `absPath` and `err` store the error produced by this operation.
	absPath, err := filepath.Abs(nodeDBPath)

	if err != nil {
		log.Printf("[WARN] failed to resolve absolute node path for %s: %v", nodeDBPath, err)
		absPath = nodeDBPath

	}

	// `startupSelfAddr` stores the address used by this operation.
	startupSelfAddr := fmt.Sprintf("/ip4/0.0.0.0/tcp/%d", listenPort)
	if ConfigP2PListenAddr != "" {
		startupSelfAddr = ConfigP2PListenAddr
	}
	// `startupSelfBase` stores the value produced by this operation.
	startupSelfBase := stripP2PComponent(startupSelfAddr)
	warnIfSelfHealMinPeersImpossible(startupSelfBase)
	// `dropSelfPeerAddr` stores the address used by this operation.
	dropSelfPeerAddr := func(peers []string) []string {
		if startupSelfBase == "" || len(peers) == 0 {
			return peers
		}
		// `out` stores the result produced by this operation.
		out := make([]string, 0, len(peers))
		// `addr` tracks the address used by this operation.
		for _, addr := range peers {
			if stripP2PComponent(addr) == startupSelfBase {
				continue
			}
			out = append(out, addr)
		}
		return out
	}

	// `persistedPeers` stores the value produced by this operation.
	persistedPeers := loadPersistentPeers(dataDir, nodeID)
	// On testnet/dev networks validators may regenerate keys frequently, which
	// also rotates libp2p peer IDs. In that mode prefer observed/persisted peers
	// so stale config.toml /p2p/ IDs do not get re-pinned on every restart.
	//
	// On non-testnet, keep config IDs authoritative for stricter operator control.
	trustedPeers := make([]string, 0, len(ConfigSeeds)+len(ConfigPersistentPeers)+len(persistedPeers))
	if PersistPeerIDRefresh {
		trustedPeers = append(trustedPeers, persistedPeers...)
	}
	if !IsTestnet || !PersistPeerIDRefresh {
		trustedPeers = append(trustedPeers, ConfigSeeds...)
		trustedPeers = append(trustedPeers, ConfigPersistentPeers...)
	}
	// `trustedPeers` and `startupPeerReconcileEvents` store the value produced by this operation.
	trustedPeers, startupPeerReconcileEvents := reconcileLocalhostPeerIDsWithPersisted(trustedPeers, persistedPeers)
	// `event` tracks the current values while iterating.
	for _, event := range startupPeerReconcileEvents {
		log.Printf("[PEER-BOOTSTRAP-RECONCILE] base=%s old=%s new=%s source=peers.json",
			event.Base,
			event.OldPeerID,
			event.NewPeerID,
		)
	}
	peerMultiaddrs = dropSelfPeerAddr(sanitizePeerListWithPreferred(peerMultiaddrs, trustedPeers))
	if PersistPeerIDRefresh && len(persistedPeers) > 0 {
		peerMultiaddrs = dropSelfPeerAddr(sanitizePeerListWithPreferred(mergePeerLists(peerMultiaddrs, persistedPeers), trustedPeers))
	}
	if PersistPeerIDRefresh {
		// `err` stores the error produced by this operation.
		if err := savePersistentPeers(dataDir, nodeID, peerMultiaddrs); err != nil && DebugNet {
			fmt.Printf("WARN failed to persist sanitized peers list: %v\n", err)
		}
	}

	// =====================================================

	// =====================================================

	vKey := LoadOrCreateValidatorKey(nodeID, absPath)
	// `keyLoaded` stores the key used to access the related value.
	keyLoaded := isValidatorKeyUsable(vKey)
	// `keyHealth` stores the key used to access the related value.
	keyHealth := CollectValidatorKeyHealth(nodeID, absPath, vKey)
	if requestedRole == "auto" {
		// `resolvedRole` and `roleReason` store the result produced by this operation.
		resolvedRole, roleReason := resolveAutoNodeRole(requestedRole, keyLoaded)
		role = resolvedRole
		log.Printf("[ROLE-AUTO] id=%s resolved=%s reason=%s key_loaded=%t", nodeID, role, roleReason, keyLoaded)
	} else {
		role = normalizeNodeRole(requestedRole)
	}
	if role == "validator" && !keyLoaded {
		if ValidatorFailOnKeyUnavailable {
			log.Printf("[FATAL] validator key unavailable for %s; startup aborted (validators.fail_on_key_unavailable=true)", nodeID)
			return nil
		}
		log.Printf("[WARN] validator key unavailable for %s; switching role to full observer mode", nodeID)
		role = "full"
	}
	applyFullNodeSafeSyncProfile(role)
	// `keyFP` stores the key used to access the related value.
	keyFP := validatorKeyFingerprint(vKey.PublicKey)
	if keyLoaded {
		log.Printf("[IDENTITY] key_loaded=true validator=%s fingerprint=%s expected=%s match=%t source=%s mode=%s",
			nodeID,
			keyFP,
			keyHealth.Expected,
			keyHealth.Match,
			keyHealth.Source,
			keyHealth.Mode,
		)
	} else {
		log.Printf("[IDENTITY] key_loaded=false validator=%s fingerprint=unavailable expected=%s match=%t source=%s mode=%s",
			nodeID,
			keyHealth.Expected,
			keyHealth.Match,
			keyHealth.Source,
			keyHealth.Mode,
		)
	}

	validatorID, validatorIdentityPath, validatorIdentityErr := writeValidatorIdentityFile(absPath, nodeID, vKey)
	if validatorIdentityErr != nil {
		log.Printf("[WARN] failed to write validator identity: %v", validatorIdentityErr)
	} else if validatorID != "" {
		log.Printf("[IDENTITY] validator_id=%s derived_from=validator_public_key path=%s", validatorID, validatorIdentityPath)
	}
	nodeWallet, nodeWalletPath, nodeWalletErr := loadOrCreateNodeWallet(absPath)
	if nodeWalletErr != nil {
		log.Printf("[WARN] failed to load/create node wallet identity: %v", nodeWalletErr)
	} else {
		log.Printf("[IDENTITY] wallet_address=%s path=%s", displayAddress(nodeWallet.Address), nodeWalletPath)
	}

	// =====================================================

	// =====================================================

	db := OpenNodeDB(absPath)

	// =====================================================

	// =====================================================

	bc := Blockchain{}

	// `moniker` stores the value produced by this operation.
	moniker := "MSC-Node-" + nodeID

	if ConfigMoniker != "" {

		moniker = ConfigMoniker

	}

	// `selfAddr` stores the address used by this operation.
	selfAddr := startupSelfAddr

	// `seedNodes` stores the value produced by this operation.
	seedNodes := ConfigSeeds

	if len(seedNodes) == 0 {

		seedNodes = peerMultiaddrs

	}

	// =====================================================

	// =====================================================

	node := &Node{

		ID: nodeID,

		NetworkID: normalizeNodeIdentityID(nodeID),

		ValidatorID: validatorID,

		WalletAddress: nodeWallet.Address,

		WalletPublicKey: hex.EncodeToString(nodeWallet.PublicKey),

		Ledger:          NewLedger(),
		ExecutionLedger: NewLedger(),

		Wallet: nodeWallet,

		Blockchain: &bc,

		ValidatorKey: vKey,

		DataDir: dataDir,

		DB: db,

		Role: role,

		SelfAddr: selfAddr,

		SeenTxIDs: make(map[string]bool),

		SeenBlockHashes: make(map[string]bool),

		ForkBlocks: make(map[uint64][]Block),

		Mempool: Mempool{

			SeenTxIDs: make(map[string]bool),
		},

		ProposalHistory: make(map[uint64]string),

		MisbehaviorLog: make(map[string][]SlashEvidence),

		shutdownCh: make(chan struct{}),

		closeChan: make(chan struct{}),

		wg: sync.WaitGroup{},

		PeersLibp2p: make([]peer.ID, 0),

		Config: &NodeConfig{

			ChainID: protocolChainID(),

			Moniker: moniker,

			Seeds: seedNodes,

			PersistentPeers: peerMultiaddrs,

			MinPeers: MinimumPeers,

			MaxPeers: MaxPeers,
		},

		PeerDiscovery: &PeerDiscovery{

			seedNodes: seedNodes,

			isRunning: false,
		},

		peerSetHash: make(map[string]string),

		peerTipHash: make(map[string]string),

		peerHashMatch: make(map[string]bool),

		peerHelloOK: make(map[string]bool),

		nodeIDToPeer: make(map[string]string),

		peerToValidator: make(map[string]string),

		validatorToPeer: make(map[string]string),

		peerRole: make(map[string]string),

		peerAckHeight: make(map[string]uint64),

		peerDriftState:        make(map[string]PeerDriftState),
		livenessReasonLogLast: make(map[string]time.Time),

		peerSyncOnlyUntil: make(map[string]time.Time),

		peerSyncOnlyClass: make(map[string]string),

		peerSyncOnlyLastDropLog: make(map[string]time.Time),

		noBlockLogAt: make(map[string]time.Time),

		peerSuspectAt: make(map[string]time.Time),

		peerHelloSentAt: make(map[string]time.Time),

		peerConnectedAt: make(map[string]time.Time),

		peerFlapTimes: make(map[string][]time.Time),

		peerGraftAt: make(map[string]time.Time),

		quarantineUntil: make(map[string]time.Time),

		peerDialFailures: make(map[string]int),

		peerDialNext: make(map[string]time.Time),

		peerSubnet: make(map[string]string),

		peerASN: make(map[string]string),

		peerOutbound: make(map[string]bool),

		peerHelloNonces: make(map[string]time.Time),

		peerResourceWindows: make(map[string]PeerResourceWindow),

		peerConnectWindows: make(map[string]PeerResourceWindow),

		connectedPeers: make(map[string]bool),

		validatorSuspect: make(map[string]time.Time),

		connectingPeers: make(map[string]bool),

		allowedPeerIDs: make(map[string]bool),

		pendingValidators: make(map[string]uint64),

		pendingValidatorRemovals: make(map[string]uint64),

		epochValidators: make(map[uint64][]string),

		frozenValidatorsByHeight:    make(map[uint64][]string),
		frozenValidatorHashByHeight: make(map[uint64]string),
		committeeByHeight:           make(map[uint64][]string),
		committeeHashByHeight:       make(map[uint64]string),
		committeeLiveByHeight:       make(map[uint64]map[string]bool),
		safeModeUntilByHeight:       make(map[uint64]time.Time),
		safeModeWindowByHeight:      make(map[uint64]time.Duration),
		safeModeObservedDelays:      make([]time.Duration, 0, 64),

		queuedValidatorSetUpdates: make(map[uint64]ValidatorSetUpdate),

		candidates:                       make(map[string]*CandidateStatus),
		transitionBarrierPauseLast:       make(map[string]time.Time),
		transitionBarrierRetryStateByKey: make(map[transitionBarrierRetryKey]transitionBarrierRetryState),
		onboardingTracker:                make(map[string]ValidatorActivationTracker),
		onboardingLogLast:                make(map[string]time.Time),

		invalidProposerSeen:         make(map[uint64]map[string]int),
		invalidProposerEvidenceSeen: make(map[string]time.Time),
		invalidProposerStrikes:      make(map[string]ExecMismatchTracker),
		invalidProposerPeerStrikes:  make(map[string]ExecMismatchTracker),
		doubleProposalEvidenceSeen:  make(map[string]time.Time),

		execResults: make(map[string]map[string]ExecutionResult),

		execBroadcasted: make(map[uint64]map[string]bool),

		execSignerSeen: make(map[uint64]map[string]map[string]bool),

		execBroadcastedByValidator: make(map[uint64]map[string]map[string]bool),

		localExecVoteByRound: make(map[uint64]map[uint32]string),

		pendingBlocks: make(map[string]Block),

		queuedExecVotes: make(map[string][]ExecutionResultMsg),

		acceptedProposal: make(map[string]string),

		acceptedProposalBlocks: make(map[string]Block),

		quorumLockedProposal: make(map[string]string),

		execVoteSeen: make(map[string]time.Time),

		execMismatch: make(map[string]ExecMismatchTracker),

		leaderBlocks:              make(map[uint64]Block),
		lastProposedRoundByHeight: make(map[uint64]uint32),

		committed: make(map[uint64]string),

		commitVotes: make(map[uint64]map[string]map[string]struct{}),

		commitVoted: make(map[uint64]map[string]string),

		logicalClock: LogicalTimeForEpoch(1),

		heightReports: make(map[uint64]map[string]time.Time),

		validatorReportHeight: make(map[string]uint64),

		validatorOfflineSince:   make(map[string]time.Time),
		validatorRejoin:         make(map[string]ValidatorRejoinState),
		validatorKeyFingerprint: keyFP,
		lastValidatorKeyHealth:  keyHealth,
		lastKeyAuditAt:          time.Now(),
		coreRegistryEntries:     make(map[string]CoreRegistryEntry),
		coreRegistryState: CoreRegistryState{
			EnforcementMode: normalizeCoreRegistryEnforcementMode(CoreRegistryEnforcementMode),
		},
		coreActivationStatus: CoreActivationStatus{
			NodeID: normalizeValidatorID(nodeID),
			Status: "none",
			Reason: "not_initialized",
		},

		snapshotOfferSent:   make(map[string]uint64),
		snapshotOfferSentAt: make(map[string]time.Time),

		snapshotExecutionLedgerByHeight: make(map[uint64]Ledger),

		snapshotMetaGossipCache:  make(map[string]SnapshotMetaGossip),
		snapshotChunkGossipCache: make(map[string]SnapshotChunkGossip),
		snapshotProofs:           make(map[string]map[string]SnapshotProof),
		snapshotProofProviders:   make(map[string]map[string]string),
		snapshotAnchorCache:      make(map[uint64]SnapshotAnchorCache),
		snapshotVotes:            make(map[string]map[string]struct{}),
		snapshotCatalog:          make(map[uint64]SnapshotCatalogEntry),

		snapshotCache:               make(map[string]*StateSnapshot),
		snapshotSession:             SnapshotSession{Stage: SnapshotSyncStageIdle, Votes: make(map[string]SnapshotVote)},
		lateJoinAuthority:           LateJoinAuthorityState{},
		syncPeerScores:              make(map[string]*SyncPeerScore),
		syncLastProgressAt:          time.Now(),
		validatorStartupCheckOK:     true,
		validatorStartupCheckReason: "not_checked",
	}
	// `rootCtx` and `rootCancel` store the context controlling this operation.
	rootCtx, rootCancel := context.WithCancel(context.Background())
	node.SetRootContext(rootCtx, rootCancel)
	node.ensureDedicatedThreads()
	node.loadPeerReputation()
	node.loadPeerHelloNonces()

	// `addr` tracks the address used by this operation.
	for _, addr := range peerMultiaddrs {

		if addr == "" {

			continue

		}

		// `maddr` and `err` store the error produced by this operation.
		if maddr, err := ma.NewMultiaddr(addr); err == nil {

			// `info` and `err` store the error produced by this operation.
			if info, err := peer.AddrInfoFromP2pAddr(maddr); err == nil {

				// `peerID` stores the value produced by this operation.
				peerID := info.ID.String()

				if strings.HasPrefix(peerID, "12D3") {

					node.allowedPeerIDs[peerID] = true

				}

			}

		}

	}

	// =====================================================

	// =====================================================

	node.validatorStatus = make(map[string]*ValidatorStatus)

	node.validatorStatus = make(map[string]*ValidatorStatus)

	// =====================================================

	// =====================================================

	// =====================================================

	// =====================================================

	if ledger, err := LoadNodeLedger(nodeID, dataDir); err == nil {
		node.Ledger = ledger
		node.setExecutionLedger(ledger)
	} else if !errors.Is(err, os.ErrNotExist) && DebugConsensus {
		fmt.Printf("[WARN] ledger load failed: %v\n", err)
	}
	// `err` stores the error produced by this operation.
	if err := node.loadMisbehaviorEvidenceFromDB(); err != nil && DebugConsensus {
		fmt.Printf("WARN misbehavior evidence load failed: %v\n", err)
	}
	// `err` stores the error produced by this operation.
	if err := node.loadConsensusEvidenceSeenFromDB(); err != nil && DebugConsensus {
		fmt.Printf("WARN consensus evidence load failed: %v\n", err)
	}

	// =====================================================

	// =====================================================

	startupChainTruncated := false
	// `startupRecoverySnapshot` stores the value used by this operation.
	var startupRecoverySnapshot *StateSnapshot
	// `startupRecoveryAnchor` stores the value used by this operation.
	var startupRecoveryAnchor Block
	// `blocks` stores the block data handled by this operation.
	blocks := node.LoadBlocksFromDB()
	// `sanitized`, `tip`, and `err` store the error produced by this operation.
	if sanitized, tip, err := sanitizeContiguousLoadedBlocks(blocks); err != nil {
		// `snap`, `anchor`, and `reason` store the value produced by this operation.
		if snap, anchor, reason := node.loadBestAnchoredStartupRecoverySnapshot(); snap != nil {
			startupRecoverySnapshot = snap
			startupRecoveryAnchor = anchor
			log.Printf("[SNAPSHOT-RECOVERY] preserve_verified_sparse_anchor height=%d tip=%d hash=%s",
				snap.Height, tip, ShortHash(snap.BlockHash))
		} else if strings.TrimSpace(reason) != "" {
			log.Printf("[SNAPSHOT-RECOVERY] no_verified_sparse_anchor tip=%d reason=%s", tip, strings.TrimSpace(reason))
		}
		blocks = sanitized
		startupChainTruncated = true
		log.Printf("[CHAIN-AUDIT] startup_truncate_sparse_blocks tip=%d reason=%s", tip, err)
		node.pruneBlocksAboveHeight(tip)
		// `err` stores the error produced by this operation.
		if err := node.pruneFinalizedHashInvariantsAboveHeight(tip); err != nil {
			log.Printf("[WARN] finalized hash invariant prune failed height=%d err=%v", tip, err)
		}
		if startupRecoverySnapshot != nil {
			node.StoreBlock(startupRecoveryAnchor)
		}
	}

	if len(blocks) > 0 {

		node.Blockchain.ReplaceChain(blocks)
		// `loadedBlocks` stores the value produced by this operation.
		loadedBlocks := append([]Block(nil), blocks...)
		node.SafeGo("startup_block_file_backfill", func() {
			node.backfillBlockFiles(loadedBlocks)
		})
		// `badHeight` and `rewound` store the value produced by this operation.
		if badHeight, rewound := node.auditAndRewindInvalidQuorumEvidence("startup"); badHeight > 0 {
			if rewound {
				startupChainTruncated = true
				log.Printf("[QUORUM-AUDIT] startup_rewind_applied bad_height=%d tip=%d", badHeight, node.Blockchain.Height())
			} else {
				log.Printf("[QUORUM-AUDIT] startup_rewind_failed bad_height=%d tip=%d", badHeight, node.Blockchain.Height())
			}
		}

	}

	node.restoreCommittedHeightFromChain()

	// Load latest snapshot before deciding whether to apply genesis.
	// Startup hardening:
	// - never hydrate validator-set state from stale snapshots below chain tip
	// - at equal height, require block-hash match before using snapshot metadata
	if node.DB != nil && node.DB.State != nil {
		if startupRecoverySnapshot == nil {
			// `snap` and `err` store the error produced by this operation.
			snap, err := node.LoadBestSnapshot()
			if err == nil && snap != nil {
				// `ok` stores whether the related condition is satisfied.
				if ok, _ := node.canApplyUnanchoredStartupRecoverySnapshot(snap, startupChainTruncated); ok {
					startupRecoverySnapshot = snap
				}
			}
		}
		// `scrubbed` and `scrubErr` store the error produced by this operation.
		if scrubbed, scrubErr := node.scrubInvalidStoredSnapshots(node.Blockchain.Height()); scrubErr != nil {
			log.Printf("[WARN] startup snapshot scrub failed: %v", scrubErr)
		} else if scrubbed > 0 {
			log.Printf("[SNAPSHOT-SCRUB] removed=%d tip=%d", scrubbed, node.Blockchain.Height())
		}
		if startupRecoverySnapshot == nil {
			// `pruned` and `pruneErr` store the error produced by this operation.
			if pruned, pruneErr := node.pruneStoredSnapshotsAboveHeight(node.Blockchain.Height()); pruneErr != nil {
				log.Printf("[WARN] startup future snapshot prune failed: %v", pruneErr)
			} else if pruned > 0 {
				log.Printf("[SNAPSHOT-SCRUB] pruned_future=%d tip=%d chain_truncated=%t", pruned, node.Blockchain.Height(), startupChainTruncated)
			}
		} else {
			log.Printf("[SNAPSHOT-SCRUB] preserve_future_recovery_import height=%d tip=%d chain_truncated=%t",
				startupRecoverySnapshot.Height, node.Blockchain.Height(), startupChainTruncated)
		}

		// `snap` and `err` store the error produced by this operation.
		if startupRecoverySnapshot != nil {
			node.applyStartupBestSnapshot(startupRecoverySnapshot, startupChainTruncated)
		} else if snap, err := node.LoadBestSnapshot(); err == nil && snap != nil {
			node.applyStartupBestSnapshot(snap, startupChainTruncated)

		} else if err != nil && !errors.Is(err, ErrKeyNotFound) {

			// Non-fatal; continue with block-based state.

		}

	}

	// `err` stores the error produced by this operation.
	if err := node.ensureNoDTLContractHistory(); err != nil {
		log.Printf("[FATAL] %v", err)
		return nil
	}

	// `genesisPath` stores the value produced by this operation.
	genesisPath := resolveGenesisPath(node.DataDir)

	// `genesisDisk` and `gErr` store the error produced by this operation.
	genesisDisk, gErr := loadGenesisFromDisk(genesisPath)

	if gErr != nil {

		log.Printf("[WARN] GENESIS READ FAILED: %v", gErr)
		genesisDisk = &Genesis{}

	}

	// State boot rule: if we already have height, do NOT apply genesis.

	if node.Blockchain.Height() == 0 {

		// `genesis` and `err` store the error produced by this operation.
		genesis, err := LoadGenesisFromFile(

			node.DB,

			node.Blockchain,

			genesisPath,
		)

		if err != nil {

		}

		genesisDisk = genesis

	}

	if ConfigChainID != "" && genesisDisk != nil && genesisDisk.ChainID != "" && ConfigChainID != genesisDisk.ChainID {

		fmt.Printf("WARN config chain_id=%s does not match genesis chain_id=%s (genesis is authoritative)\n",

			ConfigChainID,

			genesisDisk.ChainID,
		)

	}

	applyGenesisRuntimePolicy(genesisDisk)
	node.installGenesisValidatorIDs(genesisDisk)
	node.bootstrapGenesisValidators(genesisDisk)
	node.ensureGenesisCommittedValidatorRegistrySnapshot("startup")
	if node.Role == "validator" && !ValidatorAllowIdentityRotationOnExistingChain && isValidatorKeyUsable(vKey) {
		// `selfID` stores the value produced by this operation.
		selfID := node.localConsensusValidatorIDForSet(node.GenesisValidators)
		// `genesisPK` and `ok` store whether the related condition is satisfied.
		if genesisPK, ok := GenesisValidatorPubKeys[selfID]; ok && len(genesisPK) == ed25519.PublicKeySize && !bytes.Equal(genesisPK, vKey.PublicKey) {
			// `expectedFP` stores the value produced by this operation.
			expectedFP := validatorKeyFingerprint(genesisPK)
			log.Printf("[FATAL] duplicate validator node id rejected id=%s expected_genesis_fingerprint=%s local_fingerprint=%s reason=genesis_validator_key_mismatch",
				selfID,
				expectedFP,
				keyFP,
			)
			return nil
		}
	}
	node.ensureRegistrySnapshot(uint64(node.Blockchain.Height()), "startup")
	node.replayMisbehaviorSlashingThresholds("startup")
	// `chainHeight` stores the value produced by this operation.
	if chainHeight := uint64(node.Blockchain.Height()); chainHeight > 0 {
		node.SafeGo("startup_tip_snapshot_repair", func() {
			// `source` and `ok` store whether the related condition is satisfied.
			if source, ok := node.ensureCommittedTipStateSnapshot(chainHeight, "startup"); !ok {
				// `key` stores the key used to access the related value.
				key := fmt.Sprintf("startup_snapshot_unresolved:%d", chainHeight)
				if node.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
					log.Printf("[WARN] startup committed snapshot unresolved height=%d", chainHeight)
				}
			} else if source == "tip_create_snapshot_repair" {
				// `key` stores the key used to access the related value.
				key := fmt.Sprintf("startup_snapshot_repair:%d", chainHeight)
				if node.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
					log.Printf("[SNAPSHOT-REPAIR] height=%d source=%s reason=startup", chainHeight, source)
				}
			}
		})
	}

	if len(node.GenesisValidators) > 0 {

		node.validatorSetMu.Lock()

		// Track height only; authoritative validator set is resolved from
		// consensus chain/snapshot state, not permanent in-memory lists.
		if node.Blockchain.Height() == 0 {
			node.validatorSetHeight = uint64(node.Blockchain.Height())
		}

		node.validatorSetMu.Unlock()

	}

	node.logicalMu.Lock()

	node.logicalClock = LogicalTimeForEpoch(node.Blockchain.Height() + 1)

	node.logicalMu.Unlock()

	// `startupConsensusRecovery` stores the value produced by this operation.
	startupConsensusRecovery := func() {
		node.replayValidatorFreezeJournal()
		node.syncFrozenValidatorSetHashesFromChain()
		node.snapshotEpochValidators(node.currentEpoch())
		node.applyStartupConsensusRecovery()
		// `chainHeight` stores the value produced by this operation.
		if chainHeight := uint64(node.Blockchain.Height()); node.recoverDueValidatorTransitionsAtStartup(chainHeight) {
			log.Printf("[STARTUP-RECOVERY] applied due validator transition height=%d", chainHeight)
		}
	}
	if node.Role == "validator" {
		startupConsensusRecovery()
	} else {
		node.SafeGo("startup_consensus_recovery", startupConsensusRecovery)
	}
	// `err` stores the error produced by this operation.
	if err := node.initializeCoreRegistry(); err != nil {
		log.Printf("[FATAL] core registry initialization failed for %s: %v", node.ID, err)
		return nil
	}
	// `expectedCoreFP` and `ok` store whether the related condition is satisfied.
	if expectedCoreFP, ok := node.coreExpectedFingerprintForID(node.ID); ok {
		if keyFP == "" || !strings.EqualFold(expectedCoreFP, keyFP) {
			log.Printf("[WARN] validator signer unavailable for %s: core registry fingerprint mismatch expected=%s got=%s",
				node.ID,
				expectedCoreFP,
				keyFP,
			)
			if role == "validator" && ValidatorFailOnKeyUnavailable {
				log.Printf("[FATAL] validator key unavailable for %s; startup aborted (core registry fingerprint mismatch)", node.ID)
				return nil
			}
		}
	}
	if node.Role == "validator" {
		// `waitHeight` stores the value produced by this operation.
		waitHeight := node.localCommittedHistoryHeight()
		node.setValidatorStartupCheckStatus(false, waitHeight, "", "", "startup_validator_set_check_pending")
		node.SafeGo("startup_validator_set_self_check", func() {
			_, _ = node.startupValidatorSetSelfCheck()
		})
	}

	// =====================================================

	// =====================================================

	selfHeight := uint64(node.Blockchain.Height())

	// `persistedValidators` stores the value produced by this operation.
	persistedValidators := loadPersistentValidators(dataDir, nodeID)

	if len(persistedValidators) > 0 {

		// `stale` stores the value produced by this operation.
		stale := time.Unix(0, 0)

		node.validatorMu.Lock()

		// `vid` tracks the current values while iterating.
		for _, vid := range persistedValidators {
			vid = normalizeValidatorID(vid)
			if vid == "" {
				continue
			}

			// `st` and `ok` store whether the related condition is satisfied.
			st, ok := node.validatorStatus[vid]

			if !ok {

				st = &ValidatorStatus{}

				node.validatorStatus[vid] = st

			}

			st.Height = selfHeight

			// Persisted validators are NOT considered live until a heartbeat arrives.

			st.LastSeen = stale

		}

		node.validatorMu.Unlock()

	}

	// `selfID` stores the value produced by this operation.
	selfID := normalizeValidatorID(nodeID)
	node.validatorStatus[selfID] = &ValidatorStatus{

		Height: selfHeight,

		LastSeen: time.Now(),
		Active:   true,
	}

	node.validatorStatus[selfID] = &ValidatorStatus{

		Height: selfHeight,

		LastSeen: time.Now(),
		Active:   true,
	}

	validatorPubKeysMu.Lock()
	ValidatorPubKeys[selfID] = vKey.PublicKey
	validatorPubKeysMu.Unlock()

	Participation[selfID] = &ParticipationScore{

		ValidBlocks: 10,

		InvalidBlocks: 0,

		LastSeen: time.Now(),

		CooldownUntil: 0,

		Reputation: 100,
	}

	// =====================================================

	// =====================================================

	node.Consensus = NewConsensusState(uint64(node.Blockchain.Height()))
	// `err` stores the error produced by this operation.
	if err := node.restoreConsensusSafetyState(); err != nil && DebugConsensus {
		fmt.Printf("WARN consensus safety restore failed: %v\n", err)
	}

	// =====================================================

	// =====================================================

	ctx := node.RootContext()

	// `authRequired` stores the value produced by this operation.
	authRequired := node.requiresWalletAuthCurrent(node.localConsensusValidatorID())
	if ConfigAuthRequireWallet && normalizeNodeRole(node.Role) == "validator" && !authRequired {
		fmt.Printf("Validator %s: wallet auth not required by current policy\n", node.ID)
	}

	if authRequired && node.restoreWalletAuthBinding() {
		log.Printf("[AUTH] restored wallet auth binding for node %s (same datadir/key identity)", node.ID)
	}

	// `authReadyCh` stores the value produced by this operation.
	authReadyCh := make(chan struct{})
	close(authReadyCh)
	if authRequired {
		log.Printf("Wallet auth required for validator activation; network starts immediately for node %s", node.ID)
	}

	// `startAfterAuth` stores the value produced by this operation.
	startAfterAuth := func(delay time.Duration, fn func()) {

		node.SafeGo("start_after_auth", func() {

			<-authReadyCh

			if delay > 0 {

				time.Sleep(delay)

			}

			fn()

		})

	}

	startAfterAuth(0, func() {

		// `err` stores the error produced by this operation.
		if err := node.initLibp2p(ctx, listenPort); err != nil {

			return

		}

		if node.Host == nil {

			return

		}

		if len(node.Host.Addrs()) > 0 {

			if ConfigP2PExternalAddr != "" {

				if ConfigP2PExternalHasPeerID {

					node.SelfAddr = ConfigP2PExternalAddr

				} else {

					node.SelfAddr = fmt.Sprintf("%s/p2p/%s", ConfigP2PExternalAddr, node.Host.ID())

				}

			} else {

				// `selfAddr` stores the address used by this operation.
				selfAddr := node.Host.Addrs()[0]
				// `advertised` stores the value produced by this operation.
				if advertised := selectAdvertisedHostAddr(node.Host.Addrs()); advertised != nil {
					selfAddr = advertised
				}
				node.SelfAddr = fmt.Sprintf(

					"%s/p2p/%s",

					selfAddr,

					node.Host.ID(),
				)

			}

		}

		// `err` stores the error produced by this operation.
		if err := node.initPubSubTopics(); err != nil {

		}

		node.setupProtocols()

		node.SafeGo("bootstrap_connect_peers", func() {

			time.Sleep(1 * time.Second)

			node.connectToPeers(ctx, peerMultiaddrs)

		})

		node.SafeGo("bootstrap_connect_pubsub", func() {

			time.Sleep(3 * time.Second)

			node.connectPubSubPeers()

		})

		node.SafeGoLoop("maintain_validator_mesh", 3*time.Second, func() {

			time.Sleep(6 * time.Second)

			node.maintainValidatorMesh(ctx)

		})

		node.SafeGoLoop("listen_validators", 3*time.Second, func() { node.listenValidators(ctx) })
		node.SafeGoLoop("listen_consensus", 3*time.Second, func() { node.listenConsensus(ctx) })
		node.SafeGoLoop("listen_snapshot_proofs", 3*time.Second, func() { node.listenSnapshotProofs(ctx) })

		node.SafeGoLoop("listen_blocks", 3*time.Second, func() { node.listenBlocks(ctx) })

		node.SafeGoLoop("listen_tx", 3*time.Second, func() { node.listenTx(ctx) })

		node.SafeGoLoop("monitor_peer_suspects", 3*time.Second, func() { node.monitorPeerSuspects() })

		node.SafeGoLoop("peer_hello_nonce_sweeper", 3*time.Second, func() { node.startPeerHelloNonceSweeper(ctx) })

		node.SafeGoLoop("consensus_memory_guard", 3*time.Second, func() { node.startConsensusMemoryGuard(ctx) })

		node.SafeGoLoop("monitor_goroutines", 3*time.Second, func() { monitorGoroutines(ctx, node) })

		node.SafeGoLoop("self_heal", 3*time.Second, func() { node.startSelfHeal(ctx) })

		node.SafeGoLoop("autoheal_manager", 3*time.Second, func() { node.startAutoHealManager(ctx) })

		node.SafeGoLoop("late_join_sync_loop", 3*time.Second, func() { node.startLateJoinSyncLoop(ctx) })

		node.SafeGoLoop("sync_stall_watchdog", 3*time.Second, func() { node.startSyncStallWatchdog(ctx) })

		node.SafeGoLoop("history_backfill_loop", 3*time.Second, func() { node.startHistoryBackfillLoop(ctx) })

		node.SafeGoLoop("snapshot_delta_worker", 3*time.Second, func() { node.startSnapshotDeltaWorker(ctx) })

		node.SafeGoLoop("snapshot_create_worker", 3*time.Second, func() { node.startSnapshotCreateWorker(ctx) })

		node.SafeGoLoop("snapshot_proof_signer", 3*time.Second, func() { node.startSnapshotProofSigner(ctx) })

		node.SafeGoLoop("snapshot_integrity_monitor", 3*time.Second, func() { node.startSnapshotIntegrityMonitor(ctx) })

		node.SafeGoLoop("cleanup_message_limiters", 3*time.Second, func() {

			// `interval` stores the value currently being processed.
			interval := TxLimiterIdleTTL / 2

			if interval <= 0 {

				interval = 5 * time.Minute

			}

			// `ticker` stores the value produced by this operation.
			ticker := time.NewTicker(interval)

			defer ticker.Stop()

			for {

				select {

				case <-ticker.C:

					cleanupMessageLimiters()

				case <-node.shutdownCh:

					return

				}

			}

		})

		node.SafeGoLoop("heartbeat_priority", 1*time.Second, func() {
			node.startHeartbeatPriorityLoop(ctx)
		})

		node.SafeGoLoop("cleanup_inactive_validators", 3*time.Second, func() { node.cleanupInactiveValidators() })

	})

	GlobalValidatorRegistry.Ensure(node.ID, uint64(node.Blockchain.Height()))

	return node

}

// GenerateValidatorKeyOnly implements the generate validator key only helper.
func GenerateValidatorKeyOnly(id string) GenesisValidatorKey {

	// `pub` and `err` store the error produced by this operation.
	pub, _, err := ed25519.GenerateKey(rand.Reader)

	if err != nil {

		log.Printf("[WARN] validator key generation failed for %s: %v", id, err)
		return GenesisValidatorKey{
			Address:   id,
			PublicKey: "",
		}

	}

	return GenesisValidatorKey{

		Address: id,

		PublicKey: hex.EncodeToString(pub),
	}

}

// loadGenesisFromDisk implements the load genesis from disk helper.
func loadGenesisFromDisk(path string) (*Genesis, error) {
	setGenesisRewardWallets(nil)
	setGenesisBootstrapWalletBindings(nil)

	// `data` and `err` store the error produced by this operation.
	data, err := os.ReadFile(path)

	if err != nil {

		return nil, err

	}

	// `sum` stores the value produced by this operation.
	sum := sha256.Sum256(data)

	// `genesisHash` stores the digest used to identify or verify the related data.
	genesisHash := hex.EncodeToString(sum[:])

	if GenesisHashExpected != "" && genesisHash != GenesisHashExpected {

		return nil, fmt.Errorf("genesis hash mismatch: got %s", genesisHash)

	}

	// `g` stores the value used by this operation.
	var g Genesis

	// `err` stores the error produced by this operation.
	if err := json.Unmarshal(data, &g); err != nil {

		return nil, err

	}
	if !isProtocolChainID(g.ChainID) {

		return nil, fmt.Errorf("genesis chain_id mismatch: got=%s want=%s", strings.TrimSpace(g.ChainID), protocolChainID())

	}
	g.ChainID = protocolChainID()

	if len(g.Validators) == 0 {

		return nil, fmt.Errorf("genesis has no validators")

	}

	// `err` stores the error produced by this operation.
	if err := validateAndNormalizeGenesisBootstrapConfig(&g); err != nil {

		return nil, err

	}
	GenesisHash = genesisHash

	return &g, nil

}

// applyGenesisRuntimePolicy applies genesis runtime policy.
func applyGenesisRuntimePolicy(g *Genesis) {
	GenesisRuntimeLocked = false
	GenesisValidatorSetFrozen = false
	GenesisFrozenValidatorSetSize = 0
	if g == nil {
		return
	}

	GenesisRuntimeLocked = g.GenesisLocked
	GenesisValidatorSetFrozen = g.ValidatorSetFrozen
	if !g.ValidatorSetFrozen {
		return
	}

	// `ids` stores the current position in the related collection.
	ids := canonicalValidatorIDsFromMapKeys(g.Validators)
	if len(ids) == 0 {
		return
	}
	GenesisFrozenValidatorSetSize = len(ids)
}

// installGenesisValidatorIDs implements the install genesis validator i ds helper.
func (n *Node) installGenesisValidatorIDs(g *Genesis) {
	if n == nil || g == nil || len(g.Validators) == 0 {
		return
	}
	// `ids` stores the current position in the related collection.
	ids := make([]string, 0, len(g.Validators))
	// `vid` tracks the current values while iterating.
	for vid := range g.Validators {
		// `norm` stores the value produced by this operation.
		norm := normalizeValidatorID(vid)
		if norm == "" {
			continue
		}
		ids = append(ids, norm)
	}
	n.GenesisValidators = canonicalValidatorIDs(ids)
}

// normalizeGenesisAllocation normalizes genesis allocation.
func normalizeGenesisAllocation(name string, allocation *GenesisAllocation, minLockEpochs uint64) error {

	if allocation == nil {

		return nil

	}

	allocation.Wallet = strings.TrimSpace(displayAddress(allocation.Wallet))

	if allocation.Allocation < 0 {

		return fmt.Errorf("genesis %s allocation cannot be negative", name)

	}

	if allocation.Allocation > 0 && allocation.Wallet == "" {

		return fmt.Errorf("genesis %s allocation missing wallet", name)

	}

	if allocation.Locked && allocation.LockEpochs != 0 && allocation.LockEpochs < minLockEpochs {

		return fmt.Errorf("genesis %s lock_epochs %d below min %d", name, allocation.LockEpochs, minLockEpochs)

	}

	return nil

}

// validateAndNormalizeGenesisBootstrapConfig validates and normalize genesis bootstrap config.
func validateAndNormalizeGenesisBootstrapConfig(g *Genesis) error {

	if g == nil {

		return nil

	}

	if maxActive := protocolValidatorMaxActiveCommitteeValue(); maxActive > 0 && len(g.Validators) > maxActive {
		return fmt.Errorf("genesis validators %d exceed protocol active-validator cap %d", len(g.Validators), maxActive)
	}

	if g.Decimals != 0 && g.Decimals != CoinDecimals {

		return fmt.Errorf("genesis decimals %d does not match coin decimals %d", g.Decimals, CoinDecimals)

	}

	// `normalizedRewardWallets` stores the value produced by this operation.
	normalizedRewardWallets := make(map[string]string, len(g.RewardWallets))

	// `vid` and `walletAddr` track the address used by this operation.
	for vid, walletAddr := range g.RewardWallets {

		// `id` stores the current position in the related collection.
		id := normalizeValidatorID(vid)

		// `wallet` stores the value produced by this operation.
		wallet := strings.TrimSpace(displayAddress(walletAddr))

		if id == "" || wallet == "" {
			continue
		}

		normalizedRewardWallets[id] = wallet

	}

	// `normalizedStakes` stores the value produced by this operation.
	normalizedStakes := make(map[string]GenesisStake, len(g.GenesisStakes))

	// `bootstrapBindings` stores the value produced by this operation.
	bootstrapBindings := make(map[string]genesisBootstrapWalletBinding, len(g.GenesisStakes))

	// `minStake` stores the value produced by this operation.
	minStake := int(ConsensusValidatorMinStake)

	if minStake < 0 {

		minStake = 0

	}

	// `minLockEpochs` stores the value produced by this operation.
	minLockEpochs := minUnstakeEpochs()

	// `err` stores the error produced by this operation.
	if err := normalizeGenesisAllocation("foundation", &g.Foundation, minLockEpochs); err != nil {

		return err

	}

	// `err` stores the error produced by this operation.
	if err := normalizeGenesisAllocation("treasury", &g.Treasury, minLockEpochs); err != nil {

		return err

	}

	// `vid` and `raw` track the current values while iterating.
	for vid, raw := range g.GenesisStakes {

		// `id` stores the current position in the related collection.
		id := normalizeValidatorID(vid)

		if id == "" {
			continue
		}

		// `wallet` stores the value produced by this operation.
		wallet := strings.TrimSpace(raw.Wallet)

		if wallet == "" {
			wallet = normalizedRewardWallets[id]
		}

		wallet = strings.TrimSpace(displayAddress(wallet))

		if wallet == "" {

			return fmt.Errorf("genesis stake %s missing wallet and reward wallet", id)

		}

		// `walletPubKey` stores the key used to access the related value.
		walletPubKey := strings.TrimSpace(strings.ToLower(raw.WalletPubKey))

		if walletPubKey == "" {

			return fmt.Errorf("genesis stake %s missing wallet_pubkey", id)

		}

		// `pubBytes` and `err` store the error produced by this operation.
		pubBytes, err := hex.DecodeString(walletPubKey)

		if err != nil || len(pubBytes) != ed25519.PublicKeySize {

			return fmt.Errorf("genesis stake %s invalid wallet_pubkey", id)

		}

		// `derivedWallet` stores the value produced by this operation.
		derivedWallet := AddressFromPublicKeyForChain(ed25519.PublicKey(pubBytes), g.ChainID)

		if derivedWallet == "" || !addressesEqual(derivedWallet, wallet) {

			return fmt.Errorf("genesis stake %s wallet_pubkey does not match wallet", id)

		}

		// `rewardWallet` and `ok` store whether the related condition is satisfied.
		if rewardWallet, ok := normalizedRewardWallets[id]; ok && !addressesEqual(rewardWallet, wallet) {

			return fmt.Errorf("genesis stake %s wallet does not match reward wallet", id)

		}

		// `amount` stores the value produced by this operation.
		amount := raw.Amount

		if amount < minStake {

			return fmt.Errorf("genesis stake %s amount %d below min stake %d", id, amount, minStake)

		}

		// `lockEpochs` stores the synchronization state protecting shared data.
		lockEpochs := raw.LockEpochs

		if lockEpochs == 0 {

			lockEpochs = DefaultStakeLockEpochs

		}

		if lockEpochs < minLockEpochs {

			return fmt.Errorf("genesis stake %s lock_epochs %d below min %d", id, lockEpochs, minLockEpochs)

		}

		normalizedStakes[id] = GenesisStake{
			Wallet:       wallet,
			WalletPubKey: walletPubKey,
			Amount:       amount,
			LockEpochs:   lockEpochs,
		}

		bootstrapBindings[id] = genesisBootstrapWalletBinding{
			WalletAddr:   wallet,
			WalletPubKey: walletPubKey,
		}

		// `ok` stores whether the related condition is satisfied.
		if _, ok := normalizedRewardWallets[id]; !ok {
			normalizedRewardWallets[id] = wallet
		}

	}

	g.RewardWallets = normalizedRewardWallets

	g.GenesisStakes = normalizedStakes

	setGenesisRewardWallets(normalizedRewardWallets)

	setGenesisBootstrapWalletBindings(bootstrapBindings)

	return nil

}

// applyGenesisRewardWalletBindings applies genesis reward wallet bindings.
func applyGenesisRewardWalletBindings(ledger *Ledger, genesis *Genesis) {

	if ledger == nil || genesis == nil {

		return

	}

	// `vid` and `walletAddr` track the address used by this operation.
	for vid, walletAddr := range genesis.RewardWallets {

		setValidatorRewardWallet(ledger, vid, walletAddr)

	}

}

// consumeGenesisStakeFunding implements the consume genesis stake funding helper.
func consumeGenesisStakeFunding(ledger *Ledger, validatorID, walletAddr string, amount int) error {

	if ledger == nil {

		return fmt.Errorf("nil ledger for genesis stake %s", validatorID)

	}

	if amount <= 0 {

		return fmt.Errorf("invalid genesis stake amount for %s", validatorID)

	}

	// `remaining` stores the value produced by this operation.
	remaining := amount

	// `sources` stores the value produced by this operation.
	sources := []string{
		strings.TrimSpace(walletAddr),
		strings.TrimSpace(validatorID),
		VALIDATOR_BOOTSTRAP_POOL,
	}

	// `seen` stores the value produced by this operation.
	seen := make(map[string]struct{}, len(sources))

	// `source` tracks the current values while iterating.
	for _, source := range sources {

		source = strings.TrimSpace(source)

		if source == "" {
			continue
		}

		// `key` stores the key used to access the related value.
		key := strings.ToUpper(source)

		// `ok` stores whether the related condition is satisfied.
		if _, ok := seen[key]; ok {
			continue
		}

		seen[key] = struct{}{}

		// `available` stores the value produced by this operation.
		available := getBalance(*ledger, CoinSymbol, source)

		if available <= 0 {
			continue
		}

		// `used` stores the value produced by this operation.
		used := available

		if used > remaining {
			used = remaining
		}

		addBalance(ledger, CoinSymbol, source, -used)

		remaining -= used

		if remaining == 0 {
			return nil
		}

	}

	return fmt.Errorf("genesis stake %s insufficient funding: missing %d %s", validatorID, remaining, CoinSymbol)

}

// applyGenesisStakes applies genesis stakes.
func applyGenesisStakes(ledger *Ledger, genesis *Genesis) error {

	if ledger == nil || genesis == nil || len(genesis.GenesisStakes) == 0 {

		return nil

	}

	ensureStakeMap(ledger)

	ensureRewardWalletMap(ledger)

	// `vid` and `spec` track the current values while iterating.
	for vid, spec := range genesis.GenesisStakes {

		// `id` stores the current position in the related collection.
		id := normalizeValidatorID(vid)

		if id == "" {
			continue
		}

		// `err` stores the error produced by this operation.
		if err := consumeGenesisStakeFunding(ledger, id, spec.Wallet, spec.Amount); err != nil {

			return err

		}

		// `key` stores the key used to access the related value.
		key := stakeKey(spec.Wallet, id)

		// `rec` stores the value produced by this operation.
		rec := ledger.Stakes[key]

		rec.ValidatorID = id

		rec.Amount += spec.Amount

		if spec.LockEpochs > rec.LockedUntil {

			rec.LockedUntil = spec.LockEpochs

		}

		ledger.Stakes[key] = rec

		// `rewardWallet` stores the value produced by this operation.
		rewardWallet := spec.Wallet

		// `configuredRewardWallet` and `ok` store whether the related condition is satisfied.
		if configuredRewardWallet, ok := genesis.RewardWallets[id]; ok && strings.TrimSpace(configuredRewardWallet) != "" {

			rewardWallet = configuredRewardWallet

		}

		setValidatorRewardWallet(ledger, id, rewardWallet)

		refreshValidatorRewardWalletBinding(ledger, id)

	}

	return nil

}

// bootstrapGenesisValidators implements the bootstrap genesis validators helper.
func (n *Node) bootstrapGenesisValidators(g *Genesis) {

	if g == nil {

		return

	}

	// `stale` stores the value produced by this operation.
	stale := time.Unix(0, 0)

	// `height` stores the value produced by this operation.
	height := uint64(n.Blockchain.Height())

	n.validatorMu.Lock()

	// `vid` tracks the current values while iterating.
	for vid := range g.Validators {
		vid = normalizeValidatorID(vid)
		if vid == "" {
			continue
		}

		// `st` and `ok` store whether the related condition is satisfied.
		st, ok := n.validatorStatus[vid]

		if !ok {

			st = &ValidatorStatus{}

			n.validatorStatus[vid] = st

		}

		st.Height = height

		// Genesis validators are known but NOT live until a heartbeat arrives.

		st.LastSeen = stale

	}

	n.validatorMu.Unlock()

	// `vid` and `pkHex` track the current values while iterating.
	for vid, pkHex := range g.Validators {
		vid = normalizeValidatorID(vid)
		if vid == "" {
			continue
		}

		// `pkBytes` and `err` store the error produced by this operation.
		pkBytes, err := hex.DecodeString(pkHex)

		if err != nil {

			if DebugConsensus {

			}

			continue

		}

		if len(pkBytes) == ed25519.PublicKeySize {
			validatorPubKeysMu.Lock()
			ValidatorPubKeys[vid] = ed25519.PublicKey(pkBytes)
			GenesisValidatorPubKeys[vid] = ed25519.PublicKey(pkBytes)
			validatorPubKeysMu.Unlock()
		}

	}

	participationMu.Lock()

	// `vid` tracks the current values while iterating.
	for vid := range g.Validators {
		vid = normalizeValidatorID(vid)
		if vid == "" {
			continue
		}

		// `ok` stores whether the related condition is satisfied.
		if _, ok := Participation[vid]; !ok {

			Participation[vid] = &ParticipationScore{

				ValidBlocks: 1,

				InvalidBlocks: 0,

				LastSeen: stale,

				CooldownUntil: 0,

				Reputation: 100,
			}

		}

	}

	participationMu.Unlock()

	// `ids` stores the current position in the related collection.
	ids := make([]string, 0, len(g.Validators))

	// `vid` tracks the current values while iterating.
	for vid := range g.Validators {
		// `norm` stores the value produced by this operation.
		norm := normalizeValidatorID(vid)
		if norm == "" {
			continue
		}
		ids = append(ids, norm)

	}

	bootstrapValidatorRegistry(ids, height)

}

// initGenesisBalancesFromDisk implements the init genesis balances from disk helper.
func (n *Node) initGenesisBalancesFromDisk(path string) error {

	if ledgerHasPersistentState(n.Ledger) {

		n.setExecutionLedger(n.Ledger)

		return nil // preserve loaded ledger

	}

	// `genesis` and `err` store the error produced by this operation.
	genesis, err := loadGenesisFromDisk(path)

	if err != nil {

		log.Printf("[WARN] GENESIS READ FAILED: %v", err)
		genesis = &Genesis{}

	}
	// `ledger` and `err` store the error produced by this operation.
	ledger, err := buildExecutionGenesisLedgerFromGenesis(genesis)
	if err != nil {
		return err
	}
	n.setExecutionLedger(ledger)

	return nil

}

// ledgerHasPersistentState implements the ledger has persistent state helper.
func ledgerHasPersistentState(ledger Ledger) bool {
	if len(ledger.Balances) > 0 {
		return true
	}
	if len(ledger.Stakes) > 0 {
		return true
	}
	if len(ledger.Nonces) > 0 {
		return true
	}
	if len(ledger.ValidatorRewardWallets) > 0 {
		return true
	}
	if len(ledger.UsedValidatorUpdateCerts) > 0 {
		return true
	}
	return false
}

// broadcastValidatorInfo announces this node as validator

// broadcastValidatorInfo announces this node as a validator

// broadcastValidatorInfo implements the broadcast validator info helper.
func (n *Node) broadcastValidatorInfo() {

	n.broadcastValidatorInfoInternal(false)

}

// canPublishValidatorHeartbeatNow implements the can publish validator heartbeat now helper.
func (n *Node) canPublishValidatorHeartbeatNow() bool {
	if n == nil {
		return false
	}
	return n.hasWalletLoginForValidator()
}

// maybeLogHeartbeatGateBlocked implements the maybe log heartbeat gate blocked helper.
func (n *Node) maybeLogHeartbeatGateBlocked(reason string, localCandidateRefreshed bool) {
	if n == nil || !DebugConsensus {
		return
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	n.heartbeatMu.Lock()
	if !n.lastHeartbeatGateLogAt.IsZero() && now.Sub(n.lastHeartbeatGateLogAt) < 8*time.Second {
		n.heartbeatMu.Unlock()
		return
	}
	n.lastHeartbeatGateLogAt = now
	n.heartbeatMu.Unlock()
	fmt.Printf("[HEARTBEAT-GATE] validator=%s publish=false reason=%s local_candidate_refreshed=%t\n",
		n.localConsensusValidatorID(), strings.TrimSpace(reason), localCandidateRefreshed)
}

// validatorHeartbeatPriorityInterval implements the validator heartbeat priority interval helper.
func validatorHeartbeatPriorityInterval() time.Duration {
	return 500 * time.Millisecond
}

// validatorHeartbeatPublishTimeout implements the validator heartbeat publish timeout helper.
func validatorHeartbeatPublishTimeout() time.Duration {
	return 1500 * time.Millisecond
}

// requestHeartbeatBroadcast implements the request heartbeat broadcast helper.
func (n *Node) requestHeartbeatBroadcast(force bool) {
	if n == nil {
		return
	}
	var (
		// `ch` stores the value used by this operation.
		ch chan struct{}
		// `active` stores the value used by this operation.
		active bool
	)
	n.heartbeatMu.Lock()
	if n.heartbeatSignalCh == nil {
		n.heartbeatSignalCh = make(chan struct{}, 1)
	}
	if force {
		n.heartbeatForcePending = true
	}
	ch = n.heartbeatSignalCh
	active = n.heartbeatLoopActive
	n.heartbeatMu.Unlock()
	if !active {
		go n.broadcastValidatorInfoInternal(force)
		return
	}
	select {
	case ch <- struct{}{}:
	default:
	}
}

// consumeHeartbeatForcePending implements the consume heartbeat force pending helper.
func (n *Node) consumeHeartbeatForcePending() bool {
	if n == nil {
		return false
	}
	n.heartbeatMu.Lock()
	defer n.heartbeatMu.Unlock()
	// `force` stores the value produced by this operation.
	force := n.heartbeatForcePending
	n.heartbeatForcePending = false
	return force
}

// startHeartbeatPriorityLoop implements the start heartbeat priority loop helper.
func (n *Node) startHeartbeatPriorityLoop(ctx context.Context) {
	if n == nil {
		return
	}
	n.heartbeatMu.Lock()
	if n.heartbeatSignalCh == nil {
		n.heartbeatSignalCh = make(chan struct{}, 1)
	}
	// `signalCh` stores the value produced by this operation.
	signalCh := n.heartbeatSignalCh
	n.heartbeatLoopActive = true
	n.heartbeatForcePending = true
	n.heartbeatMu.Unlock()
	defer func() {
		n.heartbeatMu.Lock()
		n.heartbeatLoopActive = false
		n.heartbeatMu.Unlock()
	}()

	// `ticker` stores the value produced by this operation.
	ticker := time.NewTicker(validatorHeartbeatPriorityInterval())
	defer ticker.Stop()

	for {
		// `force` stores the value produced by this operation.
		force := n.consumeHeartbeatForcePending()
		if n.heartbeatBroadcastOverdue() {
			force = true
		}
		n.broadcastValidatorInfoInternal(force)

		select {
		case <-ctx.Done():
			return
		case <-n.shutdownCh:
			return
		case <-signalCh:
		case <-ticker.C:
		}
	}
}

// heartbeatBroadcastOverdue implements the heartbeat broadcast overdue helper.
func (n *Node) heartbeatBroadcastOverdue() bool {
	if n == nil {
		return false
	}
	// `threshold` stores the value produced by this operation.
	threshold := validatorHeartbeatFailsafeInterval()
	if threshold <= 0 {
		return false
	}
	n.heartbeatMu.Lock()
	// `last` stores the value produced by this operation.
	last := n.lastHeartbeatAt
	n.heartbeatMu.Unlock()
	if last.IsZero() {
		return true
	}
	return time.Since(last) > threshold
}

// broadcastValidatorInfoInternal implements the broadcast validator info internal helper.
func (n *Node) broadcastValidatorInfoInternal(force bool) {

	if !n.canAdvertiseValidatorPresence() {

		return

	}

	// `reported` stores the value produced by this operation.
	reported := n.Blockchain.Height()

	// `finalized` stores the value produced by this operation.
	finalized := uint64(0)

	n.commitMu.Lock()

	finalized = n.committedHeight

	n.commitMu.Unlock()

	if finalized == 0 {

		finalized = reported

	}

	// `execEpoch` stores the value produced by this operation.
	execEpoch := n.currentEpoch()
	// `validatorSetHeight` stores whether the related condition is satisfied.
	validatorSetHeight := execEpoch
	// `activeForHeartbeat` stores the value produced by this operation.
	activeForHeartbeat := true
	if validatorOnboardingStrictActivationEnabled() {
		// `active` stores the value produced by this operation.
		active, _ := n.selfActiveValidatorAt(execEpoch)
		activeForHeartbeat = active
	}
	// `consensusReadyForHeartbeat` stores the value produced by this operation.
	consensusReadyForHeartbeat := activeForHeartbeat
	// `executionReady` stores the value produced by this operation.
	if executionReady, _ := n.startupExecutionSnapshotStatus(finalized); !executionReady {
		consensusReadyForHeartbeat = false
	}
	// `syncing` stores the value produced by this operation.
	if syncing, _, _ := n.effectiveConsensusSyncState(finalized); syncing {
		consensusReadyForHeartbeat = false
	}
	// Heartbeat must advertise the same hash that this node enforces for the
	// target height; otherwise peers can form false quorum around a stale/planned
	// set and lock into split-view startup mismatches.
	validatorSetHash, _ := n.runtimeAdvertisedValidatorSetHash(validatorSetHeight)
	validatorSetHash = strings.ToLower(strings.TrimSpace(validatorSetHash))
	if validatorSetHash == "" && validatorOnboardingStrictActivationEnabled() && !activeForHeartbeat {
		validatorSetHash = strings.ToLower(strings.TrimSpace(n.stableFrozenHashForAdvertise(validatorSetHeight)))
	}
	// `nextValidatorSetHeight` stores the value produced by this operation.
	nextValidatorSetHeight := validatorSetHeight + 1
	// `nextValidatorSetHash` stores the digest used to identify or verify the related data.
	nextValidatorSetHash := strings.ToLower(strings.TrimSpace(n.deterministicNextValidatorSetHash(validatorSetHeight, validatorSetHash)))
	if nextValidatorSetHash == "" {
		nextValidatorSetHash = validatorSetHash
	}

	// `minInterval` stores the value currently being processed.
	minInterval := validatorHeartbeatBroadcastMinInterval(true)
	if normalizeHeartbeatScope(ValidatorHeartbeatScope) == "committee_only" {
		// `selfIDScope` stores the local consensus identity selected for committee scope.
		scopeSet := n.freezeValidatorSetForHeight(execEpoch, n.GetConsensusValidators(int(execEpoch)))
		selfIDScope := n.localConsensusValidatorIDForSet(scopeSet)
		// `inCommittee` stores the current position in the related collection.
		inCommittee := false
		// `id` tracks the current position in the related collection.
		for _, id := range scopeSet {
			if normalizeValidatorID(id) == selfIDScope {
				inCommittee = true
				break
			}
		}
		if !inCommittee {
			// `id` tracks the current position in the related collection.
			for _, id := range n.freezeValidatorSetForHeight(execEpoch+1, n.GetConsensusValidators(int(execEpoch+1))) {
				if normalizeValidatorID(id) == selfIDScope {
					inCommittee = true
					break
				}
			}
		}
		if !inCommittee {
			minInterval = validatorHeartbeatBroadcastMinInterval(false)
		} else {
			minInterval = validatorHeartbeatBroadcastMinInterval(true)
		}
	}
	if validatorOnboardingStrictActivationEnabled() && !activeForHeartbeat && minInterval > 2*time.Second {
		// Onboarding booster: advertise candidate liveness faster until admitted/rejected.
		minInterval = 2 * time.Second
	}
	n.heartbeatMu.Lock()

	if !force &&
		n.lastHeartbeatReported == reported &&
		n.lastHeartbeatFinalized == finalized &&
		n.lastHeartbeatEpoch == execEpoch {

		if time.Since(n.lastHeartbeatAt) < minInterval {

			n.heartbeatMu.Unlock()

			return

		}

	}

	n.lastHeartbeatReported = reported
	n.lastHeartbeatFinalized = finalized

	n.lastHeartbeatEpoch = execEpoch

	n.lastHeartbeatAt = time.Now()

	n.heartbeatMu.Unlock()
	// `selfID` stores the local consensus identity selected for heartbeat.
	heartbeatSet := n.freezeValidatorSetForHeight(execEpoch, n.GetConsensusValidators(int(execEpoch)))
	selfID := n.localConsensusValidatorIDForSet(heartbeatSet)
	if selfID == "" {
		return
	}

	// `ann` stores the value produced by this operation.
	ann := ValidatorAnnouncement{

		NodeID: selfID,

		PubKey: hex.EncodeToString(n.ValidatorKey.PublicKey),

		P2PAddr: n.SelfAddr,

		Height: reported,

		ReportedHeight: reported,

		FinalizedHeight: finalized,

		ExecEpoch: execEpoch,

		ValidatorSetHeight: validatorSetHeight,
		ActivationHeight:   validatorSetHeight,

		ValidatorSetHash:     validatorSetHash,
		NextValidatorSetHash: nextValidatorSetHash,
		NextActivationHeight: nextValidatorSetHeight,
		ConsensusReady:       consensusReadyForHeartbeat,
		ConsensusReadySet:    true,

		IsValidator: activeForHeartbeat,
	}

	if isValidatorSigningKeyUsable(n.ValidatorKey) {

		// `sig` and `ok` store whether the related condition is satisfied.
		sig, ok := n.signValidatorPayload(
			validatorAnnounceSignBytesV4(
				ann.NodeID,
				ann.PubKey,
				ann.P2PAddr,
				ann.ReportedHeight,
				ann.FinalizedHeight,
				ann.ExecEpoch,
				ann.ValidatorSetHeight,
				ann.ValidatorSetHash,
				ann.NextValidatorSetHash,
				ann.NextActivationHeight,
				ann.IsValidator,
			),
		)
		if ann.ConsensusReadySet {
			sig, ok = n.signValidatorPayload(
				validatorAnnounceSignBytesV5(
					ann.NodeID,
					ann.PubKey,
					ann.P2PAddr,
					ann.ReportedHeight,
					ann.FinalizedHeight,
					ann.ExecEpoch,
					ann.ValidatorSetHeight,
					ann.ValidatorSetHash,
					ann.NextValidatorSetHash,
					ann.NextActivationHeight,
					ann.ConsensusReadySet,
					ann.ConsensusReady,
					ann.IsValidator,
				),
			)
		}

		if ok {
			ann.Signature = hex.EncodeToString(sig)
		}

	}

	// `candidateRefreshed` stores the value produced by this operation.
	candidateRefreshed := false
	if validatorOnboardingStrictActivationEnabled() && !ann.IsValidator {
		// `pk` stores the value produced by this operation.
		pk := append(ed25519.PublicKey(nil), n.ValidatorKey.PublicKey...)
		n.registerCandidateHeartbeat(ann, pk, reported, finalized, execEpoch, validatorSetHeight, validatorSetHash)
		n.validatorMu.Lock()
		delete(n.validatorStatus, selfID)
		n.validatorMu.Unlock()
		candidateRefreshed = true
	}
	if ann.IsValidator {
		n.RegisterValidator(selfID, reported, finalized, execEpoch, validatorSetHeight, validatorSetHash)
		n.setValidatorConsensusReady(selfID, consensusReadyForHeartbeat)
	}

	if !n.canPublishValidatorHeartbeatNow() {
		if n.requiresWalletAuthCurrent(n.localConsensusValidatorID()) {
			n.maybeLogHeartbeatGateBlocked("wallet_auth_pending", candidateRefreshed)
		}
		return
	}

	if n.ValidatorTopic == nil {
		return
	}

	// `msg` stores the value produced by this operation.
	msg := Message{

		Type: MsgValidatorAnnounce,

		Data: MustJSON(ann),
	}

	// `data` and `err` store the error produced by this operation.
	data, err := MarshalP2PMessage(msg)

	if err != nil {

		return

	}

	// `publishCtx` and `cancel` store the context controlling this operation.
	publishCtx, cancel := context.WithTimeout(n.RootContext(), validatorHeartbeatPublishTimeout())
	defer cancel()
	// `err` stores the error produced by this operation.
	if err := n.ValidatorTopic.Publish(publishCtx, data); err != nil {

		return

	}
	if n.ConsensusTopic != nil {
		// `consensusCtx` and `consensusCancel` store the context controlling this operation.
		consensusCtx, consensusCancel := context.WithTimeout(n.RootContext(), validatorHeartbeatPublishTimeout())
		_ = n.ConsensusTopic.Publish(consensusCtx, data)
		consensusCancel()
	}

	if DebugConsensus {

		fmt.Printf("Heartbeat sent: %s finalized=%d epoch=%d\n", ShortID(n.ID), finalized, execEpoch)

	}

	if !ann.IsValidator {
		if !candidateRefreshed {
			// `pk` stores the value produced by this operation.
			pk := append(ed25519.PublicKey(nil), n.ValidatorKey.PublicKey...)
			n.registerCandidateHeartbeat(ann, pk, reported, finalized, execEpoch, validatorSetHeight, validatorSetHash)
			n.validatorMu.Lock()
			delete(n.validatorStatus, selfID)
			n.validatorMu.Unlock()
		}
		return
	}

	// Self-heartbeat: pubsub doesn't deliver to self, so refresh locally.

	n.validatorMu.Lock()

	// `st` and `ok` store whether the related condition is satisfied.
	st, ok := n.validatorStatus[selfID]

	if !ok {

		st = &ValidatorStatus{}

		n.validatorStatus[selfID] = st

	}

	st.Height = ann.ReportedHeight

	st.ReportedHeight = ann.ReportedHeight

	st.FinalizedHeight = ann.FinalizedHeight

	st.ExecEpoch = ann.ExecEpoch

	st.ValidatorSetHeight = ann.ValidatorSetHeight

	st.ValidatorSetHash = ann.ValidatorSetHash

	st.LastSeen = time.Now()

	n.validatorMu.Unlock()

	n.recordHeightReport(selfID, ann.FinalizedHeight)

	n.recomputeFinalizedHeight()

	// Re-gossip execution result for the current epoch to help late joiners

	// converge on quorum without forcing sync.

	syncing := false

	if n.Consensus != nil {

		n.Consensus.mu.Lock()

		syncing = n.Consensus.Syncing

		n.Consensus.mu.Unlock()

	}

	if !syncing {

		// `epoch` stores the value produced by this operation.
		epoch := n.currentEpoch()

		// `block` and `ok` store whether the related condition is satisfied.
		if block, ok := n.executionVoteTargetBlock(epoch); ok && block.ID == epoch {

			// `execHash` stores the digest used to identify or verify the related data.
			execHash := block.StateRoot

			if execHash == "" {

				execHash = n.ExecuteBlockAndGetStateRoot(block)

			}

			if execHash != "" && n.shouldRebroadcastExec(epoch, 15*time.Second) {
				// Late-join peers may miss the original leader proposal and keep
				// execution votes queued forever. Re-broadcast proposal + exec vote.
				n.BroadcastLeaderBlock(block)
				n.broadcastExecutionResultForBlockInternal(block, execHash, block.MempoolRoot, true)

			}

		}

	}

}

// listenValidators handles incoming validator announcements

// listenValidators receives validator announcements

// getValidatorList returns a snapshot of active validator IDs

// getValidatorList implements the get validator list helper.
func (n *Node) getValidatorList() []string {

	// `current` stores the value produced by this operation.
	current := n.GetConsensusValidators(int(n.currentEpoch()))
	if len(current) > 0 {
		sort.Strings(current)
		return current
	}

	n.validatorMu.RLock()
	defer n.validatorMu.RUnlock()

	// `list` stores the value produced by this operation.
	list := make([]string, 0, len(n.validatorStatus))
	// `id` tracks the current position in the related collection.
	for id := range n.validatorStatus {
		list = append(list, id)
	}
	sort.Strings(list)
	return list

}

// validatorLivenessHeartbeatTTL implements the validator liveness heartbeat ttl helper.
func validatorLivenessHeartbeatTTL() time.Duration {
	// `ttl` stores the value produced by this operation.
	ttl := ValidatorLivenessHeartbeatTTLSeconds
	if ttl == 0 {
		ttl = 25
	}
	return time.Duration(ttl) * time.Second
}

// validatorLivenessGrace implements the validator liveness grace helper.
func validatorLivenessGrace() time.Duration {
	// `grace` stores the value produced by this operation.
	grace := ValidatorLivenessGraceSeconds
	if grace == 0 {
		grace = 10
	}
	return time.Duration(grace) * time.Second
}

// sanitizeLivenessMaxHeightDriftBlocks implements the sanitize liveness max height drift blocks helper.
func sanitizeLivenessMaxHeightDriftBlocks(v uint64) uint64 {
	const (
		// `minDrift` defines the constant value used by this package.
		minDrift = uint64(1)
		// `maxDrift` defines the constant value used by this package.
		maxDrift = uint64(1024)
	)
	if v < minDrift {
		return minDrift
	}
	if v > maxDrift {
		return maxDrift
	}
	return v
}

// validatorLivenessMaxHeightDriftBlocks implements the validator liveness max height drift blocks helper.
func validatorLivenessMaxHeightDriftBlocks() uint64 {
	// `v` stores the value produced by this operation.
	v := ValidatorLivenessMaxHeightDriftBlocks
	if v == 0 {
		v = 8
	}
	return sanitizeLivenessMaxHeightDriftBlocks(v)
}

// validatorHeartbeatBroadcastMinInterval implements the validator heartbeat broadcast min interval helper.
func validatorHeartbeatBroadcastMinInterval(inCommittee bool) time.Duration {
	if !inCommittee {
		return 2 * time.Minute
	}
	// `base` stores the value produced by this operation.
	base := validatorLivenessHeartbeatTTL() / 2
	if base < 10*time.Second {
		base = 10 * time.Second
	}
	if base > 20*time.Second {
		base = 20 * time.Second
	}
	return base
}

// validatorHeartbeatFailsafeInterval implements the validator heartbeat failsafe interval helper.
func validatorHeartbeatFailsafeInterval() time.Duration {
	// `threshold` stores the value produced by this operation.
	threshold := validatorLivenessHeartbeatTTL() + validatorLivenessGrace()
	if threshold <= 0 {
		threshold = validatorLivenessHeartbeatTTL()
	}
	if threshold <= 0 {
		threshold = 30 * time.Second
	}
	return threshold
}

// validatorRejoinRequiredHeartbeats implements the validator rejoin required heartbeats helper.
func validatorRejoinRequiredHeartbeats() uint16 {
	// `v` stores the value produced by this operation.
	v := ValidatorRejoinRequiredHeartbeats
	if v == 0 {
		return 1
	}
	return v
}

// validatorRejoinRequiredSignedBlocks implements the validator rejoin required signed blocks helper.
func validatorRejoinRequiredSignedBlocks() uint64 {
	// `v` stores the value produced by this operation.
	v := ValidatorRejoinRequiredSignedBlocks
	if v == 0 {
		return 1
	}
	return v
}

// validatorRejoinWindowBlocks implements the validator rejoin window blocks helper.
func validatorRejoinWindowBlocks() uint64 {
	// `v` stores the value produced by this operation.
	v := ValidatorRejoinWindowBlocks
	if v == 0 {
		return 16
	}
	return v
}

// markValidatorOffline implements the mark validator offline helper.
func (n *Node) markValidatorOffline(id string, reason string) {
	id = normalizeValidatorID(id)
	if n == nil || id == "" {
		return
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `offlineSince` stores the value produced by this operation.
	offlineSince := now
	n.validatorMu.Lock()
	if n.validatorOfflineSince == nil {
		n.validatorOfflineSince = make(map[string]time.Time)
	}
	if n.validatorRejoin == nil {
		n.validatorRejoin = make(map[string]ValidatorRejoinState)
	}
	// `already` stores the value produced by this operation.
	_, already := n.validatorOfflineSince[id]
	if !already {
		n.validatorOfflineSince[id] = now
	} else {
		offlineSince = n.validatorOfflineSince[id]
	}
	// `st` stores the value produced by this operation.
	st := n.validatorRejoin[id]
	st.Pending = false
	st.Heartbeats = 0
	st.LastHeartbeat = time.Time{}
	st.LastSignedHeight = 0
	n.validatorRejoin[id] = st
	// `vs` and `ok` store whether the related condition is satisfied.
	if vs, ok := n.validatorStatus[id]; ok && vs != nil {
		vs.Active = false
	}
	n.validatorMu.Unlock()
	if DebugConsensus {
		fmt.Printf("[LIVENESS] validator=%s state=offline reason=%s since=%s\n",
			id, strings.TrimSpace(reason), offlineSince.Format(time.RFC3339))
	}
}

// startValidatorRejoin implements the start validator rejoin helper.
func (n *Node) startValidatorRejoin(id string) {
	id = normalizeValidatorID(id)
	if n == nil || id == "" {
		return
	}
	n.validatorMu.Lock()
	defer n.validatorMu.Unlock()
	n.startValidatorRejoinLocked(id)
}

// startValidatorRejoinLocked implements the start validator rejoin locked helper.
func (n *Node) startValidatorRejoinLocked(id string) {
	if n == nil || id == "" {
		return
	}
	if n.validatorOfflineSince == nil {
		n.validatorOfflineSince = make(map[string]time.Time)
	}
	if n.validatorRejoin == nil {
		n.validatorRejoin = make(map[string]ValidatorRejoinState)
	}
	// `offline` stores the value produced by this operation.
	if _, offline := n.validatorOfflineSince[id]; !offline {
		return
	}
	// `st` stores the value produced by this operation.
	st := n.validatorRejoin[id]
	if !st.Pending {
		st.Pending = true
		st.Heartbeats = 0
		st.LastHeartbeat = time.Time{}
		st.LastSignedHeight = 0
		n.validatorRejoin[id] = st
		if DebugConsensus {
			fmt.Printf("[LIVENESS] validator=%s state=rejoin_pending\n", id)
		}
	}
}

// recordValidatorRejoinHeartbeat implements the record validator rejoin heartbeat helper.
func (n *Node) recordValidatorRejoinHeartbeat(id string) {
	id = normalizeValidatorID(id)
	if n == nil || id == "" {
		return
	}
	n.validatorMu.Lock()
	defer n.validatorMu.Unlock()
	n.recordValidatorRejoinHeartbeatLocked(id)
}

// recordValidatorRejoinHeartbeatLocked implements the record validator rejoin heartbeat locked helper.
func (n *Node) recordValidatorRejoinHeartbeatLocked(id string) {
	if n == nil || id == "" {
		return
	}
	// `offline` stores the value produced by this operation.
	if _, offline := n.validatorOfflineSince[id]; !offline {
		return
	}
	n.startValidatorRejoinLocked(id)
	// `st` stores the value produced by this operation.
	st := n.validatorRejoin[id]
	st.Heartbeats++
	st.LastHeartbeat = time.Now()
	n.validatorRejoin[id] = st
	n.maybeCompleteValidatorRejoinLocked(id)
}

// recordValidatorRejoinSigned implements the record validator rejoin signed helper.
func (n *Node) recordValidatorRejoinSigned(id string, height uint64) {
	id = normalizeValidatorID(id)
	if n == nil || id == "" || height == 0 {
		return
	}
	n.validatorMu.Lock()
	defer n.validatorMu.Unlock()
	n.recordValidatorRejoinSignedLocked(id, height)
}

// recordValidatorRejoinSignedLocked implements the record validator rejoin signed locked helper.
func (n *Node) recordValidatorRejoinSignedLocked(id string, height uint64) {
	if n == nil || id == "" || height == 0 {
		return
	}
	// `offline` stores the value produced by this operation.
	if _, offline := n.validatorOfflineSince[id]; !offline {
		return
	}
	n.startValidatorRejoinLocked(id)
	// `st` stores the value produced by this operation.
	st := n.validatorRejoin[id]
	if height > st.LastSignedHeight {
		st.LastSignedHeight = height
	}
	n.validatorRejoin[id] = st
	n.maybeCompleteValidatorRejoinLocked(id)
}

// maybeCompleteValidatorRejoinLocked implements the maybe complete validator rejoin locked helper.
func (n *Node) maybeCompleteValidatorRejoinLocked(id string) {
	if n == nil || id == "" {
		return
	}
	// `offline` stores the value produced by this operation.
	if _, offline := n.validatorOfflineSince[id]; !offline {
		return
	}
	// `st` and `ok` store whether the related condition is satisfied.
	st, ok := n.validatorRejoin[id]
	if !ok || !st.Pending {
		return
	}
	// `requiredHB` stores the request data being processed.
	requiredHB := validatorRejoinRequiredHeartbeats()
	if st.Heartbeats < requiredHB {
		return
	}
	// `requiredSigned` stores the request data being processed.
	requiredSigned := validatorRejoinRequiredSignedBlocks()
	if requiredSigned > 0 {
		if st.LastSignedHeight == 0 {
			return
		}
		// `localFinalized` stores the value produced by this operation.
		localFinalized := n.getFinalizedHeight()
		if localFinalized > st.LastSignedHeight && localFinalized-st.LastSignedHeight > validatorRejoinWindowBlocks() {
			return
		}
	}
	delete(n.validatorOfflineSince, id)
	delete(n.validatorRejoin, id)
	// `vs` and `ok` store whether the related condition is satisfied.
	if vs, ok := n.validatorStatus[id]; ok && vs != nil {
		vs.Active = true
		vs.LastSeen = time.Now()
	}
	if DebugConsensus {
		fmt.Printf("[LIVENESS] validator=%s state=live rejoin_heartbeats=%d last_signed=%d\n",
			id, st.Heartbeats, st.LastSignedHeight)
	}
}

// isValidatorLiveForConsensus implements the is validator live for consensus helper.
func (n *Node) isValidatorLiveForConsensus(id string, st *ValidatorStatus, now time.Time, localFinalized uint64) bool {
	if n == nil {
		return false
	}
	n.validatorMu.RLock()
	defer n.validatorMu.RUnlock()
	return n.isValidatorLiveForConsensusLocked(id, st, now, localFinalized)
}

type validatorLivenessEvaluation struct {
	// `LiveStrict` stores the value associated with this record.
	LiveStrict bool
	// `InAnyHeartbeatSet` stores the current position in the related collection.
	InAnyHeartbeatSet bool
	// `FreshHeartbeat` stores the value associated with this record.
	FreshHeartbeat bool
	// `WithinDrift` stores the value associated with this record.
	WithinDrift bool
	// `HeightLagBlocks` stores the value associated with this record.
	HeightLagBlocks uint64
	// `FailReason` stores the value associated with this record.
	FailReason string
}

// absHeightLagBlocks implements the abs height lag blocks helper.
func absHeightLagBlocks(a uint64, b uint64) uint64 {
	if a >= b {
		return a - b
	}
	return b - a
}

// validatorHasConnectedPeer implements the validator has connected peer helper.
func (n *Node) validatorHasConnectedPeer(id string) bool {
	if n == nil || id == "" {
		return false
	}
	id = normalizeValidatorID(id)
	if id == "" {
		return false
	}
	n.peerStateMu.Lock()
	defer n.peerStateMu.Unlock()
	// `peerID` and `validatorID` track whether the related condition is satisfied.
	for peerID, validatorID := range n.peerToValidator {
		if normalizeValidatorID(validatorID) != id {
			continue
		}
		if n.connectedPeers[peerID] {
			return true
		}
	}
	return false
}

// evaluateValidatorLivenessLocked implements the evaluate validator liveness locked helper.
func (n *Node) evaluateValidatorLivenessLocked(id string, st *ValidatorStatus, now time.Time, localFinalized uint64) validatorLivenessEvaluation {
	// `out` stores the result produced by this operation.
	out := validatorLivenessEvaluation{WithinDrift: true}
	if st == nil {
		out.FailReason = "missing_status"
		return out
	}
	// `normID` stores the value produced by this operation.
	normID := normalizeValidatorID(id)
	if normID == "" {
		out.FailReason = "invalid_id"
		return out
	}
	// `offline` stores the value produced by this operation.
	if _, offline := n.validatorOfflineSince[normID]; offline {
		out.FailReason = "offline_marked"
		return out
	}
	if !st.Active {
		out.FailReason = "inactive"
		return out
	}
	// `ttl` stores the value produced by this operation.
	ttl := validatorLivenessHeartbeatTTL()
	// `grace` stores the value produced by this operation.
	grace := validatorLivenessGrace()
	// `age` stores the value produced by this operation.
	age := now.Sub(st.LastSeen)
	if age < 0 {
		age = 0
	}
	out.FreshHeartbeat = age <= ttl+grace
	if !out.FreshHeartbeat {
		if !n.validatorHasConnectedPeer(normID) {
			out.FailReason = "stale_heartbeat"
			return out
		}
		out.FreshHeartbeat = true
	}

	out.InAnyHeartbeatSet = n.validatorInAnyHeartbeatSet(normID, st.ReportedHeight, st.FinalizedHeight, st.ExecEpoch, st.ValidatorSetHeight)
	if !out.InAnyHeartbeatSet {
		out.FailReason = "out_of_set"
		return out
	}

	// `remoteFinalized` stores the value produced by this operation.
	remoteFinalized := st.FinalizedHeight
	if remoteFinalized == 0 {
		remoteFinalized = st.ReportedHeight
	}
	if remoteFinalized == 0 {
		remoteFinalized = st.Height
	}
	if localFinalized > 0 {
		if remoteFinalized == 0 {
			if out.FreshHeartbeat && n.validatorHasConnectedPeer(normID) {
				remoteFinalized = localFinalized
			} else {
				out.WithinDrift = false
				out.FailReason = "out_of_drift"
				return out
			}
		}
		out.HeightLagBlocks = absHeightLagBlocks(localFinalized, remoteFinalized)
		if out.HeightLagBlocks > validatorLivenessMaxHeightDriftBlocks() {
			// `execEpoch` stores the value produced by this operation.
			execEpoch := st.ExecEpoch
			if execEpoch > 0 && out.FreshHeartbeat && n.validatorHasConnectedPeer(normID) {
				// `execLag` stores the value produced by this operation.
				execLag := absHeightLagBlocks(localFinalized+1, execEpoch)
				if execLag <= validatorLivenessMaxHeightDriftBlocks()+1 {
					out.HeightLagBlocks = execLag
				} else {
					out.WithinDrift = false
					out.FailReason = "out_of_drift"
					return out
				}
			} else {
				out.WithinDrift = false
				out.FailReason = "out_of_drift"
				return out
			}
		}
	}
	if !st.ConsensusReadyKnown {
		if !n.shouldCountConsensusWaitingValidatorLive(normID, out) {
			out.FailReason = "consensus_ready_unknown"
			return out
		}
	} else if !st.Enabled {
		if !n.shouldCountConsensusWaitingValidatorLive(normID, out) {
			out.FailReason = "consensus_not_ready"
			return out
		}
	}
	out.LiveStrict = true
	out.FailReason = "live"
	return out
}

// shouldCountConsensusWaitingValidatorLive implements the should count consensus waiting validator live helper.
func (n *Node) shouldCountConsensusWaitingValidatorLive(id string, eval validatorLivenessEvaluation) bool {
	if n == nil || normalizeValidatorID(id) == "" {
		return false
	}
	if !eval.FreshHeartbeat || !eval.InAnyHeartbeatSet || !eval.WithinDrift {
		return false
	}
	if !n.validatorHasConnectedPeer(id) {
		return false
	}
	// `stall` stores the value produced by this operation.
	stall := n.commitStallDuration()
	if stall >= 15*time.Second {
		return true
	}
	if stall >= execQuorumEmergencyStallTimeout {
		return true
	}
	return false
}

// isValidatorLiveForConsensusLocked implements the is validator live for consensus locked helper.
func (n *Node) isValidatorLiveForConsensusLocked(id string, st *ValidatorStatus, now time.Time, localFinalized uint64) bool {
	return n.evaluateValidatorLivenessLocked(id, st, now, localFinalized).LiveStrict
}

// isValidatorLiveForLocalViewLocked reports heartbeat/height liveness for UI
// views only. Consensus paths must use isValidatorLiveForConsensusLocked so
// consensus-ready gates remain strict and deterministic.
func (n *Node) isValidatorLiveForLocalViewLocked(id string, st *ValidatorStatus, now time.Time, localFinalized uint64) bool {
	eval := n.evaluateValidatorLivenessLocked(id, st, now, localFinalized)
	if eval.LiveStrict {
		return true
	}
	switch eval.FailReason {
	case "consensus_ready_unknown", "consensus_not_ready":
		return eval.FreshHeartbeat && eval.InAnyHeartbeatSet && eval.WithinDrift
	default:
		return false
	}
}

// countLiveValidators implements the count live validators helper.
func (n *Node) countLiveValidators() int {

	// `now` stores the value produced by this operation.
	now := time.Now()
	// `localFinalized` stores the value produced by this operation.
	localFinalized := n.getFinalizedHeight()

	n.validatorMu.RLock()

	defer n.validatorMu.RUnlock()

	// `count` stores the measured quantity used by this operation.
	count := 0

	// `id` and `st` track the current position in the related collection.
	for id, st := range n.validatorStatus {

		if st == nil {

			continue

		}
		if !n.isValidatorLiveForConsensusLocked(id, st, now, localFinalized) {
			continue
		}

		count++

	}

	return count

}

// splitValidatorsByLiveness implements the split validators by liveness helper.
func (n *Node) splitValidatorsByLiveness(validators []string) ([]string, []string) {

	validators = canonicalValidatorIDs(validators)
	if n == nil || len(validators) == 0 {

		return []string{}, []string{}

	}

	// `now` stores the value produced by this operation.
	now := time.Now()

	// `localFinalized` stores the value produced by this operation.
	localFinalized := n.getFinalizedHeight()
	if localFinalized == 0 && n.Blockchain != nil {
		localFinalized = n.Blockchain.FinalizedHeight()
		if localFinalized == 0 {
			localFinalized = n.Blockchain.Height()
		}
	}

	// `online` stores the value produced by this operation.
	online := make([]string, 0, len(validators))
	// `offline` stores the value produced by this operation.
	offline := make([]string, 0)

	n.validatorMu.RLock()
	// `id` tracks the current position in the related collection.
	for _, id := range validators {

		// `normID` stores the value produced by this operation.
		normID := normalizeValidatorID(id)
		// `st` stores the value produced by this operation.
		st := n.validatorStatus[normID]
		if !n.isValidatorLiveForLocalViewLocked(normID, st, now, localFinalized) {
			offline = append(offline, id)
			continue
		}

		online = append(online, id)

	}
	n.validatorMu.RUnlock()

	return online, offline

}

// splitValidatorsByConsensusLiveness reports the strict heartbeat/readiness
// view used by consensus and the public committee status counters.
func (n *Node) splitValidatorsByConsensusLiveness(validators []string) ([]string, []string) {
	validators = canonicalValidatorIDs(validators)
	if n == nil || len(validators) == 0 {
		return []string{}, []string{}
	}

	now := time.Now()
	localFinalized := n.getFinalizedHeight()
	if localFinalized == 0 && n.Blockchain != nil {
		localFinalized = n.Blockchain.FinalizedHeight()
		if localFinalized == 0 {
			localFinalized = n.Blockchain.Height()
		}
	}

	online := make([]string, 0, len(validators))
	offline := make([]string, 0)
	n.validatorMu.RLock()
	for _, id := range validators {
		normID := normalizeValidatorID(id)
		st := n.validatorStatus[normID]
		if !n.isValidatorLiveForConsensusLocked(normID, st, now, localFinalized) {
			offline = append(offline, id)
			continue
		}
		online = append(online, id)
	}
	n.validatorMu.RUnlock()
	return online, offline
}

// splitValidatorsByFinalizedActivity implements the split validators by finalized activity helper.
func (n *Node) splitValidatorsByFinalizedActivity(validators []string, height uint64) ([]string, []string) {
	validators = canonicalValidatorIDs(validators)
	if n == nil || len(validators) == 0 {
		return []string{}, []string{}
	}
	// `window` stores the value produced by this operation.
	window := protocolValidatorInactiveBlocksValue()
	if window == 0 {
		window = validatorSelectionActivityWindowBlocks()
	}
	if window == 0 {
		return append([]string{}, validators...), []string{}
	}
	// `tip` stores the value produced by this operation.
	tip := uint64(0)
	if height > 1 {
		tip = height - 1
	}
	if tip == 0 {
		tip = n.getFinalizedHeight()
		if tip == 0 && n.Blockchain != nil {
			tip = n.Blockchain.FinalizedHeight()
			if tip == 0 {
				tip = n.Blockchain.Height()
			}
		}
	}
	if tip < window {
		return append([]string{}, validators...), []string{}
	}
	// `start` stores the value produced by this operation.
	start := tip - window + 1
	if n.Blockchain == nil {
		return append([]string{}, validators...), []string{}
	}
	// `h` stores the value produced by this operation.
	for h := start; h <= tip; h++ {
		// `ok` stores whether the related condition is satisfied.
		if _, ok := n.Blockchain.GetBlock(h); !ok {
			return append([]string{}, validators...), []string{}
		}
	}

	// `active` stores the value produced by this operation.
	active := n.recentActiveValidatorsFromFinalizedChain(tip, window)
	// `online` stores the value produced by this operation.
	online := make([]string, 0, len(validators))
	// `offline` stores the value produced by this operation.
	offline := make([]string, 0)
	// `id` tracks the current position in the related collection.
	for _, id := range validators {
		// `norm` stores the value produced by this operation.
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		// `ok` stores whether the related condition is satisfied.
		if _, ok := active[norm]; ok {
			online = append(online, id)
			continue
		}
		offline = append(offline, id)
	}
	return canonicalValidatorIDs(online), canonicalValidatorIDs(offline)
}

// executionQuorumTotal returns the deterministic validator-set size for quorum.
func (n *Node) executionQuorumTotal(height uint64) int {

	if n == nil {

		return 0

	}

	if height > 0 {
		// `validators` and `ok` store whether the related condition is satisfied.
		if validators, _, ok := n.deterministicCommitteeValidatorsForHeight(height); ok && len(validators) > 0 {
			return len(validators)
		}
	}

	if n.Blockchain != nil {
		// `nextHeight` stores the value produced by this operation.
		nextHeight := n.Blockchain.Height() + 1
		// `validators` and `ok` store whether the related condition is satisfied.
		if validators, _, ok := n.deterministicCommitteeValidatorsForHeight(nextHeight); ok && len(validators) > 0 {
			return len(validators)
		}
	}

	// Bootstrap fallback only when deterministic set is temporarily unavailable.
	if n.allowBootstrapLiveValidatorFallback(height) {
		// `live` stores the value produced by this operation.
		if live := n.countLiveValidators(); live > 0 {
			return live
		}
	}

	return 0

}

var (
	// If finalized height is stalled for at least this long, emergency quorum
	// diagnostics become active. The commit/finality threshold itself remains
	// strict; relaxing it below >2/3 can create conflicting finalized blocks
	// during partitions or restart storms.
	execQuorumEmergencyStallTimeout = 8 * time.Second
	// `execQuorumEmergencyMaxDrop` stores the value used by this operation.
	execQuorumEmergencyMaxDrop = 1
)

// `quorumPolicyVersionV1` defines the constant value used by this package.
const quorumPolicyVersionV1 = "v1_consensus_ready_degraded"

type quorumPolicySnapshot struct {
	// `Mode` stores the value associated with this record.
	Mode string
	// `Version` stores the value associated with this record.
	Version string
	// `Total` stores the measured quantity used by this operation.
	Total int
	// `StrictRequired` stores the value associated with this record.
	StrictRequired int
	// `Required` stores the request data being processed.
	Required int
	// `ActiveReadyCount` stores the measured quantity used by this operation.
	ActiveReadyCount int
	// `Relaxed` stores the value associated with this record.
	Relaxed bool
	// `Reason` stores the value associated with this record.
	Reason string
}

// mainnetDegradedGraceWindow implements the mainnet degraded grace window helper.
func mainnetDegradedGraceWindow() time.Duration {
	return 60 * time.Second
}

// minEmergencyQuorumFloor returns the minimum emergency quorum floor.
func minEmergencyQuorumFloor(total int) int {
	if total <= 0 {
		return 0
	}
	if total <= 3 {
		return strictExecSupermajority(total)
	}
	return 3
}

// emergencyQuorumGraceWindow implements the emergency quorum grace window helper.
func emergencyQuorumGraceWindow() time.Duration {
	// `grace` stores the value produced by this operation.
	grace := execQuorumEmergencyStallTimeout
	if grace <= 0 {
		return 0
	}
	if protocolRequiresStrictConsensusSignatures() && grace < mainnetDegradedGraceWindow() {
		return mainnetDegradedGraceWindow()
	}
	return grace
}

// commitStallDuration implements the commit stall duration helper.
func (n *Node) commitStallDuration() time.Duration {
	if n == nil {
		return 0
	}
	n.commitMu.Lock()
	// `lastCommitAt` stores the value produced by this operation.
	lastCommitAt := n.lastCommitAt
	n.commitMu.Unlock()
	if lastCommitAt.IsZero() {
		return 0
	}
	// `stall` stores the value produced by this operation.
	stall := time.Since(lastCommitAt)
	if stall < 0 {
		return 0
	}
	return stall
}

// postBlockSafeModeMinWindow implements the post block safe mode min window helper.
func postBlockSafeModeMinWindow() time.Duration {
	if ConsensusPostBlockSafeModeMin <= 0 {
		return 5 * time.Second
	}
	return ConsensusPostBlockSafeModeMin
}

// postBlockSafeModeMaxWindow implements the post block safe mode max window helper.
func postBlockSafeModeMaxWindow() time.Duration {
	// `maxW` stores the value produced by this operation.
	maxW := ConsensusPostBlockSafeModeMax
	if maxW <= 0 {
		maxW = 8 * time.Second
	}
	// `minW` stores the value produced by this operation.
	minW := postBlockSafeModeMinWindow()
	if maxW < minW {
		maxW = minW
	}
	return maxW
}

// postBlockSafeModeHistoryLimit implements the post block safe mode history limit helper.
func postBlockSafeModeHistoryLimit() int {
	// `v` stores the value produced by this operation.
	v := ConsensusPostBlockSafeModeHistoryBlocks
	if v == 0 {
		v = 32
	}
	if v > 4096 {
		v = 4096
	}
	return int(v)
}

// postBlockSafeModeLiveQuorumBPS implements the post block safe mode live quorum bps helper.
func postBlockSafeModeLiveQuorumBPS() uint64 {
	// `v` stores the value produced by this operation.
	v := sanitizeBPS(ConsensusPostBlockSafeModeLiveQuorumBPS)
	if v == 0 {
		return 6700
	}
	return v
}

// postBlockSafeModeLiveQuorumAvailable implements the post block safe mode live quorum available helper.
func (n *Node) postBlockSafeModeLiveQuorumAvailable(height uint64) (CommitteeLivenessSnapshot, int, bool) {
	if n == nil || height == 0 {
		return CommitteeLivenessSnapshot{}, 0, false
	}
	// `committee` and `ok` store whether the related condition is satisfied.
	committee, _, ok := n.deterministicCommitteeValidatorsForHeight(height)
	if !ok || len(committee) == 0 {
		return CommitteeLivenessSnapshot{}, 0, false
	}
	// `snap` stores the value produced by this operation.
	snap := n.committeeLivenessSnapshot(height)
	if snap.CommitteeSize == 0 {
		snap.CommitteeSize = len(committee)
	}
	// `required` stores the request data being processed.
	required := safeModeLiveRequired(snap.CommitteeSize)
	if required == 0 {
		return snap, required, false
	}
	return snap, required, n.effectiveSafeModeLiveCount(snap, required) >= required
}

// adaptiveSafeModeWindowLocked implements the adaptive safe mode window locked helper.
func (n *Node) adaptiveSafeModeWindowLocked() time.Duration {
	// `minW` stores the value produced by this operation.
	minW := postBlockSafeModeMinWindow()
	// `maxW` stores the value produced by this operation.
	maxW := postBlockSafeModeMaxWindow()
	if len(n.safeModeObservedDelays) == 0 {
		return minW
	}
	// `sorted` stores the value produced by this operation.
	sorted := append([]time.Duration{}, n.safeModeObservedDelays...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i] < sorted[j] })
	// `idx` stores the current position in the related collection.
	idx := int(math.Ceil(0.95*float64(len(sorted)))) - 1
	if idx < 0 {
		idx = 0
	}
	if idx >= len(sorted) {
		idx = len(sorted) - 1
	}
	// `window` stores the value produced by this operation.
	window := sorted[idx] + 500*time.Millisecond
	if window < minW {
		window = minW
	}
	if window > maxW {
		window = maxW
	}
	return window
}

// safeModeLiveRequired implements the safe mode live required helper.
func safeModeLiveRequired(committeeSize int) int {
	if committeeSize <= 0 {
		return 0
	}
	// `bps` stores the value produced by this operation.
	bps := postBlockSafeModeLiveQuorumBPS()
	// `required` stores the request data being processed.
	required := (committeeSize*int(bps) + 9999) / 10000
	if required < 1 {
		required = 1
	}
	if required > committeeSize {
		required = committeeSize
	}
	return required
}

// committeeLivenessSnapshot implements the committee liveness snapshot helper.
func (n *Node) committeeLivenessSnapshot(height uint64) CommitteeLivenessSnapshot {
	// `out` stores the result produced by this operation.
	out := CommitteeLivenessSnapshot{Height: height}
	if n == nil || height == 0 {
		return out
	}

	// `committee` and `ok` store whether the related condition is satisfied.
	committee, _, ok := n.deterministicCommitteeValidatorsForHeight(height)
	if !ok {
		return out
	}
	out.CommitteeSize = len(committee)
	if len(committee) == 0 {
		return out
	}

	// `now` stores the value produced by this operation.
	now := time.Now()
	// `localFinalized` stores the value produced by this operation.
	localFinalized := n.getFinalizedHeight()
	// `liveMap` stores the value produced by this operation.
	liveMap := make(map[string]bool, len(committee))
	// `liveCount` stores the measured quantity used by this operation.
	liveCount := 0
	// `heartbeatCount` stores the measured quantity used by this operation.
	heartbeatCount := 0
	// `outOfDriftCount` stores the measured quantity used by this operation.
	outOfDriftCount := 0

	n.validatorMu.RLock()
	// `id` tracks the current position in the related collection.
	for _, id := range committee {
		// `st` stores the value produced by this operation.
		st := n.validatorStatus[id]
		// `eval` stores the value currently being processed.
		eval := n.evaluateValidatorLivenessLocked(id, st, now, localFinalized)
		liveMap[id] = eval.LiveStrict
		if eval.LiveStrict {
			liveCount++
		}
		if eval.InAnyHeartbeatSet && eval.FreshHeartbeat {
			heartbeatCount++
			if !eval.WithinDrift {
				outOfDriftCount++
			}
		}
	}
	n.validatorMu.RUnlock()

	n.validatorSetMu.Lock()
	if n.committeeLiveByHeight == nil {
		n.committeeLiveByHeight = make(map[uint64]map[string]bool)
	}
	n.committeeLiveByHeight[height] = liveMap
	// `window` stores the value produced by this operation.
	window := n.safeModeWindowByHeight[height]
	// `safeUntil` stores the value produced by this operation.
	safeUntil := n.safeModeUntilByHeight[height]
	n.pruneCommitteeStateLocked(height)
	n.validatorSetMu.Unlock()

	out.Live = liveCount
	out.HeartbeatLive = heartbeatCount
	out.OutOfDrift = outOfDriftCount
	out.Offline = len(committee) - liveCount
	out.WindowMs = uint64(window / time.Millisecond)
	out.SafeUntil = safeUntil
	return out
}

// committeeLivenessSnapshotForValidators implements the committee liveness snapshot for validators helper.
func (n *Node) committeeLivenessSnapshotForValidators(height uint64, committee []string) CommitteeLivenessSnapshot {
	// `out` stores the result produced by this operation.
	out := CommitteeLivenessSnapshot{Height: height}
	committee = canonicalValidatorIDs(committee)
	if n == nil || height == 0 || len(committee) == 0 {
		return out
	}
	out.CommitteeSize = len(committee)
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `localFinalized` stores the value produced by this operation.
	localFinalized := n.getFinalizedHeight()
	// `liveCount` stores the measured quantity used by this operation.
	liveCount := 0
	// `heartbeatCount` stores the measured quantity used by this operation.
	heartbeatCount := 0
	// `outOfDriftCount` stores the measured quantity used by this operation.
	outOfDriftCount := 0
	n.validatorMu.RLock()
	// `id` tracks the current position in the related collection.
	for _, id := range committee {
		// `st` stores the value produced by this operation.
		st := n.validatorStatus[id]
		// `eval` stores the value currently being processed.
		eval := n.evaluateValidatorLivenessLocked(id, st, now, localFinalized)
		if eval.LiveStrict {
			liveCount++
		}
		if eval.InAnyHeartbeatSet && eval.FreshHeartbeat {
			heartbeatCount++
			if !eval.WithinDrift {
				outOfDriftCount++
			}
		}
	}
	n.validatorMu.RUnlock()
	out.Live = liveCount
	out.HeartbeatLive = heartbeatCount
	out.OutOfDrift = outOfDriftCount
	out.Offline = len(committee) - liveCount
	return out
}

// `livenessReasonLogCooldown` defines the constant value used by this package.
const livenessReasonLogCooldown = 5 * time.Second

// formatLivenessReasonCounts implements the format liveness reason counts helper.
func formatLivenessReasonCounts(counts map[string]int) string {
	if len(counts) == 0 {
		return ""
	}
	// `keys` stores the key used to access the related value.
	keys := make([]string, 0, len(counts))
	// `k` tracks the current values while iterating.
	for k := range counts {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	// `parts` stores the value produced by this operation.
	parts := make([]string, 0, len(keys))
	// `k` tracks the current values while iterating.
	for _, k := range keys {
		parts = append(parts, fmt.Sprintf("%s=%d", k, counts[k]))
	}
	return strings.Join(parts, ",")
}

// shouldLogLivenessReason implements the should log liveness reason helper.
func (n *Node) shouldLogLivenessReason(key string, cooldown time.Duration) bool {
	if n == nil || key == "" {
		return false
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	n.livenessReasonLogMu.Lock()
	defer n.livenessReasonLogMu.Unlock()
	if n.livenessReasonLogLast == nil {
		n.livenessReasonLogLast = make(map[string]time.Time)
	}
	// `last` stores the value produced by this operation.
	last := n.livenessReasonLogLast[key]
	if !last.IsZero() && now.Sub(last) < cooldown {
		return false
	}
	n.livenessReasonLogLast[key] = now
	return true
}

// collectCommitteeLivenessFailReasons implements the collect committee liveness fail reasons helper.
func (n *Node) collectCommitteeLivenessFailReasons(height uint64, sampleLimit int) (map[string]int, []string) {
	if n == nil || height == 0 {
		return nil, nil
	}
	// `committee` and `ok` store whether the related condition is satisfied.
	committee, _, ok := n.deterministicCommitteeValidatorsForHeight(height)
	if !ok || len(committee) == 0 {
		return nil, nil
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `localFinalized` stores the value produced by this operation.
	localFinalized := n.getFinalizedHeight()
	// `counts` stores the measured quantity used by this operation.
	counts := make(map[string]int)
	// `samples` stores the value produced by this operation.
	samples := make([]string, 0, sampleLimit)
	n.validatorMu.RLock()
	// `id` tracks the current position in the related collection.
	for _, id := range committee {
		// `st` stores the value produced by this operation.
		st := n.validatorStatus[id]
		// `eval` stores the value currently being processed.
		eval := n.evaluateValidatorLivenessLocked(id, st, now, localFinalized)
		if eval.LiveStrict {
			continue
		}
		// `reason` stores the value produced by this operation.
		reason := strings.TrimSpace(eval.FailReason)
		if reason == "" {
			reason = "unknown"
		}
		counts[reason]++
		if sampleLimit > 0 && len(samples) < sampleLimit {
			samples = append(samples, fmt.Sprintf("%s:%s", ShortID(id), reason))
		}
	}
	n.validatorMu.RUnlock()
	return counts, samples
}

// logLivenessReasonSummary implements the log liveness reason summary helper.
func (n *Node) logLivenessReasonSummary(scope string, height uint64, required int, snap CommitteeLivenessSnapshot) {
	if n == nil || !DebugConsensus || height == 0 || required <= 0 || snap.CommitteeSize == 0 {
		return
	}
	// `key` stores the key used to access the related value.
	key := fmt.Sprintf("%s:%d", strings.TrimSpace(scope), height)
	if !n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
		return
	}
	// `counts` and `samples` store the measured quantity used by this operation.
	counts, samples := n.collectCommitteeLivenessFailReasons(height, 4)
	// `reasonSummary` stores the value produced by this operation.
	reasonSummary := formatLivenessReasonCounts(counts)
	// `sampleSummary` stores the value produced by this operation.
	sampleSummary := strings.Join(samples, ",")
	fmt.Printf("[LIVENESS] scope=%s height=%d live=%d required=%d heartbeat_live=%d out_of_drift=%d committee=%d reasons={%s} sample=[%s]\n",
		scope,
		height,
		snap.Live,
		required,
		snap.HeartbeatLive,
		snap.OutOfDrift,
		snap.CommitteeSize,
		reasonSummary,
		sampleSummary,
	)
}

// enterPostBlockSafeMode implements the enter post block safe mode helper.
func (n *Node) enterPostBlockSafeMode(nextHeight uint64) {
	if n == nil || nextHeight == 0 {
		return
	}
	if !ConsensusPostBlockSafeModeEnabled {
		return
	}
	if !n.postBlockSafeModeGateActiveForHeight(nextHeight) {
		return
	}

	// `committee` and `ok` store whether the related condition is satisfied.
	committee, _, ok := n.deterministicCommitteeValidatorsForHeight(nextHeight)
	if !ok {
		n.clearPostBlockSafeModeGate(nextHeight)
		if DebugConsensus {
			fmt.Printf("[SAFE-MODE] height=%d ended=committee_unavailable\n", nextHeight)
		}
		return
	}
	if len(committee) == 0 {
		n.clearPostBlockSafeModeGate(nextHeight)
		if DebugConsensus {
			fmt.Printf("[SAFE-MODE] height=%d ended=empty_committee\n", nextHeight)
		}
		return
	}
	// `snap`, `requiredLive`, and `liveReady` store the request data being processed.
	if snap, requiredLive, liveReady := n.postBlockSafeModeLiveQuorumAvailable(nextHeight); liveReady {
		n.clearPostBlockSafeModeGate(nextHeight)
		if DebugConsensus {
			fmt.Printf("[SAFE-MODE] height=%d window=%s live=%d required=%d heartbeat_live=%d out_of_drift=%d committee=%d ended=skip_live_quorum\n",
				nextHeight,
				0*time.Second,
				snap.Live,
				requiredLive,
				snap.HeartbeatLive,
				snap.OutOfDrift,
				snap.CommitteeSize,
			)
		}
		return
	}

	// `now` stores the value produced by this operation.
	now := time.Now()
	n.validatorSetMu.Lock()
	if n.safeModeUntilByHeight == nil {
		n.safeModeUntilByHeight = make(map[uint64]time.Time)
	}
	if n.safeModeWindowByHeight == nil {
		n.safeModeWindowByHeight = make(map[uint64]time.Duration)
	}
	// `window` stores the value produced by this operation.
	window := n.adaptiveSafeModeWindowLocked()
	n.safeModeWindowByHeight[nextHeight] = window
	n.safeModeUntilByHeight[nextHeight] = now.Add(window)
	n.pruneCommitteeStateLocked(nextHeight)
	n.validatorSetMu.Unlock()

	if DebugConsensus {
		// `snap` stores the value produced by this operation.
		snap := n.committeeLivenessSnapshot(nextHeight)
		// `requiredLive` stores the request data being processed.
		requiredLive := safeModeLiveRequired(snap.CommitteeSize)
		fmt.Printf("[SAFE-MODE] height=%d window=%s live=%d required=%d heartbeat_live=%d out_of_drift=%d committee=%d ended=started\n",
			nextHeight,
			window,
			snap.Live,
			requiredLive,
			snap.HeartbeatLive,
			snap.OutOfDrift,
			snap.CommitteeSize,
		)
	}
	n.persistConsensusSafetyStateAsync("post_block_safe_mode_started")
}

// enterPostBlockSafeModeAsync implements the enter post block safe mode async helper.
func (n *Node) enterPostBlockSafeModeAsync(nextHeight uint64) {
	if n == nil || nextHeight == 0 {
		return
	}
	// `liveReady` stores the value produced by this operation.
	if _, _, liveReady := n.postBlockSafeModeLiveQuorumAvailable(nextHeight); liveReady {
		return
	}
	if !n.armPostBlockSafeModeGate(nextHeight) {
		return
	}
	if !n.scheduleExecutionTask(func() {
		if n == nil {
			return
		}
		if n.shutdownCh != nil {
			select {
			case <-n.shutdownCh:
				return
			default:
			}
		}
		n.enterPostBlockSafeMode(nextHeight)
	}) {
		n.clearPostBlockSafeModeGate(nextHeight)
		return
	}
}

// postBlockSafeModeState implements the post block safe mode state helper.
func (n *Node) postBlockSafeModeState(height uint64) (active bool, until time.Time, window time.Duration) {
	if n == nil || height == 0 || !ConsensusPostBlockSafeModeEnabled {
		return false, time.Time{}, 0
	}
	// `gateArmed` stores the value produced by this operation.
	gateArmed := n.postBlockSafeModeGateActiveForHeight(height)
	n.validatorSetMu.RLock()
	if n.safeModeUntilByHeight == nil {
		n.validatorSetMu.RUnlock()
		if gateArmed {
			return true, time.Time{}, 0
		}
		return false, time.Time{}, 0
	}
	until = n.safeModeUntilByHeight[height]
	window = n.safeModeWindowByHeight[height]
	n.validatorSetMu.RUnlock()
	if until.IsZero() {
		if gateArmed {
			return true, time.Time{}, 0
		}
		return false, time.Time{}, 0
	}
	if time.Now().After(until) {
		return false, until, window
	}
	return true, until, window
}

// finishPostBlockSafeMode implements the finish post block safe mode helper.
func (n *Node) finishPostBlockSafeMode(height uint64, reason string) {
	if n == nil || height == 0 {
		return
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	n.validatorSetMu.Lock()
	// `until` and `ok` store whether the related condition is satisfied.
	until, ok := n.safeModeUntilByHeight[height]
	if !ok || until.IsZero() {
		n.validatorSetMu.Unlock()
		n.clearPostBlockSafeModeGate(height)
		return
	}
	// `window` stores the value produced by this operation.
	window := n.safeModeWindowByHeight[height]
	delete(n.safeModeUntilByHeight, height)
	delete(n.safeModeWindowByHeight, height)
	if window <= 0 {
		window = now.Sub(until)
	}
	// `start` stores the value produced by this operation.
	start := until.Add(-window)
	if start.After(now) {
		start = now
	}
	// `delay` stores the value produced by this operation.
	delay := now.Sub(start)
	if delay < 0 {
		delay = 0
	}
	// `historyLimit` stores the value produced by this operation.
	historyLimit := postBlockSafeModeHistoryLimit()
	n.safeModeObservedDelays = append(n.safeModeObservedDelays, delay)
	if len(n.safeModeObservedDelays) > historyLimit {
		n.safeModeObservedDelays = n.safeModeObservedDelays[len(n.safeModeObservedDelays)-historyLimit:]
	}
	n.pruneCommitteeStateLocked(height)
	n.validatorSetMu.Unlock()
	n.clearPostBlockSafeModeGate(height)

	if DebugConsensus {
		// `snap` stores the value produced by this operation.
		snap := n.committeeLivenessSnapshot(height)
		// `required` stores the request data being processed.
		required := safeModeLiveRequired(snap.CommitteeSize)
		fmt.Printf("[SAFE-MODE] height=%d window=%s live=%d required=%d ended=%s\n", height, window, snap.Live, required, reason)
	}
	n.persistConsensusSafetyStateAsync("post_block_safe_mode_finished")
}

// effectiveSafeModeLiveCount returns effective safe mode live count.
func (n *Node) effectiveSafeModeLiveCount(snap CommitteeLivenessSnapshot, required int) int {
	if snap.Live > 0 {
		return snap.Live
	}
	if required <= 0 {
		return snap.Live
	}
	if snap.HeartbeatLive >= required {
		if n != nil {
			// `key` stores the key used to access the related value.
			key := fmt.Sprintf("safe_mode_hb_fallback:%d", snap.Height)
			if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
				log.Printf("[SAFE-MODE] using heartbeat fallback height=%d heartbeat_live=%d required=%d", snap.Height, snap.HeartbeatLive, required)
			}
		}
		return snap.HeartbeatLive
	}
	return snap.Live
}

// tryExitPostBlockSafeMode implements the try exit post block safe mode helper.
func (n *Node) tryExitPostBlockSafeMode(height uint64) bool {
	// `active` and `until` store the value produced by this operation.
	active, until, _ := n.postBlockSafeModeState(height)
	if !active {
		if !until.IsZero() {
			n.finishPostBlockSafeMode(height, "timeout")
		}
		return true
	}
	// `snap` stores the value produced by this operation.
	snap := n.committeeLivenessSnapshot(height)
	// `required` stores the request data being processed.
	required := safeModeLiveRequired(snap.CommitteeSize)
	// `effectiveLive` stores the value produced by this operation.
	effectiveLive := n.effectiveSafeModeLiveCount(snap, required)
	if required == 0 || effectiveLive >= required {
		n.finishPostBlockSafeMode(height, "live_quorum")
		return true
	}
	if until.IsZero() {
		n.finishPostBlockSafeMode(height, "gate_only_no_window")
		return true
	}
	if DebugConsensus {
		n.logLivenessReasonSummary("safe_mode", height, required, snap)
	}
	if time.Now().After(until) {
		n.finishPostBlockSafeMode(height, "timeout")
		return true
	}
	return false
}

// countRecentHeartbeatValidatorsInSet implements the count recent heartbeat validators in set helper.
func (n *Node) countRecentHeartbeatValidatorsInSet(height uint64, ttl time.Duration) int {
	if n == nil || ttl <= 0 {
		return 0
	}
	// `validators` and `ok` store whether the related condition is satisfied.
	validators, _, ok := n.deterministicCommitteeValidatorsForHeight(height)
	if !ok {
		return 0
	}
	if len(validators) == 0 {
		return 0
	}
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `localFinalized` stores the value produced by this operation.
	localFinalized := n.getFinalizedHeight()

	n.validatorMu.RLock()
	defer n.validatorMu.RUnlock()

	// `count` stores the measured quantity used by this operation.
	count := 0
	// `id` tracks the current position in the related collection.
	for _, id := range validators {
		// `st` stores the value produced by this operation.
		st := n.validatorStatus[id]
		if st == nil || !st.Active || !st.ConsensusReadyKnown || !st.Enabled {
			continue
		}
		if !n.isValidatorLiveForConsensusLocked(id, st, now, localFinalized) {
			continue
		}
		if now.Sub(st.LastSeen) > ttl {
			continue
		}
		count++
	}
	return count
}

// inheritedDegradedQuorumPolicy implements the inherited degraded quorum policy helper.
func (n *Node) inheritedDegradedQuorumPolicy(height uint64, policy quorumPolicySnapshot, live int) (quorumPolicySnapshot, bool) {
	if n == nil || n.Blockchain == nil || policy.Required <= 0 {
		return policy, false
	}
	// `last` stores the value produced by this operation.
	last := n.Blockchain.LastBlock()
	if last.ID == 0 || (height > 0 && last.ID+1 != height) {
		return policy, false
	}
	if !strings.EqualFold(strings.TrimSpace(last.ConsensusMode), "DEGRADED") {
		return policy, false
	}
	if last.RequiredQuorum <= 0 || last.RequiredQuorum >= policy.Required {
		return policy, false
	}
	// `lastStrict` stores the value produced by this operation.
	lastStrict := last.StrictQuorum
	if lastStrict <= 0 {
		lastStrict = policy.StrictRequired
	}
	if lastStrict > 0 && last.RequiredQuorum < lastStrict {
		policy.Reason = "degraded_below_strict_ignored"
		return policy, false
	}
	if live < last.RequiredQuorum {
		return policy, false
	}
	n.commitMu.Lock()
	// `lastCommitAt` stores the value produced by this operation.
	lastCommitAt := n.lastCommitAt
	n.commitMu.Unlock()
	if lastCommitAt.IsZero() || time.Since(lastCommitAt) > blockProductionStaleThreshold() {
		return policy, false
	}
	policy.Mode = "DEGRADED"
	policy.Required = last.RequiredQuorum
	if last.StrictQuorum > 0 {
		policy.StrictRequired = last.StrictQuorum
	}
	if strings.TrimSpace(last.QuorumPolicyVersion) != "" {
		policy.Version = last.QuorumPolicyVersion
	}
	policy.Relaxed = true
	policy.Reason = "degraded_mode_continuation"
	return policy, true
}

// executionQuorumPolicy returns the exec quorum threshold and committed
// observability metadata for a given height. Commit/finality quorum follows the
// configured deterministic execution threshold; degraded liveness is reported as
// diagnostics rather than as a locally weakened finality threshold.
func (n *Node) executionQuorumPolicy(height uint64) quorumPolicySnapshot {
	// `total` stores the measured quantity used by this operation.
	total := n.executionQuorumTotal(height)
	// `required` stores the request data being processed.
	required := execQuorumRequired(total)
	// `policy` stores the value produced by this operation.
	policy := quorumPolicySnapshot{
		Mode:           "NORMAL",
		Version:        quorumPolicyVersionV1,
		Total:          total,
		StrictRequired: required,
		Required:       required,
	}
	if n == nil || total == 0 || required == 0 {
		return policy
	}
	if height == 0 && n.Blockchain != nil {
		height = n.Blockchain.Height() + 1
	}
	// `live` stores the value produced by this operation.
	live := len(n.consensusReadyValidatorsForHeight(height, nil))
	if live == 0 {
		live = n.countRecentHeartbeatValidatorsInSet(height, validatorLivenessHeartbeatTTL())
	}
	policy.ActiveReadyCount = live
	if live >= required {
		policy.Reason = "strict_quorum_satisfied"
		return policy
	}
	if !ExecQuorumEmergencyEnabled {
		policy.Reason = "emergency_disabled"
		return policy
	}
	// `grace` stores the value produced by this operation.
	grace := emergencyQuorumGraceWindow()
	if grace <= 0 || execQuorumEmergencyMaxDrop <= 0 {
		policy.Reason = "emergency_unconfigured"
		return policy
	}
	// `stall` stores the value produced by this operation.
	stall := n.commitStallDuration()
	if stall < grace {
		policy.Reason = "grace_window"
		return policy
	}
	if live == 0 {
		policy.Reason = "no_consensus_ready_heartbeats"
		return policy
	}

	// `relaxed` stores the value produced by this operation.
	relaxed := execQuorumRequired(live)
	// `floor` stores the value produced by this operation.
	floor := minEmergencyQuorumFloor(total)
	if relaxed < floor {
		relaxed = floor
	}
	// `minAfterDrop` stores the value produced by this operation.
	minAfterDrop := required - execQuorumEmergencyMaxDrop
	if minAfterDrop < floor {
		minAfterDrop = floor
	}
	if relaxed < minAfterDrop {
		relaxed = minAfterDrop
	}
	if relaxed > required || live < relaxed {
		policy.Reason = "insufficient_consensus_ready"
		return policy
	}
	if relaxed < required && DebugConsensus {
		fmt.Printf("[EXEC-QUORUM] height=%d strict=%d observed_relaxed=%d total=%d live=%d stall=%s action=strict_finality\n",
			height, required, relaxed, total, live, n.commitStallDuration().Round(time.Second))
	}
	if relaxed < required {
		policy.Reason = "strict_finality_required"
		return policy
	}
	policy.Reason = "strict_quorum_satisfied"
	return policy
}

// runtimeObservableQuorumPolicy implements the runtime observable quorum policy helper.
func (n *Node) runtimeObservableQuorumPolicy(height uint64, policy quorumPolicySnapshot) quorumPolicySnapshot {
	if n == nil || policy.Required <= 0 || policy.ActiveReadyCount >= policy.Required {
		return policy
	}
	if n.Blockchain == nil {
		return policy
	}
	// `last` stores the value produced by this operation.
	last := n.Blockchain.LastBlock()
	if last.ID == 0 || (height > 0 && last.ID+1 != height) {
		return policy
	}
	if !strings.EqualFold(strings.TrimSpace(last.ConsensusMode), "DEGRADED") {
		return policy
	}
	if last.RequiredQuorum <= 0 || last.RequiredQuorum >= policy.Required {
		return policy
	}
	// `lastStrict` stores the value produced by this operation.
	lastStrict := last.StrictQuorum
	if lastStrict <= 0 {
		lastStrict = policy.StrictRequired
	}
	if lastStrict > 0 && last.RequiredQuorum < lastStrict {
		policy.Reason = "recent_degraded_below_strict_ignored"
		return policy
	}
	if policy.ActiveReadyCount < last.RequiredQuorum {
		return policy
	}
	n.commitMu.Lock()
	// `lastCommitAt` stores the value produced by this operation.
	lastCommitAt := n.lastCommitAt
	n.commitMu.Unlock()
	if lastCommitAt.IsZero() || time.Since(lastCommitAt) > blockProductionStaleThreshold() {
		return policy
	}
	policy.Mode = "DEGRADED"
	policy.Required = last.RequiredQuorum
	if policy.StrictRequired == 0 {
		policy.StrictRequired = last.StrictQuorum
	}
	if strings.TrimSpace(policy.Version) == "" {
		policy.Version = last.QuorumPolicyVersion
	}
	policy.Relaxed = true
	policy.Reason = "recent_degraded_commit"
	return policy
}

// executionQuorumRequired returns the exec quorum threshold for a given height.
func (n *Node) executionQuorumRequired(height uint64) int {
	return n.executionQuorumPolicy(height).Required
}

// countLiveValidatorsReportingHeight implements the count live validators reporting height helper.
func (n *Node) countLiveValidatorsReportingHeight(height uint64) int {

	if height == 0 {

		return 0

	}

	// `now` stores the value produced by this operation.
	now := time.Now()

	// `statusTTL` defines the constant value used by this package.
	const statusTTL = 2 * time.Minute

	n.validatorMu.RLock()

	defer n.validatorMu.RUnlock()

	// `count` stores the measured quantity used by this operation.
	count := 0

	// `id` and `st` track the current position in the related collection.
	for id, st := range n.validatorStatus {

		if st == nil {

			continue

		}

		if now.Sub(st.LastSeen) > statusTTL {

			continue

		}

		// `inSet` stores the current position in the related collection.
		inSet := n.isValidatorInSetForHeight(id, height)
		if !inSet && height > 1 {
			inSet = n.isValidatorInSetForHeight(id, height-1)
		}
		if !inSet {
			inSet = n.isValidatorInSetForHeight(id, height+1)
		}
		if !inSet {

			continue

		}

		// `h` stores the value produced by this operation.
		h := st.FinalizedHeight

		if h == 0 {

			h = st.ReportedHeight

		}

		// Allow +/-1 block tolerance to absorb heartbeat race while keeping same epoch cohort.
		if h+1 < height || h > height+1 {

			continue

		}

		count++

	}

	return count

}

// maxValidatorHeight returns the maximum validator height.
func (n *Node) maxValidatorHeight() uint64 {

	// `maxHeight` stores the value produced by this operation.
	maxHeight := n.Blockchain.Height()

	// `now` stores the value produced by this operation.
	now := time.Now()

	// `statusTTL` defines the constant value used by this package.
	const statusTTL = 2 * time.Minute

	n.validatorMu.RLock()

	// `st` tracks the current values while iterating.
	for _, st := range n.validatorStatus {

		if st == nil {

			continue

		}

		if now.Sub(st.LastSeen) > statusTTL {

			continue

		}

		// `h` stores the value produced by this operation.
		h := st.FinalizedHeight

		if h == 0 {

			h = st.ReportedHeight

		}

		if h > maxHeight {

			maxHeight = h

		}

	}

	n.validatorMu.RUnlock()

	return maxHeight

}

// touchValidator implements the touch validator helper.
func (n *Node) touchValidator(id string, height uint64) {

	id = normalizeValidatorID(id)
	if id == "" {

		return

	}

	n.validatorMu.Lock()

	defer n.validatorMu.Unlock()

	// `st` and `ok` store whether the related condition is satisfied.
	st, ok := n.validatorStatus[id]

	if !ok {

		st = &ValidatorStatus{}

		n.validatorStatus[id] = st

	}

	if height > st.Height {

		st.Height = height

	}

	st.LastSeen = time.Now()
	st.Active = true
	if height > 0 {
		n.recordValidatorRejoinSignedLocked(id, height)
	}

}

// recordCommitVote implements the record commit vote helper.
func (n *Node) recordCommitVote(height uint64, hash string, from string) (int, int) {

	from = normalizeValidatorID(from)
	hash = strings.TrimSpace(hash)
	if from == "" || hash == "" || height == 0 {

		return 0, 0

	}

	// `validators` stores whether the related condition is satisfied.
	validators := n.freezeValidatorSetForHeight(height, n.GetConsensusValidators(int(height)))

	// `allowed` stores whether the related condition is satisfied.
	allowed := make(map[string]bool, len(validators))

	// `v` tracks the current values while iterating.
	for _, v := range validators {

		allowed[v] = true

	}

	if !allowed[from] {

		// `required` stores the request data being processed.
		required := n.executionQuorumRequiredForEpoch(height)
		if required == 0 {
			required = execQuorumRequired(len(validators))
		}
		return 0, required

	}

	// `required` stores the request data being processed.
	required := n.executionQuorumRequiredForEpoch(height)
	if required == 0 {
		required = execQuorumRequired(len(validators))
	}
	if required < 1 {
		required = 1
	}

	if n != nil && n.isCommittedReplayHeight(height) {
		return 0, required
	}

	n.commitMu.Lock()

	defer n.commitMu.Unlock()

	if n.commitVoted == nil {

		n.commitVoted = make(map[uint64]map[string]string)

	}

	// `ok` stores whether the related condition is satisfied.
	if _, ok := n.commitVoted[height]; !ok {

		n.commitVoted[height] = make(map[string]string)

	}

	// `prev` and `ok` store whether the related condition is satisfied.
	if prev, ok := n.commitVoted[height][from]; ok && prev != hash {

		// One commit vote per validator per height.

		return 0, required

	}

	n.commitVoted[height][from] = hash

	if n.commitVotes == nil {

		n.commitVotes = make(map[uint64]map[string]map[string]struct{})

	}

	// `ok` stores whether the related condition is satisfied.
	if _, ok := n.commitVotes[height]; !ok {

		n.commitVotes[height] = make(map[string]map[string]struct{})

	}

	// `ok` stores whether the related condition is satisfied.
	if _, ok := n.commitVotes[height][hash]; !ok {

		n.commitVotes[height][hash] = make(map[string]struct{})

	}

	n.commitVotes[height][hash][from] = struct{}{}

	// `count` stores the measured quantity used by this operation.
	count := len(n.commitVotes[height][hash])

	return count, required

}

// getCommittedHash implements the get committed hash helper.
func (n *Node) getCommittedHash(height uint64) (string, bool) {

	n.commitMu.Lock()

	defer n.commitMu.Unlock()

	if n.committed == nil {

		return "", false

	}

	// `h` and `ok` store whether the related condition is satisfied.
	h, ok := n.committed[height]

	return h, ok

}

// hasCommittedDifferentHash implements the has committed different hash helper.
func (n *Node) hasCommittedDifferentHash(height uint64, hash string) bool {

	if hash == "" || height == 0 {

		return false

	}

	// `committedHash` and `ok` store whether the related condition is satisfied.
	committedHash, ok := n.getCommittedHash(height)

	if ok && !strings.EqualFold(strings.TrimSpace(committedHash), strings.TrimSpace(hash)) {
		return true
	}
	// `persistedHash`, `found`, and `err` store the error produced by this operation.
	persistedHash, found, err := n.loadFinalizedHashInvariant(height)
	if err == nil && found && strings.TrimSpace(persistedHash) != "" {
		return !strings.EqualFold(strings.TrimSpace(persistedHash), strings.TrimSpace(hash))
	}
	return false

}

// hasCommitQuorum implements the has commit quorum helper.
func (n *Node) hasCommitQuorum(height uint64, hash string) bool {
	// `count` and `required` store the measured quantity used by this operation.
	_, _, count, required := n.commitVoteEvidence(height, hash)
	if required > 0 && count >= required {
		return true
	}
	if n == nil || n.Blockchain == nil {
		return false
	}
	// `block` and `ok` store whether the related condition is satisfied.
	block, ok := n.Blockchain.GetBlock(height)
	if !ok || !strings.EqualFold(strings.TrimSpace(block.BlockHash), strings.TrimSpace(hash)) {
		return false
	}
	if required == 0 {
		required = n.executionQuorumRequiredForEpoch(height)
	}
	return required > 0 && n.verifyFinalityCertificate(block, finalitySignersForBlock(block), required) == nil

}

type StringList []string

// UnmarshalTOML implements the unmarshal toml helper.
func (s *StringList) UnmarshalTOML(data interface{}) error {

	// `v` stores the value produced by this operation.
	switch v := data.(type) {

	case string:

		*s = splitCommaList(v)

		return nil

	case []interface{}:

		// `out` stores the result produced by this operation.
		out := make([]string, 0, len(v))

		// `raw` tracks the current values while iterating.
		for _, raw := range v {

			// `str` and `ok` store whether the related condition is satisfied.
			str, ok := raw.(string)

			if !ok {

				return fmt.Errorf("string list contains non-string value")

			}

			str = strings.TrimSpace(str)

			if str != "" {

				out = append(out, str)

			}

		}

		*s = out

		return nil

	case []string:

		// `out` stores the result produced by this operation.
		out := make([]string, 0, len(v))

		// `str` tracks the current values while iterating.
		for _, str := range v {

			str = strings.TrimSpace(str)

			if str != "" {

				out = append(out, str)

			}

		}

		*s = out

		return nil

	default:

		return fmt.Errorf("unsupported string list type %T", data)

	}

}

