// handleSnapshotDownload handles snapshot download.
func (s *Server) handleSnapshotDownload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	if !authorizedSubmit(r) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	if s == nil || s.Node == nil {
		http.Error(w, "node unavailable", http.StatusServiceUnavailable)
		return
	}
	// `height` and `err` store the error produced by this operation.
	height, err := snapshotQueryUint64(r, "height")
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	// `minHeight` and `err` store the error produced by this operation.
	minHeight, err := snapshotQueryUint64(r, "min_height")
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	// `apply` stores the value produced by this operation.
	apply := true
	// `raw` stores the value produced by this operation.
	if raw := strings.TrimSpace(r.URL.Query().Get("apply")); raw != "" {
		apply = snapshotQueryBool(r, "apply")
	}
	// `allowReapply` stores the value produced by this operation.
	allowReapply := snapshotQueryBool(r, "reapply")
	// `strictCore` stores the value produced by this operation.
	strictCore := snapshotQueryBool(r, "strict_core")
	// `result` and `err` store the error produced by this operation.
	result, err := s.Node.downloadTrustedSnapshotAndStore(height, minHeight, strictCore, apply, allowReapply, true)
	if err != nil || result == nil {
		// `reason` stores the value produced by this operation.
		reason := "nil_result"
		if err != nil {
			reason = err.Error()
		}
		fmt.Printf("[SNAPSHOT-DOWNLOAD-FAIL] path=/snapshot/download height=%d min=%d apply=%t strict_core=%t reason=%s\n",
			height,
			minHeight,
			apply,
			strictCore,
			reason,
		)
		http.Error(w, "snapshot download failed", http.StatusServiceUnavailable)
		return
	}
	// `resp` stores the response produced by this operation.
	resp := snapshotDownloadResponse(result)
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(resp)
}

