	if bridgeGatewayState, err := s.bridgeGatewaySnapshot(); err == nil {
		bridgeRoutes := s.bridgeRoutesForState(bridgeGatewayState)
		readyRoutes := 0
		for _, route := range bridgeRoutes {
			if route.Ready {
				readyRoutes++
			}
		}
		pendingTransfers, completedTransfers := countBridgeTransferStates(bridgeGatewayState)
		freshCheckpoints := 0
		for _, checkpointID := range bridgeGatewayState.LatestCheckpointByChain {
			if checkpoint, ok := bridgeGatewayState.Checkpoints[checkpointID]; ok && bridgeCheckpointIsFresh(checkpoint, time.Now().UTC()) {
				freshCheckpoints++
			}
		}
		appendPromGauge(&out, "msc_bridge_emergency_paused", "Bridge gateway emergency pause state (1/0).", promLabels(baseLabels, map[string]string{"version": BridgeGatewayVersion}), boolToPromFloat(bridgeGatewayState.Paused))
		appendPromGauge(&out, "msc_bridge_registered_contracts", "Registered external bridge contracts.", promLabels(baseLabels, map[string]string{"version": BridgeGatewayVersion}), float64(len(bridgeGatewayState.Contracts)))
		appendPromGauge(&out, "msc_bridge_validators_active", "Active cryptographically valid bridge validator keys.", promLabels(baseLabels, map[string]string{"version": BridgeGatewayVersion}), float64(activeBridgeValidatorCount(bridgeGatewayState.Validators)))
		appendPromGauge(&out, "msc_bridge_finality_checkpoints", "Persisted threshold-signed source finality checkpoints.", promLabels(baseLabels, map[string]string{"version": BridgeGatewayVersion}), float64(len(bridgeGatewayState.Checkpoints)))
		appendPromGauge(&out, "msc_bridge_finality_checkpoints_fresh", "Source chains with a fresh latest threshold finality checkpoint.", promLabels(baseLabels, map[string]string{"version": BridgeGatewayVersion}), float64(freshCheckpoints))
		appendPromGauge(&out, "msc_bridge_routes_ready", "Bridge routes that pass all readiness gates.", promLabels(baseLabels, map[string]string{"version": BridgeGatewayVersion}), float64(readyRoutes))
		appendPromGauge(&out, "msc_bridge_transfers_pending", "Bridge transfers awaiting a terminal state.", promLabels(baseLabels, map[string]string{"version": BridgeGatewayVersion}), float64(pendingTransfers))
		appendPromGauge(&out, "msc_bridge_transfers_completed", "Completed bridge transfers retained by the gateway.", promLabels(baseLabels, map[string]string{"version": BridgeGatewayVersion}), float64(completedTransfers))
	}
