// handleAuthChallenge handles auth challenge.
func (s *Server) handleAuthChallenge(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet && r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	// `req` stores the request data being processed.
	var req struct {
		// `SessionID` stores the value associated with this record.
		SessionID string `json:"session_id"`

		// `NodeID` stores the value associated with this record.
		NodeID string `json:"node_id"`
	}

	if r.Method == http.MethodPost {

		// `err` stores the error produced by this operation.
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {

			http.Error(w, "invalid request body", http.StatusBadRequest)

			return

		}

	}

	// `sessionID` stores the value produced by this operation.
	sessionID := strings.TrimSpace(r.URL.Query().Get("session"))

	if sessionID == "" {

		sessionID = strings.TrimSpace(req.SessionID)

	}

	// `nodeID` stores the value produced by this operation.
	nodeID := strings.TrimSpace(r.URL.Query().Get("node_id"))

	if nodeID == "" {

		nodeID = strings.TrimSpace(req.NodeID)

	}

	if nodeID == "" && s.Node != nil {

		nodeID = s.Node.ID

	}

	if nodeID == "" {

		http.Error(w, "node_id required", http.StatusBadRequest)

		return

	}

	// `now` stores the value produced by this operation.
	now := time.Now()

	// `sess` stores the value used by this operation.
	var sess *AuthSession

	authMu.Lock()

	cleanupAuthLocked(now)

	if sessionID != "" {

		// `existing` and `ok` store whether the related condition is satisfied.
		if existing, ok := authSessions[sessionID]; ok && now.Before(existing.ExpiresAt) {

			if existing.NodeID != nodeID {
				delete(authSessions, sessionID)
			} else {
				sess = existing

			}

		} else {

			delete(authSessions, sessionID)

		}

	}

	authMu.Unlock()

	if sess == nil {

		validatorID := ""
		if s.Node != nil && nodeIdentityMapKey(s.Node.ID) == nodeIdentityMapKey(nodeID) {
			validatorID = s.Node.localConsensusValidatorIDForHeight(s.Node.currentEpoch())
		}
		sess = initAuthSession(nodeID, validatorID)

	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"session_id": sess.SessionID,

		"node_id": sess.NodeID,

		"validator_id": sess.ValidatorID,

		"chain_id": sess.ChainID,

		"timestamp": sess.CreatedAt.Unix(),

		"nonce": sess.Nonce,

		"message": sess.Message,

		"expires_at": sess.ExpiresAt.Unix(),
	})

}

// handleAuthVerify handles auth verify.
func (s *Server) handleAuthVerify(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	// `req` stores the request data being processed.
	var req struct {
		// `SessionID` stores the value associated with this record.
		SessionID string `json:"session_id"`

		// `PublicKey` stores the key used to access the related value.
		PublicKey string `json:"public_key"`

		// `Signature` stores the value associated with this record.
		Signature string `json:"signature"`
	}

	// `err` stores the error produced by this operation.
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {

		http.Error(w, "invalid request body", http.StatusBadRequest)

		return

	}

	req.SessionID = strings.TrimSpace(req.SessionID)

	req.PublicKey = strings.TrimSpace(req.PublicKey)

	req.Signature = strings.TrimSpace(req.Signature)

	if req.SessionID == "" || req.PublicKey == "" || req.Signature == "" {

		http.Error(w, "session_id, public_key, signature required", http.StatusBadRequest)

		return

	}

	// `now` stores the value produced by this operation.
	now := time.Now()

	authMu.Lock()

	cleanupAuthLocked(now)

	// `sess` and `ok` store whether the related condition is satisfied.
	sess, ok := authSessions[req.SessionID]

	if !ok || now.After(sess.ExpiresAt) {

		delete(authSessions, req.SessionID)

		authMu.Unlock()

		http.Error(w, "session expired", http.StatusGone)

		return

	}

	authMu.Unlock()

	// `pubBytes` and `err` store the error produced by this operation.
	pubBytes, err := hex.DecodeString(req.PublicKey)

	if err != nil || len(pubBytes) != ed25519.PublicKeySize {

		http.Error(w, "invalid public key", http.StatusBadRequest)

		return

	}

	// `sigBytes` and `err` store the error produced by this operation.
	sigBytes, err := hex.DecodeString(req.Signature)

	if err != nil || len(sigBytes) != ed25519.SignatureSize {

		http.Error(w, "invalid signature", http.StatusBadRequest)

		return

	}

	if !ed25519.Verify(ed25519.PublicKey(pubBytes), []byte(sess.Message), sigBytes) {

		http.Error(w, "signature verification failed", http.StatusBadRequest)

		return

	}

	// `addr` stores the address used by this operation.
	addr := AddressFromPublicKey(ed25519.PublicKey(pubBytes))

	if addr == "" {

		http.Error(w, "address derivation failed", http.StatusBadRequest)

		return

	}

	// `balance` stores the value produced by this operation.
	balance := 0

	if s.Node != nil {

		balance = getBalance(s.Node.Ledger, CoinSymbol, addr)

	}

	// `staked`, `lockedUntil`, `eligible`, and `reason` store the synchronization state protecting shared data.
	validatorID := normalizeValidatorID(sess.ValidatorID)
	if validatorID == "" {
		validatorID = normalizeValidatorID(sess.NodeID)
	}
	staked, lockedUntil, eligible, reason := validatorStakeStatus(s.Node, addr, validatorID)

	// `token` stores the value produced by this operation.
	token := randomHex(32)

	sess.WalletAddr = addr

	sess.WalletPubKey = req.PublicKey

	sess.Token = token

	sess.TokenExpires = now.Add(authTokenTTL())

	sess.ValidatorOK = eligible

	sess.ValidatorNote = reason

	authMu.Lock()

	authSessions[req.SessionID] = sess

	authTokens[token] = sess

	if s.Node != nil && nodeIdentityMapKey(s.Node.ID) == nodeIdentityMapKey(sess.NodeID) {

		authWalletAddr = addr

		authWalletPub = req.PublicKey

		authNodeID = sess.NodeID

		// Wallet login readiness is independent from stake eligibility.
		authReady = true

	}

	authMu.Unlock()

	if s.Node != nil && nodeIdentityMapKey(s.Node.ID) == nodeIdentityMapKey(sess.NodeID) {
		s.Node.persistWalletAuthBinding(addr, req.PublicKey)
	}

	// Bind validator rewards to the authenticated wallet for this node.
	// This ensures proposer/validator rewards are credited to the same wallet
	// used for validator auth (subject to stake eligibility rules).
	if s.Node != nil && nodeIdentityMapKey(s.Node.ID) == nodeIdentityMapKey(sess.NodeID) && s.Node.Role == "validator" {
		setValidatorRewardWallet(&s.Node.Ledger, validatorID, addr)
		_ = SaveNodeLedger(s.Node.ID, s.Node.DataDir, s.Node.currentExecutionLedgerClone())
	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"token": token,

		"wallet": addr,

		"balance": balance,

		"locked_stake": staked,

		"locked_until_epoch": lockedUntil,

		"validator_id": validatorID,

		"validator_eligible": eligible,

		"note": reason,

		"token_expires_at": sess.TokenExpires.Unix(),
	})

}

// handleBalance handles balance.
func (s *Server) handleBalance(

	w http.ResponseWriter,

	r *http.Request,

) {

	// `ip` stores the current position in the related collection.
	ip := strings.Split(r.RemoteAddr, ":")[0]

	if rateLimited(ip) {

		http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	if s == nil || s.Node == nil {

		http.Error(w, "node unavailable", http.StatusServiceUnavailable)

		return

	}

	// `addr` stores the address used by this operation.
	addr := r.URL.Query().Get("address")

	if addr == "" {

		http.Error(w, "address required", http.StatusBadRequest)

		return

	}
	addr = canonicalAddressKey(addr)

	// `coin` stores the value produced by this operation.
	coin := r.URL.Query().Get("coin")

	if coin == "" {

		coin = CoinSymbol

	}

	// `stateTag` stores the value produced by this operation.
	stateTag := strings.TrimSpace(r.URL.Query().Get("state"))
	// `ledger`, `ledgerHeight`, `resolvedState`, and `ok` store whether the related condition is satisfied.
	ledger, ledgerHeight, resolvedState, ok := s.resolveBalanceLedger(stateTag)
	if !ok {
		http.Error(w, "invalid state (use latest|finalized|pending)", http.StatusBadRequest)
		return
	}

	// `bal` stores the value produced by this operation.
	bal := getBalance(ledger, coin, addr)

	_ = json.NewEncoder(w).Encode(map[string]any{

		"address": displayAddress(addr),

		"balance": bal,

		"coin": coin,

		"state": resolvedState,

		"height": ledgerHeight,
	})

}

// resolveBalanceLedger implements the resolve balance ledger helper.
func (s *Server) resolveBalanceLedger(state string) (Ledger, uint64, string, bool) {
	if s == nil || s.Node == nil {
		return Ledger{}, 0, "", false
	}
	// `tag` stores the value produced by this operation.
	tag := strings.ToLower(strings.TrimSpace(state))
	if tag == "" {
		tag = "latest"
	}

	switch tag {
	case "latest":
		// `height` stores the value produced by this operation.
		height := uint64(0)
		if s.Node.Blockchain != nil {
			height = s.Node.Blockchain.Height()
		}
		// Latest and finalized balances must share the same authoritative
		// height resolver. Reading Node.Ledger directly allows a stale runtime
		// copy to overwrite a verified post-commit balance at the same height.
		ledger, ok := s.ledgerAtHeight(height)
		if !ok {
			return Ledger{}, 0, "", false
		}
		return ledger, height, tag, true
	case "finalized":
		// `height` stores the value produced by this operation.
		height := s.explorerAvailableFinalizedHeight()
		// `ledger` and `ok` store whether the related condition is satisfied.
		ledger, ok := s.ledgerAtHeight(height)
		if !ok {
			return Ledger{}, 0, "", false
		}
		return ledger, height, tag, true
	case "pending":
		// `ledger`, `height`, and `ok` store whether the related condition is satisfied.
		ledger, height, ok := s.pendingLedger()
		if !ok {
			return Ledger{}, 0, "", false
		}
		return ledger, height, tag, true
	default:
		return Ledger{}, 0, "", false
	}
}

