// handleWalletStatus handles wallet status.
func (s *Server) handleWalletStatus(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	// `addr` stores the address used by this operation.
	addr := strings.TrimSpace(r.URL.Query().Get("address"))

	if addr == "" {

		// `wallet` and `err` store the error produced by this operation.
		if wallet, err := LoadSecureWallet(); err == nil {

			addr = wallet.Address

		}

	}
	addr = canonicalAddressKey(addr)

	if addr == "" {

		http.Error(w, "address required", http.StatusBadRequest)

		return

	}

	// `validatorID` stores whether the related condition is satisfied.
	validatorID := ""

	// `staked` stores the value produced by this operation.
	staked := 0

	// `lockedUntil` stores the synchronization state protecting shared data.
	lockedUntil := uint64(0)

	if s.Node != nil {

		// `key` and `rec` track the key used to access the related value.
		for key, rec := range s.Node.Ledger.Stakes {

			if rec.Amount <= 0 {

				continue

			}

			// `parts` stores the value produced by this operation.
			parts := strings.SplitN(key, "|", 2)

			if len(parts) != 2 {

				continue

			}

			if !addressesEqual(parts[0], addr) {

				continue

			}

			// `vid` stores the value produced by this operation.
			vid := strings.TrimSpace(parts[1])

			if vid == "" {

				continue

			}

			if rec.Amount > staked {

				validatorID = vid

				staked = rec.Amount

				lockedUntil = rec.LockedUntil

			}

		}

	}

	// `eligible` stores the value produced by this operation.
	eligible := !ValidatorRequireStake

	// `eligibleReason` stores the value produced by this operation.
	eligibleReason := ""

	if s.Node != nil && validatorID != "" {

		staked, lockedUntil, eligible, eligibleReason = validatorStakeStatus(s.Node, addr, validatorID)

	}

	// `height` stores the value produced by this operation.
	height := uint64(0)

	if s.Node != nil && s.Node.Blockchain != nil {

		height = s.Node.Blockchain.FinalizedHeight()

		if height == 0 {

			height = s.Node.Blockchain.Height()

		}

	}

	if height == 0 {

		s.Node.commitMu.Lock()

		height = s.Node.committedHeight

		s.Node.commitMu.Unlock()

	}

	// `status` stores the value produced by this operation.
	status := "none"

	// `pendingAddHeight` stores the value produced by this operation.
	pendingAddHeight := uint64(0)

	// `pendingRemoveHeight` stores the value produced by this operation.
	pendingRemoveHeight := uint64(0)

	if validatorID != "" && s.Node != nil {

		status = "inactive"
		// `isActive` stores the current position in the related collection.
		isActive := false
		// `checkHeights` stores the value produced by this operation.
		checkHeights := []uint64{s.Node.currentEpoch()}
		if height > 0 {
			checkHeights = append(checkHeights, height)
			checkHeights = append(checkHeights, height+1)
		}
		// `seenCheck` stores the value produced by this operation.
		seenCheck := make(map[uint64]struct{}, len(checkHeights))
		// `h` tracks the current values while iterating.
		for _, h := range checkHeights {
			if h == 0 {
				continue
			}
			// `ok` stores whether the related condition is satisfied.
			if _, ok := seenCheck[h]; ok {
				continue
			}
			seenCheck[h] = struct{}{}
			if s.Node.isValidatorInSetForHeight(validatorID, h) {
				isActive = true
				break
			}
		}
		// `lookupPendingActivation` stores the value produced by this operation.
		lookupPendingActivation := func(set map[string]uint64, id string) (uint64, bool) {
			if set == nil {
				return 0, false
			}
			// `act` and `ok` store whether the related condition is satisfied.
			if act, ok := set[id]; ok {
				return act, true
			}
			// `key` and `act` track the key used to access the related value.
			for key, act := range set {
				if strings.EqualFold(strings.TrimSpace(key), strings.TrimSpace(id)) {
					return act, true
				}
			}
			return 0, false
		}

		s.Node.validatorSetMu.RLock()

		// `act` and `ok` store whether the related condition is satisfied.
		if act, ok := lookupPendingActivation(s.Node.pendingValidators, validatorID); ok {

			pendingAddHeight = act

		}

		// `act` and `ok` store whether the related condition is satisfied.
		if act, ok := lookupPendingActivation(s.Node.pendingValidatorRemovals, validatorID); ok {

			pendingRemoveHeight = act

		}

		s.Node.validatorSetMu.RUnlock()

		if isActive {
			status = "active"
		}
		if pendingAddHeight > 0 && !isActive {
			status = "pending_add"
		}
		if pendingRemoveHeight > 0 {
			if isActive {
				status = "active_pending_remove"
			} else {
				status = "pending_remove"
			}
		}

	}

	// `rewardWallet` stores the value produced by this operation.
	rewardWallet := ""
	if s.Node != nil && validatorID != "" {
		// `addr` and `ok` store whether the related condition is satisfied.
		if addr, ok := validatorRewardWallet(&s.Node.Ledger, validatorID); ok {
			rewardWallet = addr
		}
	}

	// `validatorConsensusPubKey` stores whether the related condition is satisfied.
	validatorConsensusPubKey := ""
	// `validatorConsensusPubKeyAnchored` stores whether the related condition is satisfied.
	validatorConsensusPubKeyAnchored := false
	// `validatorConsensusPubKeySource` stores whether the related condition is satisfied.
	validatorConsensusPubKeySource := "none"
	if s.Node != nil && validatorID != "" {
		// `snapshotHeight` stores the value produced by this operation.
		snapshotHeight := height + 1
		if snapshotHeight == 0 {
			snapshotHeight = 1
		}
		// `registrySnapshot` stores the value produced by this operation.
		registrySnapshot := s.Node.validatorRegistrySnapshotForHeight(snapshotHeight)
		validatorConsensusPubKey = validatorConsensusPubKeyHexFromSnapshot(registrySnapshot, validatorID)
		validatorConsensusPubKeyAnchored, validatorConsensusPubKeySource = s.Node.validatorConsensusPubKeyStatus(validatorID, registrySnapshot)
	}

	// `localValidatorID` stores the value produced by this operation.
	localValidatorID := ""
	// `localValidatorKeyLoaded` stores the value produced by this operation.
	localValidatorKeyLoaded := false
	// `localValidatorConsensusPubKey` stores the key used to access the related value.
	localValidatorConsensusPubKey := ""
	// `localValidatorConsensusPubKeyAnchored` stores the value produced by this operation.
	localValidatorConsensusPubKeyAnchored := false
	// `localValidatorConsensusPubKeySource` stores the value produced by this operation.
	localValidatorConsensusPubKeySource := "none"
	if s.Node != nil {
		localValidatorID = s.Node.localConsensusValidatorIDForHeight(height + 1)
		// `keyHealth` stores the key used to access the related value.
		keyHealth := CollectValidatorKeyHealth(localValidatorID, s.Node.DataDir, s.Node.ValidatorKey)
		localValidatorKeyLoaded = keyHealth.Loaded
		if localValidatorKeyLoaded && len(s.Node.ValidatorKey.PublicKey) == ed25519.PublicKeySize {
			localValidatorConsensusPubKey = strings.ToLower(hex.EncodeToString(s.Node.ValidatorKey.PublicKey))
		}
		if localValidatorID != "" {
			// `snapshotHeight` stores the value produced by this operation.
			snapshotHeight := height + 1
			if snapshotHeight == 0 {
				snapshotHeight = 1
			}
			// `registrySnapshot` stores the value produced by this operation.
			registrySnapshot := s.Node.validatorRegistrySnapshotForHeight(snapshotHeight)
			localValidatorConsensusPubKeyAnchored, localValidatorConsensusPubKeySource = s.Node.validatorConsensusPubKeyStatus(localValidatorID, registrySnapshot)
		}
	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"wallet": displayAddress(addr),

		"validator_id": validatorID,

		"stake": staked,

		"locked_until_epoch": lockedUntil,

		"eligible": eligible,

		"eligible_reason": eligibleReason,

		"reward_wallet": displayAddress(rewardWallet),

		"status": status,

		"pending_add_height": pendingAddHeight,

		"pending_remove_height": pendingRemoveHeight,

		"validator_consensus_pubkey":          validatorConsensusPubKey,
		"validator_consensus_pubkey_anchored": validatorConsensusPubKeyAnchored,
		"validator_consensus_pubkey_source":   validatorConsensusPubKeySource,

		"local_validator_id":                        localValidatorID,
		"local_validator_key_loaded":                localValidatorKeyLoaded,
		"local_validator_consensus_pubkey":          localValidatorConsensusPubKey,
		"local_validator_consensus_pubkey_anchored": localValidatorConsensusPubKeyAnchored,
		"local_validator_consensus_pubkey_source":   localValidatorConsensusPubKeySource,

		"height": height,
	})

}

// handleWalletCreate handles wallet create.
func (s *Server) handleWalletCreate(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	// `req` stores the request data being processed.
	var req struct {
		// `Password` stores the value associated with this record.
		Password string `json:"password"`

		// `Force` stores the value associated with this record.
		Force bool `json:"force"`

		// `Account` stores the measured quantity used by this operation.
		Account uint32 `json:"account"`
		// `Change` stores the value associated with this record.
		Change uint32 `json:"change"`
		// `Index` stores the current position in the related collection.
		Index uint32 `json:"index"`
	}

	// `err` stores the error produced by this operation.
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {

		http.Error(w, "invalid request body", http.StatusBadRequest)

		return

	}

	if strings.TrimSpace(req.Password) == "" {

		http.Error(w, "password required", http.StatusBadRequest)

		return

	}

	if !req.Force {

		// `err` stores the error produced by this operation.
		if _, err := os.Stat(secureWalletPath()); err == nil {

			http.Error(w, "wallet already exists", http.StatusConflict)

			return

		}

	}

	// `wallet`, `mnemonic`, and `err` store the error produced by this operation.
	wallet, mnemonic, err := CreateSecureWalletWithPath(
		req.Password,
		req.Account,
		req.Change,
		req.Index,
	)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"address": wallet.Address,

		"publicKey": wallet.PublicKey,

		"mnemonic": mnemonic,
		"hd":       wallet.HD,
	})

}

// handleWalletRecover handles wallet recover.
func (s *Server) handleWalletRecover(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	// `req` stores the request data being processed.
	var req struct {
		// `Mnemonic` stores the value associated with this record.
		Mnemonic string `json:"mnemonic"`

		// `Password` stores the value associated with this record.
		Password string `json:"password"`

		// `Account` stores the measured quantity used by this operation.
		Account uint32 `json:"account"`
		// `Change` stores the value associated with this record.
		Change uint32 `json:"change"`
		// `Index` stores the current position in the related collection.
		Index uint32 `json:"index"`
	}

	// `err` stores the error produced by this operation.
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {

		http.Error(w, "invalid request body", http.StatusBadRequest)

		return

	}

	if strings.TrimSpace(req.Mnemonic) == "" || strings.TrimSpace(req.Password) == "" {

		http.Error(w, "mnemonic and password required", http.StatusBadRequest)

		return

	}

	// `wallet` and `err` store the error produced by this operation.
	wallet, err := RecoverWalletWithPath(
		req.Mnemonic,
		req.Password,
		req.Account,
		req.Change,
		req.Index,
	)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// `err` stores the error produced by this operation.
	if err := SaveSecureWallet(wallet); err != nil {

		http.Error(w, "failed to save wallet", http.StatusInternalServerError)

		return

	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"address": wallet.Address,

		"publicKey": wallet.PublicKey,

		"hd": wallet.HD,
	})

}

// handleStake handles stake.
func (s *Server) handleStake(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	// `req` stores the request data being processed.
	var req struct {
		// `ValidatorID` stores whether the related condition is satisfied.
		ValidatorID string `json:"validator_id"`

		// `ValidatorPubKey` stores whether the related condition is satisfied.
		ValidatorPubKey string `json:"validator_pubkey"`

		// `Amount` stores the value associated with this record.
		Amount int `json:"amount"`

		// `Coin` stores the value associated with this record.
		Coin string `json:"coin"`

		// `Password` stores the value associated with this record.
		Password string `json:"password"`

		// `LockEpochs` stores the synchronization state protecting shared data.
		LockEpochs uint64 `json:"lock_epochs"`
	}

	// `err` stores the error produced by this operation.
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {

		http.Error(w, "invalid request body", http.StatusBadRequest)

		return

	}

	if strings.TrimSpace(req.ValidatorID) == "" || req.Amount <= 0 {

		http.Error(w, "validator_id and amount required", http.StatusBadRequest)

		return

	}

	// `wallet` and `err` store the error produced by this operation.
	wallet, err := LoadSecureWallet()

	if err != nil {

		http.Error(w, "secure wallet not found", http.StatusNotFound)

		return

	}

	// `other` and `ok` store whether the related condition is satisfied.
	if other, ok := walletBoundValidator(&s.Node.Ledger, wallet.Address, req.ValidatorID); ok {

		http.Error(w, fmt.Sprintf("wallet already bound to validator %s", other), http.StatusBadRequest)

		return

	}

	// `coin` stores the value produced by this operation.
	coin := normalizeCoin(req.Coin)
	if !isProtocolCoinAllowed(coin) {

		http.Error(w, "unsupported coin", http.StatusBadRequest)

		return

	}

	// `requiredFee` stores the request data being processed.
	requiredFee := ComputeTxFee(req.Amount)
	// `totalCost` stores the measured quantity used by this operation.
	totalCost := req.Amount + requiredFee
	if getBalance(s.Node.Ledger, coin, wallet.Address) < totalCost {

		http.Error(w, "insufficient balance", http.StatusBadRequest)

		return

	}

	// `currentNonce` stores the value produced by this operation.
	currentNonce := getNonce(s.Node.Ledger, wallet.Address)

	// `tx` and `err` store the error produced by this operation.
	tx, err := BuildSignedStakeTxSecure(

		wallet,

		req.Password,

		req.ValidatorID,

		req.ValidatorPubKey,

		req.Amount,

		currentNonce,

		coin,

		req.LockEpochs,
	)

	if err != nil {

		http.Error(w, err.Error(), http.StatusBadRequest)

		return

	}

	if !s.Node.ReceiveTransaction(tx) {

		http.Error(w, "transaction rejected", http.StatusBadRequest)

		return

	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"status": "accepted",

		"tx_id": tx.ID,

		"nonce": tx.Nonce,

		"validator_id": strings.TrimSpace(req.ValidatorID),

		"amount": tx.Amount,

		"coin": tx.Coin,
	})

}

// handleUnstake handles unstake.
func (s *Server) handleUnstake(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	// `req` stores the request data being processed.
	var req struct {
		// `ValidatorID` stores whether the related condition is satisfied.
		ValidatorID string `json:"validator_id"`

		// `Amount` stores the value associated with this record.
		Amount int `json:"amount"`

		// `Coin` stores the value associated with this record.
		Coin string `json:"coin"`

		// `Password` stores the value associated with this record.
		Password string `json:"password"`
	}

	// `err` stores the error produced by this operation.
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {

		http.Error(w, "invalid request body", http.StatusBadRequest)

		return

	}

	if strings.TrimSpace(req.ValidatorID) == "" || req.Amount <= 0 {

		http.Error(w, "validator_id and amount required", http.StatusBadRequest)

		return

	}

	// `wallet` and `err` store the error produced by this operation.
	wallet, err := LoadSecureWallet()

	if err != nil {

		http.Error(w, "secure wallet not found", http.StatusNotFound)

		return

	}

	// `currentNonce` stores the value produced by this operation.
	currentNonce := getNonce(s.Node.Ledger, wallet.Address)

	// `tx` and `err` store the error produced by this operation.
	tx, err := BuildSignedUnstakeTxSecure(

		wallet,

		req.Password,

		req.ValidatorID,

		req.Amount,

		currentNonce,

		req.Coin,
	)

	if err != nil {

		http.Error(w, err.Error(), http.StatusBadRequest)

		return

	}

	if !s.Node.ReceiveTransaction(tx) {

		http.Error(w, "transaction rejected", http.StatusBadRequest)

		return

	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"status": "accepted",

		"tx_id": tx.ID,

		"nonce": tx.Nonce,

		"validator_id": strings.TrimSpace(req.ValidatorID),

		"amount": tx.Amount,

		"coin": tx.Coin,
	})

}

// defaultValidatorViewHeight returns the default validator view height.
func (s *Server) defaultValidatorViewHeight() int {
	if s == nil || s.Node == nil || s.Node.Blockchain == nil {
		return 1
	}
	// `localHeight` stores the value produced by this operation.
	localHeight := s.Node.Blockchain.Height()
	// `height` stores the value produced by this operation.
	height := s.Node.getFinalizedHeight()
	if localHeight > 0 && (height == 0 || height > localHeight) {
		height = localHeight
	}
	if height == 0 {
		height = s.Node.Blockchain.FinalizedHeight()
		if localHeight > 0 && height > localHeight {
			height = localHeight
		}
	}
	if height == 0 {
		return 1
	}
	return int(height)
}

// handleValidators handles validators.
func (s *Server) handleValidators(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	// `height` stores the value produced by this operation.
	height := s.defaultValidatorViewHeight()

	// `hq` stores the value produced by this operation.
	if hq := r.URL.Query().Get("height"); hq != "" {

		// `parsed` and `err` store the error produced by this operation.
		if parsed, err := strconv.Atoi(hq); err == nil && parsed > 0 {

			height = parsed

		}

	}

	// `validators` stores whether the related condition is satisfied.
	validators := canonicalValidatorIDs(s.Node.GetConsensusValidators(height))
	// Public online/offline fields use the same strict heartbeat/readiness view as /status.
	onlineValidators, offlineValidators := s.Node.splitValidatorsByConsensusLiveness(validators)
	// Recent finalized participation is activity evidence, not node liveness.
	recentlyParticipatingValidators, recentlyInactiveValidators := s.Node.splitValidatorsByFinalizedActivity(validators, uint64(height))
	// `localOnlineValidators` and `localOfflineValidators` store the value produced by this operation.
	localOnlineValidators, localOfflineValidators := s.Node.splitValidatorsByLiveness(validators)
	// `validatorLiveness` stores whether the related condition is satisfied.
	validatorLiveness := make(map[string]map[string]any, len(validators))
	// `now` stores the value produced by this operation.
	now := time.Now()
	// `localFinalized` stores the value produced by this operation.
	localFinalized := s.Node.getFinalizedHeight()
	if localFinalized == 0 && s.Node.Blockchain != nil {
		localFinalized = s.Node.Blockchain.FinalizedHeight()
		if localFinalized == 0 {
			localFinalized = s.Node.Blockchain.Height()
		}
	}
	s.Node.validatorMu.RLock()
	// `id` tracks the current position in the related collection.
	for _, id := range validators {
		// `vid` stores the value produced by this operation.
		vid := normalizeValidatorID(id)
		if vid == "" {
			continue
		}
		// `st` stores the value produced by this operation.
		st := s.Node.validatorStatus[vid]
		// `entry` stores the value produced by this operation.
		entry := map[string]any{
			"offline_since":             int64(0),
			"rejoin_pending":            false,
			"rejoin_heartbeats":         uint16(0),
			"rejoin_last_signed_height": uint64(0),
			"last_seen_unix":            int64(0),
			"age_seconds":               int64(0),
			"in_any_heartbeat_set":      false,
			"height_lag_blocks":         uint64(0),
			"live_strict":               false,
			"fail_reason":               "missing_status",
		}
		// `ts` stores the value produced by this operation.
		if ts := s.Node.validatorOfflineSince[vid]; !ts.IsZero() {
			entry["offline_since"] = ts.Unix()
		}
		// `re` and `ok` store whether the related condition is satisfied.
		if re, ok := s.Node.validatorRejoin[vid]; ok {
			entry["rejoin_pending"] = re.Pending
			entry["rejoin_heartbeats"] = re.Heartbeats
			entry["rejoin_last_signed_height"] = re.LastSignedHeight
		}
		if st != nil {
			if !st.LastSeen.IsZero() {
				entry["last_seen_unix"] = st.LastSeen.Unix()
				// `ageSeconds` stores the value produced by this operation.
				ageSeconds := now.Sub(st.LastSeen) / time.Second
				if ageSeconds < 0 {
					ageSeconds = 0
				}
				entry["age_seconds"] = int64(ageSeconds)
			}
			entry["in_any_heartbeat_set"] = s.Node.validatorInAnyHeartbeatSet(
				vid,
				st.ReportedHeight,
				st.FinalizedHeight,
				st.ExecEpoch,
				st.ValidatorSetHeight,
			)
		}
		// `eval` stores the value currently being processed.
		eval := s.Node.evaluateValidatorLivenessLocked(vid, st, now, localFinalized)
		entry["height_lag_blocks"] = eval.HeightLagBlocks
		entry["live_strict"] = eval.LiveStrict
		entry["fail_reason"] = eval.FailReason
		validatorLiveness[id] = entry
	}
	s.Node.validatorMu.RUnlock()

	_ = json.NewEncoder(w).Encode(map[string]any{

		"height": height,

		"validators": validators,

		"online_validators": onlineValidators,

		"inactive_validators": offlineValidators,

		"offline_validators":                offlineValidators,
		"local_online_validators":           localOnlineValidators,
		"local_inactive_validators":         localOfflineValidators,
		"recently_participating_validators": recentlyParticipatingValidators,
		"recently_inactive_validators":      recentlyInactiveValidators,
		"committee_size":                    len(validators),
		"online_count":                      len(onlineValidators),
		"offline_count":                     len(offlineValidators),
		"heartbeat_online_count":            len(localOnlineValidators),
		"recently_participating_count":      len(recentlyParticipatingValidators),
		"liveness_source":                   "strict_consensus_heartbeat",
		"local_liveness_source":             "heartbeat_height_view",
		"finalized_activity_source":         "recent_finalized_blocks",
		"validator_liveness":                validatorLiveness,
	})

}

// handleValidatorSetHash handles validator set hash.
func (s *Server) handleValidatorSetHash(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	// `height` stores the value produced by this operation.
	height := int(s.Node.Blockchain.Height() + 1)

	// `hq` stores the value produced by this operation.
	if hq := r.URL.Query().Get("height"); hq != "" {

		// `parsed` and `err` store the error produced by this operation.
		if parsed, err := strconv.Atoi(hq); err == nil && parsed > 0 {

			height = parsed

		}

	}

	// `validators` stores whether the related condition is satisfied.
	validators := s.Node.GetConsensusValidators(height)

	// `sorted` stores the value produced by this operation.
	sorted := append([]string{}, validators...)

	sort.Strings(sorted)

	// `hash` stores the digest used to identify or verify the related data.
	hash := ""

	if len(sorted) > 0 {

		hash = ValidatorSetHash(sorted)

	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"height": height,

		"validator_set_hash": hash,

		"validators": sorted,
	})

}

// handleValidatorSetAudit handles validator set audit.
func (s *Server) handleValidatorSetAudit(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	if s.Node == nil || s.Node.Blockchain == nil {

		http.Error(w, "node unavailable", http.StatusServiceUnavailable)

		return

	}

	// `height` stores the value produced by this operation.
	height := int(s.Node.Blockchain.Height() + 1)

	// `hq` stores the value produced by this operation.
	if hq := r.URL.Query().Get("height"); hq != "" {

		// `parsed` and `err` store the error produced by this operation.
		if parsed, err := strconv.Atoi(hq); err == nil && parsed > 0 {

			height = parsed

		}

	}

	if height <= 0 {

		height = 1

	}

	// `lockHeight` stores the synchronization state protecting shared data.
	lockHeight := uint64(0)

	if height > 1 {

		lockHeight = uint64(height - 1)

	}

	// `validators` stores whether the related condition is satisfied.
	validators := canonicalValidatorIDs(s.Node.GetConsensusValidators(height))

	// `setHash` stores the digest used to identify or verify the related data.
	setHash := ""

	if len(validators) > 0 {

		setHash = ValidatorSetHash(validators)

	}

	type pendingEntry struct {
		// `ID` stores the current position in the related collection.
		ID string `json:"id"`
		// `ActivationHeight` stores the value associated with this record.
		ActivationHeight uint64 `json:"activation_height"`
	}

	type peerAuditEntry struct {
		// `PeerID` stores the value associated with this record.
		PeerID string `json:"peer_id"`
		// `ValidatorID` stores whether the related condition is satisfied.
		ValidatorID string `json:"validator_id"`
		// `ValidatorSetHash` stores whether the related condition is satisfied.
		ValidatorSetHash string `json:"validator_set_hash"`
		// `HashMatch` stores the digest used to identify or verify the related data.
		HashMatch bool `json:"hash_match"`
		// `HelloOK` stores whether the related condition is satisfied.
		HelloOK bool `json:"hello_ok"`
		// `AckHeight` stores the value associated with this record.
		AckHeight uint64 `json:"ack_height"`
	}

	// `currentValidators` stores the value produced by this operation.
	currentValidators := make([]string, 0)
	// `pendingAdds` stores the value produced by this operation.
	pendingAdds := make([]pendingEntry, 0)
	// `pendingRemoves` stores the value produced by this operation.
	pendingRemoves := make([]pendingEntry, 0)
	// `validatorSetHeight` stores whether the related condition is satisfied.
	validatorSetHeight := uint64(0)

	s.Node.validatorSetMu.RLock()

	validatorSetHeight = s.Node.validatorSetHeight

	// `id` and `act` track the current position in the related collection.
	for id, act := range s.Node.pendingValidators {

		pendingAdds = append(pendingAdds, pendingEntry{

			ID: id,

			ActivationHeight: act,
		})

	}

	// `id` and `act` track the current position in the related collection.
	for id, act := range s.Node.pendingValidatorRemovals {

		pendingRemoves = append(pendingRemoves, pendingEntry{

			ID: id,

			ActivationHeight: act,
		})

	}

	s.Node.validatorSetMu.RUnlock()

	currentValidators = append(currentValidators, validators...)
	currentValidators = canonicalValidatorIDs(currentValidators)

	sort.Slice(pendingAdds, func(i, j int) bool {

		if pendingAdds[i].ActivationHeight == pendingAdds[j].ActivationHeight {

			return pendingAdds[i].ID < pendingAdds[j].ID

		}

		return pendingAdds[i].ActivationHeight < pendingAdds[j].ActivationHeight

	})

	sort.Slice(pendingRemoves, func(i, j int) bool {

		if pendingRemoves[i].ActivationHeight == pendingRemoves[j].ActivationHeight {

			return pendingRemoves[i].ID < pendingRemoves[j].ID

		}

		return pendingRemoves[i].ActivationHeight < pendingRemoves[j].ActivationHeight

	})

	// `peerHashes` stores the value produced by this operation.
	peerHashes := make([]peerAuditEntry, 0)

	s.Node.peerStateMu.Lock()

	// `pid` and `phash` track the digest used to identify or verify the related data.
	for pid, phash := range s.Node.peerSetHash {

		peerHashes = append(peerHashes, peerAuditEntry{

			PeerID: pid,

			ValidatorID: s.Node.peerToValidator[pid],

			ValidatorSetHash: phash,

			HashMatch: s.Node.peerHashMatch[pid],

			HelloOK: s.Node.peerHelloOK[pid],

			AckHeight: s.Node.peerAckHeight[pid],
		})

	}

	s.Node.peerStateMu.Unlock()

	sort.Slice(peerHashes, func(i, j int) bool {

		return peerHashes[i].PeerID < peerHashes[j].PeerID

	})

	// `snapshotAudit` stores the value produced by this operation.
	snapshotAudit := map[string]any{
		"requested_lock_height": lockHeight,
		"found":                 false,
	}

	if lockHeight > 0 {

		// `source` stores the value produced by this operation.
		source := "exact"
		// `snap` and `err` store the error produced by this operation.
		snap, err := s.Node.GetSnapshot(lockHeight)

		if err != nil || snap == nil {

			source = "at_or_below"
			snap, err = s.Node.GetSnapshotAtOrBelow(lockHeight)

		}

		if err != nil {

			snapshotAudit["error"] = err.Error()

		}

		if snap != nil {

			// `snapValidators` stores the value produced by this operation.
			snapValidators := canonicalValidatorIDs(validatorsFromSnapshot(snap))
			// `snapHash` stores the digest used to identify or verify the related data.
			snapHash := ""

			if len(snapValidators) > 0 {

				snapHash = ValidatorSetHash(snapValidators)

			}

			snapshotAudit = map[string]any{
				"requested_lock_height": lockHeight,
				"found":                 true,
				"source":                source,
				"height":                snap.Height,
				"block_hash":            snap.BlockHash,
				"state_root":            snap.StateRoot,
				"ledger_hash":           snap.LedgerHash,
				"validator_count":       len(snapValidators),
				"validator_set_hash":    snapHash,
				"registry_count":        len(snap.ValidatorRegistry),
			}

		}

	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"height": height,

		"lock_height": lockHeight,

		"validator_set_hash": setHash,

		"expected_validator_set_hash": func() string {
			// `hash` stores the digest used to identify or verify the related data.
			hash, _ := s.Node.expectedValidatorSetHashWithSource(uint64(height))
			return hash
		}(),
		"expected_validator_set_source": func() string {
			// `source` stores the value produced by this operation.
			_, source := s.Node.expectedValidatorSetHashWithSource(uint64(height))
			return normalizeExpectedValidatorSetSource(source)
		}(),

		"validators": validators,

		"validator_count": len(validators),

		"runtime": s.Node.runtimeStatusSnapshot(),

		"validator_set_height": validatorSetHeight,
		"activation_height":    validatorSetHeight,

		"current_validators": currentValidators,

		"pending_adds": pendingAdds,

		"pending_removes": pendingRemoves,

		"peer_hashes": peerHashes,

		"snapshot": snapshotAudit,
	})

}

type pendingValidatorEntry struct {
	// `ID` stores the current position in the related collection.
	ID string `json:"id"`
	// `ActivationHeight` stores the value associated with this record.
	ActivationHeight uint64 `json:"activation_height"`
	// `ScheduledHeight` stores the value associated with this record.
	ScheduledHeight uint64 `json:"scheduled_height,omitempty"`
	// `EffectiveHeight` stores the value associated with this record.
	EffectiveHeight uint64 `json:"effective_height,omitempty"`
	// `State` stores the value associated with this record.
	State string `json:"state,omitempty"`
	// `BlockerReason` stores the block data handled by this operation.
	BlockerReason string `json:"blocker_reason,omitempty"`
	// `BlockerClass` stores the block data handled by this operation.
	BlockerClass string `json:"blocker_class,omitempty"`
}

// collectPendingValidators implements the collect pending validators helper.
func (s *Server) collectPendingValidators() (uint64, []pendingValidatorEntry, []pendingValidatorEntry) {
	// `height` stores the value produced by this operation.
	height := uint64(0)
	if s != nil && s.Node != nil && s.Node.Blockchain != nil {
		height = s.Node.Blockchain.FinalizedHeight()
	}

	// `pendingAdds` stores the value produced by this operation.
	pendingAdds := make([]pendingValidatorEntry, 0)
	// `pendingRemoves` stores the value produced by this operation.
	pendingRemoves := make([]pendingValidatorEntry, 0)
	if s == nil || s.Node == nil {
		return height, pendingAdds, pendingRemoves
	}

	// `nextEvalHeight` stores the value produced by this operation.
	nextEvalHeight := height + 1
	// `classifyBlocker` stores the value produced by this operation.
	classifyBlocker := func(reason string) string {
		// `r` stores the value produced by this operation.
		r := strings.TrimSpace(strings.ToLower(reason))
		switch {
		case r == "", r == "active":
			return ""
		case strings.Contains(r, "core_registry_unverified"):
			return "D"
		case strings.Contains(r, "barrier"):
			return "C"
		case strings.Contains(r, "not_due"), strings.Contains(r, "scheduled"):
			return "B"
		default:
			return "A"
		}
	}

	s.Node.validatorSetMu.RLock()
	// `id` and `act` track the current position in the related collection.
	for id, act := range s.Node.pendingValidators {
		// `effective` stores the value produced by this operation.
		effective := validatorSetTransitionActivationHeightAt(act, nextEvalHeight)
		// `state` stores the value produced by this operation.
		state := string(OnboardingStateScheduled)
		// `reason` stores the value produced by this operation.
		reason := "scheduled_not_due"
		if effective > 0 && effective <= height {
			state = string(OnboardingStateActivating)
			reason = "transition_barrier_pending"
		}
		// `tracker` and `ok` store whether the related condition is satisfied.
		if tracker, ok := s.Node.onboardingTrackerSnapshot(id); ok {
			if strings.TrimSpace(string(tracker.State)) != "" {
				state = string(tracker.State)
			}
			if strings.TrimSpace(tracker.LastReason) != "" {
				reason = tracker.LastReason
			}
		}
		pendingAdds = append(pendingAdds, pendingValidatorEntry{
			ID:               id,
			ActivationHeight: act,
			ScheduledHeight:  act,
			EffectiveHeight:  effective,
			State:            state,
			BlockerReason:    reason,
			BlockerClass:     classifyBlocker(reason),
		})
	}
	// `id` and `act` track the current position in the related collection.
	for id, act := range s.Node.pendingValidatorRemovals {
		// `effective` stores the value produced by this operation.
		effective := validatorSetTransitionActivationHeightAt(act, nextEvalHeight)
		// `reason` stores the value produced by this operation.
		reason := "scheduled_not_due"
		if effective > 0 && effective <= height {
			reason = "transition_barrier_pending"
		}
		pendingRemoves = append(pendingRemoves, pendingValidatorEntry{
			ID:               id,
			ActivationHeight: act,
			ScheduledHeight:  act,
			EffectiveHeight:  effective,
			State:            string(OnboardingStateActivating),
			BlockerReason:    reason,
			BlockerClass:     classifyBlocker(reason),
		})
	}
	s.Node.validatorSetMu.RUnlock()

	sort.Slice(pendingAdds, func(i, j int) bool {
		if pendingAdds[i].ActivationHeight == pendingAdds[j].ActivationHeight {
			return pendingAdds[i].ID < pendingAdds[j].ID
		}
		return pendingAdds[i].ActivationHeight < pendingAdds[j].ActivationHeight
	})

	sort.Slice(pendingRemoves, func(i, j int) bool {
		if pendingRemoves[i].ActivationHeight == pendingRemoves[j].ActivationHeight {
			return pendingRemoves[i].ID < pendingRemoves[j].ID
		}
		return pendingRemoves[i].ActivationHeight < pendingRemoves[j].ActivationHeight
	})

	return height, pendingAdds, pendingRemoves
}

// handleValidatorsPending handles validators pending.
func (s *Server) handleValidatorsPending(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	// `height`, `pendingAdds`, and `pendingRemoves` store the value produced by this operation.
	height, pendingAdds, pendingRemoves := s.collectPendingValidators()
	_ = json.NewEncoder(w).Encode(map[string]any{

		"height": height,

		"pending_add": pendingAdds,

		"pending_remove": pendingRemoves,
	})

}

