// handleV1Validators handles v1 validators.
func (s *Server) handleV1Validators(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeV1Error(w, http.StatusMethodNotAllowed, "", "method not allowed")
		return
	}
	if !authorized(r) {
		writeV1Error(w, http.StatusUnauthorized, "", "unauthorized")
		return
	}
	if s == nil || s.Node == nil || s.Node.Blockchain == nil {
		writeV1Error(w, http.StatusServiceUnavailable, "", "node unavailable")
		return
	}

	// `height` stores the value produced by this operation.
	height := s.defaultValidatorViewHeight()
	// `hq` stores the value produced by this operation.
	if hq := strings.TrimSpace(r.URL.Query().Get("height")); hq != "" {
		// `parsed` and `err` store the error produced by this operation.
		if parsed, err := strconv.Atoi(hq); err == nil && parsed > 0 {
			height = parsed
		} else {
			writeV1Error(w, http.StatusBadRequest, "", "invalid height")
			return
		}
	}

	// `validators` stores whether the related condition is satisfied.
	validators := canonicalValidatorIDs(s.Node.GetConsensusValidators(height))
	// Public online/offline fields use the same strict heartbeat/readiness view as /status.
	onlineValidators, offlineValidators := s.Node.splitValidatorsByConsensusLiveness(validators)
	// Recent finalized participation is activity evidence, not node liveness.
	recentlyParticipatingValidators, recentlyInactiveValidators := s.Node.splitValidatorsByFinalizedActivity(validators, uint64(height))
	// `localOnlineValidators` and `localOfflineValidators` store the value produced by this operation.
	localOnlineValidators, localOfflineValidators := s.Node.splitValidatorsByLiveness(validators)
	// `pendingHeight`, `pendingAdds`, and `pendingRemoves` store the value produced by this operation.
	pendingHeight, pendingAdds, pendingRemoves := s.collectPendingValidators()

	writeV1Data(w, http.StatusOK, map[string]any{
		"height":                            height,
		"validators":                        validators,
		"online_validators":                 onlineValidators,
		"inactive_validators":               offlineValidators,
		"offline_validators":                offlineValidators,
		"local_online_validators":           localOnlineValidators,
		"local_inactive_validators":         localOfflineValidators,
		"recently_participating_validators": recentlyParticipatingValidators,
		"recently_inactive_validators":      recentlyInactiveValidators,
		"committee_size":                    len(validators),
		"online_count":                      len(onlineValidators),
		"offline_count":                     len(offlineValidators),
		"heartbeat_online_count":            len(localOnlineValidators),
		"recently_participating_count":      len(recentlyParticipatingValidators),
		"liveness_source":                   "strict_consensus_heartbeat",
		"local_liveness_source":             "heartbeat_height_view",
		"finalized_activity_source":         "recent_finalized_blocks",
		"pending_height":                    pendingHeight,
		"pending_add":                       pendingAdds,
		"pending_remove":                    pendingRemoves,
	})
}

