// handleV1TxByID handles v1 tx by id.
func (s *Server) handleV1TxByID(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeV1Error(w, http.StatusMethodNotAllowed, "", "method not allowed")
		return
	}
	if !authorized(r) {
		writeV1Error(w, http.StatusUnauthorized, "", "unauthorized")
		return
	}
	if s == nil || s.Node == nil || s.Node.Blockchain == nil {
		writeV1Error(w, http.StatusServiceUnavailable, "", "node unavailable")
		return
	}

	// `txID` stores the transaction data handled by this operation.
	txID := strings.TrimSpace(strings.TrimPrefix(r.URL.Path, "/v1/tx/"))
	if txID == "" {
		txID = strings.TrimSpace(r.URL.Query().Get("tx_id"))
	}
	if txID == "" {
		writeV1Error(w, http.StatusBadRequest, "", "tx id required")
		return
	}

	s.Node.Mempool.mu.Lock()
	// `i` and `tx` track the transaction data handled by this operation.
	for i, tx := range s.Node.Mempool.Transactions {
		if tx.ID != txID {
			continue
		}
		// `pendingTx` stores the transaction data handled by this operation.
		pendingTx := tx
		// `pos` stores the value produced by this operation.
		pos := i
		s.Node.Mempool.mu.Unlock()
		// `resp` stores the response produced by this operation.
		resp := map[string]any{
			"tx_id":            txID,
			"state":            "pending",
			"mempool_position": pos,
			"tx":               pendingTx,
		}
		attachDTLDeployMetadata(resp, pendingTx, nil)
		writeV1Data(w, http.StatusOK, resp)
		return
	}
	s.Node.Mempool.mu.Unlock()

	s.Node.Blockchain.mu.RLock()
	// `blocks` stores the block data handled by this operation.
	blocks := append([]Block{}, s.Node.Blockchain.Blocks...)
	s.Node.Blockchain.mu.RUnlock()

	// `latestHeight` stores the value produced by this operation.
	latestHeight := uint64(0)
	if len(blocks) > 0 {
		latestHeight = blocks[len(blocks)-1].ID
	}
	// `finalizedHeight` stores the value produced by this operation.
	finalizedHeight := s.explorerAvailableFinalizedHeight()

	// `i` stores the current position in the related collection.
	for i := len(blocks) - 1; i >= 0; i-- {
		// `block` stores the synchronization state protecting shared data.
		block := blocks[i]
		// `txIndex` and `tx` track the transaction data handled by this operation.
		for txIndex, tx := range block.Transactions {
			if tx.ID != txID {
				continue
			}
			// `confirmations` stores the value produced by this operation.
			confirmations := uint64(0)
			if latestHeight >= block.ID {
				confirmations = latestHeight - block.ID + 1
			}
			// `resp` stores the response produced by this operation.
			resp := map[string]any{
				"tx_id":            txID,
				"state":            "confirmed",
				"height":           block.ID,
				"tx_index":         txIndex,
				"confirmations":    confirmations,
				"latest_height":    latestHeight,
				"finalized_height": finalizedHeight,
				"is_finalized":     finalizedHeight >= block.ID,
				"block":            buildExplorerBlockSummary(block),
				"tx":               tx,
			}
			if txIndex >= 0 && txIndex < len(block.Receipts) {
				if !attachDTLReceiptPresentationMetadata(resp, block.Receipts[txIndex]) {
					attachDTLDeployMetadata(resp, tx, &s.Node.Ledger)
				}
			} else {
				attachDTLDeployMetadata(resp, tx, &s.Node.Ledger)
			}
			writeV1Data(w, http.StatusOK, resp)
			return
		}
	}

	writeV1Error(w, http.StatusNotFound, "", "tx not found")
}

// handleV1TxStatus handles v1 tx status.
func (s *Server) handleV1TxStatus(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeV1Error(w, http.StatusMethodNotAllowed, "", "method not allowed")
		return
	}
	if !authorized(r) {
		writeV1Error(w, http.StatusUnauthorized, "", "unauthorized")
		return
	}

	// `txID` stores the transaction data handled by this operation.
	txID := strings.TrimSpace(r.URL.Query().Get("tx_id"))
	if txID == "" {
		writeV1Error(w, http.StatusBadRequest, "", "tx_id required")
		return
	}

	// `snap` stores the value produced by this operation.
	snap := s.buildTxStatusSnapshot(txID)
	writeV1Data(w, http.StatusOK, snap)
}

// handleV1SubmitTx handles v1 submit tx.
func (s *Server) handleV1SubmitTx(w http.ResponseWriter, r *http.Request) {
	// `out`, `status`, and `errText` store the error produced by this operation.
	out, status, errText := s.processSubmitTx(r)
	if errText != "" {
		writeV1Error(w, status, "", errText)
		return
	}
	writeV1Data(w, status, out)
}

// handleTxHistory handles tx history.
func (s *Server) handleTxHistory(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	// `addr` stores the address used by this operation.
	addr := strings.TrimSpace(r.URL.Query().Get("address"))

	if addr == "" {

		http.Error(w, "address required", http.StatusBadRequest)

		return

	}
	addr = canonicalAddressKey(addr)

	// `limit` stores the value produced by this operation.
	limit := 25

	// `lq` stores the value produced by this operation.
	if lq := r.URL.Query().Get("limit"); lq != "" {

		// `parsed` and `err` store the error produced by this operation.
		if parsed, err := strconv.Atoi(lq); err == nil {

			limit = parsed

		}

	}

	if limit < 1 {

		limit = 1

	}

	if limit > 200 {

		limit = 200

	}

	s.Node.Blockchain.mu.RLock()

	// `blocks` stores the block data handled by this operation.
	blocks := append([]Block{}, s.Node.Blockchain.Blocks...)

	s.Node.Blockchain.mu.RUnlock()

	type txEntry struct {
		// `ID` stores the current position in the related collection.
		ID string `json:"id"`

		// `From` stores the value associated with this record.
		From string `json:"from"`

		// `To` stores the value associated with this record.
		To string `json:"to"`

		// `Amount` stores the value associated with this record.
		Amount int `json:"amount"`

		// `Fee` stores the value associated with this record.
		Fee int `json:"fee"`

		// `Nonce` stores the value associated with this record.
		Nonce int `json:"nonce"`

		// `Coin` stores the value associated with this record.
		Coin string `json:"coin"`

		// `Type` stores the value associated with this record.
		Type TxType `json:"type"`

		// `Height` stores the value associated with this record.
		Height uint64 `json:"height"`

		// `Timestamp` stores the value associated with this record.
		Timestamp int64 `json:"timestamp"`
	}

	// `hits` stores the value produced by this operation.
	hits := make([]txEntry, 0, limit)

	// `i` stores the current position in the related collection.
	for i := len(blocks) - 1; i >= 0 && len(hits) < limit; i-- {

		// `block` stores the synchronization state protecting shared data.
		block := blocks[i]

		// `j` stores the current position in the related collection.
		for j := len(block.Transactions) - 1; j >= 0 && len(hits) < limit; j-- {

			// `tx` stores the transaction data handled by this operation.
			tx := block.Transactions[j]

			if !addressesEqual(tx.From, addr) && !addressesEqual(tx.To, addr) {

				continue

			}

			// `coin` stores the value produced by this operation.
			coin := tx.Coin

			if coin == "" {

				coin = CoinSymbol

			}

			hits = append(hits, txEntry{

				ID: tx.ID,

				From: tx.From,

				To: tx.To,

				Amount: tx.Amount,

				Fee: tx.Fee,

				Nonce: tx.Nonce,

				Coin: coin,

				Type: tx.Type,

				Height: block.ID,

				Timestamp: block.Timestamp,
			})

		}

	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"address": displayAddress(addr),

		"txs": hits,
	})

}

