// buildExplorerBlockSummary builds explorer block summary.
func buildExplorerBlockSummary(block Block) explorerBlockSummary {
	return explorerBlockSummary{
		Height:                 block.ID,
		Hash:                   block.BlockHash,
		PrevHash:               block.PrevHash,
		Proposer:               block.Proposer,
		Type:                   block.Type.String(),
		Timestamp:              block.Timestamp,
		BlockTime:              block.BlockTime,
		TxCount:                len(block.Transactions),
		ExecutionResultCount:   len(block.ExecutionResults),
		ReceiptCount:           len(block.Receipts),
		SignatureCount:         len(block.Signatures),
		MempoolRoot:            block.MempoolRoot,
		StateRoot:              block.StateRoot,
		ValidatorSetHash:       block.ValidatorSetHash,
		ValidatorSetRoot:       block.ValidatorSetRoot,
		ValidatorRegistryHash:  block.ValidatorRegistryHash,
		NextValidatorSetHash:   block.NextValidatorSetHash,
		NextValidatorSetRoot:   block.NextValidatorSetRoot,
		NextValidatorSetHeight: block.NextValidatorSetHeight,
		ActivationHeight:       blockActivationHeight(block),
		ConsensusMode:          strings.TrimSpace(block.ConsensusMode),
		QuorumPolicyVersion:    strings.TrimSpace(block.QuorumPolicyVersion),
		ActiveReadyCount:       block.ActiveReadyCount,
		RequiredQuorum:         block.RequiredQuorum,
		StrictQuorum:           block.StrictQuorum,
	}
}

// explorerFinalizedHeight implements the explorer finalized height helper.
func (s *Server) explorerFinalizedHeight() uint64 {
	if s == nil || s.Node == nil || s.Node.Blockchain == nil {
		return 0
	}
	// `finalized` stores the value produced by this operation.
	finalized := s.Node.Blockchain.FinalizedHeight()
	// `local` stores the value produced by this operation.
	if local := s.Node.getFinalizedHeight(); local > finalized {
		finalized = local
	}
	return finalized
}

// explorerAvailableFinalizedHeight implements the explorer available finalized height helper.
func (s *Server) explorerAvailableFinalizedHeight() uint64 {
	if s == nil || s.Node == nil || s.Node.Blockchain == nil {
		return 0
	}
	// `latest` stores the value produced by this operation.
	latest := s.Node.Blockchain.Height()
	// `finalized` stores the value produced by this operation.
	finalized := s.explorerFinalizedHeight()
	if finalized > latest {
		return latest
	}
	return finalized
}

// handleExplorerBlocks handles explorer blocks.
func (s *Server) handleExplorerBlocks(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	if s.Node == nil || s.Node.Blockchain == nil {

		http.Error(w, "node unavailable", http.StatusServiceUnavailable)

		return

	}

	// `limit` stores the value produced by this operation.
	limit := 25
	// `lq` stores the value produced by this operation.
	if lq := strings.TrimSpace(r.URL.Query().Get("limit")); lq != "" {
		// `parsed` and `err` store the error produced by this operation.
		if parsed, err := strconv.Atoi(lq); err == nil {
			limit = parsed
		}
	}
	if limit < 1 {
		limit = 1
	}
	if limit > 200 {
		limit = 200
	}

	// `fromHeight` stores the value used by this operation.
	var fromHeight uint64
	// `hq` stores the value produced by this operation.
	if hq := strings.TrimSpace(r.URL.Query().Get("from_height")); hq != "" {
		// `parsed` and `err` store the error produced by this operation.
		if parsed, err := strconv.ParseUint(hq, 10, 64); err == nil {
			fromHeight = parsed
		}
	}

	s.Node.Blockchain.mu.RLock()
	// `blocks` stores the block data handled by this operation.
	blocks := append([]Block{}, s.Node.Blockchain.Blocks...)
	s.Node.Blockchain.mu.RUnlock()

	// `latestHeight` stores the value produced by this operation.
	latestHeight := uint64(0)
	if len(blocks) > 0 {
		latestHeight = blocks[len(blocks)-1].ID
	}

	if fromHeight == 0 || fromHeight > latestHeight {
		fromHeight = latestHeight
	}

	// `out` stores the result produced by this operation.
	out := make([]explorerBlockSummary, 0, limit)
	// `i` stores the current position in the related collection.
	for i := len(blocks) - 1; i >= 0 && len(out) < limit; i-- {
		// `block` stores the synchronization state protecting shared data.
		block := blocks[i]
		if fromHeight > 0 && block.ID > fromHeight {
			continue
		}
		out = append(out, buildExplorerBlockSummary(block))
	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"latest_height": latestHeight,

		"finalized_height": s.explorerAvailableFinalizedHeight(),

		"from_height": fromHeight,

		"limit": limit,

		"blocks": out,
	})

}

// handleExplorerBlock handles explorer block.
func (s *Server) handleExplorerBlock(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	if s.Node == nil || s.Node.Blockchain == nil {

		http.Error(w, "node unavailable", http.StatusServiceUnavailable)

		return

	}

	var (
		// `targetHeight` stores the value used by this operation.
		targetHeight uint64
		// `targetHash` stores the digest used to identify or verify the related data.
		targetHash string
	)

	// `hq` stores the value produced by this operation.
	if hq := strings.TrimSpace(r.URL.Query().Get("height")); hq != "" {
		// `parsed` and `err` store the error produced by this operation.
		parsed, err := strconv.ParseUint(hq, 10, 64)
		if err != nil {
			http.Error(w, "invalid height", http.StatusBadRequest)
			return
		}
		targetHeight = parsed
	}
	targetHash = strings.TrimSpace(r.URL.Query().Get("hash"))

	s.Node.Blockchain.mu.RLock()
	// `blocks` stores the block data handled by this operation.
	blocks := append([]Block{}, s.Node.Blockchain.Blocks...)
	s.Node.Blockchain.mu.RUnlock()

	// `latestHeight` stores the value produced by this operation.
	latestHeight := uint64(0)
	if len(blocks) > 0 {
		latestHeight = blocks[len(blocks)-1].ID
	}

	var (
		// `found` stores whether the related condition is satisfied.
		found Block
		// `ok` stores whether the related condition is satisfied.
		ok bool
	)

	switch {
	case targetHash != "":
		// `i` stores the current position in the related collection.
		for i := len(blocks) - 1; i >= 0; i-- {
			if strings.EqualFold(strings.TrimSpace(blocks[i].BlockHash), targetHash) {
				found = blocks[i]
				ok = true
				break
			}
		}
	case targetHeight > 0:
		// `i` stores the current position in the related collection.
		for i := len(blocks) - 1; i >= 0; i-- {
			if blocks[i].ID == targetHeight {
				found = blocks[i]
				ok = true
				break
			}
		}
		if !ok {
			found, ok = s.Node.LoadBlock(int(targetHeight))
		}
	default:
		if len(blocks) > 0 {
			found = blocks[len(blocks)-1]
			ok = true
		}
	}

	if !ok {
		http.Error(w, "block not found", http.StatusNotFound)
		return
	}

	// `txs` stores the transaction data handled by this operation.
	txs := append([]Transaction{}, found.Transactions...)
	// `execResults` stores the value produced by this operation.
	execResults := append([]ExecutionResult{}, found.ExecutionResults...)
	// `receipts` stores the value produced by this operation.
	receipts := append([]StateReceipt{}, found.Receipts...)
	// `signatures` stores the result produced by this operation.
	signatures := append([]string{}, found.Signatures...)

	// `finalized` stores the value produced by this operation.
	finalized := s.explorerAvailableFinalizedHeight()
	// `confirmations` stores the value produced by this operation.
	confirmations := uint64(0)
	if latestHeight >= found.ID {
		confirmations = latestHeight - found.ID + 1
	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"summary": buildExplorerBlockSummary(found),

		"height": found.ID,

		"hash": found.BlockHash,

		"prev_hash": found.PrevHash,

		"type": found.Type.String(),

		"round": found.Round,

		"proposer": found.Proposer,

		"timestamp": found.Timestamp,

		"block_time": found.BlockTime,

		"mempool_root": found.MempoolRoot,

		"state_root": found.StateRoot,

		"validator_set_hash": found.ValidatorSetHash,

		"validator_set_root": found.ValidatorSetRoot,

		"validator_registry_hash": found.ValidatorRegistryHash,

		"next_validator_set_hash": found.NextValidatorSetHash,

		"next_validator_set_root": found.NextValidatorSetRoot,

		"next_validator_set_height": found.NextValidatorSetHeight,

		"activation_height": blockActivationHeight(found),

		"consensus_mode": found.ConsensusMode,

		"quorum_policy_version": found.QuorumPolicyVersion,

		"active_ready_count": found.ActiveReadyCount,

		"required_quorum": found.RequiredQuorum,

		"strict_quorum": found.StrictQuorum,

		"tx_count": len(txs),

		"execution_result_count": len(execResults),

		"receipt_count": len(receipts),

		"signature_count": len(signatures),

		"signatures": signatures,

		"transactions": txs,

		"execution_results": execResults,

		"receipts": receipts,

		"latest_height": latestHeight,

		"finalized_height": finalized,

		"confirmations": confirmations,

		"is_finalized": finalized >= found.ID,
	})

}

// handleExplorerTx handles explorer tx.
func (s *Server) handleExplorerTx(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	if s.Node == nil || s.Node.Blockchain == nil {

		http.Error(w, "node unavailable", http.StatusServiceUnavailable)

		return

	}

	// `txID` stores the transaction data handled by this operation.
	txID := strings.TrimSpace(r.URL.Query().Get("tx_id"))
	if txID == "" {
		http.Error(w, "tx_id required", http.StatusBadRequest)
		return
	}

	s.Node.Mempool.mu.Lock()
	// `i` and `tx` track the transaction data handled by this operation.
	for i, tx := range s.Node.Mempool.Transactions {
		if tx.ID != txID {
			continue
		}
		// `pendingTx` stores the transaction data handled by this operation.
		pendingTx := tx
		// `queuePos` stores the value produced by this operation.
		queuePos := i
		s.Node.Mempool.mu.Unlock()
		// `resp` stores the response produced by this operation.
		resp := map[string]any{
			"tx_id":            txID,
			"state":            "pending",
			"mempool_position": queuePos,
			"tx":               pendingTx,
		}
		attachDTLDeployMetadata(resp, pendingTx, nil)
		_ = json.NewEncoder(w).Encode(resp)
		return
	}
	s.Node.Mempool.mu.Unlock()

	s.Node.Blockchain.mu.RLock()
	// `blocks` stores the block data handled by this operation.
	blocks := append([]Block{}, s.Node.Blockchain.Blocks...)
	s.Node.Blockchain.mu.RUnlock()

	// `latestHeight` stores the value produced by this operation.
	latestHeight := uint64(0)
	if len(blocks) > 0 {
		latestHeight = blocks[len(blocks)-1].ID
	}

	// `i` stores the current position in the related collection.
	for i := len(blocks) - 1; i >= 0; i-- {
		// `block` stores the synchronization state protecting shared data.
		block := blocks[i]
		// `txIndex` and `tx` track the transaction data handled by this operation.
		for txIndex, tx := range block.Transactions {
			if tx.ID != txID {
				continue
			}
			// `confirmations` stores the value produced by this operation.
			confirmations := uint64(0)
			if latestHeight >= block.ID {
				confirmations = latestHeight - block.ID + 1
			}
			// `resp` stores the response produced by this operation.
			resp := map[string]any{
				"tx_id":         txID,
				"state":         "confirmed",
				"height":        block.ID,
				"tx_index":      txIndex,
				"confirmations": confirmations,
				"block":         buildExplorerBlockSummary(block),
				"tx":            tx,
			}
			if txIndex >= 0 && txIndex < len(block.Receipts) {
				resp["receipt"] = block.Receipts[txIndex]
			}
			if txIndex >= 0 && txIndex < len(block.Receipts) {
				if !attachDTLReceiptPresentationMetadata(resp, block.Receipts[txIndex]) {
					attachDTLDeployMetadata(resp, tx, &s.Node.Ledger)
				}
			} else {
				attachDTLDeployMetadata(resp, tx, &s.Node.Ledger)
			}
			_ = json.NewEncoder(w).Encode(resp)
			return
		}
	}

	http.Error(w, "tx not found", http.StatusNotFound)

}

