// GetValidatorAddr returns validator addr.
func (n *Node) GetValidatorAddr(validatorID string) string {

	if validatorID == "" {

		return ""

	}

	// `normalized` stores the value produced by this operation.
	normalized := strings.ToUpper(strings.TrimSpace(validatorID))

	ValidatorAddrBook.mu.RLock()

	defer ValidatorAddrBook.mu.RUnlock()

	// `addr` stores the address used by this operation.
	if addr := ValidatorAddrBook.m[validatorID]; addr != "" {

		return addr

	}

	if normalized != "" {

		// `addr` stores the address used by this operation.
		if addr := ValidatorAddrBook.m[normalized]; addr != "" {

			return addr

		}

	}

	// `id` and `addr` track the address used by this operation.
	for id, addr := range ValidatorAddrBook.m {

		if strings.EqualFold(id, validatorID) {

			return addr

		}

	}

	return ""

}
